/* ÇEVİRİ bs · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("bs","olay",{
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Čelebi prešao u Vlašku", "8441267a"], "d": ["Čelebi Mehmed, koji je nakon gubitka Burse i Ankare od Sulejmana Čelebija povučen u Tokat–Amasyu, potaknuo je brata Musu da ode u Rumeliju. Musa je prihvatio poziv vlaškog vojvode Mirče i morem stigao u Vlašku; odatle će krenuti u borbu koja će Sulejmana staviti između dva fronta.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Čelebi Mehmed ponovo zauzeo Bursu i Ankaru — anadolski dio oduzet Sulejmanu Čelebiju", "bfb69f12"], "d": ["Zbog uspjeha Musa-čelebije u Rumeliji (Jambol, 13. februara 1410) emir Sulejman Čelebi, koji je bio u Anadoliji, prešao je u Rumeliju. Nakon Sulejmanovog odlaska iz Anadolije Mehmed Čelebi ponovo je zauzeo brusanski kraj, uključujući Ankaru, i kao znak stupanja na prijestolje dao iskovati novac s godinom 813. Na karti anadolska strana Mramornog mora prelazi iz dijela emira Sulejmana u boju Čelebi Mehmeda.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Bitka kod Kosmidiona", "0efc2caa"], "d": ["U bici vođenoj pred istanbulskim bedemima uz bizantsku podršku Sulejman Čelebi pobijedio je brata Musu; ali njegova podrška u Rumeliji već je počela brzo kopnjeti. Ostala naselja izgubljena istog datuma: Elasona, Aitos, Bolayır (na karti mjesta u Rumeliji koja od Muse prelaze Sulejmanu).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Musa-čelebijina opsada Istanbula", "4932f586"], "d": ["Musa Čelebi, koji je želio kazniti Bizant zbog podrške Sulejmanu, opsjeo je Istanbul; ta opsada gurnula je Bizant u savez s Čelebi Mehmedom.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Smrt emira Sulejmana — Musa gospodar Rumelije", "325c1549"], "d": ["Sulejman Čelebi, uhvaćen dok je bježao iz Edirne, ubijen je; cijela Rumelija prešla je u ruke Musa-čelebije. Na karti Rumelija iz plave boje prelazi u ljubičastu.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Bitka kod Čamurlua — ponovna uspostava jedinstva", "0b23173e"], "d": ["Čelebi Mehmed, koji je dobio podršku Bizanta, Srpske despotovine i rumelijskih begova, kod Čamurlua je odlučno porazio brata Musu; Musa je ubijen dok je bježao. Rumelija koju je držao Musa, zajedno s Edirnom, prešla je Mehmedu, a Mehmed Čelebi se u Edirni proglasio jedinim vladarom Osmanske države. Jedanaestogodišnje doba Fetreta je okončano, a prinčevski dijelovi na karti spojili su se u jedno tijelo.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Odluka o pohodu na Beč — mir iz Vašvara nije obnovljen, cilj s Đura (Yanıkkale) preusmjeren na Beč", "1bf278f2"], "d": ["Car Leopold I tražio je obnovu Vašvarskog mira kojem rok još nije istekao, a i Mehmed IV izgledao je sklon miru. Veliki vezir Merzifonli Kara Mustafa-paša, međutim, kao razlog navodeći pritužbe Imre Thökölyja, kojeg je dao proglasiti kraljem Srednje Ugarske, spriječio je obnovu mira; pokrenuvši propovjednike, na čelu s Vanijem Mehmed-efendijom, nagovorio je sultana na rat. Na održanom vijećanju odlučeno je da sultan ostane u Beogradu, a da serdar-i ekrem napreduje radi zauzimanja Đura; ali na vijećanju u Stolnom Biogradu, unatoč prigovorima krimskog kana Murad Giraja i budimskog valije Uzun Ibrahim-paše, cilj je promijenjen u opsadu Beča.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Počela Druga opsada Beča — vojska pred Bečom", "bb542e49"], "d": ["Osmanska vojska pod komandom velikog vezira Kara Mustafa-paše stigla je pred Beč 14. jula 1683. Car Leopold I povjerio je odbranu grada Starhembergu i povukao se u unutrašnjost Austrije. Ta druga opsada, za razliku od prve pripremljena s Bečom kao izravnim ciljem, trajat će do 12. septembra.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Poraz kod Parkana i gubitak Ostrogona", "a7366740"], "d": ["Vojska koja se povlačila od Beča po drugi je put poražena kod Parkana; zatim je pao Ostrogon, jedna od ključnih tvrđava Ugarske. Povlačenje se počelo pretvarati u slom.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Pogubljenje Merzifonli Kara Mustafa-paše", "ce8b10ac"], "d": ["Veliki vezir, smatran odgovornim za bečki poraz, zadavljen je u Beogradu; no njegovo pogubljenje nije popravilo front niti vratilo poljuljani ugled države.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Osnovana Sveta liga", "060280d0"], "d": ["Na inicijativu papinstva Austrija, Poljska i Venecija osnovale su protiv Osmanlija Svetu ligu; 1686. pridružila se i Rusija. Tako je carstvo ušlo u rat na više frontova koji će trajati šesnaest godina.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Prva odbrana Budima", "ccc43630"], "d": ["Prva opsada Budima koju je poduzela vojska Svete lige odbijena je četveromjesečnom upornom odbranom tvrđave; ali tvrđave u Ugarskoj nastavile su padati jedna za drugom.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Gubitak Novih Zamkova (Uyvar)", "689ab78c"], "d": ["Pala je tvrđava Nove Zamke, koja je dvadeset dvije godine bila u osmanskim rukama i postala poslovična u Evropi; raspalo se osmansko prisustvo u Gornjoj Ugarskoj.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Hapšenje Thökölyja u Varadu — raspalo se Kraljevstvo Srednje Ugarske, predale se tvrđave Gornje Ugarske", "1741aaaf"], "d": ["Nakon bečkog poraza Osmanlije su i Thökölyja počele ubrajati među one koji su doveli do rata i poraza. 15. oktobra 1685. po naredbi serdara Melek Ibrahim-paše varadski beglerbeg Ahmed-paša dao je uhapsiti Thökölyja koji je došao u pomoć; nadalo se da će se njegovom predajom Habsburgovcima dobiti bolji mirovni uvjeti. Kad se pročula vijest o hapšenju, osim Munkača koji je branila njegova supruga Ilona Zrínyi, sve tvrđave i gradovi Kraljevstva Srednje Ugarske predali su se Habsburgovcima; većina kuruckih vojnika prešla je u habsburšku vojsku. Kad je Thököly 2. januara 1686. oslobođen u Beogradu, kraljevstvo je već nestalo.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Gubitak Budima — 145-godišnje mađarske prijestolnice", "70800e2b"], "d": ["Na kraju opsade koja je trajala sedamdeset osam dana Budim je pao; posljednji beglerbeg Abdurrahman Abdi-paša poginuo je kao šehid na bedemima. Gubitak grada koji je od 1541. bio pod osmanskom upravom smatra se simbolom gubitka Ugarske. Ostala naselja izgubljena istog datuma: Pešta.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Poraz u Drugoj mohačkoj bici (Harşan) — gubitak Erdelja i Mohača", "a7922681"], "d": ["Na polju na kojem je 1526. izvojevana velika pobjeda ovaj put pretrpljen je težak poraz; vojska se raspala, a pobunjeni vojnici izdejstvovali su smjenu velikog vezira. Poraz je doveo i do gubitka Erdelja.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Gubitak Atine i eksplozija Partenona", "b6691730"], "d": ["Bomba ispaljena iz venecijanske artiljerije digla je u zrak Partenon, koji su Osmanlije koristile kao barutanu; dvije hiljade godina star hram pretvoren je u ruševinu. Grad je pao u venecijanske ruke (povraćen 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Svrgavanje Mehmeda IV i stupanje Sulejmana II na prijestolje", "9f53037c"], "d": ["Zbog katastrofa na frontu i vojne pobune, nakon 39 godina vladavine Mehmed IV je svrgnut; na njegovo mjesto doveden je njegov brat Sulejman II, četrdeset godina držan u kafesu.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Prvi gubitak Beograda — opsada Svete lige", "c6b9b19a"], "d": ["Beograd, od 1521. u osmanskim rukama, predao se vojsci Svete lige; neprijatelju su se otvorila vrata Srbije, a opasnost je stigla do linije Niš–Sofija. Drugo naselje koje istog datuma u atlasu od Osmanlija prelazi Habsburgovcima: Grocka (Hisarcık) — slijedi lanac glavnog središta Beograda (TDV belgrad; deklarirana približnost).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden kod Požarevca prešao Moravu — Požarevac pao Austriji", "bcf3fc59"], "d": ["Markgraf Ludwig von Baden u augustu 1689. prešao je Moravu kod Požarevca i napredovao prema Nišu; grad je ostao u austrijskim rukama do ljeta 1690. (TDV suleyman-ii navodi da je Požarevac povraćen 1690). Datum i čitanje Rödera nisu u ovoj sesiji ponovo provjereni.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Gubitak Niša — habsburško (kruna Kraljevine Ugarske) napredovanje, najkritičnija godina", "c5e27b3f"], "d": ["Habsburško (kruna Kraljevine Ugarske) napredovanje oduzelo je Osmanlijama i Niš; upadi su sezali sve do Skoplja i Prištine. Vidin je pao nakon toga, u oktobru 1689. (zasebna stavka). U najmračnijoj godini rata država je osjećala da je ugrožena čak i prijestolnica.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Oršava i Fethülislam (Kladovo) dobili austrijski garnizon", "ee8dd875"], "d": ["Nakon zauzimanja Vidina bez borbe (oktobar 1689, TDV vidin) Baden je 25. oktobra 1689. popravio Oršavu i Fethülislam i postavio garnizone; Oršava je do jeseni 1690. ostala Austriji. Datum se oslanja na Bánlakyja/Rödera i nije u ovoj sesiji ponovo provjeren.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš ponovo u osmanskim rukama", "0c4f44eb"], "d": ["Fazil Mustafa-paša krenuo je u pohod u julu 1690; nakon zauzimanja Pirota, Požarevca i Golupca opsjednuti Niš 27. septembra 1690. prešao je u osmanske ruke (TDV semendire). U isto vrijeme povraćen je i Vidin. Ostala naselja koja istog datuma u atlasu od Habsburgovaca vraćaju se Osmanlijama: Jagodina i Prokuplje (Ürküp) — budući da nije pronađen datum na razini mjesta, uzet je datum Niša (TDV semendire; deklarirana približnost; Röder 1842. piše da je vezir prošao kroz Jagodinu 8-24. septembra, proturječnost nije razriješena).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Austrijske jedinice u Smederevu predale se", "90da20c4"], "d": ["Nakon zauzimanja Niša 27. septembra 1690. austrijske jedinice u Smederevu predale su se nakon četverodnevne opsade (TDV semendire). Bánlaky/Röder navode 24. septembar; izvori se razilaze, TDV je uzet kao mjerodavan.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Povraćen Beograd", "ab435838"], "d": ["Veliki vezir Köprülüzade Fazil Mustafa-paša 8. oktobra 1690. povratio je Beograd od Austrije; grad izgubljen 1688. tako se vratio Osmanlijama (TDV suleyman-ii). Drugo naselje koje istog datuma u atlasu od Habsburgovaca vraća se Osmanlijama: Grocka (Hisarcık) — slijedi lanac glavnog središta Beograda (TDV suleyman-ii; deklarirana približnost).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Poraz kod Slankamena — Fazil Mustafa-paša pao kao šehid", "10d626f1"], "d": ["U jednoj od najkrvavijih bitaka na otvorenom polju toga stoljeća veliki vezir pogođen je u čelo i pao kao šehid; vojska se raspala. Nada u oporavak ugasila se s tom bitkom.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Gubitak otoka Hiosa", "07c084f8"], "d": ["Venecijanska flota okupirala je Hios; osmanska vlast na Egeju došla je pod prijetnju. Otok će biti povraćen sljedeće godine.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Odluka Mustafe II da lično krene u pohod", "61c3ba9c"], "d": ["Novi sultan objavio je da će, slijedeći put predaka, lično predvoditi vojsku u pohodu; ta je odluka podigla moral vojske i otvorila doba ličnih pohoda koje će trajati dvije godine.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Povratak Hiosa", "6b496fca"], "d": ["Mezomorto Husein-paša, koji je porazio venecijansku flotu u pomorskim bitkama kod otoka Oinouses (Koyun Adaları), povratio je Hios; to je bio znak kratkog oživljavanja osmanskog pomorstva.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Pobjeda kod Lugoša — prvi austrijski pohod Mustafe II", "d5ee9b34"], "d": ["U prvom pohodu u kojem je sultan lično učestvovao povraćena je Lipova, a kod Lugoša su poražene austrijske snage; došlo je do prvog prekida u dugogodišnjem nizu poraza. Atlas i Karánsebes (Caransebeș) smatra povraćenim u tom pohodu od Habsburgovaca Osmanlijama; izvor navodi samo septembar 1695. (TDV mustafa-ii), a datum u atlasu preuzet je iz zapisa o Lugošu (deklarirana približnost).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Gubitak tvrđave Azov", "2b78b5cd"], "d": ["Petar I, koji je ciljao izlaz na Crno more, u drugoj je opsadi zauzeo Azov; Rusija se prvi put trajno učvrstila u jednoj osmanskoj tvrđavi i načinila prvi korak na putu da postane pomorska sila.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Pobjeda kod Ulaša (Olaschin)", "02ac9ca8"], "d": ["Pobjeda izvojevana na obali Dunava u drugom sultanovom pohodu poremetila je austrijski plan zauzimanja Temišvara; ipak nije promijenila opću ravnotežu rata.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Poraz kod Sente — određena sudbina rata", "475c4a7b"], "d": ["Dok je vojska prelazila rijeku Tisu, pretrpjela je iznenadni napad princa Eugena; snage podijeljene na obje obale rijeke uništene su za nekoliko sati, poginule su hiljade vojnika i državnika, među njima i veliki vezir Elmas Mehmed-paša. Senta, jedan od najtežih poraza u osmanskoj historiji, učinila je mirovni sto neizbježnim.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Počeli Karlovački mirovni pregovori", "1f395cf3"], "d": ["U pregovorima započetim uz posredovanje Engleske i Nizozemske osmansko izaslanstvo prvi je put moralo prihvatiti načelo 'uti possidetis' (ostaje ono što se drži); pregovori od sedamdeset dvije sjednice smatraju se rođenjem moderne osmanske diplomatije.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali iz Kavale stigao u Egipat", "514c943f"], "d": ["U osmanskoj vojsci poslanoj da povrati Egipat od francuske okupacije bila je i dobrovoljačka jedinica prikupljena u Kavali. Tridesetogodišnji Mehmed Ali bio je drugi zapovjednik te jedinice; u Egipat nije stupio kao valija, nego kao četni oficir.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Albanski vojnici svrgnuli valiju Egipta", "c76a0ec2"], "d": ["Albanske jedinice, kojima nisu isplaćene plaće, pobunile su se i natjerale valiju Husrev-pašu da pobjegne iz tvrđave. U praznini nastaloj povlačenjem Francuza memlučki begovi, albanski odžak i valije koje je postavljala Porta ušli su u trostranu borbu; Mehmed Ali istakao se uspostavljajući ravnotežu u tom trouglu. Ostala naselja izgubljena istog datuma: Taif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Kairska ulema proglasila Mehmeda Alija valijom", "a16752f2"], "d": ["Kairski zanatlije i ulema, iscrpljeni poreskim pritiskom, pod vodstvom nakibul-ešrafa Omera Mekrema pobunili su se, objavili da ne priznaju valiju Huršid-pašu i postavili Mehmeda Alija na valijski položaj. U osmanskoj historiji to da je narod izabrao valiju rijedak je događaj.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Porta prihvatila svršen čin: ferman o egipatskom namjesništvu", "b86736a3"], "d": ["Porta, koja nije imala snage da u Egiptu održi vlastitog kandidata, poslala je Mehmedu Aliju ferman o egipatskom namjesništvu s vezirskim činom. Na karti Egipat od tog datuma prelazi u vazalni (svijetli ton) sloj: pravno osmanska zemlja, faktički zemlja dinastije Kavalali. Ostala naselja koja istog datuma prelaze u vazalni sloj: Kairo, Aleksandrija, Damijeta, Asjut, Asuan, İbrim, Suez, Rašid (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Engleska Fraserova ekspedicija iskrcala se u Aleksandriji", "4d6c31be"], "d": ["Kao odgovor na osmansko približavanje Francuskoj, Engleska je u Egipat poslala desantne snage. Mehmed Ali tada se u Gornjem Egiptu borio s Memlucima; brzo se vratio i organizirao odbranu.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Poraz kod Rašida (Rosette) — Englezi odbijeni", "3636004c"], "d": ["Engleska kolona koja je ušla u mjesto Rašid pretrpjela je teške gubitke u uličnim borbama; u septembru su snage potpuno napustile Egipat. Ta je pobjeda učvrstila ugled Mehmeda Alija i u Egiptu i u Istanbulu.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Događaj u tvrđavi: likvidacija memlučkih begova", "84030b97"], "d": ["Memlučki begovi, pozvani na svečanu povorku priređenu povodom pohoda na Hidžaz, uhvaćeni su u klopku u uskom prolazu Kairske tvrđave i ubijeni. Tako je okončan pet stoljeća dug memlučki utjecaj i Mehmed Ali u Egiptu više nije imao suparnika.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Počeo hidžaski pohod — vojska iz Sueza morem i hadžijskim putem kopnom krenula na Janbu", "1c05c159"], "d": ["Povratak Dva sveta mjesta (Haremejna), od 1803. pod saudijsko-vehabijskom upravom, bio je najveće pitanje legitimiteta Mahmuda II; kad Porta za to nije imala snage, zadatak je dat valiji Egipta. Mehmed Ali poslao je svog šesnaestogodišnjeg sina Tosuna na čelu vojske.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Zauzet Janbu — prva obalna baza hidžaskog pohoda", "179bc78d"], "d": ["Oko dvije hiljade albanskih pješaka, koji su iz Sueza krenuli novosagrađenim brodovima, u oktobru 1811. iskrcalo se kod Janbua; mjesto se predalo nakon slabog dvodnevnog otpora. Konjica pod Tosunovom komandom, prateći hadžijski put kopnom, preko Akabe i Wajha stigla je u Janbu tek dvije sedmice kasnije. Janbu je postao prva hidžaska baza egipatske vojske koja će krenuti na Medinu i Meku.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Prvi poraz u klancu Safra–Džedida", "99ef804d"], "d": ["Egipatska prethodnica, uhvaćena u zasjedu u uskim planinskim klancima, raspršena je. Poraz je bio taktička pouka pohoda: shvaćeno je da se po Hidžazu ne može napredovati bez podrške beduinskih plemena.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Povraćena Medina", "6f6a5d55"], "d": ["Nakon duge opsade Medina se predala. Povratak Poslanikovog grada proslavljen je u Istanbulu topovskim plotunima; Mehmedu Aliju kao nagrada dato je i namjesništvo Džide.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Povraćena Meka — otvoren hadžijski put", "3d6d66a0"], "d": ["Egipatske snage koje su ušle u Meku ponovo su u Kabi dale učiti hutbu u ime osmanskog sultana. Hadžijske karavane, deset godina prekinute, mogle su ponovo na put. Na karti se Hidžaz vraća pod osmansku vlast, ali se prikazuje u vazalnom tonu jer je uprava u Kairu. Drugo mjesto koje istog datuma prelazi pod vazalnu upravu: Džida.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Povratak Taifa — dovršen hidžaski pohod", "6315fb31"], "d": ["Nakon Medine (decembar 1812) i Meke (januar 1813) egipatska vojska pod komandom Tosun-paše na kraju je od vehabija povratila i Taif. Desetogodišnja saudijska vlast okončana je, a sva tri sveta središta Hidžaza ponovo su došla pod osmansko-egipatski nadzor.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali lično prešao u Hidžaz", "fda0ea2d"], "d": ["Vidjevši da pohod teče sporo, valija je preuzeo upravu u svoje ruke; pogađajući se s plemenskim poglavicama, pokušao je iznutra razbiti saudijski front. S tim pohodom porastao je i udio Egipta u crvenomorskoj trgovini.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Bitka kod Bisela: poražene saudijske snage", "9c9ab91f"], "d": ["Saudi, teško poraženi u bici na otvorenom polju, povukli su se u unutrašnjost. Sklopljeno primirje nije bilo trajno; dvije godine kasnije operacije će se prenijeti u srce Nedžda. Atlas nakon te pobjede Turabu i Khurmu istočno od Taifa smatra oduzetima iz saudijskih ruku (izvor za događaj Lorimer, Gazetteer; svjedočanstvo za pojedina naselja i datum 13. januara deklarirana su približnost).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim-paša krenuo na nedždski pohod", "d5ed80d1"], "d": ["Ibrahim-paša, koji je preuzeo komandu nakon smrti brata Tosuna, upustio se u težak dvogodišnji marš kroz pustinju. Napredujući od bunara do bunara, vojska je jedno po jedno eliminirala plemena i došla pred saudijsku prijestolnicu.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Pala Dirija — kraj prve saudijske države", "aa96206d"], "d": ["Nakon šestomjesečne opsade Dirija se predala i bila razorena. Emir Abdullah bin Saud poslan je u Istanbul i pogubljen. Osmanska zastava prvi je put stigla tako duboko u unutrašnjost Arabije; nedždski garnizon ostao je do 1824. Ostala mjesta pripojena istog datuma: Dirija (Nedžd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Počeo sudanski pohod", "b1fc6905"], "d": ["Cilj Mehmeda Alija bio je trostruk: prikupiti vojnike za vojsku, domoći se zlata Sennara i uništiti odbjegle ostatke Memluka. Snage pod komandom njegovog sina Ismail-paše spustile su se na jug prateći Nil.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola bez nasilja prešla egipatskoj vojsci (Memluci su je napustili u junu 1820)", "bc5942c0"], "d": ["Dongola na velikom zavoju Nila, nakon što su je Memluci napustili u junu 1820, bez nasilja je prešla u ruke egipatske vojske Ismail-paše. Na karti se Sudan od tog datuma pojavljuje u vazalnom sloju: osvajač je Kairo, a Kairo će i upravljati.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Bitka kod Džebel ed-Dajke — šajkijska konfederacija odlučno poražena od egipatske vojske", "befc9539"], "d": ["Vojska Ismail-paše, sina Muhammeda Ali-paše, mjesec dana nakon prvog sukoba kod Kurtija porazila je Šajkije u drugoj i odlučnoj bici blizu Džebel ed-Dajke. Šajkijski poglavica Makk Subajr predao se; Makk Šaviš nastavio je otpor. Nakon toga egipatska vlast na nilskom zavoju postala je trajna.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Predao se Sultanat Sennar (Fundž)", "3cac7dd2"], "d": ["Tri stoljeća stara dinastija Fundž predala se bez borbe. Vojni logor osnovan iste godine na spoju dva kraka Nila ubrzo se pretvorio u Kartum, upravno središte Sudana. Ostala mjesta pripojena istog datuma: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Zauzet Kordofan", "06440602"], "d": ["Druga kolona poslana na zapad porazila je darfurske snage kod Bare i zauzela Kordofan s okolicom Nuhuda. Egipatska vlast u Sudanu tako se proširila iz doline Nila na zapadne stepe.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Egipatske snage iskrcale se na Kretu", "835aee90"], "d": ["Kad se grčki ustanak proširio na Kretu, Porta je zatražila da se na otok pošalju egipatske snage. Utjecaj Mehmeda Alija na otoku počeo je tom intervencijom i osam godina kasnije doveo do toga da mu se povjeri namjesništvo Krete.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Ubistvo Ismail-paše u Šendiju", "223860c9"], "d": ["Lokalni emir Nimr, ogorčen teškim zahtjevima za porezima i vojnicima, zapalio je kuću u kojoj je Ismail-paša odsjeo i spalio njega i njegovu pratnju. Kaznena ekspedicija pretvorila je kraj u krvoproliće; uprava Sudana otad je počivala na strogosti.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II zatražio pomoć Mehmeda Alija za Moreju", "03594a42"], "d": ["Za ustanak u Moreji, koji se tri godine nije mogao ugušiti janjičarskom vojskom, sultan se obratio egipatskoj vojsci obučenoj po evropskom uzoru. Zauzvrat su obećani namjesništvo Moreje i Kreta. Taj je zahtjev bio prvo otvoreno priznanje da je carstvo postalo ovisno o vlastitom vilajetu.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim-paša iskrcao se kod Modona", "9c993dba"], "d": ["Desantne snage, pod zaštitom egipatske flote, stupile su na jugozapadni kraj Moreje. Ta vojska, opremljena regularnim pješaštvom i poljskom artiljerijom, ubrzo je stekla prednost nad ustaničkim četama.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Povraćena Tripolica — palo središte Moreje", "8a478c11"], "d": ["Padom Tripolice, upravnog središta ustanka, veći dio Moreje ponovo je stavljen pod nadzor. Na karti se poluotok pojavljuje u vazalnom tonu jer je u rukama egipatskih snaga.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Pao Misolongi", "07257f87"], "d": ["Nakon jednogodišnje opsade grad je zauzet. Međutim, odjek koji je odbrana izazvala u evropskoj štampi doveo je simpatije za grčku stvar do vrhunca i pripremio teren za intervenciju velikih sila.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Predata atinska Akropola", "3b19f946"], "d": ["Padom Akropole grčki ustanak vojno je bio gotovo okončan. Upravo u tom trenutku pitanje je prestalo biti unutrašnja pobuna i postalo predmet evropske diplomatije.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Londonski ugovor: tri države nametnule grčku autonomiju", "7ce46fd8"], "d": ["Engleska, Francuska i Rusija odlučile su zajednički djelovati kako bi Osmanlijama i Grcima nametnule primirje i uvjet autonomije; objavljeno je da će, bude li to odbijeno, intervenirati njihove flote. Porta je prijedlog odbila.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Aleksandrijska konvencija: odluka Egipta o povlačenju iz Moreje", "cc978f37"], "d": ["Mehmed Ali, koji je kod Navarina izgubio flotu, ne savjetujući se s Istanbulom izravno se sporazumio s engleskim admiralom i pristao povući snage iz Moreje. To što je jedan valija sklopio samostalan ugovor s velikim silama bilo je nagovještaj buduće krize.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Egipatske snage napustile Moreju", "8fb742dd"], "d": ["Posljednje jedinice ukrcane su na brodove; poluotok je faktički izgubljen i Londonskim protokolom iz 1830. postao jezgro nezavisne Grčke. Mehmed Ali nije dobio obećano namjesništvo Moreje, a zauzvrat je izgubio veliku flotu i vojsku. Ostala naselja izgubljena istog datuma: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Uprava Krete prepuštena Mehmedu Aliju", "7f76396d"], "d": ["Kao nadoknada za gubitak Moreje Mehmedu Aliju dato je namjesništvo Krete. Otokom se deset godina upravljalo iz Kaira; na karti se tokom tog razdoblja vidi u vazalnom tonu. Ostala mjesta pripojena istog datuma: Kandija (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim-paša ušao u Siriju — počela prva kriza", "1a5cc386"], "d": ["Povod je bio valija Akke koji nije vraćao felahe odbjegle iz Egipta; stvarni razlog bila je potreba Mehmeda Alija za sirijskom građom, lukama i ljudstvom. Vojska je prešla Sinaj i brzo zauzela palestinsku obalu.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Počela opsada Akke", "b211d96d"], "d": ["Tvrđava koja je 1799. zaustavila Napoleona odolijevala je šest mjeseci. Opsada je bila prvi veliki ispit moderne artiljerije egipatske vojske.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Pala Akka", "0f47917b"], "d": ["Kad su baterije koje su tukle bedeme otvorile proboj, tvrđava je zauzeta. Vrata Sirije bila su otvorena; Porta je tih dana proglasila Mehmeda Alija buntovnikom i ukinula mu namjesništvo.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Predao se Damask", "48da3b62"], "d": ["Grad se predao bez borbe. Ibrahim-paša nastojao je steći lokalnu podršku proglašavajući poreski poredak i jednakost priznatu nemuslimanima; iste te politike nekoliko godina kasnije bit će i uzrok pobuna protiv njega. Ostala mjesta pripojena istih dana: Bejrut, Tripoli (Libanon), Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Bitka kod Homsa", "867810ee"], "d": ["Osmanska vojska poslana da spasi Siriju poražena je na otvorenom terenu. Pokazalo se da nova vojska, osnovana šest godina nakon ukidanja janjičara, još nije spremna.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Zauzet Alep", "9c0ead76"], "d": ["Palo je i trgovačko i upravno središte sjeverne Sirije. Tako je egipatska vojska došla do podnožja Taurusa i uputila se ka prijevojima na vratima Anadolije.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Poraz na prijevoju Belen (Beylan) — otvorena Čukurova", "4bae872b"], "d": ["U uskom prijevoju planina Amanos probijena je odbrambena linija. Antiohija, Adana i Tarsus prešli su egipatskim snagama (okupacija Maraša prema TDV-u je 1833, zasebna stavka); na karti Čukurova prelazi u vazalni ton. Put u unutrašnjost Anadolije bio je od tada nebranjen.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Pao klanac Gülek (Kilikijska vrata) — obala İçela (Mersin, Silifke) pod egipatskim nadzorom", "d9049b5b"], "d": ["Klanac Gülek, vrata Taurusa prema Čukurovi, prešao je u ruke egipatske vojske. Ibrahim-paša postavio je svog mutesellima u sandžak İçel i sva pristaništa na obali došla su pod egipatski nadzor. Na karti se Mersin i Silifke od tog dana (donja granica; dan postavljenja nema u izvoru) prikazuju vezani za Egipat; budući da je u kütahyjskoj odluci prešao samo adanski muhasillik, taj nadzor prestaje evakuacijom Anadolije.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konjski Ereğli pod egipatskom okupacijom — taurusko ušće puta Konya–Adana", "fb908900"], "d": ["Ereğli, na putu prema Konyi egipatske vojske koja je prešla klanac Gülek, 1832. došao je pod okupaciju Ibrahim-paše, a kad je kütahyjskim uređenjem 1833. evakuiran, ponovo je vezan za Karamanski vilajet. Na karti je to međutačka okupacijske linije između Adane i Konye potkrijepljena izvorom; za Ulukışlu i Karapınar nije pronađeno svjedočanstvo na razini grada.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Egipatska vojska ušla u Konyu", "13952a2d"], "d": ["Vojska koja je prešla Taurus stigla je u srednju Anadoliju. Prvi put snage jednog osmanskog valije napredovale su po središnjim zemljama carstva. Ostala mjesta pripojena istog datuma: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Bitka kod Konye: veliki vezir zarobljen", "ec82cc9a"], "d": ["Osmanska vojska, razbijena u maglovitom vremenu, pretrpjela je težak poraz, a veliki vezir Rešid Mehmed-paša zarobljen je. Država više nije imala središnju vojsku; između Istanbula i egipatskih snaga nije ostala nikakva sila koja bi stala.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraš pod egipatskom okupacijom", "f558e383"], "d": ["Prema TDV-u, Maraš je 1833. okupirao Ibrahim-paša Kavalali i ostao je pod njegovom upravom gotovo devetnaest mjeseci. Budući da je Maraš ostao izvan ejaletskih granica kütahyjskog uređenja, ta uprava nije pravna, nego faktička.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisar-i Sahib (Afyon) pod egipatskom okupacijom — put Konya–Kütahya", "ae0c2c78"], "d": ["Karahisar-i Sahib, na putu egipatske vojske koja je nakon bitke kod Konye napredovala prema Kütahyi, 1833. neko je vrijeme ostao u rukama Ibrahim-paše. Na karti je to međutačka okupacijske linije između Konye i Kütahye potkrijepljena izvorom; za Akşehir, Ilgın i İshaklı nije pronađeno svjedočanstvo na razini grada, pa su u osmanskoj boji.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Egipatska vojska stigla do Kütahye", "214f8df6"], "d": ["Ibrahim-paša zaustavio se u Kütahyi, na tri konaka od Istanbula. To što nije išao dalje nije bilo vojno, nego političko pitanje: uzete su u obzir ruska intervencija i reakcija Evrope.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Ruska flota pred Büyükdereom", "6f836d61"], "d": ["Mahmud II, koji nije mogao dobiti pomoć od Engleske i Francuske, obratio se jučerašnjem neprijatelju Rusiji. Ta odluka, koja se pamti po sultanovim riječima \"ko pada u more, hvata se i za zmiju\", dovela je do iskrcavanja ruskih vojnika na moreuze i podigla uzbunu u Evropi.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Kütahyjski sporazum (usmeni) — Sirija i Adana Kavaliji", "25fe9985"], "d": ["Porta je Mehmedu Aliju, uz Egipat, Kretu i Hidžaz, prepustila namjesništva Damaska, Alepa, Tripolija (Libanon) i Sidona, a Ibrahim-paši adanski muhasillik. Zauzvrat se vojska povukla južno od Taurusa. To nije bio ugovor, nego su to bili fermani koje je sultan dao jednom valiji — pitanje nije riješeno, nego odgođeno.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Povlačenje egipatske vojske iz Anadolije dovršeno kroz Gülek", "a53ac2a3"], "d": ["Nakon kütahyjskog uređenja egipatske snage napustile su Anadoliju; do sredine juna cijela vojska prešla je kroz klanac Gülek u Čukurovu. Obala İçela (Mersin, Silifke) vraća se pod osmansku upravu; adanski muhasillik i Sirija ostaju Egiptu.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Ugovor iz Hünkâr İskelesija", "da741d5c"], "d": ["S Rusijom je potpisan osmogodišnji savez o uzajamnoj odbrani. Prema tajnoj odredbi, ako Rusija bude napadnuta, Osmanlije će zatvoriti moreuze za ratne brodove. To je bila jedna od najspornijih odluka osmanske diplomatije i učinila je Englesku aktivnom u egipatskom pitanju.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Palestinsko-nablusiski ustanak protiv egipatske uprave", "4fe43e27"], "d": ["Obavezna vojna služba, prikupljanje oružja i novi porezi izazvali su u Palestini širok ustanak. Ustanak je surovo ugušen; podrška egipatskoj upravi među lokalnim stanovništvom brzo je kopnjela.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Kraj egipatske uprave u Marašu (približno)", "bb46ca42"], "d": ["Računajući TDV-ovu rečenicu o trajanju od 'gotovo devetnaest mjeseci' od okupacije 1833, egipatska uprava završava oko ljeta 1834. I to što se Mustafa-beg iz roda Küçükalioglu 1834, ne mogavši se oduprijeti egipatskoj vojsci, povukao prema Marašu pokazuje da je Maraš tada bio utočište izvan egipatskog nadzora.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Ustanak u Džebel Druzu", "12e74626"], "d": ["Otpor izbio u druzijskom području trajao je dvije godine. Nezadovoljstvo nagomilano u Siriji 1840, kad su savezničke flote došle pred obalu, ostavit će egipatsku vojsku bez zaleđa.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali objavio namjeru nezavisnosti", "48633bbd"], "d": ["Valija je konzulima velikih sila saopćio da razmišlja o proglašenju nezavisnosti Egipta i Sirije. Engleska se tome odlučno usprotivila: nastanak snažne i Francuskoj bliske države na Sredozemlju ugrozio bi put za Indiju.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Osmanska vojska prešla Eufrat", "9af1ea69"], "d": ["Mahmud II poslao je vojsku na sirijsku granicu da povrati ono što je izgubio u Kütahyi. Pruski oficir Moltke, koji je bio savjetnik u vojsci, usprotivio se izboru položaja i prijevremenom napadu; njegovi prigovori nisu uvaženi.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Bitka kod Nizipa — osmanska vojska raspršena", "156b3cdf"], "d": ["Loše raspoređena osmanska vojska za nekoliko sati pretrpjela je poraz. Sultan je umro prije nego što je vijest o porazu stigla u Istanbul; država će za nekoliko dana izgubiti vojsku, vladara, a zatim i flotu.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Smrt Mahmuda II", "07eccfff"], "d": ["Sultan, koji je tokom trideset jedne godine vladavine ukinuo janjičarstvo i ponovo uspostavio centralnu upravu, umro je a da nije savladao svog najvećeg protivnika. Njegovoj bolesti nije postavljena tačna dijagnoza. Smrt je, zbog straha da će se pokrenuti janjičarski mentalitet, tajena do 30. juna, dok se u gradu nisu poduzele vojne mjere.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Stupanje Abdulmedžida na prijestolje i sahrana Mahmuda II", "d0f3d2cc"], "d": ["Nakon očeve smrti na prijestolje je stupio šesnaestogodišnji Abdulmedžid. Istog dana tijelo Mahmuda II dopremljeno je u Topkapi saraj; strahovani nemiri nisu izbili, a široke mase muslimana i nemuslimana pridružile su se pogrebnoj povorci.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Predaja flote Aleksandriji", "a53e6103"], "d": ["Kapudan-paša Ahmed Fevzi-paša, sumnjajući da će veliki vezir Koča Husrev-paša flotu predati Rusiji, odveo ju je u Aleksandriju i predao Mehmedu Aliju. Osmanska država je u istom mjesecu ostala bez vojske, bez sultana i bez flote.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Zajednička nota velikih sila", "2a3b8316"], "d": ["Pet sila predalo je Porti notu tražeći da u egipatskom pitanju ne sklapa sporazum sama. Unutrašnje pitanje tako je službeno postalo \"evropsko pitanje\"; osmanska država faktički je izgubila ovlast da odlučuje o vlastitom vilajetu.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Londonski ugovor: četiri države na strani Osmanlija", "a517f775"], "d": ["Ugovor potpisan bez Francuske uputio je Mehmedu Aliju ultimatum: pristane li u roku od deset dana, nasljedno namjesništvo Egipta i doživotno Akku; pristane li u roku od dvadeset dana, samo Egipat; odbije li, ništa. Valija je odbio.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardiranje Bejruta i saveznički desant", "0905ce92"], "d": ["Englesko-austrijska flota bombardirala je Bejrut; narodu koji se u libanskim planinama digao protiv egipatske uprave dijeljeno je oružje. Ibrahim-pašina kontrola nad Sirijom srušila se između unutrašnje pobune i vanjske intervencije.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Izgubljeni Bejrut i obalni gradovi", "09bdaf23"], "d": ["Nakon sukoba u pravcu Baalbeka egipatske snage povukle su se s obale. Na karti libanska obala izlazi iz vazalnog tona i vraća se pod izravnu osmansku upravu.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka pala za dva sata", "5aec21f0"], "d": ["U bombardiranju savezničke flote eksplodirala je barutana tvrđave i Akka se predala za nekoliko sati. Tvrđava koju je osam godina ranije Ibrahim-paša mogao zauzeti tek za šest mjeseci pokazala je nadmoć pomorske artiljerije.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Aleksandrijska konvencija", "85cb47b0"], "d": ["Mehmed Ali pristao je odreći se Sirije, Adane, Krete i Hidžaza, vratiti osmansku flotu i priznati sultanovu vlast; zauzvrat je osigurano nasljedno namjesništvo Egipta.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Egipatska vojska napustila Siriju i Čukurovu", "719a28dc"], "d": ["Devetogodišnja okupacija okončana je; Ibrahim-pašina vojska preko Sinaja vratila se u Egipat. Na karti široki pojas od Alepa do Gaze i od Adane do Krete ponovo prelazi pod izravnu osmansku upravu. Ostala naselja izgubljena istog datuma: Urfa, Maraš, Tarsus, Antiohija, Kandija (Kreta), Hama, Damask, Jerusalem, Jafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ferman: egipatsko namjesništvo nasljedno prepušteno porodici Kavalali", "87b89ff8"], "d": ["Sultanov ferman priznao je namjesništvo koje će unutar dinastije prelaziti s oca na sina; zauzvrat je brojno stanje vojske smanjeno na osamnaest hiljada, porez vezan za Istanbul, a ovlast kovanja novca i sklapanja ugovora ukinuta. Egipat je ostao vilajet, ali je sada bio zemlja zasebne dinastije. Uprava Hidžaza i Haremejna vratila se Porti. Ostala naselja koja istog datuma iz vazalnog sloja prelaze u izravni: Meka, Medina, Džida, Janbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Londonska konvencija o moreuzima", "0e95a1ea"], "d": ["Konvencija koja je zamijenila Hünkâr İskelesi propisala je da su u mirnodopsko vrijeme moreuzi zatvoreni za sve ratne brodove. Povlastica koju je Rusija sama stekla tako se pretvorila u zajedničko evropsko jamstvo; pitanje moreuza dobilo je međunarodni status.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim-paša faktički postao valija Egipta", "9e14f5d9"], "d": ["Umjesto ostarjelog Mehmeda Alija, koji je izgubio umne sposobnosti, na namjesništvo je doveden njegov sin Ibrahim-paša. Međutim, nekoliko mjeseci kasnije, u novembru 1848, umro je prije oca.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Smrt Mehmed Ali-paše Kavalalija", "871310e0"], "d": ["Valija koji se rodio u Kavali, osnovao dinastiju u Egiptu i dvaput doveo carstvo na rub provalije umro je u osamdesetoj godini. Dinastija koju je osnovao vladala je Egiptom do 1953; država je pak, vidjevši da je ranu koju je otvorio mogla zatvoriti evropskom intervencijom, krenula putem Tanzimata.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Sulejman b. Kutalmiš poražen i poginuo kod Ajn Sejlema; Antiohija izašla iz ruku anadolskih Seldžuka", "0412dfa1"], "d": ["Sulejman b. Kutalmiš, koji je 1084. oduzeo Antiohiju Bizantu, poginuo je u bitki kod Ajn Sejlema protiv sirijskog seldžučkog vladara Tutuša; grad je prešao pod nadzor velikog seldžučkog sultana Melikšaha i za valiju je postavljen Jagisijan.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikšah umro; Antiohija s Jagisijanom vezana za sirijskog Seldžuka Tutuša", "c61da1b4"], "d": ["Nakon smrti velikog seldžučkog sultana Melikšaha država se podijelila među nasljednicima; antiohijski valija Jagisijan priklonio se vladaru Sirije Tutušu.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikeja (Iznik) predala se križarima; seldžučko središte povuklo se u Konyu, Bizant počeo vraćati zapadnu Anadoliju", "8a4e90fa"], "d": ["Nakon opsade Nikeje od križara grad se 19. juna 1097. predao Bizantu; seldžučki sultan Kilič Arslan I povukao je svoje središte u unutrašnjost, u Konyu, a Bizant je vratio mjesta na zapadnoj anadolskoj obali, kao što je Efez.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kilič Arslan II oduzeo Bizantu Dorileju (Eskišehir) i Kütahyu", "3ddee6c2"], "d": ["Nakon Miriokefalona (1176) bizantske tvrđave Dorileja i Kütahya u unutrašnjosti Anadolije prešle su 576/1180, u posljednjim godinama Manuela / nakon njegove smrti, u ruke Kiliča Arslana II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoglu Mehmed-beg postavljen za subašu Ermeneka, preuzeo upravu nad Ič-Ilom", "6d62be11"], "d": ["Karamanoglu Mehmed-beg 675. (1276) postavljen je za subašu Ermeneka i stavio pod svoju upravu Ič-Il; Ermenek je postao prvo središte Karamanogulla, koji će iduće godine krenuti na Konyu.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Smrt Ertugrul-gazije i preuzimanje bejluka od Osman-bega — naslijeđe Söğüta i Domaniça", "395fb9fa"], "d": ["Prema TDV-u, Ertugrul-gazi umro je 680. (1281-82); natuknica bilježi da se navode i godine 1288. i 1289. Osman-beg od oca nije naslijedio osvojeni grad, nego dvije dodjele koje je seldžučki sultan dao Ertugrulu kad ga je smjestio na najisturenijoj liniji pograničnog područja: zimovalište (jurtluk, kışlak) u Söğütu i ljetnu ispašu (jajlak) u Domaniçu. Dakle, bejluk nije počeo s osvajačkim naslijeđem, nego s dvije dodjele pašnjaka; na karti su ta dva mjesta prikazana kao 'naslijeđe', a ne 'osvajanje'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Sicilijanske večernje — Anžuvinska dinastija izgubila Siciliju", "547db635"], "d": ["Ustanak koji je u Palermu, u vrijeme večernje molitve na Uskrsni ponedjeljak, izbio protiv uprave Karla I Anžuvinskog otrgnuo je otok Siciliju od anžuvinske dinastije. Sicilijansko kraljevstvo podijelilo se na dva dijela: otok se okrenuo Aragonu, a anžuvinska dinastija održala se u kopnenom kraljevstvu sa središtem u Napulju. Vanjski posjedi dinastije na Jadranu i Sredozemlju također su ostali vezani za to kraljevstvo: Krf, koji su držali od 1267, i Drač, koji su držali od 1270-ih, ostali su dio Napuljskog kraljevstva; i tvrđave Vlora, Kanina i Himara na albanskoj obali ostale su u kraljevstvu sa središtem u Napulju (zapovjednik Vlore John of Taxis odolijevao je Bizantincima tokom cijele 1282; Drač, Vlora i Kanina najvjerovatnije su početkom 1285. prešli Bizantu). Malta je pak tek 1284. pala u ruke Aragonaca.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Prepad na Kulacahisar — prva vojna operacija Osman-bega", "79b00b14"], "d": ["TDV-ova natuknica Osman I: 'Opljačkao je i zapalio mali Kulaca Hisar blizu İnegöla (684/1285).' To je prvi vojni pothvat Osman-bega koji se prema izvorima može datirati. Nije zauzeto nikakvo trajno naselje; tvrđava je opljačkana i spaljena; stoga je to više klasičan pogranični upad nego osvajanje. Smatra se početnom tačkom vojne djelatnosti bejluka.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Osvajanje Karacahisara — prvo stjecanje grada i vlast nad Eskišehirom", "178ae619"], "d": ["TDV-ova natuknica Osman I: Osman-beg je 687. (1288) 'osvojio Karacahisar i postao gospodar Eskišehira'. To je prvo stvarno stjecanje grada bejluka i, prema predaji, tim je uspjehom Osman-beg na granici uzdignut u položaj sandžakbega; prenosi se da je prva džuma-hutba u njegovo ime proučena u Karacahisaru i da je ovdje postavljen prvi kadija. TDV-ova natuknica Eskişehir navodi da osmanska tradicija daje godinu 1291, ali da je njena tačnost sumnjiva.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Pad Akke Memlucima — uklanjanje krstaša sa sirijske obale: Sidon i Bejrut", "3ca7a464"], "d": ["Akku, koja je dugo bila središte krstaškog Jerusalemskog kraljevstva, osvojio je memlučki sultan al-Malik al-Ašraf Halil i krstaška vlast u Palestini prestala je. Templari koji su se povukli iz Akke sklonili su se u Sidon; kad se približila memlučka vojska, napustili su morsku tvrđavu i pobjegli na Kipar, a grad je istog ljeta prešao Memlucima. I Bejrut, od 1197. u rukama krstaša, 1291. zauzeo je damaski valija Sandžar eš-Šudžai. Tako je dva stoljeća dugo krstaško prisustvo izbrisano sa sirijsko-palestinske obale.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Osvajanje Bileciqa i Yarhisara noćnim prepadom", "f461b0af"], "d": ["TDV-ova natuknica Bilecik: 'Iako su ostali tekfuri tog kraja, među kojima i bilecički tekfur, pripremili atentat na Osman-gaziju, kad se za tu zavjeru saznalo, osmanske snage iznenadnim su prepadom osvojile Yarhisar i Bilecik (1299).' Dvije su tvrđave zauzete u jednoj operaciji, u istom noćnom prepadu. Taj je datum prekretnica koja se smatra godinom osnivanja Osmanske države. Ostala mjesta pripojena istog datuma: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Bitka kod Koyunhisara (Bafeja) — prva velika pobjeda nad bizantskom vojskom", "584a9512"], "d": ["TDV-ova natuknica Osman I: Osman-beg je 27. jula 1302. kod Bafeja (Koyunhisar) ratovao s bizantskom vojskom i porazio je. Ta je pobjeda prekretnica koja je Osman-bega od regionalnog pograničnog bega uzdigla u status osnivača dinastije. Nakon bitke brusanska ravnica došla je pod osmanski nadzor i počela je blokada Iznika.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Pobjeda kod Dimbosa i potom zauzimanje Kitea i Ulubata", "e168ab64"], "d": ["TDV-ova natuknica Osman I: 702. (1303) savez koji su sklopili tekfuri Burse, Kestela, Kitea i Adranosa poražen je u klancu Dimbos; neprijatelj je, boreći se, povučen do uskog klanca, a kestelski tekfur poginuo je na bojištu. Odmah nakon pobjede zauzimanjem tvrđava Kite i Ulubat presječena je kopnena veza Burse i pooštrena njena blokada. U toj je bici učestvovao i mladi Orhan.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Sakarijski pohod: zauzimanje Leblebicihisara, Lefkea, Mekecea i Geyvea", "a51ba4d3"], "d": ["TDV-ova natuknica Osman I daje redoslijed sakarijskog pohoda 704. (1304): 'Kad je stigao do Leblebüdži Hisara, tekfur se pokorio... Stigao je u Lefke... Došao do Mekecea... Otišao u Geyve i zauzeo tvrđavu koju je zatekao praznu.' Lefke su vrata doline Sakarje prema Bilecicu. Taj jedan pohod, stavivši pod osmanski nadzor lanac tvrđava duž doline, zatvorio je istočno krilo izničkog bazena.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Hios prešao pod nadzor đenoveške porodice Zaccaria", "9eebe4de"], "d": ["Pred prijetnjom Ajdinogulla bizantski car zatražio je pomoć od Đenovljanina Benedetta Zaccarije; otok je prešao pod njegov nadzor (nominalno bizantsko vazalstvo). Vlast Zaccaria trajala je do 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos ušao u posjed Đenovljana (Zaccaria) s Hiosa", "0e6f51e3"], "d": ["Đenoveška porodica Zaccaria, koja je preuzela nadzor nad Hiosom, pripojila je svom posjedu i gotovo opustjeli Samos (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Osvajanje tvrđava Geyvejskog klanca: Karaçepüş, Karatigin i Absu", "76907c78"], "d": ["TDV-ova natuknica Orhan: Orhan je u sakarijskom pohodu 705. (1305) 'osvojio tvrđave Karaçepüş (Katoikia), Karatigin pred Iznikom i Absu (Hypsu: u Geyvejskom klancu)'. Te tri tvrđave, zatvorivši prolaz između doline Sakarje i izničkog bazena, potpuno su presjekle kopnenu pomoć Izniku. U Karaçepüş i Absu u Geyvejskom klancu postavljen je Gazi Abdurrahman; grad se sada mogao oboriti samo glađu.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Pohod na Adranos (Orhaneli) — posljednji pohod Osman-bega", "4811546c"], "d": ["TDV-ova natuknica Orhan bilježi pohod na tvrđavu Adranos u jesen 1323. kao posljednji pohod Osman-bega. Adranoski tekfur bio je član saveza tekfura sklopljenog protiv Osmanlija dvadeset godina ranije kod Dimbosa; ovaj je pohod značio zatvaranje tog računa. Tačan dan konačnog osvajanja tvrđave nije poznat; operaciju je nastavio Orhan-beg.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Smrt Osman-gazije i preuzimanje bejluka od Orhan-bega", "021487cd"], "d": ["Osman-gazi, po kojem bejluk nosi ime, prema svjedočanstvu vakufnama Asporče-hatun i Mekecea umro je 724. (1324). Njegov sin Orhan, koji je od 1305. bio na čelu vojske u pohodima, nakon očeve smrti stao je na čelo bejluka bez ikakve borbe za prijestolje. To što je osnivačka generacija predala zastavu bez potresa pokazuje da je dinastija na putu od pograničnog bejluka do države mirno prošla svoj prvi veliki ispit.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Hios oduzet porodici Zaccaria i pripojen Bizantu", "f6741b26"], "d": ["Car Andronik III uklonio je Zaccariu s otoka i pripojio otok Bizantu pod upravom Benedetta III. Otok će 1346. okupirati Đenovljanin Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos se od Zaccaria vratio Bizantu (lanac Hiosa)", "08034974"], "d": ["Propašću gospodstva Zaccaria (pripajanjem Hiosa Bizantu 1329) okončan je i đenoveški posjed na Samosu.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Bitka kod Pelekanona (Maltepe) i zauzimanje cijelog Kocaelija", "389e7bd4"], "d": ["TDV-ova natuknica Orhan: prvog dana bitke Orhan-gazi poslao je trista ljudi da privuče bizantsku vojsku k sebi; drugog dana, silaskom jedinica pod komandom Pazarlua u ravnicu, bitka se rasplamsala, a kad je car ranjen strijelom, u bizantskoj vojsci nastala je panika. Ishod je jasan: 'Orhan je zauzeo cijeli Kocaeli; nakon pobjede Izničanima nije ostala nikakva nada.' Obalni gradići od Herekea do Uskudara došli su pod osmansku vlast, a Gebze je postalo središte kraja. To je bila posljednja bizantska carska vojska koja je došla spasiti Istanbul.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Osnivanje prve osmanske medrese u Izniku", "c85fb625"], "d": ["Orhan-beg je odmah nakon zauzimanja Iznika ovdje za kadiju postavio Čandarli Kara Halila, jednu baziliku pretvorio u džamiju, uz nju dao sagraditi imaret i medresu te tako započeo obnovu grada. Prema TDV-ovoj natuknici Davud el-Kajseri, gradnja medrese dovršena je 1336, a Orhan-gazi za muderrisa je doveo Davuda el-Kajserija uz dnevnicu od 30 akči. Ta je medresa prvi institucionalni korak osmanskog naučnog života; bejluk je tako uz osvajačku snagu dodao i naučnu tradiciju. Pretvaranje jedne osvajanjem zauzete bizantske prijestolnice u središte islamske nauke bio je prvi konkretni znak osmanske pretenzije da postanu sjedilačka država.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizant obavezan na harač — opsada Izmita i ugovor", "0c1ec8d3"], "d": ["TDV-ova natuknica Orhan: Orhan je u ljeto 733. (1333) opsjeo Izmit velikom vojskom i katapultima, a car je pristao na ugovor. U zamjenu za odustajanje od opsade Bizant je prihvatio da Orhanu plaća 12.000 zlatnika (hiperpera) godišnje; 'tako je u očima osmanskog emira Bizant pao na položaj haračke zemlje'. Zauzvrat će Orhan biti carev prijatelj i neće napadati gradove podložne Bizantu. To što je jedan pogranični bejluk obavezao Istočni Rim na porez bilo je objavljivanje koliko se ravnoteža snaga preokrenula.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotraka prešla od Venecijanaca đenoveškoj porodici Gattilusio", "c499ed5f"], "d": ["Venecijance, koji su držali otok od 1204, đenoveška porodica Gattilusio istjerala je s otoka.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksija bejluka Karesi: Balıkesir, Bergama, Biga, Edremit i Erdek", "c7cb0511"], "d": ["TDV-ova natuknica Orhan (İnalcık) aneksiju stavlja u 735. (1334-35): nakon smrti Demirhan-bega karesijske gazije i Hadži Ilbej pozvali su Dursun-bega na prijestolje i zatražili pomoć od Orhana. Orhan je najprije krenuo na Balıkesir; kad je Dursun-beg, koji je otišao na mirovne pregovore, poginuo od strijele ispaljene s tvrđave Bergama, bejluk je u cijelosti pripojen osmanskoj zemlji. U istoj operaciji pokorili su se Kirmasti i Mihaliç, zauzet je Gölyazı, a Ulubat, koji je ranije ostavljen uz aman, konačno je osvojen. Orhan je za sandžak Karesi postavio Sulejman-pašu, a Bigu učinio pograničnim središtem — tako su stečeni pomorski kadrovi za prelazak u Rumeliju. Napomena: TDV-ova natuknica Karesiovići za isti događaj daje 746. (1345); enciklopedija je sama sebi proturječna. Ostala mjesta pripojena istog datuma: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos ušao u posjed hioške Maone", "01628b2f"], "d": ["Kad je Đenovljanin Simone Vignosi zauzeo Hios, a uprava prepuštena kompaniji Maona, i Samos je ušao u posjed hioških Đenovljana (Maone) (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Prve kapitulacije Orhan-gazije Đenovljanima", "e64cb196"], "d": ["Orhan-gazi, koji se tokom venecijansko-đenovljanskog rata sporazumio s Đenovljanima, nakon bitke na Bosforu u februaru 1352. poslao je 1000 strijelaca za odbranu Pere i osigurao 60.000 zlatnika za prevoz vojnika; zauzvrat je Đenovljanima podijelio prve kapitulacije. Potpuni tekst ugovora nije sačuvan do danas. To je prvi službeni sporazum koji su Osmanlije sklopile s jednom evropskom pomorskom silom i trideset pet godina kasnije, 1387, bit će obnovljen.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Zauzimanje Galipolja — trajni mostobran u Rumeliji", "ba51a160"], "d": ["Galipolje, čiju su okolicu upoznali 1349-1352. kao Kantakuzenovi saveznici, Osmanlije su zauzele 1354; priliku je stvorio veliki zemljotres koji je srušio gradske bedeme. Uski mostobran u Çimpeu tako se pretvorio u pravu bazu na rumelijskoj strani moreuza, a vrata prema Trakiji širom su se odškrinula. Galipolje će 1366. biti izgubljeno savojskim krstaškim pohodom, ali će drugim osvajanjem 1376. konačno ući pod osmansku vlast. Ostala mjesta pripojena istog datuma: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Smrt Sulejman-paše, osvajača Rumelije", "2dc98228"], "d": ["Sulejman-paša, stariji sin Orhan-bega i tvorac rumelijskih osvajanja, umro je padom s konja tokom lova u jesen 1357, što je među datumima koje izvori navode kao 758. (1357), 759. i 760. (1359) najprihvaćeniji. Smrt princa koji je svojim prelascima 1352-1354. uspostavio trajno osmansko prisustvo u Rumeliji ostavila je red prijestolonasljedstva njegovom bratu Muratu. Turbe Sulejman-paše, sahranjenog u Bolayıru, ostalo je najstariji osmanski dinastički spomenik u Evropi.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Zakon o pendžiku — polaganje temelja janjičarskog odžaka", "e5877c2d"], "d": ["Nakon rumelijskih osvajanja, na savjet Karamanlije Kara Rustema iz redova uleme, stavljen je na snagu sistem pendžika, koji je predviđao da se petina ratnih zarobljenika ili njena novčana protivvrijednost izdvoji za državu. Odgajanjem odabranih među tim zarobljenicima uz turske porodice i njihovim uzimanjem u vojsku nastalo je jezgro stalne pješadijske snage izravno vezane za sultana — janjičarskog odžaka. Preobrazba pograničnog bejluka koji se oslanjao na plemensku konjicu u državu s centralnom vojskom počela je tim uređenjem.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Silazak u zapadnu Trakiju: osvajanje Komotinija", "9ef69221"], "d": ["Pogranične snage koje su se nakon zauzimanja Edirne uputile zapadno od Marice, pod komandom Gazi Evrenos-bega zauzele su Komotini, središte zapadne Trakije. Grad je postao isturena baza iz koje će Evrenos-begovi upadi biti preneseni u Makedoniju. Tako je dio Trakije koji se proteže do egejske obale došao pod osmanski nadzor i otvoren je put za Solun.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna prešla Dobrudžanskoj kneževini i postala prijestolnica", "2bfe73f9"], "d": ["U procesu raspada Bugarskog carstva Varna na obali Crnog mora pripojena je Dobrudžanskoj kneževini koju je osnovao Dobrotica i postala prijestolnica te male države.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Zapadno od Plovdiva: pripojenje Pazardžika i Ihtimana", "1664d0e1"], "d": ["Nakon zauzimanja Plovdiva 1372. Pazardžik u gornjem toku Marice i Ihtiman, koji drži prijevoj što se otvara prema Sofiji, vezani su za osmansku upravu. Ta linija, u rukama lokalnih velikaša vazaliziranih nakon bitke kod Černomena, prelaskom pod izravnu upravu učinila je pravac Plovdiv–Sofija neprekinutim. Ovo napredovanje priprema je puta koji će dvanaest godina kasnije dovesti do osvajanja Sofije.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Ustanak Savči-bega — zajednička pobuna princa i bizantskog prijestolonasljednika", "75198c33"], "d": ["Savči-beg, sin Murata I, i Andronik Paleolog, sin bizantskog cara Ivana V, početkom maja 1373. istovremeno su se u Bursi i Istanbulu pobunili protiv očeva. Taj savez koji je ujedinio prijestolonasljednike dviju dinastija brzo je ugušen; Savči-beg je uhvaćen, oslijepljen i pogubljen. Godina 787. (1385) koju za pobunu navodi osmanska predaja pogrešna je; događaj pada odmah nakon godina kad je Bizant ušao u osmansko vazalstvo i pokazuje koliko su dva dvora bila isprepletena.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Doline Strume i Meste: pripojenje Ćustendila, Petriča, Nevrokopa i Drame", "8c0980c4"], "d": ["Doline Strume i Meste, u rukama srpskih i bugarskih lokalnih velikaša koji su nakon pobjede kod Černomena počeli plaćati harač Osmanlijama, napredovanjem pograničnih begova stavljene su pod izravnu osmansku upravu. Pripojenjem Ćustendila, Petriča, Nevrokopa i Drame otvorena je istočna polovina Makedonije, a Solun i Serez ušli su u opsadni obruč. Širenje Rumelije prema jugozapadu na karti rezultat je tih operacija.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Kraj bejluka Eretna i osnivanje države Kadi Burhanuddina", "60dcaf57"], "d": ["Eretnaovići, koji su nastali 1335. iz ilkanidskog namjesništva i četrdeset šest godina upravljali srednjom Anadolijom sa središtem u Sivasu i Kayseriju, raspali su se u dvorskim sukobima. Kadi Burhanuddin, koji je u maju 1378. postao vezir, nakon što je uklonio suparnike Kilidžarslana i Hadži Šadgeldija, u jesen 1381. proglasio se sultanom, okončao bejluk i osnovao državu nazvanu po njemu. Tako je istočni susjed Osmanlija promijenio gospodara; pravac Sivas–Kayseri otad će sedamnaest godina ostati u rukama Kadi Burhanuddina.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur zauzeo Herat: kraj dinastije Kert i prelazak Horasana Timuridima", "15f6019e"], "d": ["Horasan je 1380. bio razbijen u borbi Serbedara, Kerta i Muzafferida. Nakon što je sina Miran-šaha poslao u to područje, Timur je sam krenuo na Herat i nakon neke vrijeme trajuće opsade preuzeo grad od kertskog melika Gijasudina Pira Alija. Pobunu koja je izbila nakon njegovog odlaska Miran-šah krvavo je ugušio i okončao dinastiju Kert, koja je od 1255. vladala u Heratu. Cijeli Horasan od Mešheda do Nišapura toga datuma ušao je pod timuridsku upravu.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Napredovanje u unutrašnjost Makedonije: osvajanje Bitole i Ohrida", "63bb7838"], "d": ["Bitola na Via Egnatiji i Ohrid na obali jezera ušli su pod osmansku upravu tokom upada prema Albaniji. Oba su bila ključne tačke puta koji se pruža do Jadrana; Ohrid je k tome bio sjedište jedne od najstarijih pravoslavnih arhiepiskopija na Balkanu. TDV bilježi da za datum osvajanja Ohrida nema pouzdanih podataka i da se predlažu godine 787. (1385) i 797. (1395), nakon smrti Kraljevića Marka; ovdje je uzeta 1385. Bitola će u narednim stoljećima postati jedno od najvažnijih vojnih središta Rumelije.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Bitka na Savri — otvaranje vrata Albanije", "dda6671b"], "d": ["Na poziv za pomoć albanskog velikaša Karla Topije, pritisnutog od dinastije Balšića, osmanske snage na Savrskom polju porazile su vojsku Balše II; Balša je poginuo na bojištu. Taj rat, u koji se ušlo na poziv jednog domaćeg velikaša, donio je Osmanlijama prvi trajni utjecaj u albanskim zemljama koje se protežu do jadranske obale. Ta politika korištenja međusobnih sukoba velikaša tog kraja bit će tokom sljedećeg stoljeća nepromjenjiva metoda balkanskih osvajanja.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Timurov 'trogodišnji pohod': zauzimanje Azerbejdžana i sjevernog Irana", "2a98ec51"], "d": ["Timur, koji je tokom horasanskih pohoda izbliza vidio rascjepkanost Irana, 788. (1386) krenuo je na zapad. U operacijama 1386-1388, poznatim kao 'trogodišnji pohod', preko Mazandarana, Luristana i Gruzije prešao je u Azerbejdžan i stigao u Karabah; Tabriz, Ardebil, Urmija i Nahičevan ušli su pod timuridsku upravu. Zauzimanje sjevernog Irana i Azerbejdžana bilo je, kao nekoć između Džudžijevog ulusa i Ilkanida, i početak dugog nadmetanja sa Zlatnom Hordom.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Bitka kod Frenk Yazısıja i opsada Konye — prvi karamanski pohod", "af4e5d77"], "d": ["Protiv Karamanovića Alaudina Alija-bega, koji je, iako mu je bio zet, bio uznemiren osmanskim širenjem u zapadnoj Anadoliji, Murat I lično je krenuo u pohod; u bici na mjestu zvanom Frenk Yazısı uvježbana i iskusna osmanska vojska porazila je karamanske snage. Zatim je opsjednuta tvrđava Konya, ali je pomilovanjem Alaudin-bega bejluk nije potpuno uklonjen. Taj je pohod uvodni čin dugog obračuna Osmanlija i Karamana koji će trajati jedno stoljeće i završiti tek konačnom aneksijom 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muš prešao od uprave Kara-Kojunlua pod Timurovu upravu (789/1387)", "ed2e7a11"], "d": ["Muš, koji je nakon mongolskog razdoblja prešao pod upravu Kara-Kojunlua, 789. (1387) dospio je pod upravu Timura, koji je ovladao zemljama Kara-Kojunlua. U atlasu je Muš te godine upisan kao prelazak od Kara-Kojunlua Timuridima.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Osnivanje brodogradilišta u Galipolju — rođenje osmanske flote", "47546241"], "d": ["Prvo organizirano brodogradilište Osmanske države osnovao je Bajazid Munja 1390. u Galipolju, na mjestu brodogradilišta naslijeđenog od Bizanta. Osmanlije, preuzevši pomorsko naslijeđe zapadnoanadolskih bejluka, tako su prvi put postale pomorska sila koja sama gradi svoje brodove. Brodogradilište smješteno na ključnoj tački Dardanela vijek i po služilo je kao glavna baza osmanske flote, od opsade Istanbula do egejskih pohoda.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamidska oblast pripojena Osmanlijama: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Zbog napada Karamanovića Alaudin-bega na Hamidsku oblast i žalbi stanovništva Bajazid Munja krenuo je u pohod, zauzeo sve preostale zemlje Hamidovića i upravu povjerio sinu Isi Čelebiju.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Kraj dinastije Muzafferida: poraz šaha Mansura pred Širazom", "5fd14eb8"], "d": ["Šah Mansur, posljednji snažni vladar Muzafferida, koji su od 1318. vladali u Jezdu, Farsu, Isfahanu i Kermanu, ujedinio se s rođacima i krenuo protiv Timura. U bici blizu Širaza, nakon prelaska jednog od njegovih emira na protivničku stranu, izgubio je većinu snaga, poražen je i ubijen. Kad je Timur potom dao ubiti sve članove dinastije, vlast Muzafferida prestala je, a Fars i Kerman pripojeni su timuridskoj upravi.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Pripojenje Amasye osmanskim zemljama", "fe2860cf"], "d": ["Tokom operacija Bajazida Munje u srednjoj Anadoliji opsjednuti emir Amasye predao je grad Osmanlijama i Bajazid je 1393. ušao u grad. Sultan je upravu ovdje povjerio sinu Čelebi Mehmedu; kao prinčevski sandžak Amasya je otad postala jedno od najvažnijih odgojnih ognjišta osmanske dinastije. Ostala naselja izgubljena istog datuma: Ladik (Amasya), Merzifon, Osmancık, Çorum. Ta će odluka biti presudna u kasnijem dobu Fetreta, a Čelebi Mehmed vodit će borbu za ponovno ujedinjenje države upravo s amasijske osnove.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur zauzeo Bagdad — Džalairidi pobjegli u Anadoliju", "4d5602b3"], "d": ["Nakon duge opsade Timur je zauzeo Bagdad; gospodar grada, Džalairid sultan Ahmed, pobjegao je na zapad i sklonio se najprije kod Memluka, a zatim na osmanskom dvoru. Timurovo širenje na zapad tako je prvi put izravno dodirnulo osmansku sferu utjecaja. Odavde počinje prva karika neprijateljstva dvaju vladara.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Zauzimanje Varne na obali Crnog mora", "a84b2abf"], "d": ["Tokom stezanja zemalja Bugarskog carstva između Dunava i Crnog mora, Varna, najveća obalna luka, prešla je pod osmansku upravu. Zauzimanje luke otvorilo je put napredovanju prema Dobrudži i Osmanlijama donijelo prvo veliko pristanište na zapadnoj obali Crnog mora. Varna će pedeset jednu godinu kasnije biti i poprište pobjede 1444. u kojoj će biti uništena krstaška vojska.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Oblast Nevšehira i Ürgüpa prešla od Karamanogulla Osmanlijama", "06ff59e8"], "d": ["U pohodima Bajazida I Munje protiv Karamanogulla oblast Nevšehira (Muškara) i Ürgüpa prešla je 800/1398. pod osmansku upravu; nakon Ankarske bitke 1402. Timur je oblast vratio Karamanogullima.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Pad države Kadi Burhanuddina", "b13391e3"], "d": ["Kadi Burhanuddin, koji je pao u zarobljeništvo ak-kojunluskog vladara Karajuluk Osman-bega, iako je ponudio da bude oslobođen u zamjenu za predaju Sivasa, gradsko je stanovništvo pružilo otpor, a sultan je pogubljen pred bedemima. Iako su ugledni ljudi Sivasa na čelo doveli njegovog sina Alaudina Alija Čelebija, pred pritiskom Ak-Kojunlua zatražili su pomoć od Bajazida Munje; osmanske snage pod komandom Sulejmana Čelebija porazile su Karajuluka i zavladale gradom. Tako je država Kadi Burhanuddina otišla u historiju, a Sivas, Tokat, Niksar i Kayseri pripojeni su osmanskim zemljama. Ostala mjesta pripojena istog datuma: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Timurov izazov: odbijeno izručenje bjegunaca", "33790bc8"], "d": ["Pod Timurovim pritiskom Džalairid sultan Ahmed i vođa Kara-Kojunlua Kara Jusuf sklonili su se na osmanske zemlje; Timur je tražio izručenje te dvojice bjegunaca, a Bajazid Munja odbio je. Na to su dva vladara počela razmjenjivati pisma puna uzajamnih teških uvreda. Ideološka podloga rata uspostavljena je tom prepiskom, prije nego što se pokrenuo i jedan vojnik.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Munjina daruššifa u Bursi — prva osmanska bolnica", "5f0dc59a"], "d": ["U godinama kad je u Bursi podizao veličanstvenu Ulu džamiju, Bajazid Munja je gradu dao i jednu daruššifu; to je bila karika njegovog širokog dobrotvornog programa, koji se sastojao od imareta, medrese, hana i mosta, namijenjena medicini. Ta građevina, prva bolnica koju je osnovala država, djelovala je i kao medicinska škola koja je odgajala ljekare te odredila model osmanskih zdravstvenih ustanova. Djelo, dovršeno samo dvije godine prije katastrofe kod Ankare, jedna je od posljednjih karika Munjine zamisli o pretvaranju Burse u carsku prijestolnicu.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur sravnio Sivas sa zemljom", "f4d79de6"], "d": ["Timur, koji je pod vodstvom Ak-Kojunlua Karajuluk Osman-bega i erzindžanskog emira Mutahhartena krenuo na Sivas, opsjedao je grad osamnaest dana i, preuzevši ga uz obećanje da ničija krv neće biti prolivena, počinio veliki pokolj; branitelje je dao nabacati u rovove i žive zatrpati. Uništene su znamenite građevine grada, na čelu s bedemima, a Sivas je demografski propao. To je prvi veliki udarac koji je Timur zadao osmanskim zemljama dvije godine prije bitke kod Ankare.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bajazid Munja povratio Erzindžan i Kemah", "7047ca08"], "d": ["Koristeći priliku Timurovog odlaska na sirijski pohod, Bajazid Munja oduzeo je Erzindžan i Kemah od erzindžanskog emira Mutahhartena, Timurovog vazala. Iako nije intervenirao protiv razaranja Sivasa, taj je potez značio izravan izazov Timurovoj sferi utjecaja u istočnoj Anadoliji. Odnos dvaju vladara otad je postao nepopravljiv.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Timurov ultimatum iz Tabriza — četiri uvjeta", "3e1ac50e"], "d": ["Poslanikom koji je poslao iz Tabriza Timur je saopćio četiri uvjeta: vraćanje Kemaha Mutahhartenu, vraćanje zemalja oduzetih anadolskim begovima njihovim vlasnicima, slanje jednog osmanskog princa kao taoca te prihvatanje kape i pojasa kao znakova podaništva, i predaju Kara Jusufa. Bajazid nijedan nije prihvatio; unatoč ustrajanju državnika i posredovanju Mutahhartena pregovori su propali. Timur je bio odlučan da prije kineskog pohoda konačno zatvori anadolsko pitanje.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Ponovo uspostavljeni Saruhanovići — Manisa izašla iz osmanskih ruku", "ac747b05"], "d": ["Tri sedmice nakon poraza kod Ankare Orhan-beg je uz Timurovu podršku preuzeo čelo bejluka i oblast Saruhan ponovo je postala nezavisna. Oblast sa središtem u Manisi, dvanaest godina nakon osmanske aneksije 1390, nestala je s karte. To je jedna od prvih primjena Timurove politike oživljavanja bejluka čiji je datum pouzdano poznat.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Sulejman pobjegao u Rumeliju s državnom blagajnom", "0a2b7363"], "d": ["Emir Sulejman, uzevši sa sobom državnu blagajnu u Bursi, arhive, porodicu i braću, brodom je iz Gemlika prešao u Güzelce Hisar (Anadolu Hisar), odatle stigao u Galipolje i u Edirni proglasio svoju vladavinu. Prenošenje državne arhive i blagajne u Rumeliju početak je pomjeranja osmanskog težišta na Balkan za jednu generaciju. Na karti se Rumelija od tog datuma crta vlastitom bojom emira Sulejmana.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur obnovio anadolske bejluke — raspalo se tursko jedinstvo", "15187774"], "d": ["Nakon pobjede kod Ankare Timur je begovima koji su bili uz njega vratio njihove nekadašnje zemlje. Karamanovićima Mehmed-begu i Ali-begu dati su oblast Karaman te Kayseri, Kırşehir, Sivrihisar i Beyşehir; Germijanoviću Jakubu II Kütahya i oblast Germijan; Džandaroviću Isfendijar-begu, uz pravac Kastamonu–Sinop, Çankırı i Kalecik. Oblasti Aydın, Menteše i Teke također su se vratile starim dinastijama. Anadolsko tursko jedinstvo koje je Bajazid Munja za deset godina uspostavio raspalo se u jednom ljetu; na karti se ti bejluci ponovo pojavljuju svojim bojama. Ostala naselja koja su u istom procesu promijenila vlasnika: Aksaray, Denizli, Ereğli (Konya), Ermenek, Ilgın, Karapınar, Kayseri, Konya, Kırşehir, Kütahya, Sivrihisar, Söke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur oduzeo Izmir vitezovima svetog Ivana", "66dd1dd4"], "d": ["Timur, koji se na zapad spustio preko Kütahye, Denizlija, Aydına, Ajasuluka i Tirea, opsjeo je i zauzeo obalni Izmir, koji je od 1344. bio u kršćanskim rukama. Zauzevši za kratko vrijeme tvrđavu koju Bajazid Munja godinama nije mogao zauzeti, nakon osvajanja i okolnih tvrđava prepustio je oblast Aydın starim vlasnicima i vratio se na istok. Grad je potom došao pod upravu Džunejd-bega Ajdinoglua.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Čelebi zauzeo Bursu — nastao anadolski dio", "955128c1"], "d": ["Isa Čelebi, koji se nakon poraza kod Ankare povukao prema Karesiju, zauzeo je Bursu dok je Timur bio u Izmiru. U staroj prijestolnici, koju su Timurovi vojnici opljačkali i spalili, proglasio je svoju vladavinu i dao kovati novac u svoje ime; u januaru 1403. priznavan je u Anadoliji kao 'vladar Turaka'. Na karti se taj dio, koji se proteže duž azijske obale Mramornog mora, vidi u vlastitoj boji Ise Čelebija.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Timurovo povlačenje iz Anadolije", "93a98839"], "d": ["Kad je primio vijest da je Bajazid Munja umro u Akşehiru, Timur je, smatrajući svoj posao u Anadoliji završenim, krenuo na istok. Iza njega su ostali bejluci koji su mu izrazili vjernost i međusobno zavađeni osmanski prinčevi; neki gradovi poput Sivasa ostavljeni su u rukama emira poput Mezid-bega, Timurovog vazala. Timur se više nikada nije vratio u Anadoliju, ali je rascjepkani poredak koji je uspostavio trajao deset godina.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Sulejman prešao u Anadoliju: Bursa pala u njegove ruke", "9b27aa5f"], "d": ["Čuvši za poraz Ise Čelebija, emir Sulejman s Čandarli Ali-pašom i snažnom vojskom prešao je u Anadoliju i zauzeo Bursu; zapisi iz marta 1404. pokazuju da je i Karadeniz Ereğli bio pod njegovom upravom. Čelebi Mehmed nije mogao odoljeti Sulejmanu, koji je ubrzo zavladao i Rumelijom i većim dijelom Anadolije. Ostala naselja koja su u istom procesu od Čelebi Mehmeda prešla emiru Sulejmanu: Akyazı, Anadolu Hisar, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, tvrđava Aydos, Ayvalık, Balıkesir, Behramkale (Assos), Bergama, Beykoz, Biga. Na karti od tog datuma do ponovnog Mehmedovog zauzimanja Burse (1410) obje obale vide se u jednoj boji, u dijelu emira Sulejmana.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Bitka na Jenišehirskoj ravnici — Čelebi Mehmed povukao se u Amasyu", "f1568288"], "d": ["Čelebi Mehmed, koji je izgubio Bursu i Ankaru, poražen je od emira Sulejmana na Jenišehirskoj ravnici, izgubio je sve dobitke u zapadnoj Anadoliji i povukao se u bazu Tokat–Amasya. Nakon tog poraza izbjegavao je izravan sukob i okrenuo se učvršćivanju vlasti u unutrašnjosti Anadolije. Tako je počela najduža mirna faza Fetreta.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Sulejman oduzeo Ankaru Čelebi Mehmedu", "d6a2acd6"], "d": ["Ankaru, koja je nakon Timurovog povlačenja iz Anadolije ostala u rukama Čelebi Mehmeda, 1406. opsjeo je emir Sulejman. Zapovjednik tvrđave Jakub-beg neko se vrijeme održao, ali je zbog varke velikog vezira Čandarli Ali-paše tvrđavu predao Sulejmanu. Na to se Čelebi Mehmed sporazumio s Karamanovićem Mehmed-begom i krenuo protiv Sulejmana.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Čelebi Mehmed povratio Sivas od Timuridovog Mezid-bega", "90079b0c"], "d": ["Nakon Timurove invazije uprava Sivasa prepuštena je Mezid-begu, Timurovom vazalu. Čelebi Mehmed u Amasyi poslao je svog zapovjednika Bajazid-pašu da zauzme grad i nakon žestokog otpora Sivas je po drugi put prešao u ruke osmanske dinastije. Tako je Mehmedov dio, šest godina nakon bitke kod Ankare, na istoku dostigao staru granicu.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Kraj dinastije Artukida: predaja Mardina Kara-Kojunluima", "15b06f33"], "d": ["Artukidi, koji su od 1106. vladali u Mardinu i bili najdugovječniji ogranak dinastije, nisu se mogli održati pred pritiskom Ak-Kojunlua. Melik Ahmed, shvativši da grad ne može braniti, sporazumio se s kara-kojunluskim vladarom Kara Jusufom i predao mu Mardin. Tako je okončana više od tri stoljeća duga artukidska vlast; Mardin i okolica bili su poprište borbe Kara-Kojunlua i Ak-Kojunlua dok stoljeće kasnije nisu prešli Osmanlijama.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Bitka kod Jambola — Musa Čelebi ušao u Edirne", "8f978408"], "d": ["Musa Čelebi, koji je preko Vlaške prešao u Rumeliju, uz vlašku i srpsku podršku porazio je kod Jambola snage emira Sulejmana i ušao u Edirne. U doba Fetreta Rumelija je prvi put izašla iz ruku emira Sulejmana. Ipak, njegova vlast nije bila trajna; četiri mjeseca kasnije, poražen kod Kosmidiona, povući će se u unutrašnjost Balkana.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Bitka kod İnceğiza — prvi rumelijski poraz Čelebi Mehmeda", "3c35cd43"], "d": ["Čelebi Mehmed, koji je bizantskim brodovima prešao u Rumeliju, upustio se u bitku s Musom Čelebijem kod İnceğiza; Musa je sa sedam hiljada janjičara pod svojom komandom porazio Mehmeda i Mehmed se morao vratiti u Anadoliju. Taj je poraz Mehmeda usmjerio, umjesto na izravan rat, na strategiju pridobijanja rumelijskih pograničnih begova i Srpske despotovine. Tom diplomatijom pripremljen je teren za pobjedu kod Čamurlua devet mjeseci kasnije.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Opsada Konye i ugovor s Karamanovićima — povraćeni Hamidska oblast, Saidska oblast, Beyşehir, Seydişehir i Akşehir", "0996257e"], "d": ["Protiv Karamanovića, koji su u doba Fetreta napadali osmanske zemlje i opsjeli i spalili Bursu, Čelebi Mehmed organizirao je veliki pohod i u muharremu 818. opsjeo Konyu. Karamanović Mehmed II-beg bio je prisiljen tražiti mir; ugovorom su Hamidska oblast (kraj Isparte) i Saidska oblast ponovo pripojene osmanskim zemljama, vraćeni su i Beyşehir, Seydişehir i Akşehir; Sivrihisar, koji je Timur 1402. dao Karamanovićima, također se vratio Osmanlijama. Taj pohod, kojim se počelo krpiti anadolsko jedinstvo rasuto bitkom kod Ankare, jedan je od konkretnih razloga što se Čelebi Mehmed smatra 'drugim osnivačem'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Oduzimanje Izmira Džunejd-begu Ajdinogluu", "2377ca51"], "d": ["Izmir, središte Džunejd-bega Ajdinoglua, koji je tokom Fetreta stalno mijenjao stranu među prinčevima, nakon desetodnevne opsade zauzeo je Čelebi Mehmed; Džunejd je pomilovan i poslan za sandžakbega Nikopolja. Grad koji je Timur 1402. vratio Aydınovićima tako se nakon trinaest godina vratio Osmanlijama. Džunejd će 1422. ponovo zauzeti grad, a pitanje će tek 1424-1426. zatvoriti Murat II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Pogubljenje Torlaka Kemala — Saruhan konačno osmanski", "8a09dbf1"], "d": ["Torlak Kemal, koji je vodio zapadnoanadolski krak pokreta šejha Bedreddina, poražen je u manisanskom kraju i pogubljen. Od toga datuma oblast Saruhan konačno je došla pod osmanski nadzor, a bejluk koji je Timur 1402. oživio otišao je u historiju. Tako su uklonjeni posljednji politički ostaci doba Fetreta u zapadnoj Anadoliji.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Osvajanje Vlore, Berata i Kanine", "1e1949b8"], "d": ["Osmanlije su 1417. stavile pod svoju vlast Vloru na jadranskoj obali, zajedno s gradom Beratom u unutrašnjosti i tvrđavom Kaninom. Godinu dana kasnije pokušaj Venecije da povrati grad propao je, a uspostavljanjem sandžačke organizacije ovdje je osmanska vlast postala trajna. Zauzimanje Vlore prvi je put Osmanlije učinilo izravnim vlasnicima jedne luke na Jadranu i dalo im prekomorsku odskočnu dasku prema Italiji.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Povratak srednje Anadolije: Kayseri i Kırşehir", "204eacb3"], "d": ["Gradovi srednje Anadolije koji su u doba Fetreta prešli u ruke Karamanovića tokom pohoda Čelebi Mehmeda za ponovno sabiranje države vratili su se pod osmansku upravu. Pripojenjem Kayserija i Kırşehira uglavnom je povraćen sliv Kizilirmaka izgubljen u bici kod Ankare. To je napredovanje nastavak politike usmjerene na istok koja je počela opsadom Konye četiri godine ranije.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Memluci dali Kayseri Dulkadiroviću Nasirudinu Muhammedu", "aad4b00c"], "d": ["Memlučka vojska koja je krenula u pohod protiv Karamanovića Mehmed-bega okupirala je Kayseri; memlučki zapovjednik prepustio je grad i okolicu Dulkadiroviću Nasirudinu Muhammedu i vratio se u svoju zemlju.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Smrt Mehmeda I i stupanje na prijestolje Murata II", "98acac77"], "d": ["Mehmed I, koji je okončao Doba bezvlašća (Fetret) i ponovo objedinio osmansku zemlju pod jednom rukom, umro je u Edirnama 25. juna 1421, a njegov sin Murat stupio je na prijestolje u Bursi. Prema uređenju s Bizantom prije njegove smrti, njegovi mlađi sinovi trebali su kao taoci biti poslani caru, a car neće pustiti pretendenta na prijestolje Mustafu Čelebija koga je držao; Murat II odbio je poslati braću caru.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Konačna likvidacija Tekeovića: zauzimanje Antalije", "e65565b2"], "d": ["Bejluk Tekeovića, ponovo uspostavljen Timurovim oživljavanjem nakon bitke kod Ankare, prestao je kad su osmanske snage pod komandom Hamza-bega opsjele Antaliju; uklonjen je i posljednji važan čovjek bejluka, Osman Čelebi. Tako je oblast Teke na obali Sredozemlja nakon dvadeset jedne godine odvojenosti konačno pripojena Osmanlijama. Bejluk, kao ogranak odvojen od Hamidovića, vladao je u Antaliji od 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Turahan-begov pohod na Moreju i rušenje zida Heksamiliona", "c6c2706d"], "d": ["Zbog toga što je Bizant podržavao suparničkog pretendenta na prijestolje Mustafu Čelebija, Murat II poslao je Turahan-bega na Moreju. Turahan-beg srušio je zid Heksamilion, koji je s kraja na kraj zatvarao Korintsku prevlaku, ušao na poluotok i izazvao veliko razaranje. Mir je postignut pod uvjetom da se zid više ne gradi i da se plaća godišnji porez; Morejska despotovina tako je vojno ostavljena nebranjena i teren za konačno osvajanje 1460. pripremljen je trideset sedam godina unaprijed.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Manastiri Atosa (Aynaroz) pod osmanskom zaštitom", "562de5ea"], "d": ["U godinama kad je Solun bio pod opsadom, monaška republika Atos na istočnom prstu Halkidikija obratila se Muratu II tražeći zaštitu i priznala osmansku vlast. Zajamčena su vlasnička i vjerska prava monaha; manastirima je uz porez ostavljena sloboda u unutrašnjim poslovima. Taj je poredak postao najdugovječniji primjer zaštitničkog odnosa koji su Osmanlije uspostavile s pravoslavnim ustanovama i trajao je pet stoljeća.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksija bejluka Tadžedinovića: Niksar", "370ffd47"], "d": ["Pod pritiskom amasijskog beglerbega Jörgüč-paše, Husamuddin Hasan-beg Tadžedinoglu 830. (1427) predao je ključeve svoje zemlje sa središtem u Niksaru; njemu je dat jedan sandžak u Rumeliji. Tako je prestao bejluk osnovan u drugoj polovini XIV stoljeća, čije su se granice povremeno protezale do Kelkita, Amasye, Samsuna, Orduua i Giresuna. Iste godine popisane su i zemlje Hadžiemirovića i pripojene sandžaku Džanik; doba bejluka u srednjem crnomorskom pojasu okončano je.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Prepuštanje Beograda Ugarskoj — Tatski ugovor", "62481183"], "d": ["Nakon smrti srpskog despota Stefana Lazarevića, prema Tatskom ugovoru sklopljenom između ugarskog kralja Sigismunda i nasljednika Đurđa Brankovića, Beogradska tvrđava predana je Ugarskoj. Tvrđava na ušću Save u Dunav dotad je bila u rukama Srpske despotovine i za Osmanlije je bila ključ vrata prema Srednjoj Evropi. Taj prijenos stotinu godina učinio je Beograd najtvrđom preprekom osmanskom napredovanju: opsade 1440. i 1456. bit će neuspješne, a tvrđava će pasti tek 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin od kara-kojunluskog čuvara prešao ak-kojunluskom Karajuluk Osman-begu", "d82bc97f"], "d": ["Mardinom, koji je Kara Jusuf zauzeo 1409, Kara-Kojunlui upravljali su putem namjesnika; ostavljeni čuvar emir Nasir 835. (1432) predao je grad ak-kojunluskom Karajuluk Osman-begu. Uprava Ak-Kojunlua trajala je do početka XVI stoljeća.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanovići oduzeli Kayseri Dulkadirovićima", "2b09e8e8"], "d": ["Karamanski beg pobjedom nad Dulkadirovićima pripojio je svojoj zemlji Kayseri, Ürgüp, Develi Karahisar i Uçhisar.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Događaj na Bučuktepeu — prvi janjičarski ustanak i povratak Murata II na prijestolje", "6388dda1"], "d": ["Događaj na Bučuktepeu, koji je izbio u Edirni i prvi je janjičarski ustanak koji historija poznaje, počeo je zahtjevom za povećanje plaća za pola akče i završio svrgavanjem mladog Mehmeda II s prijestolja. Murat II 8. safera 850. žurno je krenuo iz Manise i počeo svoju drugu vladavinu. Događaj je bio prvi znak da je kapikulu-odžak postao sila koja ima riječ o prijestolju i oblikovao je Osvajačev doživotni oprez prema janjičarima.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Pripojenje epirske obale: Arta i Preveza", "796f7ecf"], "d": ["Devetnaest godina nakon predaje Janjine 1430. i Arta i Preveza u obalnom dijelu Epirske despotovine došle su pod osmansku upravu. Tako je stavljen pod nadzor Ambrakijski zaljev, koji se otvara na Jonsko more, i upotpunjena pomorska veza Janjine. Preveza je ključna tačka zaljeva koji će devedeset godina kasnije dati ime Barbarosinoj historijskoj pobjedi.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Smrt Murata II i drugo stupanje Mehmeda II na prijestolje", "8f8256ad"], "d": ["Murat II, koji se razbolio nakon sinovljeve svadbe, umro je u Edirni 1. muharrema 855. (3. februara 1451). Devetnaestogodišnji Mehmed II 16. muharrema 855. (18. februara 1451) po drugi je put stupio na osmansko prijestolje — ovaj put trajno. Povratak mladog vladara, svrgnutog pet godina ranije na Bučuktepeu, početak je vladavine koja će dvije godine kasnije biti okrunjena osvajanjem Istanbula i Osmanski bejluk pretvoriti u svjetsko carstvo.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Prva opsada Kafe zajedničkih osmansko-krimskih snaga", "e346d163"], "d": ["Krimski kan Hadži Giraj, koji se u junu 1454. sporazumio sa sultanom Mehmedom Osvajačem, sa 7000 konjanika opsjeo je Kafu s kopna; pedeset-šezdeset osmanskih galija zauzelo je položaje na pučini. Đenovljanska Kafa plaćanjem harača postigla je podizanje opsade, a konačno osvajanje ostalo je za dvadeset jednu godinu kasnije, 1475. Ta prva zajednička operacija bila je prvi primjer osmansko-krimske vojne saradnje koja će se kasnije ponoviti pri konačnom osvajanju Kafe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Zauzimanje sjevernoegejskih otoka: Tenedos, Imbros i Tasos", "76575895"], "d": ["Odmah nakon osvajanja Istanbula sultan Mehmed Osvajač, da bi osigurao morski put do nove prijestolnice, okrenuo se otocima na egejskom ušću Dardanela; Tenedos (Bozcaada) i Imbros (İmroz) uzeti su od Bizanta, a Tasos od porodice Gattilusio, đenovljanskog porijekla. Ti otoci, koji zaključavaju obje strane moreuza, otad su postali prva karika linije snabdijevanja i odbrane Istanbula. Zbog intervencija papinske i venecijanske flote vlast je neko vrijeme prelazila iz ruke u ruku i učvrstila se tek 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Osvajanje Kosova: zauzimanje Prištine i Novog Pazara", "d7ed2345"], "d": ["Osmanska vojska koja je krenula na Srpsku despotovinu zauzela je Prištinu na Kosovu polju i Novi Pazar, središte Raške oblasti; u istoj operaciji zauzeto je i Novo Brdo, poznato po rudnicima srebra. Tako je južna polovina Srbije vezana za izravnu osmansku upravu, a despotovina u Smederevu odsječena od središnjih zemalja. To je osvajanje bilo presudan korak na putu koji je četiri godine kasnije vodio do potpune aneksije Srbije.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) ušla pod osmansku upravu — jedno od središta Dukađinskog sandžaka", "19511588"], "d": ["Odmah nakon pohoda sultana Mehmeda Osvajača na Srbiju 1455. Peć, sjedište Srpske patrijaršije, prešla je pod osmansku upravu; u osmanskim izvorima nema zapisa o tom prelasku. Varošica je s vremenom postala mala muslimanska varošica i jedno od sjedišta sandžakbega u Dukađinskom sandžaku.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Osvajanje Enosa i Samotrake — upotpunjenje zapadnotrakijske obale", "106e723b"], "d": ["Enos (Enez) na ušću rijeke Marice u more uzet je od porodice Gattilusio, đenovljanskog porijekla, koja ga je držala osamdeset godina; u istoj operaciji zauzet je i otok Samotraka, koji mu je pripadao. Padom Enosa zapadnotrakijski obalni pojas postao je neprekinuta osmanska zemlja od Soluna do Galipolja. U rukama porodice Gattilusio ostao je samo Lezbos; i on će biti zauzet šest godina kasnije.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Neuspjeh opsade Beograda", "3d53a604"], "d": ["Sultan Mehmed Osvajač nakon osvajanja Istanbula opsjeo je Beograd, smatran ključem srednje Evrope; ali pojačanja koja je Janko Hunjadi doveo s Dunava i dobrovoljci koje je okupio krstaški propovjednik Kapistran spriječili su pad tvrđave. Sultan se, unatoč ličnom junaštvu pokazanom pred opsadom, ranjen morao povući. Taj neuspjeh zatvorit će ugarsku granicu osmanskom napredovanju na šezdeset pet godina; Beograd će moći zauzeti tek Zakonodavac 1521.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Osvajanje sjeverne Moreje: Patras (Balyabadra)", "c08a8509"], "d": ["Snage sultana Mehmeda Osvajača, koje su se istih godina kad i aneksija Srbije usmjerile na Morejsku despotovinu, zauzele su Patras na sjeverozapadu poluotoka. Ta luka, koja drži ušće Korintskog zaljeva, ključ je kopnenog ulaza u Moreju; njeno zauzimanje pripremilo je teren za konačno osvajanje dvije godine kasnije. Grad je bio posljednje veliko pristanište preko kojeg su bizantski despoti održavali vezu s latinskim svijetom.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Zauzimanje zapadne crnomorske obale: Amasra", "f43608fc"], "d": ["Amasra, utvrđena đenovljanska kolonija na zapadnom Crnom moru, predala se bez otpora pod zajedničkim pritiskom flote i kopnenih snaga sultana Mehmeda Osvajača. Ta luka na obali Bartın–Zonguldak stajala je kao latinski džep između zemalja Džandarovića i Osmanlija; njenim zauzimanjem obala se objedinila. Pad Amasre prvi je korak velikog crnomorskog pohoda koji će se dvije godine kasnije (1461) usmjeriti na Sinop i Trabzon.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Osvajanje otoka Lezbosa", "fe17aeba"], "d": ["Osmanska vojska pod komandom sultana Mehmeda Osvajača u zu-l-hidždžetu 866. nakon kratke ali žestoke opsade oduzela je Lezbos od porodice Gattilusio, đenovljanskog porijekla, i anektirala ga. Pad najvećeg otoka sjevernog Egeja likvidirao je i posljednju važnu đenovljansku bazu u tom području. Otok će, zahvaljujući blizini anadolske obale, otad služiti kao isturena straža osmanske flote, a ući će u historiju pomorstva i kao mjesto gdje su stasala braća Barbarosa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Počeo šesnaestogodišnji osmansko-venecijanski rat", "563ddb68"], "d": ["Venecijanci su, da bi zaustavili osmansko napredovanje u Moreji i na Egeju, sklopili savez s vladarima Karamana i Ak-Kojunlua i 1463. započeli rat. Ta strategija okruženja uspostavljena s Uzun Hasanom na istoku, Venecijom na zapadu i Karamanom između prisilila je Osvajača da istovremeno ratuje na više frontova. Šesnaestogodišnja borba obuhvatit će sve velike operacije tog razdoblja, od Otlukbelija do albanskih pohoda, i okončat će se tek Istanbulskim mirom 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Osvajanje većeg dijela Hercegovine: Trebinje i Mostar", "f54c0100"], "d": ["Zemlje hercegovačkog vojvode Stjepana Vukčića Kosače, koji je uspostavio upravu odvojenu od Bosne, tri godine nakon pada Bosanskog kraljevstva uglavnom su prešle pod osmansku upravu: na jugu je Trebinje 1466. zauzeto \"gotovo zajedno s cijelom hercegovačkom oblašću\". I Mostar, nastao oko dviju malih tvrđava na mostu na Neretvi, morao je biti zauzet nešto prije osvajanja Blagaja, središta Hercegovine, 1466-1468; u bosanskom sumarnom popisu (idžmal tahriru) iz 1468-1469. zapisan je pod imenom \"Köprülü Hisar\" (Tvrđava s mostom). Sa preostalim tvrđavama vojvodstva osvajanje Hercegovine dovršeno je 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Drugi albanski pohod — Osvajačev lični pohod na Skenderbega", "9cdd2bfa"], "d": ["Da bi slomio Skenderbegov otpor koji je trajao više od četvrt stoljeća, sultan Mehmed Osvajač 1466-1467. organizirao je velike pohode kojima je lično komandovao. Osmanska vojska opsjela je Kroju (Akçahisar) i sagradila tvrđavu Elbasan (İlbasan) da bi stavila kraj pod nadzor. Pohod, iako je slomio kičmu albanskog otpora, nije uspio oboriti tvrđavu; potpuno potčinjavanje kraja potrajat će deset godina nakon Skenderbegove smrti.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Ak-Kojunlu prethodnice oduzele tvrđavu Bingöl od Kara-Kojunlua", "51b94cbc"], "d": ["U posljednjim sedmicama pohoda u koji je Džihan-šah krenuo protiv Uzun Hasana, Ak-Kojunlu prethodne snage zauzele su tvrđavu Bingöl; ubistvom Džihan-šaha 10. novembra 1467. vlast Kara-Kojunlua u toj oblasti okončana je.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Slom države Kara-Kojunlua: ubistvo Džihan-šaha", "30bc6358"], "d": ["Kara-kojunluski vladar Džihan-šah, koji je zbog nastupa zime napadnut dok se vraćao s pohoda na Uzun Hasana, ubijen je dok je bježao između Bingöla i Kiğija. Nakon tog udarca država se nije mogla oporaviti; posljednjeg vladara Hasana Alija 1469. zarobio je i ubio Uzun Hasanov sin Ugurlu Mehmed. Kara-kojunluska vlast, koja je gotovo stoljeće vladala istočnom Anadolijom, Azerbejdžanom i Irakom, tako je prešla Ak-Kojunluima.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Smrt Skenderbega — gašenje albanskog otpora", "9158c35f"], "d": ["Skenderbeg, koji se, iako odgojen na osmanskom dvoru, 1444. nakon poraza kod Zlatice pobunio i više od četvrt stoljeća pružao otpor u Albaniji, umro je u Lježu, gdje se sklonio. Taj otpor, koji je u doba Murata II i Osvajača više puta zadržavao osmanske vojske, njegovom je smrću izgubio centralno vodstvo. Slomom albanskog fronta, koji su hranili papinstvo i Venecija, Osmanlije su u roku od deset godina zauzele Kroju i Skadar i konačno pripojile kraj svojim zemljama.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Uspostavljena osmanska uprava u Kayseriju: Gedik Ahmed-paša okončao Karamanogulle", "33cf35fc"], "d": ["Kad je Gedik Ahmed-paša 1474. okončao Karamanogulle, Kayseri je ušao pod osmansku upravu; grad je tokom 15. stoljeća prelazio iz ruke u ruku između Dulkadirogulla, Ramazanogulla i Karamanogulla. Pod osmanskom upravom Kayseri je postao sjedište sandžaka Karamanskog beglerbegluka.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos napušten: okončan đenoveški (Maona) posjed", "5bdc380c"], "d": ["Prema TDV-u otok je napušten nakon 1475; 1479. sultan Mehmed II Osvajač osvojio je otok i dao sagraditi tvrđavu.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Poraz kod Rakove (Vaslui) u Moldaviji", "a1a74bf7"], "d": ["Moldavski vojvoda Stefan Veliki (cel Mare) navukao je osmanske snage pod komandom rumelijskog beglerbega Hadim Sulejman-paše na močvarno zemljište i nanio im težak poraz. Taj poraz, jedan od najtežih kopnenih poraza Osvajačevog doba, izazvao je veliki odjek u Evropi i Stefanu donio slavu u krstaškom svijetu. Sultan će sljedeće godine lično krenuti u pohod radi odmazde.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Pobjeda kod Valea Albă (Akdere) — pohod na Moldaviju", "45a66791"], "d": ["Sultan Mehmed Osvajač, koji je lično krenuo u pohod da osveti prošlogodišnji poraz kod Rakove, s osmanskom vojskom nanio je moldavskim jedinicama kod Valea Albă veliki poraz i ušao u Suceavu, središte kneževine. Ali tvrđave nisu zauzete; zbog nestašice hrane, kuge koja se pojavila među janjičarima i ugarskih priprema vojska se morala povući. Konačno podaništvo Moldavije moglo se postići tek sljedećih godina i zauzimanjem Kilije i Akkermana 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Osvajanje Kroje (Akçahisar) i dovršenje osvajanja Albanije", "559a79b4"], "d": ["Deset godina nakon Skenderbegove smrti, 1478, zauzimanjem Kroje, Drivasta, Lježa i Žabljaka osvajanje Albanije uglavnom je dovršeno. Pad tvrđave Kroja, koja je godinama pružala otpor osmanskim vojskama i bila simbol Skenderbegovog otpora, značio je kraj venecijansko-albanskog saveza u tom kraju. Preostali Skadar bit će prepušten Osmanlijama Istanbulskim mirom koji će se potpisati sljedeće godine.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Pripojenje Tamanskog poluotoka", "4ef917b8"], "d": ["Nakon zauzimanja Kafe i Kerča 1475, flota koju je sultan Mehmed Osvajač poslao na kavkaske obale zauzela je, uz Anapu i Kopu, i đenovljansku Matregu (Tamatarha) na Tamanskom poluotoku. Tako su obje obale moreuza stavljene pod nadzor, a ulaz u Azovsko more postao potpuno kontroliran. Taman je, kao vrata prema sjevernom Kavkazu, pripojen sandžaku Kafa.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Ulazak Samosa pod osmansku upravu (Mehmed II Osvajač)", "c877bc14"], "d": ["Sultan Mehmed II Osvajač osvojio je Samos, dao sagraditi tvrđavu i ponovo uredio popis; tvrđavu je 1483. iz političkih razloga dao srušiti Bajazid II.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Neuspjeh opsade Rodosa", "35a85c28"], "d": ["Po naredbi sultana Mehmeda Osvajača flota od 160 plovila pod komandom Mesih-paše u proljeće 885. (1480) opsjela je Rodos i otok je tri mjeseca bio pod blokadom. Vitezovi svetog Ivana pod vodstvom velikog majstora Pierrea d'Aubussona, unatoč teškim gubicima, žestoko su se odupirali; kad je odbijen i posljednji veliki juriš izveden 20. džumade-l-ula 885., flota se 3. augusta povukla. Nakon tog neuspjeha gradski bedemi obnovljeni su iz temelja i pretvoreni u najjače utvrđenje Evrope, a otok je mogao zauzeti tek Zakonodavac 1522.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikarija (Ikarija) ušla pod upravu rodoskih vitezova sv. Ivana", "5cbc2669"], "d": ["Nikarija, između Samosa i Hiosa, od 1481. do 1521. bila je pod upravom rodoskih vitezova sv. Ivana.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Bitka kod Yenişehira — poraz Džem-sultana", "c35abee2"], "d": ["Dva brata, koji su se nakon Osvajačeve smrti pokrenula za prijestolje, sukobila su se na Jenišehirskoj ravnici i Džem-sultan pretrpio je odlučan poraz. Princ, koji je osamnaest dana vladao u Bursi i dao učiti hutbu u svoje ime, nakon poraza morao se skloniti najprije u Konyu, a odatle na memlučku zemlju. Yenişehir je pokrenuo najdugotrajniju dinastičku krizu u osmanskoj historiji: Džemovo pitanje četrnaest godina paralizirat će osmansku vanjsku politiku prema Evropi.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksija Hercegovine", "bf247891"], "d": ["Zemlje Hercegovačkog vojvodstva, koje je opstalo nakon osvajanja Bosne 1463, postepeno su prelazile pod osmansku upravu: Trebinje i Mostar zauzeti su 1466, Hercegovački sandžak ustanovljen je 1470, a posljednje zemlje vojvodstva na jadranskoj obali, s Herceg Novim, osvojene su početkom 1482. i pripojene sandžaku. Tako je planinsko područje iza Jadrana u cijelosti postalo osmansko, a Bosna i Hercegovina postale su jedinstven upravni prostor. Sin posljednjeg hercega koji je stupio na osmanski dvor je Hersekzade Ahmed-paša, koji će se kasnije uzdići do velikog vezira.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Prepuštanje Zakintosa (Zaklise) Veneciji uz godišnji harač", "268a691a"], "d": ["Zakintos, jedan od jonskih otoka oduzetih porodici Tocco na kraju doba Mehmeda II Osvajača, prepušten je Veneciji u potrazi za mirom na Zapadu novog sultana, zaokupljenog pitanjem Džem-sultana. Otok je predan venecijanskoj upravi koja je priznavala osmanski suverenitet i plaćala godišnji harač od pet stotina dukata. Tako je u Jonskom moru neposredna osmanska uprava ostala samo na Lefkadi.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Sklanjanje Džem-sultana na Rodos", "2228d6da"], "d": ["Džem-sultan, čiji je i pokušaj opsade Konye ostao bez rezultata, s tridesetak ljudi pobjegao je iz Anadolije i stigao na Rodos, gdje su ga vitezovi svetog Ivana svečano dočekali. Ali gostovanje se ubrzo pretvorilo u zarobljeništvo; princ je najprije predat Francuskoj, zatim papinstvu, i postao adut u rukama evropske politike. Bajazid II morao je u zamjenu za zadržavanje brata plaćati godišnju naknadu, a osmanski vojni potezi prema Zapadu odgođeni su do Džemove smrti.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Počeo osmansko-memlučki rat (front u Čukurovi)", "3fe3f0c7"], "d": ["Borba za utjecaj nad Dulkadirovićima i neprijateljstvo koje je ostavilo Džem-sultanovo sklanjanje na memlučku zemlju 1485. pokrenuli su rat dviju sunitskih velikih sila koji će trajati šest godina. U sukobima u Čukurovi oko Adane i Tarsusa nijedna strana nije mogla steći nadmoć; osmanske vojske pretrpjele su nekoliko teških udaraca. Taj je rat prva faza loma u osmansko-memlučkim odnosima i početak procesa koji će trideset godina kasnije biti okončan Javuzovim pohodima kod Mardž Dabika i Ridanije.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Osmansko-memlučki mir — tuniško posredovanje", "60dd6719"], "d": ["U osmansko-memlučkom ratu koji je počeo 1485. strane nisu mogle izvojevati odlučnu pobjedu; posredovanjem tuniškog vladara Osmana Hafsida 1491. postignut je sporazum. Ugovor je granice uglavnom vratio u stanje prije rata i obračun dviju islamskih država odgodio na jednu generaciju. Šestogodišnja iscrpljujuća borba jedan je od glavnih razloga oprezne vanjske politike Bajazida II i davanja prednosti unutrašnjim uređenjima umjesto okretanja prema istoku.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Prijem sefardskih Jevreja protjeranih iz Španije u Osmansko Carstvo", "5c2b5c24"], "d": ["Dio Jevreja koji su nakon pada Granade pobjegli od inkvizicijskog nasilja u Španiji sklonio se na osmanske zemlje i naseljen je u razne gradove. Pod osmanskom upravom te sefardske zajednice dobile su slobodu kakvu dotad nisu vidjele: da se nastane gdje žele, da žive po svojoj vjeri, da otvaraju obrazovne ustanove i grade nove sinagoge. Ta seoba, koja je znanjem o štamparstvu, medicini i finansijama koje su donijeli preobrazila privredni život Soluna i Istanbula, postala je u Evropi najviše spominjani primjer osmanskog poretka tolerancije.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Smrt Džem-sultana — kraj četrnaestogodišnjeg zatočeništva", "f6588b70"], "d": ["Džem-sultan, kojeg je papinstvo predalo francuskom kralju Karlu VIII, nakon što je 27. januara 1495. krenuo iz Rima, umro je u mjestu zvanom Castel Capuana; izvori bilježe da su ga mogli otrovati papinski krugovi. Smrt princa, kojeg su evropske države četrnaest godina držale kao prijeteću kartu protiv Osmanlija, napokon je odriješila ruke Bajazidu II. I zaista, sultan će potom objaviti rat Veneciji i povesti flotu do prve velike pobjede.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Pomorska pobjeda kod Sapienze (Zonchio) — prvi veliki uspjeh flote na Sredozemlju", "9754aaef"], "d": ["Bajazid II, kojem su se okončanjem Džemovog pitanja odriješile ruke, 1499. objavio je rat Veneciji; osmanska flota porazila je venecijansku eskadru na pučini kod Sapienze (Zonchio) i izvojevala prvu veliku pomorsku pobjedu na Sredozemlju. Tom je pobjedom flota objavila da se od tada može suprotstaviti Veneciji na moru.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Gubitak Kefalonije i Itake", "60f0f687"], "d": ["Venecija, uzdrmana zauzimanjem Modona i Korona, ujedinila se sa Španijom, prešla u protunapad i opsjela Kefaloniju, koja je od 1479. bila u osmanskim rukama. Nakon otpora od četrdeset sedam dana tvrđava je pala, otok je zajedno s Itakom prešao Veneciji i trista godina nije se vratio pod osmansku upravu. Taj gubitak stvorio je ravnotežu u kojoj je ono što je dobiveno u Moreji vraćeno u Jonskom moru.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Slom Zlatne Horde i uspon Krima", "0d1dc515"], "d": ["Posljednji vladar, kan Šejh Ahmed (1481-1502), nije mogao spasiti zemlju iz krize u koju je zapala, i Kanat Zlatne Horde 1502. otišao je u historiju udarcem krimskog kana Mengli Giraja. Kao posljedica borbi za prijestolje i rascjepa na nekadašnjim zemljama Zlatne Horde nastali su Krimski, Kazanski, Nogajski, Astrahanski i Sibirski kanat. Ta pobjeda Krima pod osmanskom zaštitom učinila je osmanski utjecaj sjeverno od Crnog mora neupitnim, dok će prazninu nastalu u tom području u narednom stoljeću popuniti Moskva.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Kraj osmansko-venecijanskog rata i mir", "125b1526"], "d": ["Rat koji je počeo 1499. i uzdrmao Veneciju gubitkom Sapienze, Lepanta, Modona i Korona okončan je mirom 1502. Venecija, izgubivši najvažnija uporišta u Moreji, morala je priznati osmansku nadmoć u zamjenu za očuvanje trgovačkih povlastica na istočnom Sredozemlju. Vladavina Bajazida II, smatrana opreznom, tim je ratom Osmanlije prvi put uzdigla u položaj ozbiljne pomorske sile na Sredozemlju.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Ustanak Šahkulua — kizilbaški ustanak od kraja Teke do Sivasa", "3beadca7"], "d": ["Šahkulu Baba Tekeli, koji je pod utjecajem safavidske propagande u Anadoliji 1510. otvoreno digao pobunu, u martu 1511. napao je antalijsku čaršiju, a u aprilu porazio osmanske snage u Kütahyi i okolici. U posljednjem sukobu s velikim vezirom Hadim Ali-pašom kod Sivasa obje strane pretrpjele su teške gubitke; poginuli su i veliki vezir i vođa ustanka. Taj ustanak koji je uzdrmao državni autoritet u Anadoliji razotkrio je prazninu vlasti u posljednjim godinama Bajazida II i postao najjači razlog za put princa Selima ka prijestolju.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Odreknuće Bajazida II od prijestolja i stupanje sultana Selima Javuza", "c4cfab69"], "d": ["Pod pritiskom princa Selima, koji je u borbi za prijestolje s braćom imao podršku janjičara, Bajazid II je 24. aprila 1512. odstupio s prijestolja i Selim I istog je dana stupio na prijestolje kao deveti osmanski vladar. Stari sultan umro je na putu prema rodnoj Didimotici, u selu Abalar kod Çorlua, 25. rebiu-l-evvela 918. (10. juna 1512). Na mjesto trideset jednu godinu duge oprezne i prema unutra okrenute vladavine došlo je doba Javuza, koji će za osam godina udvostručiti granice carstva.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Osvajanje tvrđave Sinj", "83271ea5"], "d": ["Osmanske akindžijske snage na bosanskoj granici zauzele su od Ugarskog kraljevstva tvrđavu Sinj, koja je sezala u unutrašnjost Dalmacije. To je bila rana karika dalmatinske granične linije, koja će se devet godina kasnije proširiti Gazi Husrev-begovim osvajanjem Knina i okoline; tvrđavu će 1686. zauzeti Venecija.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Bitka kod Yenişehira i uklanjanje princa Ahmeda", "e2ed15dd"], "d": ["Sultan Selim Javuz porazio je na Jenišehirskoj ravnici blizu Burse starijeg brata princa Ahmeda, najsnažnijeg suparnika za prijestolje, i, zarobivši ga, uklonio. Tako je zatvorena bratska borba koja je trajala od 1511. i okončana unutrašnja podjela u Anadoliji. Osiguravši leđa, Selim je stekao slobodu da se okrene safavidskom pitanju.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Ulazak sultana Selima Javuza u Tabriz", "dad2e227"], "d": ["Nakon pobjede kod Čaldirana osmanska vojska ušla je u safavidsku prijestolnicu Tabriz i u gradu je hutba proučena u sultanovo ime. Selim je ovdje ostao sedmicu dana i dio tabriskih umjetnika i uleme dao preseliti u Istanbul; to preseljenje duboko će utjecati na osmansku dvorsku umjetnost. Iako je grad zbog približavanja zime i nezadovoljstva janjičara napušten, safavidska nadmoć na istoku bila je slomljena. Mjesta koja na karti toga dana prelaze Osmanlijama nisu međusobno povezana i to je tačno: Tabriz je devetodnevna vojna okupacija; Erzindžanska ravnica predala se bez borbe tokom pohoda, dok se tvrđava Kemah usred nje održala pod Safavidima do 19. maja 1515; Siirt je od Safavida povratio hasankejfski melik Halil-beg, koji se iz šah-Ismailovog zatvora u Tabrizu izbavio pokoravajući se Osmanlijama — okolni Diyarbakır ostao je safavidski do 1515, a Hasankeyf do 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muš i Bingöl (Čapakčur) prešli od Safavida pod osmansku upravu", "b0a53b5a"], "d": ["Kad je nakon Čaldirana Istočna Anadolija oduzeta Safavidima, Muš je 921/1515. ušao pod osmansku upravu; susjedni Čapakčur (Bingöl) u istom je procesu pripojen Osmanlijama.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Osvajanje tvrđave Kemah od Safavida", "73fd8671"], "d": ["Sultan Selim Javuz, koji je na povratku s Čaldirana zimu proveo u Amasyi, za osvajanje utvrđene tvrđave Kemah, koja drži prijelaz na Eufratu, zadužio je Bijikli Mehmed-pašu. Na kraju opsade, u kojoj je sultan lično učestvovao, tvrđava je oduzeta od Safavida i otvorena su vrata istočne Anadolije. To je osvajanje prvi konkretni korak koji je pobjedu kod Čaldirana pretvorio u trajni teritorijalni dobitak.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Pobjeda kod Turnadaga — bejluk Dulkadira postao osmanski vazal", "fd879145"], "d": ["Osmanske snage porazile su kod Ördeklija, između Göksuna i Andırına, dulkadirskog bega Alauddevlea Bozkurta, koji se tokom čaldiranskog pohoda dvosmisleno držao; Alauddevle je poginuo u toj bici. Bejluk tada nije anektiran: nakon Alauddevlea sultan Selim Javuz na čelo bejluka Dulkadirovića doveo je Šehsuvaroglu Ali-bega i zemlja sa središtem u Maraşu i Elbistanu nastavila je kao osmanski vazalni bejluk. Tako je tampon na memlučkoj granici došao pod osmanski nadzor i otvoren je put egipatskom pohodu dvije godine kasnije; aneksija će uslijediti nakon ubistva Ali-bega.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Osvajanje Amida (Dijarbekir) i osnivanje Dijarbekirskog beglerbegluka", "a6867d5b"], "d": ["Nakon što je Idris Bitlisi za Osmanlije pridobio sunitske kurdske begove tog kraja, safavidske snage nisu izdržale dugu opsadu i ključevi Amida predati su Bijikli Mehmed-paši. Grad je postao središte novoosnovanog Dijarbekirskog beglerbegluka. Tako je upravno jezgro Gornje Mezopotamije prešlo u osmanske ruke.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Osvajanje Harputa — otvaranje puta za Dijarbekir", "564eb269"], "d": ["Karamanski beglerbeg Husrev-paša, koji je krenuo spasiti Dijarbekir, zauzet nakon Čaldirana, od safavidske opsade, na kraju trodnevne opsade zauzeo je tvrđavu Harput, čiju je okolicu ranije zauzeo Čerkez Husein-beg. Tako je osiguran put istočno od Eufrata koji vodi do Dijarbekira.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Bitka kod Koçhisara (Kızıltepe) — poraz Kara-kana", "9ea9e843"], "d": ["Osmanska vojska pod komandom Bijikli Mehmed-paše blizu Koçhisara, na mjestu Koruk u pustinji Dede Garkin, u cjelodnevnoj bici na otvorenom polju porazila je safavidskog valiju Kara-kana; njegova odsječena glava poslana je u sultanov logor. Zatim su osmanske snage ušle u grad Mardin, ali su se zadržale svega nekoliko dana i otišle; tvrđava Mardin, koju su držali safavidski čuvari, mogla se zauzeti tek godinu dana kasnije. Ta je pobjeda, osiguravši Javuzovu južnu granicu, omogućila mu da se okrene egipatskom pohodu. Ostala mjesta pripojena istog datuma: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Polazak sultana Selima Javuza iz Istanbula na egipatski pohod", "ac258b4b"], "d": ["Sultan Selim Javuz krenuo je iz Istanbula, naizgled pripremajući novi istočni pohod protiv Safavida, i preko Akşehira uputio se na jug. To što je memlučki sultan Kansuh Gavri stupio u vezu sa šahom Ismailom i ugrozio osmansko istočno krilo ubrzo će dovesti do promjene cilja. Pohod je početak velike operacije koja će trajati dvije godine i pretvoriti Osmanlije u bliskoistočno carstvo.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Zauzimanje Zebida: prvi ulazak osmanskih pomoraca u Crveno more", "38740e0c"], "d": ["Pred portugalskim pritiskom u Indijskom okeanu pomorci osmanskog porijekla Husein-beg i Selman Reis, poslani u Crveno more na traženje memlučkog sultana Kansuha Gavrija, svojom flotom zauzeli su Zebid. Ta operacija, još vođena u memlučkoj službi, prvo je faktičko prisustvo osmanske mornarice na pravcu Crveno more–Indija. Kad Egipat godinu dana kasnije pređe Osmanlijama, ista će eskadra biti izravno vezana za Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Službena objava Memluka i Alepa kao cilja pohoda", "689e310d"], "d": ["Sultan Selim Javuz, kad se Kansuh Gavri sporazumio sa Safavidima i poveo vojsku na Alep, otvoreno je kao cilj pohoda objavio memlučkog sultana i Alep. Tako se dugogodišnje prikriveno nadmetanje dviju sunitskih država pretvorilo u otvoreni rat. Ta je objava pokrenula četverosedmično odbrojavanje do Mardž Dabika.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Neuspjeh opsade Adena: prvi pokušaj protiv Portugala u Crvenom moru", "8ffd46f2"], "d": ["Selman Reis i Husein-beg vodili su osmodnevnu opsadu da zauzmu Aden, vrata Crvenog mora prema Indijskom okeanu, ali su se pred snažnim gradskim utvrdama morali povući. To što Aden nije zauzet godinama će kočiti južnu strategiju protiv Portugala. Taj je pokušaj prvi osmanski ispit u okeanskoj politici.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Pridruženje bejluka Ramazanovića Osmanlijama", "cfaa3754"], "d": ["Tokom dodjela provedenih nakon pobjede kod Mardž Dabika bejluk Ramazanovića sa središtem u Adani dat je Mahmud-begu i stavljen pod osmansku vlast. Bejluk koji je izašao iz memlučkog podaništva, umjesto da bude uklonjen, prepušten je porodici sa statusom 'odžakluka'; Ramazanovići su nastavili upravljati Čukurovom u svojstvu osmanskih sandžakbegova. Taj povlašteni poredak trajao je do 1608, kad se Pir Mansur odrekao bejluka. Ostala mjesta pripojena istog datuma: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Alep, Raka i Deir ez-Zor pod osmanskom vlašću", "2088eb6a"], "d": ["Četiri dana nakon Mardž Dabika sultan Selim Javuz bez otpora ušao je u Alep i u gradskim džamijama hutba je proučena u njegovo ime. Tako brz pad Alepa, smatranog trgovačkom i upravnom prijestolnicom Sirije, pokazuje da je memlučki autoritet u tom kraju bio srušen. Zauzimanje grada odjednom je otvorilo put u Damask i odatle u Egipat. Ostala mjesta pripojena istog datuma: Antiohija, Raka, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Susret s abasidskim halifom Mutevekkilom III na Gökmejdanu u Alepu", "22979f42"], "d": ["Kairski abasidski halifa Mutevekkil III, zarobljen s memlučkom vojskom kod Mardž Dabika, izveden je pred sultana na Gökmejdanu u Alepu i sultan Selim Javuz ukazao mu je veliko poštovanje. Kairski hilafet, od 1261. simbolična čast u sjeni memlučkih sultana, tim je susretom faktički prešao pod osmansku zaštitu. Halifa će kasnije sa sultanom biti odveden u Istanbul.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli (Libanon) i Hama pod osmanskom upravom", "a1e19a79"], "d": ["Nakon Alepa i Hame i Tripoli na sirijskoj obali bez otpora je prešao pod osmansku upravu. Grad, jedna od najprometnijih luka istočnog Sredozemlja, bio je damaska vrata prema moru i središte trgovine svilom i šećerom. Njegovim zauzimanjem obalni pojas Bilad al-Šama u cijelosti je promijenio gospodara.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damask (Dimašk) pod osmanskom vlašću", "2b844d91"], "d": ["Kad mu je predajom Hame i Homsa nakon Alepa otvoren put, sultan Selim Javuz stigao je pred Damask 27. septembra; nije odmah ušao u grad, nego je razapeo šator vani, na mjestu Mastaba, i dvanaestog dana od dolaska uz veliku svečanost ušao unutra. U Damasku se dosta zadržao, uspostavio upravni poredak Sirije i dao sagraditi mauzolej Muhjiddina Ibnu-l-Arabija. Tako je cijeli Bilad al-Šam izašao iz memlučke uprave. Ostala mjesta pripojena istog datuma: Bejrut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Proglašenje Tumanbaja memlučkim sultanom u Kairu", "6020d90d"], "d": ["Nakon Kansuha Gavrija, poginulog kod Mardž Dabika, memlučki emiri doveli su na prijestolje Tumanbaja, koji će biti posljednji sultan države. Novi sultan čerkeskog porijekla preuzeo je državu koja je izgubila Siriju, kojoj je blagajna bila iscrpljena i koja je bila bez vatrenog oružja. Unatoč tome, uspostavit će odbrambenu liniju pred Kairom i organizirati posljednji otpor osmanskom napredovanju.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Bitka kod Gaze (Han Junusa): poraz Džanbirdija Gazalija", "9f1eb8cb"], "d": ["Sultan Selim Javuz poslao je velikog vezira Hadim Sinan-pašu s prethodnicom od četiri hiljade ljudi na Gazu. Džanbirdi Gazali, kojeg je Tumanbaj postavio za namjesnika Damaska, pokušao je zaustaviti osmansku prethodnicu na liniji Gaza–Han Junus, ali je teško poražen i pobjegao u Egipat. Rasipanjem posljednje memlučke tampon-snage u Palestini potpuno se otvorio put prema Sinajskoj pustinji.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Istočno od Jordana: Aman pod osmanskom upravom", "9db62667"], "d": ["Dok su se osmanske snage koje su se nakon bitke kod Gaze pripremale za egipatski pohod spuštale na jug, i Aman istočno od Jordana došao je pod osmansku upravu. Obalni i unutrašnji gradovi Palestine (Jafa, Nablus, Sidon, Akka, Jerusalem) već su pak nakon Mardž Dabika, u jesen 1516, promijenili gospodara. Tim se gradovima četiri stoljeća upravljalo kao sandžacima Damaščanskog ejaleta.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Dolazak sultana Selima Javuza u Jerusalem", "66d7bfad"], "d": ["U Jerusalem, koji je nakon Mardž Dabika bez otpora prešao pod osmansku upravu, nakon bitke kod Gaze došao je sultan Selim Javuz s državnim uglednicima i vojskom. Sultan je posjetio Kupolu na stijeni i Al-Aksa džamiju i potvrdio sveti status grada. Jerusalem će od toga datuma do decembra 1917. punih četiri stoljeća ostati pod osmanskom upravom.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Ulazak sultana Selima Javuza u Gazu i okretanje prema Sinajskoj pustinji", "2106bfc7"], "d": ["Nakon poraza Džanbirdija Gazalija kod Han Junusa (21. decembra 1516) Gaza je bila u rukama prethodnice. Sultan je 2. januara 1517. ušao u Gazu, ondje se sastao sa Sinan-pašom, koji je bio na čelu prethodnice, i vojska je obavila posljednje pripreme za prelazak u Egipat. Kroz bezvodnu pustinju Katja (Sinaj), od Gaze do Salihije, trebalo je prevaliti osam konaka, a voda se imala nositi na devama. Taj je prijelaz najrizičnija i logistički najteža faza pohoda.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Zauzimanje Sueza — vrata prema Crvenom moru", "05f3324e"], "d": ["Ulaskom osmanskih jedinica u Kairo nakon pobjede kod Ridanije i Suez na sjevernom kraju Crvenog mora prešao je pod osmansku upravu. Ta brodogradilišna luka iz koje su Memluci slali flotu u Indijski okean postala je baza južne politike koja će se voditi protiv Portugala. Suez je sjeverno ušće linije na kojoj će tri stoljeća kasnije biti prokopan kanal.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Prvi ulazak osmanskih jedinica u Kairo", "0a3f4f4d"], "d": ["Dan nakon pobjede kod Ridanije osmanskim je vojskama dopušteno da uđu u Kairo i 24. januara jedinice su se smjestile u gradu. Međutim, taj ulazak nije značio potpunu kontrolu grada; Tumanbaj se povukao u Gornji Egipat i memlučki otpor još nije bio slomljen. Osvajanje Kaira neće biti dovršeno u jednom danu, nego u krvavom procesu koji će se protegnuti na sedmice.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Tumanbajev napad na Kairo i trodnevne ulične borbe", "b83b6ce6"], "d": ["Tumanbaj, koji se povukao u Gornji Egipat, s oko sedam hiljada ljudi u noći 27-28. januara iznenada je ušao u Kairo, pokrenuo otpor u gradu i osmanske jedinice doveo u izuzetno težak položaj. U trodnevnim žestokim uličnim sukobima Memluci su privremeno držali veći dio grada. Otpor se mogao slomiti tek uključivanjem osmanske artiljerije i pojačanja.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Stupanje Džanbirdija Gazalija u osmansku službu", "a94ea459"], "d": ["Bivši memlučki emir Džanbirdi Gazali, koji se nakon Ridanije povukao u Salihiju, obratio se sultanu tražeći aman. Sultan Selim Javuz, smatrajući da će biti koristan u uspostavljanju reda u Egiptu i Siriji, primio ga je u svoju službu. Ta je odluka prvi veliki primjer osmanske politike uključivanja memlučkih kadrova u sistem umjesto njihovog uklanjanja.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Svečani ulazak sultana Selima Javuza u Kairo i učenje hutbe", "6d98080c"], "d": ["Nakon gušenja uličnih sukoba sultan je 15. februara 1517. uz vrlo sjajnu svečanost ušao u Kairo i u džamijama je hutba proučena u njegovo ime. Učenje hutbe u Kairu u ime osmanskog sultana objava je da je memlučka vlast, koja je trajala od 1250, pravno okončana. Taj se datum smatra simboličnim trenutkom dovršenja faktičkog osvajanja Egipta.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Hvatanje posljednjeg memlučkog sultana Tumanbaja u Terrudži", "7058e6ad"], "d": ["Tumanbaj, koji se nakon napuštanja Kaira skrivao u delti Nila, prokazan je od beduina koji su mu pružili utočište i uhvaćen u području Terrudže. Njegovo hvatanje uklonilo je organizirano središte memlučkog otpora. Posljednji sultan potom će četrnaest dana biti držan u osmanskim rukama.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Pogubljenje Tumanbaja na Bab Zuvejli i kraj Memlučke države", "ad9820be"], "d": ["Četrnaest dana nakon hvatanja Tumanbaj je obješen na glasovitoj kairskoj kapiji Bab Zuvejli; njegovo je tijelo kasnije sahranjeno u medresi koju je dao sagraditi njegov amidža. Tako je Memlučka država, koja je od 1250. vladala Egiptom i Sirijom, službeno otišla u historiju. Slomom otpora i gradovi Gornjeg Egipta (Said), poput Asjuta i Asuana, pripojeni su osmanskoj upravi.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Portugalski napad na Džidu i odbrana Selmana Reisa", "52322cf5"], "d": ["Portugalska flota od tridesetak galija i galija velikih (galeona) napala je Džidu; Selman Reis, vodeći odbranu grada, spriječio je neprijatelja da se iskrca i potopio nekoliko portugalskih brodova. Ta je odbrana spriječila da luka Meke, a time i hadžijski put, padne u ruke jedne kršćanske države. Džida će nekoliko mjeseci kasnije, priznanjem (bejatom) Hidžaza, službeno biti uključena u osmansku upravu.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Preuzimanje Aleksandrije flotom — dovršenje osvajanja Egipta", "386878fe"], "d": ["Točno četiri mjeseca nakon Ridanije i trideset šest dana nakon Tumanbajevog pogubljenja, dolaskom osmanske flote pod Džafer-begom u luku, Aleksandrija je prešla pod osmansku upravu; u istom procesu pripojene su i luke delte poput Rašida i Damijete. To što je ta velika egipatska luka na Sredozemlju preuzeta mjesecima nakon pada Kaira, i to s mora, a ne s kopna, jasno pokazuje da osvajanje nije dovršeno jednom bitkom, nego područje po područje. Aleksandrija će otad postati životno važna luka koja povezuje Istanbul i Kairo. Ostala mjesta pripojena istog datuma: Rašid (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Pridruženje Hidžaza bez rata: bejat Ebu Numejja, sina mekanskog šerifa", "c13b98c7"], "d": ["Sultan Selim Javuz najprije je namjeravao poslati vojsku radi zauzimanja Meke i okolice, ali je od toga odustao kad je mekanski emir šerif Berekat javio svoju pokornost. Berekatov dvanaestogodišnji sin Ebu Numejj s očevim darovima i ključevima Meke došao je u Kairo i primljen pred sultana. Tako je Hidžaz pridružen Osmanlijama ne kao automatska posljedica Ridanije, nego pet i po mjeseci kasnije, bez ijednog ispaljenog metka, mirnim putem i bejatom. Ostala mjesta pripojena istog datuma: Taif. Ostala naselja izgubljena istog datuma: Khurma (istočno od Taifa), Rabig, Bedr.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Prihvatanje titule Hadimu-l-Haremejn i hutba u Medini", "63b32b59"], "d": ["Nakon drugog prijema mekanskog izaslanstva sultan Selim Javuz službeno je preuzeo zaštitu Haremejna i počeo koristiti titulu 'hadimu-l-Haremejni-š-šerifejn' (sluga dvaju časnih svetih mjesta). Šerif Berekat obukao je počasnu odoru (hilat) koja mu je poslana i dao učiti hutbu u sultanovo ime; odlaskom i medinskog izaslanstva u Istanbul Berekatov emirat potvrđen je beratom. Sultan je stanovnicima Haremejna poslao dvjesta hiljada zlatnika i obilnu hranu te tako započeo tradiciju surre koja će se ponavljati svake godine. Ostala mjesta pripojena istog datuma: Janbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Stupanje Selmana Reisa u osmansku službu i preuzimanje crvenomorske politike", "771da99a"], "d": ["Selman Reis, koji je branio Džidu od Portugalaca, došao je u Kairo i stupio pred sultana Selima Javuza; neko je vrijeme bio zadržan, ali je 1519. pozvan u Istanbul i obavezao se da će protiv portugalske prijetnje pripremiti trideset galija i nekoliko kalijata. Taj susret je početak toga da se politika Crvenog mora i Indijskog okeana preuzme iz memlučkog naslijeđa i izravno veže za Istanbul. Osmanlije su sada bile ne samo sredozemna država, nego i sila koja vodi okeansku politiku.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Odlazak sultana Selima Javuza iz Kaira i beglerbegluk Hajir-bega", "8cd4fb23"], "d": ["Sultan Selim Javuz, koji je ostao u Egiptu oko osam mjeseci i uspostavio upravni, finansijski i vojni poredak, napustio je Kairo; Hajir-beg, bivši namjesnik Alepa, koji je kod Mardž Dabika povlačenjem lijevog krila ubrzao memlučki poraz, počeo je upravljati iz Kairske tvrđave (Kal'atu-l-džebel) kao prvi osmanski beglerbeg Egipta. Izbor valije memlučkog porijekla bio je svjesna prijelazna politika koja je osiguravala da nova uprava domaćem stanovništvu ne izgleda strana. Na povratku sultan je u Istanbul sa sobom poveo posljednjeg abasidskog halifu Mutevekkila III i odabrane egipatske umjetnike i učenjake.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Kraj kairskog abasidskog hilafeta — predaja o 'ceremoniji predaje'", "1d357640"], "d": ["Kad je sultan Selim Javuz zauzeo Egipat, sa sobom je u Istanbul odveo posljednjeg halifu Mutevekkila III alallaha, zarobljenog kod Mardž Dabika; tako je okončan kairski abasidski hilafet, koji je od 1261. trajao bez ovlasti u sjeni memlučkih sultana. S druge strane, poznata predaja da je hilafet službenom ceremonijom u Aja Sofiji predat Javuzu prvi se put javlja krajem XVIII stoljeća u djelu d'Ohssona i nema je ni u jednom izvoru iz Javuzovog doba. TDV Islamska enciklopedija, budući da nema izvornog dokumenta koji bi potvrdio ceremoniju, predaju smatra izmišljenom; ali bilježi i da po šerijatu za prijenos hilafeta takva ceremonija predaje nije bila potrebna.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum pripojen osmanskoj upravi — slomljen safavidski utjecaj u istočnoj Anadoliji", "78d1be02"], "d": ["Iako je nakon pobjede kod Čaldirana (1514) osmanski utjecaj u tom kraju porastao, potpuno zauzimanje Erzuruma odgodilo se dok iranski utjecaj nije slomljen; grad je pripojen osmanskoj upravi tek nakon egipatskog pohoda, 1518-19. Erzurum je 1502, kad je šah Ismail okončao Ak-Kojunluski bejluk, došao pod safavidsku vlast; tako je zatvoreno to šesnaestogodišnje razdoblje. Erzurumski beglerbegluk bit će osnovan 1534. tokom pohoda na dva Iraka. Između 1518. i 1519. zajedno s erzurumskim područjem pod osmansku upravu došao je i Aşkale (dan nepotvrđen).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Početak dželalijskih ustanaka: ustanak šejha Dželala iz Bozoka", "99bd8a99"], "d": ["U bozočkom kraju čovjek po imenu šejh Dželal proglasio se mahdijem i digao ustanak oko Tokata; iako je ustanak ugušen, njegovo je ime stoljeće davalo naziv svim razbojničkim i ustaničkim pokretima u Anadoliji. Dželalijstvo se krajem XVI stoljeća, spojivši se s raspadom timarskog poretka i demografskim pritiskom, pretvorilo u najdugotrajniji problem unutrašnje sigurnosti carstva. Ustanci su u Anadoliji doveli do masovnih seoba zvanih 'veliki bijeg'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Vezivanje Alžira za Osmansku državu", "b8eba4c1"], "d": ["Hajrudin Reis, koji se u sjevernoj Africi opirao španjolskom pritisku, da bi se mogao održati obratio se Istanbulu i ponudio Alžir sultanu, a hutba je proučena u ime sultana Selima Javuza. Tako je Alžir službeno pripojen osmanskim zemljama, a Hajrudinu su, s titulom beglerbega, poslani vojnici i topovi. To vezivanje postavilo je temelj osmanske pomorske vlasti na zapadnom Sredozemlju koja će trajati stoljećima. Ostala mjesta pripojena istog datuma: Konstantina, Šeršel (Cherchell), Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Smrt sultana Selima Javuza u Çorluu", "9fe83744"], "d": ["Selim I, koji je za osam godina više nego udvostručio državni teritorij, 18. jula 1520. krenuo je iz Istanbula na novi pohod; zbog velikog čira koji mu se pojavio na leđima nije mogao dalje od Çorlua. Unatoč intervenciji ljekara bolest se pogoršala i nakon dvomjesečnog beznadnog liječenja umro je ovdje 8-9. ševvala 926. (21-22. septembra 1520). Čaldiranom, Mardž Dabikom i Ridanijom zaustavio je Iran i uklonio Memlučku državu, a Osmanlijama donio hilafet i zaštitništvo Haremejna. Iza sebe je ostavio samo jednog muškog potomka: Sulejmana.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Otok Nikarija (Ikarija) ulazi pod osmansku upravu", "6afa972b"], "d": ["Nikarija, između Samosa i Hiosa, od 1481. do 1521. bila je pod upravom rodoskih vitezova sv. Ivana; prvo osmansko razdoblje na otoku počelo je 1522. i trajalo do 1822. U tom razdoblju za ubiranje i uplatu poreza bio je odgovoran kajmakam; kao i na drugim egejskim otocima, mjesno vijeće staraca (demogerontia) nastavilo je postojati i s vremena na vrijeme sukobljavalo se s osmanskom upravom.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksija zemlje Dulkadira — Dulkadirski ejalet sa središtem u Marašu", "595c3c30"], "d": ["Zemlja Dulkadira, koja je nakon poraza kod Turnadaga 1515. trajala kao bejluk podložan Osmanlijama, nakon pogubljenja Šehsuvaroglu Ali-bega zajedno s djecom u Artukovi neposredno je pripojena osmanskim zemljama i pretvorena u ejalet sa središtem u Marašu. Oblast Bozok toga bejluka vezana je za osmansku upravu kao zaseban sandžak. Tako je zatvoreno gotovo dva stoljeća dugo dulkadirsko razdoblje Maraša, Elbistana, Göksuna, Gürüna, Zamantija i Darendea; tampon-bejluk na memlučkoj granici potpuno je nestao.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Osvajanje Knina", "a46d3117"], "d": ["Prepadima bosanskog sandžakbega Gazi Husrev-bega 927–928. (1521–1522) niz venecijanskih tvrđava, na čelu s Kninom, Skradinom i Ostrovicom, prešao je pod osmansku upravu; granica je potisnuta iza drugog planinskog lanca. Taj niz osvajanja postavio je temelj Dalmatinskog sandžaka, koji će petnaest godina kasnije biti dovršen zauzimanjem Klisa.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Povlačenje vitezova: predaja Bodruma, Kosa i Dodekaneza", "ea01666e"], "d": ["Prema uslovima predaje Rodosa vitezovi sv. Ivana ispraznili su ne samo glavni grad otoka, nego sve položaje koje su dvjesto godina držali. Tvrđava Bodrum (sv. Petra) na anadolskoj obali te otoci Kos, Kalimnos i Leros tako su bez sukoba prešli pod osmansku upravu. Tim prijenosom, dovršenim dvije sedmice nakon pada Rodosa, latinsko prisustvo u jugoistočnom uglu Egeja potpuno je okončano.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Ustanak Ahmed-paše Izdajnika u Egiptu", "b18bb805"], "d": ["Ahmed-paša, koji je, čekajući položaj velikog vezira, poslan za valiju Egipta, u Kairu se proglasio 'al-Malikom al-Mansurom sultanom Ahmedom' i objavio nezavisnost. Ustanak je ubrzo ugušen, a paša ubijen, ali je događaj pokazao krhkost centralnog nadzora u najbogatijem ejaletu carstva. Na to je Ibrahim-paša otišao u Egipat i dao pripremiti glasovitu egipatsku kanun-namu, koja je nanovo uredila upravu ejaleta.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksija Sjeverne Bosne: Jajce i Banja Luka", "8ec86cfa"], "d": ["Kad se nakon Mohača urušila ugarska odbrambena linija, bosanski sandžakbeg Gazi Husrev-beg krenuo je dolinom Vrbasa i zauzeo posljednje bosanske tvrđave koje su ostale u rukama Ugarskog kraljevstva. Padom Jajca i Banje Luke Bosanski ejalet naslonio se na sjeveru na rijeku Savu i nastao je hrvatski front. Banja Luka ubrzo je postala drugo središte ejaleta.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Zauzimanje Budima i predaja Zapolji", "fba4f89b"], "d": ["Na putu bečkog pohoda osmanska vojska opsjela je i povratila Budim, koji je bio pao u Ferdinandove ruke, i grad predala ugarskom kralju Ivanu Zapolji pod osmanskom zaštitom. Tako je nad Ugarskom u habsburško-osmanskom rivalstvu uspostavljen model tampon-vazalnog kraljevstva. Taj poredak trajat će do 1541, kad će nakon Zapoljine smrti Budim biti pretvoren u izravni osmanski ejalet.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Zakonodavac krenuo na njemački pohod — izazov Karlu V", "7c3d7055"], "d": ["Nakon neuspješne opsade Beča i Ferdinandove ponovne opsade Budima sultan je iz Istanbula krenuo na put, ovaj put da cara Karla V izravno privuče na bitku na otvorenom polju. Vojsku će u augustu zadržati otpor male tvrđave Güns (Kőszeg), a kad car nije izašao u boj, pohod je ostao ograničen na upade. Pohod je pripremio teren za prvi mir s Habsburgovcima sklopljen sljedeće godine.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Njemački pohod i opsada Günsa (Kőszeg)", "8aec937a"], "d": ["Zakonodavac je, s ciljem da Karla V prisili na bitku na otvorenom polju, s vojskom krenuo na Austriju; mala tvrđava Güns pružala je otpor dvadeset pet dana i usporila napredovanje vojske. Kad car nije izašao u boj, akindžije su udarile na okolicu Beča i zbog odmakle sezone vojska se vratila. Pohod nije donio teritorijalni dobitak, ali je, posadivši Habsburgovce za pregovarački stol, pripremio teren za mir sljedeće godine.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Istanbulski mir — prvi mir s Habsburgovcima", "b085767a"], "d": ["Sultan je, primivši Ferdinandovog poslanika Corneliusa, pristao na primirje i nastao je prvi službeni mirovni tekst između Osmanlija i Austrije. Ugovorom je Ferdinand pristao plaćati godišnji porez za ugarske zemlje koje je držao, a austrijski nadvojvoda u protokolu je smatran ravnim velikom veziru. Taj neravnopravni status bio je otvoreni izraz pretenzije na nadmoć osmanske diplomatije u XVI stoljeću.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Zauzimanje Karsa i otvaranje sjeveroistočne granice", "742e3101"], "d": ["Dok je prethodna kolona pohoda na dva Iraka (Irakejn) kretala iz Erzuruma na istok, tvrđava Kars, koja je bila u rukama gruzijskog atabegata i od Timura ležala u ruševinama, zauzeta je bez otpora. Budući da je grad držao prolaz između luka Araksa i Čildira, smatran je ključem sjevernih vrata prema Iranu. Taj dobitak postao je prva karika Karskog beglerbegluka, osnovanog trideset godina kasnije, i kavkaske linije.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Prvi ulazak u Tabriz — otvaranje pohoda na dva Iraka", "cf7ed4e3"], "d": ["Ibrahim-paša, koji je u svojstvu serdar-ekrema išao naprijed, kad se šah Tahmasp, izbjegavajući bitku na otvorenom polju, povukao u unutrašnjost, bez otpora je ušao u safavidsku prijestolnicu Tabriz. I Sulejman Zakonodavac stigao je u grad u septembru; ali zbog nadolaska zime i prevelike duljine linije opskrbe vojska se uputila prema Bagdadu, a Tabriz se nije mogao dugo zadržati. Grad, zauzet po drugi put nakon Čaldirana, postao je mjesto na kojem su Osmanlije naučile da je na istoku lako osvojiti, a teško zadržati.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Barbarosino osvajanje Tunisa", "d8754216"], "d": ["Kapudan-paša Barbarosa Hajrudin-paša, nakon što je flotom udario na obale Italije, okrenuo se Tunisu i, otjeravši hafsidskog vladara Mevlaja Hasana, ušao u grad. Zauzimanje Tunisa, svojim položajem koji kontrolira Sicilijanski prolaz, odjednom je ravnotežu snaga na zapadnom Sredozemlju okrenulo u osmansku korist. Ta vlast, međutim, neće dugo trajati; Karlo V sljedeće će godine odgovoriti velikom flotom.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Gubitak Tunisa Karlu V", "a691f0f8"], "d": ["Karlo V je u velikom pohodu, potpomognutom đenovljanskom i papinskom flotom, nakon što je oborio La Goulette (Halkulvad), zauzeo Tunis i Mevlaja Hasana vratio na prijestolje pod španjolskom zaštitom. U grad je smješten španjolski garnizon i osmansko napredovanje na srednjem Sredozemlju privremeno je zaustavljeno. Konačno osvajanje Tunisa bit će moguće tek četrdeset godina kasnije, 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Gazi Husrev-begova akcija uz Savu: Brod i Jasenovac", "3740ec83"], "d": ["Nakon zauzimanja Jajca i Banje Luke 1528, tvrđave uz rijeku Savu još su neko vrijeme ostale na hrvatsko-slavonskoj granici podložnoj habsburškoj kruni. Gazi Husrev-beg, koji je 1536. po treći put postao bosanski sandžakbeg, te je godine, zauzimajući Požegu i okolinu, pod osmansku upravu pripojio i tvrđave Brod i Jasenovac na Savi. Tako se sjeverna granica Bosne naslonila na Savu; oblast je dovršena zauzimanjem Dubice dvije godine kasnije.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Pogubljenje Makbul Ibrahim-paše", "348aa7b8"], "d": ["Ibrahim-paša, koji je trinaest godina bio veliki vezir, Zakonodavčev najbliži prijatelj i faktički drugi čovjek države, pozvan na iftar u saraj, zadavljen je i pogubljen bez ikakvog obrazloženja. Smatra se da su na njegovu smrt utjecali stav koji je zauzeo u pohodu na dva Iraka, korištenje titule 'serasker-sultan' i ravnoteže unutar dvora. Pogubljenje je prekretnica koja pokazuje da u osmanskoj centralnoj upravi veliki veziri nisu imali apsolutnu sigurnost.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Osvajanje tvrđave Klis i osnivanje Dalmatinskog sandžaka", "6ffd4ebf"], "d": ["Kethuda Gazi Husrev-bega, Murat-beg, preobraćenik hrvatskog porijekla, oduzeo je od Venecije stratešku tvrđavu Klis neposredno sjeverno od Splita. Odmah nakon osvajanja Klis je postao središte novog sandžaka i kaze koji su obuhvatali okolicu; granice tog sandžaka uglavnom su iscrtale okvir osmanske Hrvatske. To osvajanje, petnaest godina nakon Knina, dovršilo je upravni kostur unutrašnjosti Dalmacije.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Opsada Krfa i rat s Venecijom", "11af95bd"], "d": ["Nakon apulijskog (Puglia) pohoda osmanska vojska iskrcala je trupe na Krf i opsjela snažnu venecijansku tvrđavu na otoku. Zbog strmog položaja tvrđave, teških gubitaka i vremenskih prilika 6. septembra blokada je podignuta i vojska se povukla. Iako je opsada ostala bez rezultata, rat otvoren s Venecijom rezultirao je pripajanjem mnogih otoka na Egeju i Jadranu Osmanlijama i, sljedeće godine, pobjedom kod Preveze.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Barbarosov egejski pohod: zauzimanje otoka kojima je Venecija neposredno upravljala", "1b32ed96"], "d": ["Flota koja se vraćala s opsade Krfa, koristeći to što je Veneciji objavljen rat, redom je u Egeju preuzela otoke koji nisu bili vezani za vojvodstvo, nego neposredno za Veneciju. Egina je zauzeta nakon žestokog otpora, predali su se Astipaleja, u rukama porodice Querini, te Karpatos i Kasos, a Patmos, pod manastirskom upravom, prihvatio je osmansko pokroviteljstvo. Naksoski dukat, pak, ostavljen je na mjestu uz obavezu plaćanja harača; njegova aneksija čekat će 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Barbarosov pohod na sjeverni Egej: zauzimanje Skirosa i Sjevernih Sporada", "20ab688e"], "d": ["Na putu prema Prevezi flota je redom preuzela sjevernoegejske otoke koji su se nakon osvajanja Istanbula sklonili pod Veneciju. Tako su pod osmansku upravu ušli Skiros, sjeverno od Negroponta, te Skijatos, Skopelos i Alonisos, koji drže ulaz u Solunski zaljev. Ti otoci zatvorili su posljednju prazninu u sjevernom Egeju, koja je, iako je Negropont zauzet 1470, ostala u venecijanskim rukama još šezdeset osam godina.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Zauzimanje Adena i aneksija jemenske obale", "e7d46d8f"], "d": ["Flota koja je krenula iz Sueza na indijski pohod najprije se uputila prema jemenskoj obali, jer se na okean nije moglo izaći bez osiguranja Crvenog mora. Hadum Sulejman-paša 3. augusta 1538. ušao je u luku Aden; tahiridski vladar Amir b. Davud, koji je naginjao Portugalcima, doveden je na kapetanska vrata i pogubljen, a u gradu je ostavljena posada od 500 ljudi. U istom pohodu preuzeti su i Moka te otoci Kameran i Farasan, koji gospodare moreuzom, i postavljeni temelji Jemenskog beglerbegluka. Tako je Osmanska država prvi put posjedovala cijelu sjevernu obalu Bab el-Mandeba; Sana i unutrašnje oblasti, pak, morale su čekati još devet godina.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Moldavski pohod i aneksija oblasti Budžak (Bender)", "90a88a56"], "d": ["U pohodu poduzetom protiv moldavskog vojvode Petrua Rareşa, koji nije ispunjavao obaveze prema Osmanlijama, zauzeta je Suceava, a grad Jaši opljačkao je krimski kan Sahib Giraj. Sultan je na vojvodsko mjesto doveo Stefana Skakavca (Čekirge Stefan) i oblast Budžak (južnu Besarabiju) s Benderom izravno pripojio osmanskim zemljama. Ta je aneksija bila jedna od karika koje su sjeverozapadne obale Crnog mora pretvorile u osmansko unutrašnje more. Moldavija je već bila osmansko vazalno vojvodstvo; ovaj pohod nije oduzeo zemlju stranoj državi, nego je samo unutrašnju upravu Bendera i Budžaka oduzeo vojvodi i vezao izravno za sultana; ostatak vojvodstva zadržao je vazalni status. Ista struktura ponovit će se 1484. u Kiliji i Akkermanu, a 1713. i u Hotinu: pogranične tvrđave izravno, unutrašnje zemlje vazalne.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Preuzimanje Nauplije (Anabolu) ugovorom", "104d0937"], "d": ["Trogodišnji venecijanski rat nakon Preveze završio je pristankom republike da napusti posljednje dvije tvrđave u Moreji. Anabolu i Monemvasija (Benefše), koje se nisu mogle zauzeti opsadom, predane su Osmanlijama za pregovaračkim stolom, uz ratnu odštetu od trista hiljada dukata. Tako je poluotok Moreja objedinjen tako da na njemu nije ostalo nijednog venecijanskog uporišta.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Segedin ulazi pod osmansku upravu i formira se Segedinski sandžak", "019aa000"], "d": ["Nakon što je 1541. potpuno uspostavljena osmanska uprava u Budimu, prvaci Segedina prihvatili su vlast Ferdinanda I i pripremili se za oružanu odbranu. Budimski beglerbeg Kučuk Bali-paša početkom 1543. pozvao je k sebi upravitelje grada i pogubio ih zbog izdaje, a zatim poslao jedinicu da zauzme grad. Tada je formiran Segedinski sandžak i za prvog sandžakbega postavljen Derviš-beg, sin Bali-paše; sandžak se u početku prostirao između Dunava i Tise.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Osvajanje Valpova, Šikloša i Pečuha", "2ca030a3"], "d": ["Prvi cilj ugarskog pohoda poduzetog dvije godine nakon aneksije Budima bio je osigurati južno krilo novog ejaleta između Drave i Dunava. Nakon zauzimanja tvrđava Valpovo i Šikloš predalo se središte Baranje, Pečuh. Grad će postati najnaseljenije i najviše izgrađivano središte osmanske Ugarske, a historičar Ibrahim Pečevi po njemu će dobiti ime.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Osvajanje Ostrogona i Stolnog Biograda", "efca9e05"], "d": ["U ugarskom pohodu u koji je lično krenuo Zakonodavac, nakon dvosedmične i po opsade, vjersko središte Ugarskog kraljevstva i nadbiskupski grad Ostrogon ušao je pod osmansku upravu. Zatim je zauzet i Stolni Biograd, krunidbeni grad ugarskih kraljeva, čime je dovršen odbrambeni pojas Budimskog ejaleta. Ostrogon će do 1595. kao ključna tvrđava dunavske linije ostati u osmanskim rukama.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Sjeverni i zapadni odbrambeni pojas Budima: Vac, Hatvan i Šimontornja", "733ee5ce"], "d": ["Nakon zauzimanja Ostrogona i Stolnog Biograda, budimski beglerbeg krenuo je bez sultanovog pohoda da dopuni prsten tvrđava oko prijestolnice. Redom su preuzeti Vac na koljenu Dunava, Hatvan, kapija Alfölda, i Šimontornja na liniji Šija. Dobici te tihe godine pretvorili su Budim iz krajiškog grada u središte ejaleta koje će izdržati sto četrdeset godina.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksija Basre i izlazak na Perzijski zaljev", "02f87c11"], "d": ["Za vrijeme osvajanja Bagdada (1534) vladar Basre Rašid b. Megamis iskazao je pokornost Sulejmanu Zakonodavcu, a 1538. poslao ključeve grada. Kad je njegov nasljednik šejh Jahja stao protiv Osmanlija, bagdadski beglerbeg Ajas-paša krenuo je kopnom, a sandžakbeg Mosula sa 120 brodova niz Eufrat; Ajas-paša je 26. decembra 1545. ušao u Basru, a grad je postao sjedište beglerbegluka. Ta luka na ušću Šat al-Araba bila je kapija kroz koju su Osmanlije izašle u zaljev koji su Portugalci nadzirali iz Hormuza; Amasijskim mirom 1555. i Iran je priznao to stanje.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Osvajanje Sane i unutrašnjosti Jemena", "d31ded85"], "d": ["Nakon Taiza zauzeta je i Sana, i cijela zemlja pripojena je beglerbegluku. Međutim, zbog krševitog reljefa i razlike u mezhebima ta vlast nikada nije bila mirna; Jemen je za Osmanlije postao front koji je neprestano gutao vojnike.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Osvajanje Taiza", "d4509df9"], "d": ["U Jemenu, u kojem se devet godina ranije zadovoljilo obalnim pojasom, budući da su zejdijski imami sve više jačali u brdovitoj unutrašnjosti, snage Ozdemir-paše popele su se na visoravan i zauzele Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Istanbulski mir — petogodišnji mir s Habsburgovcima", "41f81773"], "d": ["Između Osmanlija i Habsburgovaca potpisan je mir na rok od pet godina; Ferdinand je pristao plaćati 30.000 dukata godišnje za ugarske zemlje koje je držao. Ugovor je pravno ozakonio faktičko trodijelno stanje Ugarske. Time što je zapadni front tako osiguran Zakonodavac je dobio mogućnost da organizira nove pohode protiv Irana.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Drugi iranski pohod i ponovno zauzimanje Tabriza", "e82365df"], "d": ["U pohodu poduzetom na poticaj Elkas-mirze, brata šaha Tahmaspa koji se pobunio protiv njega i sklonio u Istanbul, vojska je drugi put ušla u Tabriz. Budući da su se Safavidi opet nisu upustili u bitku na otvorenom polju, nego su se povlačili spaljujući zemlju, u gradu se moglo ostati samo nekoliko sedmica. Pohod je potvrdio da se Tabriz ne može zadržati i usmjerio osmansku strategiju na uspostavu trajne granične linije, odnosno na utvrđivanje Vana.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Osvajanje Vana i utvrđivanje istočne granice", "fc8f930b"], "d": ["Tvrđava Van, opsjednuta na povratku iz Tabriza, svojim položajem na stjenovitom uzvišenju na istočnoj obali jezera bila je neosporni ključ oblasti i predala se nakon kratke opsade. Grad je odmah postao sjedište beglerbegluka; za njega su vezani sandžaci Erdžiš, Adildževaz i Hakari. Za razliku od Tabriza, Van je zadržan i četiri stotine godina ostao najistureniji trajni osmanski položaj na istoku.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksija Lahse i Katifa — arapska obala zaljeva", "f6701e60"], "d": ["Nakon zauzimanja Basre osvojen je Katif, koji je na zapadnoj obali zaljeva postao istureno portugalsko uporište, te je zajedno s oazama Lahse u unutrašnjosti osnovan novi beglerbegluk. Odatle su polazile akcije prema Bahreinu i Hormuzu. Osmanska država tako je istovremeno imala riječ i na crvenomorskoj i na zaljevskoj obali Arabijskog poluotoka.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Gubitak Šehrizora — ardalanski beg Suhrab priklonio se Safavidima", "5600efc9"], "d": ["Oblast Šehrizor, koja je za pohoda na dva Iraka (1535) priznala osmansku upravu, bila je pod upravom ardalanskog emira Bige-bega, koji je sjedio u tvrđavi Zalm. Nakon smrti Bige-bega 1550. njegov brat Suhrab, koji je zauzeo tvrđavu Zalm i zagospodario bejlukom, priklonio se Safavidima i otkazao pokornost Osmanlijama; tako je oblast Šehrizor izašla ispod osmanskog uticaja. Oblast je vraćena tek za nahičevanskog pohoda 1554, opsadom i zauzimanjem tvrđave Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Zauzimanje Ardahana i bazena Čildira", "14c9eb76"], "d": ["Erzurumski beglerbeg, tokom rata sa Safavidima, okrenuo se prema zemljama gruzijskih atabega na luku Kure i pripojio Ardahan i okolinu Čildira osmanskoj upravi. Tako se objedinila linija Kars–Ardahan, a pod nadzor su stavljene visoravni na sjeveroistoku koje se otvaraju prema Gruziji. Konačno upravno uređenje oblasti dovršit će Čildirski ejalet, osnovan dvadeset sedam godina kasnije.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Mehmed-paša Sokolović prešao Dunav — početak erdeljskog rata", "38fde931"], "d": ["Zbog nereda koje je izazvao monah Martinuzzi, tutor malog erdeljskog kralja Ivana Žigmunda (János Zsigmond), i zbog toga što je Erdelj prepustio banatske tvrđave Ferdinandu, ocijenjeno je da je potreban novi pohod; zapovjedništvo je povjereno rumelijskom beglerbegu Mehmed-paši Sokoloviću. Vojska je, uprkos Martinuzzijevim pokušajima odugovlačenja, prešla Dunav i zauzela Bečej, Bečkerek, Čanad i Lipu; ali opsada Temišvara dignuta je 16. novembra zbog hladnoće. Tako je u Ugarskoj otvoren novi osmansko-habsburški rat.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Grad Lipova (Lippa) prešao u ruke Castaldove austrijske vojske — tvrđava se predala 5. decembra", "a0e1ff0d"], "d": ["Lipovu, koju je Mehmed-paša Sokolović zauzeo u oktobru 1551, vojska generala Castalda opsjela je 4. novembra; dva dana kasnije grad je prešao u austrijske ruke. Ulama-paša s posadom od 5.000 ljudi branio je tvrđavu još devet dana i 5. decembra 1551. izašao po dogovoru. Do pada Temišvara 1552. Lipova je ostala u habsburškim rukama.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Snage poslane iz Temišvara zaposjele palanke Južnog Banata — Vršac, Haram, Kovin", "edca0921"], "d": ["Nakon predaje Temišvara osmanskoj vojsci, jedinice izdvojene iz opsadne vojske uputile su se prema malim palankama Banata; prema Bánlakyjevom opisu, te su snage zaposjele palanke Vršac, Facset, Mehádia, Csákóvár, Haramvár i Kovin. Tako je i Haram na obali Dunava prešao u osmanske ruke.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Osvajanje Solnoka i neuspjeh opsade Jegra", "a7156e8f"], "d": ["Dvije osmanske vojske, ujedinjene nakon zauzimanja Temišvara, gotovo bez sukoba zauzele su Solnok na Tisi, jer su plaćenički branioci napustili tvrđavu. Zatim opsjednuta tvrđava Jegar nije mogla biti zauzeta pred tridesetosmodnevnim otporom posade od dvije hiljade ljudi pod zapovjedništvom Istvána Dobóa, pa se vojska povukla s dolaskom zime. To što je u istom pohodu jedna tvrđava lako pala, a druga izdržala prvi je jasan znak da se granica u Ugarskoj više ne pomjera sama od sebe u korist Osmanlija.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Osmansko-francuski savez — francuska flota pod osmanskom komandom", "a8e01b22"], "d": ["Ugovorom od 1. februara 1553. francuska flota stavljena je pod komandu osmanske flote; predviđene su zajedničke operacije protiv Španije na zapadnom Sredozemlju. Nakon ugovora Turgut Reis 15. juna 1553. krenuo je s četrdeset pet galija u pohod radi potpore Francuskoj. To je bio prvi službeni savezni ugovor koji je trgovačku osnovu kapitulacija iz 1536. prenio u vojnu saradnju.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Pogubljenje princa Mustafe u Konjskom Ereğliju", "dec36858"], "d": ["Princ Mustafa, koji je ušao u očev šator da se priključi vojsci okupljenoj za pohod na Nahičevan, upravo kad je trebao stati pred sultana, zatekao je krvnike i zadavljen je. Ubistvo prijestolonasljedničkog kandidata, vrlo omiljenog u vojsci, izazvalo je dubok gnjev među janjičarima, a Rustem-paša smijenjen je s mjesta velikog vezira. Događaj je kao jedan od najspornijih lomova osmanske politike prema prinčevima ušao u književnost i narodno pamćenje.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Pomjeranje granice kod Ibrima i Nubije na jug", "c57d5d77"], "d": ["Južna granica Egipatskog beglerbegluka pomjerena je iza drugog katarakta time što je Ozdemir-beg utvrdio tvrđavu Ibrim, koja se uzdiže na stjenovitom rtu na Nilu, a Donja Nubija potpuno pripojena osmanskom Egiptu. (Osmanska upravna organizacija u Ibrimu uspostavljena je nakon osvajanja Egipta; na karti se Ibrim prikazuje kao osmanski od 1517. Ova godina je približna, izvor ne daje godinu.) Tvrđava je bila i brana protiv prepada iz Nubije i kontrolna tačka na putu zlata i robova prema Sennaru. Bosanska posada koja je ondje smještena bila je toliko trajna da su se njeni potomci i trista godina kasnije još nalazili u tvrđavi. Izvori daju dvije različite priče o vremenu ulaska Ibrima pod osmansku upravu: članak TDV-a o Sudanu pripajanje Donje Nubije osmanskom Egiptu veže za akciju Ozdemir-paše sredinom XVI stoljeća, dok članak o Nubiji navodi da su oblast sve do doline Halfe i upravna organizacija u Ibrimu uspostavljene neposredno nakon osvajanja 1517. Sandžak Ibrim je 26. jula 1573. pripojen Habeškom ejaletu.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Oduzimanje Bedžaje (Bougie) od Španaca", "49691cda"], "d": ["Bedžaja, četrdeset tri godine u rukama Španije i koja je prepolovljavala obalu između Alžira i Konstantine, predala se nakon opsade s kopna i mora. Padom tvrđave obala alžirskog odžaka postala je neprekinuta sve do Orana. Taj gubitak izazvao je u Španiji toliko ogorčenje da je zapovjednik koji je predao tvrđavu, Alonso de Peralta, pogubljen u svojoj zemlji.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Pripajanje Zejle Habeškom ejaletu", "7bbf369a"], "d": ["Na južnom kraju Habeškog ejaleta luka Zejla na afričkoj obali Adenskog zaljeva pripojena je osmanskoj upravi. Taj grad, vrata Adalskog sultanata prema moru, bio je posljednja tačka opskrbe za brodove koji su izlazili iz Bab el-Mandeba. Pripajanjem Zejle osmanska granica u Africi dosegla je najjužniju tačku.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Bitka prinčeva kod Konye", "1c8de387"], "d": ["Princ Bajazid, koji se upustio u borbu za prijestolje, sa snagom od oko 30.000 ljudi stigao je pred Konyu i u dvodnevnom sukobu poražen je od brata princa Selima. Poraženi Bajazid preko Amasye sklonio se u Iran, kod šaha Tahmaspa. Bitka je u posljednjim godinama Zakonodavca krizu nasljeđivanja prijestolja pretvorila u vanjskopolitički problem.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Pomorska pobjeda kod Džerbe", "c7b905c1"], "d": ["Osmanska flota pod komandom Pijale-paše manevrom razdvajanja na dva dijela razbila je pred Džerbom savezničku španjolsko-đenovljansko-maltešku flotu okupljenu da povrati Tripoli. Saveznici su izgubili veći dio flote, a uskoro je pala i tvrđava na otoku. Džerba se smatra drugom velikom pomorskom pobjedom, nakon Preveze, koja je učvrstila osmansku nadmoć na Sredozemlju.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Pogubljenje šehzade Bajazida u Kazvinu", "a759de14"], "d": ["Šehzada Bajazid, koji se sklonio u Iran, nakon dugih pregovora šah Tahmasp predao je osmanskom izaslanstvu, te je zajedno sa četiri sina zadavljen. U zamjenu za predaju Safavidi su dobili značajne materijalne ustupke i garancije za granicu. Ovim pogubljenjem uklonjena je posljednja prepreka dolasku Selima II na prijestolje i očuvan je mirovni poredak Amasijskog mira.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Oduzimanje Hiosa od Đenovljana", "a4559b96"], "d": ["Hios, dvjesto godina upravljan kao trgovačka kolonija đenoveške porodice Giustiniani, koja je plaćala harač Osmanlijama, preuzeo je Pijale-paša bez ijednog ispaljenog metka pod obrazloženjem da je neredovno plaćao harač i davao luku neprijateljskim brodovima. Zajedno s Hiosom i Psarom likvidirano je i posljednje đenoveško prisustvo na istočnoj obali Egeja. Proizvodnja mastike i povlastice Hiošana sačuvane su, a otok je pripojen ejaletu Džezair-i Bahr-i Sefid.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Aneksija Naksoskog dukata — svi Kikladski otoci", "68f0ec0b"], "d": ["Latinski Naksoski dukat, koji je trajao od 1207. i od 1537. plaćao harač Osmanlijama, ukinut je pod obrazloženjem pritužbi da posljednji vojvoda Giacomo Crispo tlači narod. Naksos, Paros, Milos, Andros, Siros, Mikonos, Ios, Amorgos i svi okolni Kikladski otoci jednom su odlukom prešli pod neposrednu osmansku upravu. Sulejman Zakonodavac neko je vrijeme upravu otoka dao Josipu Nasiju; tako je u srcu Egeja okončana tri i po stoljeća duga latinska vlast.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Ustanak u Jemenu i jemenski pohod Kodža Sinan-paše", "c8218d8e"], "d": ["Zejdijski imam Mutahhar podigao je ustanak pod izgovorom da se porez ubire silom i istisnuo osmansku upravu iz većeg dijela Jemena. Kodža Sinan-paša, poslan iz Istanbula, u pohodu vođenom 1568–1570. zauzeo je Kavkaban nakon duge opsade i ponovo uspostavio osmansku vlast u toj oblasti. Pohod je bio od životne važnosti za očuvanje nadzora nad južnim vratima Crvenog mora i trgovačkim putem Indijskog okeana.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Odbrambeni savez sa Sultanatom Aceh i pomoć na Indijskom okeanu", "8e835f24"], "d": ["Izaslanici Aceha, koji su od Sulejmana Zakonodavca zatražili pomoć protiv portugalskih napada, nakon sultanove smrti kod Sigeta iskazali su odanost Selimu II i s njim potpisali odbrambeni ugovor. Sultan je naredio da se iz Aleksandrije pošalju topovi, puške, municija i majstori; za upućivanje u indijske vode pripremljeno je sedamnaest ratnih brodova. Širenje ustanka u Jemenu spriječilo je isplovljavanje flote, ali su osmanski tobdžije i majstori koji su stigli u Aceh ostavili trajan trag u toj oblasti.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Iskrcavanje na Kipar: zauzimanje Limasola", "9074ccc9"], "d": ["Osmanska vojska koja se iskrcala na otok bez većeg otpora zauzela je Limasol i idućeg dana uputila se prema Larnaki. Budući da domaće stanovništvo nije bilo zadovoljno venecijanskom upravom i pomagalo je osmanske snage, ni u Larnaki nije bilo ozbiljnog otpora; pristanište Tuzla (kod Larnake) postalo je baza za iskrcavanje vojske i opreme. Venecija je odbranu nagomilala u Nikoziji i Famagusti; upravitelj Pafosa iskazao je pokornost serdaru tek nakon pada Nikozije.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Osvajanje Nikozije", "413d866b"], "d": ["Nakon opsade koja je počela 25. jula 1570. i trajala četrdeset pet dana, Nikozija, glavni grad Kipra pod venecijanskom upravom, predala se osmanskoj vojsci. Pad središta otoka sveo je venecijanski otpor na tvrđavu Famagustu. Osvajanje je snažno odjeknulo na Zapadu i ubrzalo proces koji je doveo do stvaranja flote Svete lige pod papinim vodstvom.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Predaja Kirenije — sjeverna obala Kipra", "39fdeea5"], "d": ["Pad Nikozije 9. septembra uz pokolj slomio je otpor na sjeveru Kipra. Tvrđava Kirenija, iza planina Pentadaktilos (Beşparmak), kad je saznala za sudbinu prijestolnice, osam dana kasnije predala se uz uslove, a posadi je dozvoljeno da napusti otok. Na otoku je venecijanska zastava ostala samo u Famagusti; i ona će izdržati još jedanaest mjeseci.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Obnova mornarice nakon Lepanta", "db51fe44"], "d": ["Prvi zadatak Kilič Ali-paše, postavljenog za kapudan-pašu nakon poraza kod Lepanta, bio je obnova mornarice koja je pretrpjela teške gubitke; brodogradilišta su tokom zime 1571–1572. radila bez prekida. U junu 1572. u Sredozemno more isplovila je nova flota od oko 250 galija i 300 galija dobrovoljnih reisa. Ovaj brzi oporavak pokazao je da Lepanto nije trajno slomio osmansku pomorsku moć.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Istanbulski mir s Venecijom — priznanje Kipra", "4d08ef50"], "d": ["Venecija, ostavši sama nakon raspada Svete lige, sklopila je zaseban mir s Osmanlijama, zvanično priznala da Kipar pripada Osmanskoj državi i pristala platiti ratnu odštetu. Ugovor je jasno pokazao da pobjeda kod Lepanta nije kršćanskom svijetu donijela političku korist. Venecija će nakon toga sedamdeset godina izbjegavati neposredan rat s Osmanlijama.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Smrt Selima II", "c289f5ee"], "d": ["Selim II nakon pada oko dva mjeseca nije mogao izaći na divan i umro je. Njegova smrt držana je u tajnosti u saraju dvanaest dana, dok iz Manise u Istanbul nije stigao njegov stariji sin Murat. Izvori se razilaze oko dana smrti: Selaniki navodi 15. decembar; Gerlach, Mehmed b. Mehmed i Dženabi navode 13. decembar.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Objava smrti Selima II i stupanje na prijestolje Murata III", "84334d70"], "d": ["Smrt Selima II i stupanje na prijestolje Murata III, dovedenog iz Manise, zvanično su objavljeni 22. decembra 1574. Novi sultan ostat će na prijestolju dvadeset jednu godinu, a njegova vladavina pamtit će se po dugim ratovima s Iranom na istoku, po predvečerju Dugog rata na zapadu i po kvarenju akče u unutrašnjosti. Do smrti Mehmed-paše Sokolovića 1579. u upravljanju državom trajao je stari poredak.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Bitka kod Vadi al-Mahazina (Alcácer Quibir) — Abdulmelik, uz osmansku podršku, uništio portugalsku vojsku", "21280dac"], "d": ["Abdulmelik, koji je uz osmansku podršku došao na prijestolje Maroka, uništio je kod Vadi al-Mahazina veliku vojsku portugalskog kralja Sebastijana; budući da su u bitki poginula čak tri vladara, u zapadnim izvorima naziva se 'Bitka tri kralja'. Portugalska vojna moć se urušila, a zemlja je ubrzo prešla u španske ruke. I Abdulmelik je poginuo u bitki; njegov brat i nasljednik Ahmed el-Mansur o pobjedi je izaslanstvom obavijestio Istanbul. Odnosi dviju država nisu bili odnosi harača ili vazalstva, nego su ostali na nivou razmjene izaslanika i darova, a ubrzo su se zbog pitanja darova zaoštrili.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Stanovnici Derbenta iskazali odanost Lala Mustafa-paši — Demirkapija pod osmanskom upravom", "9c55aeff"], "d": ["Za širvanskog pohoda delegacija od sedam stanovnika Derbenta otišla je serdaru Lala Mustafa-paši, koji je bio u Erešu, i iskazala mu odanost. Derbent (Demirkapija), koji zatvara uski prolaz između Kavkaskog zida i Kaspijskog jezera, kao obavezni prolaz kopnenih puteva sa sjevera, imao je ključnu ulogu u zadržavanju Širvana. Osmanska vlast ovdje je trajala do 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Osvajanje Širvana: zauzimanje Šamahija", "9afae4c1"], "d": ["Vojska koja se nakon pobjede kod Čildira otvorila prema Kavkazu ušla je u Širvan, najbogatiju safavidsku pokrajinu na obali Kaspijskog jezera, i zauzela glavni grad Šamahi. Ozdemiroglu Osman-paša postavljen je ovdje za beglerbega, čime je sjeverni krak Puta svile stavljen pod osmanski nadzor. Širvan će postati front koji je u dvanaestogodišnjem istočnom ratu najčešće mijenjao gospodara i najskuplje koštao.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Zauzimanje Bakua — izlazak na obalu Kaspijskog jezera", "eb5adab8"], "d": ["Kao posljednja karika širvanske akcije zauzeta je luka Baku na zapadnoj obali Kaspijskog jezera. Naftni izvori u okolini grada bili su već tada poznat izvor prihoda, a luka je bila izlazna tačka iranske svile koja je dolazila preko Kaspijskog jezera. Tako je Osmanska država prvi i jedini put u historiji imala obalu na Kaspijskom jezeru.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Osvajanje Erivana (Revana) i gradnja tvrđave", "7f623b7b"], "d": ["Ferhad-paša, koji je u Karsu dobio naredbu da ode u Erivan i ondje sagradi tvrđavu, krenuo je na Erivan, a grad je početkom ramazana 991 (sredinom septembra 1583) stavljen pod osmanski nadzor. U Erivanu, koji drži sjeverna vrata doline Araksa, sagrađena je nova i velika tvrđava; grad je postao sjedište beglerbegluka. Erivan, na sredini vojnog puta između Karsa i Tabriza, bio je logistička okosnica istočnog fronta. Tvrđava je sagrađena toliko čvrsto da je sljedećih dvjesto godina bila stalna meta osmansko-iranskih ratova.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Aneksija Karabaha i Gandže", "29abaead"], "d": ["Kao posljednji dobitak desetogodišnjeg istočnog rata Ferhad-paša je 1588. krenuo na Gandžu i 1. septembra ušao u grad; oblast Karabah između Kure i Araksa i njeno središte Gandža stavljeni su pod osmansku upravu. Tako su se ujedinili Širvan, Erivan i Karabah i na Kavkazu nastala neprekinuta osmanska linija. Ferhad-pašin mir potpisan 1590. potvrdit će tu granicu, ali će dobitak moći biti zadržan samo dvadeset godina.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Osvajanje Bihaća", "651a7275"], "d": ["Bosanski beglerbeg Telli Hasan-paša, nakon što je u novembru 1591. zauzeo Ripač, isturenu tvrđavu Bihaća, 1592. osvojio je i sam grad i tvrđavu; nakon desetodnevne opsade zapovjednik Lamberg se predao. Ovo osvajanje pomjerilo je bosansku granicu naprijed duž rijeke Une i bilo je posljednji veliki osmanski dobitak uoči Dugog rata, koji će izbiti godinu kasnije pogibijom Telli Hasan-paše pred Kupom.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Početak osmansko-austrijskog 'Dugog rata'", "bd22c392"], "d": ["Nakon što je bosanski beglerbeg Telli Hasan-paša poražen pred Kupom (kod Siska) i poginuo kao šehid, Osmanska država objavila je rat Austriji i počeo je Dugi rat koji će trajati trinaest godina. Ovaj rat, u kojem je pješadija s vatrenim oružjem imala presudnu ulogu, ubrzao je u osmanskom vojnom ustrojstvu zapošljavanje sekbana i vojnika naoružanih puškama te produbio opadanje timarskih spahija. Rat će se završiti 1606. Žitvanskim mirom.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Kodža Sinan-paša krenuo u pohod na Austriju — prvi pohod Dugog rata", "d4a2f46d"], "d": ["Nakon što je bosanski beglerbeg Hasan-paša poražen pred Siskom i poginuo kao šehid, veliki vezir Kodža Sinan-paša slatkim riječima i obećanjima nagovorio je sultana na rat i krenuo s 12.000 janjičara i drugim jedinicama. Tako je započeo prvi pohod osmansko-austrijskog rata koji će trajati trinaest godina.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Osvajanje Đura (Győr)", "14b75207"], "d": ["Veliki vezir Kodža Sinan-paša, nakon opsade duže od mjesec dana, preuzeo je Đur, smatran ključem puta prema Beču. Pad tvrđave izazvao je veliku paniku u Evropi i bio je najblistaviji osmanski dobitak u Dugom ratu. Međutim, tvrđavu će biti moguće zadržati samo četiri godine.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Smrt Murata III", "1b62e886"], "d": ["Nakon dvadeset jedne godine vladavine, Murat III umro je u danima kada je vlaška vojska spalila Brailu i prodrla do Silistre, te je sahranjen u haremu Aja Sofije. Njegov sin Mehmed III, pozvan iz Manise, deset dana kasnije stigao je u Istanbul i stupio na prijestolje (27. januara 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Gubitak Ostrogona u korist Austrije", "f420d333"], "d": ["U opsadi kojom je zapovijedao Karl von Mansfeld, branioci Ostrogona, ne dobivši dovoljnu pomoć, predali su tvrđavu nadvojvodi Matiji. Završetkom pedesetdvogodišnje osmanske vlasti prekinut je odbrambeni lanac na dunavskoj liniji i Budim se našao pod neposrednom prijetnjom. Tvrđava će se moći povratiti tek deset godina kasnije, 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Osvajanje tvrđave Jegar (Eger)", "3e511629"], "d": ["Nakon trosedmične borbe, snažna tvrđava Jegar, koju Osmanlije ranije nikako nisu mogle zauzeti, pala je predajom branilaca. Ovo osvajanje, kojem je sultan lično prisustvovao, donekle je popravilo moral narušen gubitkom Ostrogona i osnovan je Jegarski ejalet. Zajedno s pobjedom kod Mezőkeresztesa (Hačova), izvojevanom dvije sedmice kasnije, 1596. postala je najuspješnija osmanska godina Dugog rata.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Gubitak Đura (Győr)", "b4ccc679"], "d": ["Jedinice pod zapovjedništvom Miklósa Pálffyja i Adolfa von Schwarzenberga prepadom su raznijele vrata tvrđave i povratile Đur. Gubitak tvrđave, koju je četiri godine ranije Kodža Sinan-paša s velikim mukama osvojio, srušio je isturenu osmansku liniju u Ugarskoj. Iako su iste godine neprijateljske snage koje su opsjedale Budim bile odbijene, ravnoteža rata postepeno se pretvarala u rat iscrpljivanja.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Ustanak Karajazidžija Abdulhalima", "30493b0d"], "d": ["Karajazidži Abdulhalim, koji je okupio sekbane i levende pobjegle iz vojske u Dugom ratu, stavio je pod svoju kontrolu veliko područje u Srednjoj Anadoliji, zauzeo tvrđavu Urfu (novembar 1599) i proglasio se vladarom s titulom 'Halim-šah', šaljući fermane sa vlastitom tugrom. Karajazidži, smatran prvim vođom velikog dželalijskog vala, umro je 1602, a pokret je nastavio njegov brat Deli Hasan. Ustanak je početak perioda 'velikog bijega', kada su anadolski seljaci masovno napuštali svoju zemlju.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Odbrana Kaniže Tirjaki Hasan-paše", "d56a5e6a"], "d": ["Nadvojvoda Ferdinand i njegovi saveznici, želeći povratiti Kanižu osvojenu godinu ranije, opsjedali su tvrđavu više od dva mjeseca; Tirjaki Hasan-paša pružao je otpor sa snagom od 9000 ljudi. Iako nije mogao dobiti pomoć izvana, odbio je opće juriše i ispadima natjerao neprijatelja da se povuče uz teške gubitke. Odbrana je u osmanskoj historiografiji postala legenda, a 'Opsada Kaniže' postala je zaseban književni žanr.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Smrt Mehmeda III i stupanje na prijestolje Ahmeda I", "da735fde"], "d": ["Nakon smrti Mehmeda III 20. decembra, na prijestolje je stupio njegov četrnaestogodišnji sin Ahmed I. To što je bio prvi sultan koji je na prijestolje sjeo kao dijete i bez prethodnog odlaska na upravu sandžaka pokazuje da je praksa odgajanja šehzada u provinciji faktički prestala. Za vladavine Ahmeda I napustit će se bratoubistvo i preći na načelo 'ekberijeta' (nasljeđivanja prijestolja od strane najstarijeg muškog člana).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Povratak Ostrogona", "7330f273"], "d": ["Veliki vezir Lala Mehmed-paša opsjeo je Ostrogon, izgubljen deset godina ranije, i ponovo ga vratio pod osmansku upravu. U istom pohodu oslobođeni su i Pešta i Vac, čime su Osmanlije sredile svoju liniju u Ugarskoj. Ovaj uspjeh omogućio je da se iduće godine u Žitvi za pregovarački stol sjedne s razmjerno jake pozicije; Ostrogon će ostati u osmanskim rukama do 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Pobjeda na Oručkom polju i gušenje ustanka Džanbulatoglua", "30f93532"], "d": ["Džanbulatoglu Ali-paša, koji je u Alepu uspostavio nezavisan bejluk i tražio savez s Toskanom, teško je poražen na Oručkom polju od velikog vezira Kujudžu Murat-paše. Ponovnom uspostavom centralne vlasti u Siriji slomljen je najopasniji krak dželalijskog vala. Dvogodišnji nemilosrdni obračun Kujudžu Murat-paše osigurao je, makar i privremeno, javni red u Anadoliji.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Pobjeda kod Aladžajira i gušenje ustanka Kalenderoglua", "55db0485"], "d": ["Dželalijskog vođu Kalenderoglua, koji je ucjenjivao oblasti Manise i Burse, Kujudžu Murat-paša porazio je kod Aladžajira i primorao ga da pobjegne u Iran. Ovom pobjedom razbijena je posljednja od velikih dželalijskih vojski u Anadoliji. Strogi obračun Kujudžu Murat-paše, za kojeg se prenosi da je pogubljene pobunjenike bacao u bunare koje je dao iskopati, kratkoročno je uspostavio red, ali nije mogao nadoknaditi gubitke Anadolije u stanovništvu i proizvodnji.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Dodjela prve ahdname Holandiji", "5d9d117e"], "d": ["Izaslanik Republike Ujedinjenih nizozemskih provincija Cornelis Haga uspio je od Ahmeda I dobiti ahdnamu istog obima kao one date Francuskoj i Engleskoj. Holandija je tako stekla pravo na poslanstvo u Istanbulu, na otvaranje konzulata u osmanskim lukama i na trgovinu pod vlastitom zastavom. Ova ahdnama simbolizira ulazak na osmansko tržište sjevernih pomorskih sila, koje su u sredozemnoj trgovini zauzele mjesto Venecije.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Smrt Ahmeda I i stupanje na prijestolje Mustafe I — načelo ekberijeta", "9901c09e"], "d": ["Nakon želučane bolesti koja je trajala pedeset jedan dan, umro je dvadesetosmogodišnji Ahmed I, a na prijestolje je umjesto njegovog sina doveden njegov brat Mustafa I. Time je napušten način nasljeđivanja s oca na sina i faktički je prešlo se na sistem 'ekberijeta', po kojem na prijestolje dolazi najstariji muški član dinastije. Ova prva vladavina, koja je trajala devedeset šest dana, ujedno je početak doba odrastanja šehzada u 'kafezu'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Svrgavanje Mustafe I i stupanje na prijestolje Mladog Osmana (Osmana II)", "e0f552f2"], "d": ["Mustafa I svrgnut je s prijestolja nakon devedeset šest dana pod obrazloženjem da nije zdravog uma, a sultan je postao četrnaestogodišnji sin Ahmeda I, Osman II. Prema predaji koja se oslanja na Hasanbejzadea, u toj odluci o svrgavanju utjecajan je bio kizlar-aga Mustafa-aga. Mladi Osman, sa zamisli da ukine janjičarski odžak i osnuje novu vojsku, smatra se prvim radikalnim imenom osmanskih rasprava o reformama. Ta zamisao koštat će ga života četiri godine kasnije.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Seravski mir — obnova mira s Iranom", "e778aca8"], "d": ["Seravski mir, sklopljen s Iranom nakon poraza kod Pul-i Šikestea, u velikoj je mjeri potvrdio uslove Nasuh-pašinog ugovora iz 1612; godišnja količina svile koju su Safavidi trebali slati smanjena je sa dvije stotine na stotinu tovara. Time je zatvorena druga faza istočnih ratova koji su trajali od 1603. Mir neće biti dugovječan, a rat će se ponovo rasplamsati gubitkom Bagdada 1623.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Hotinski pohod i Hotinski mir", "bc4c823c"], "d": ["Utvrđeni logor koji je Chodkiewicz podigao pred Hotinom protiv velike vojske kojom je lično zapovijedao Osman II nije mogao biti savladan, a višemjesečni juriši nisu donijeli rezultat. Ugovorom potpisanim 9. oktobra rijeka Dnjestar prihvaćena je kao granica, a Poljaci su se obavezali spriječiti kozačke prepade. Pohod koji nije dao rezultate, iako predstavljen kao pobjeda, učvrstio je nepovjerenje mladog sultana prema janjičarima i njegovu namjeru da ukine odžak.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Oduzimanje Hormuza od Portugalaca", "93e5f6cf"], "d": ["Safavidske snage opsjele su i povratile Hormuz, koji je od 1515. bio u portugalskim rukama; i Kešm i Gamrun (Bender Abas) na obali prešli su pod safavidsku upravu, a zaljevska trgovina preselila se u novu luku.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Drugo svrgavanje Mustafe I i stupanje na prijestolje Murata IV", "1b3a9e74"], "d": ["Mustafa I, koji je nakon ubistva Osmana II drugi put doveden na prijestolje, ponovo je svrgnut nakon godinu i tri mjeseca, a sultanom je proglašen jedanaestogodišnji Murat IV. Prvih devet godina državom su faktički upravljali njegova majka Kosem-sultanija i dvorski velikodostojnici. Murat IV od 1632. lično će preuzeti upravu i započeti period stroge centralizacije.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Gubitak Bagdada u korist Safavida", "db81be0c"], "d": ["Nakon pregovora koje je Bekir Subaši, pobunjen u Bagdadu, vodio sa Safavidima, njegov sin Derviš Mehmed, koji je branio unutrašnju tvrđavu, predao je grad snagama šaha Abasa. Gubitak jednog od simboličnih gradova hilafetskog naslijeđa i većeg dijela Iraka izazvao je veliko ogorčenje u Istanbulu. Povratak Bagdada bit će petnaest godina jedini cilj osmanske istočne politike.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Gušenje ustanka Abaza Mehmed-paše sa središtem u Erzurumu", "e6da2729"], "d": ["Erzurumski beglerbeg Abaza Mehmed-paša, koji se pobunio protiv janjičara tvrdeći da želi osvetiti ubistvo Osmana II, godinama je držao Istočnu Anadoliju pod svojom kontrolom i pružao otpor centru. Opsadom Erzuruma veliki vezir Husrev-paša primorao ga je na predaju, nakon čega je pomilovan i postavljen u Bosnu. Okončanje ustanka bilo je preduslov da Murat IV krene u pohod na Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Prvo pogubljenje šejhul-islama: Ahizade Husein-efendija", "a60a58c5"], "d": ["Uz obrazloženje da je posredovao u vojnim neredima i sultanu uputio pismeno upozorenje o sudskom postupku, šejhul-islam Ahizade Husein-efendija pogubljen je u blizini Büyükçekmecea. Kao prvi pogubljeni osmanski šejhul-islam, ovaj slučaj prekinuo je duboko ukorijenjenu tradiciju po kojoj je najteža kazna za pripadnike ilmije bila progonstvo. Događaj se smatra simbolom zaoštrene vlasti Murata IV i narušene ravnoteže između države i uleme.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Murat IV osvaja Erivan (Revan)", "b65a9b73"], "d": ["Murat IV, koji je 28. marta 1635. krenuo iz Istanbula, opsjeo je Erivan 28–29. jula, a 8. augusta preuzeo tvrđavu; zatim je ušao u ispražnjeni Tabriz i dao ga razoriti. U spomen na pobjedu sultan je u Topkapi saraju dao sagraditi Revanski paviljon. Ovaj pohod bio je prvi veliki istočni pohod kojim je sultan lično zapovijedao nakon tridesetogodišnje pauze.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Gubitak Erivana (Revan) u korist Safavida", "fbb8dd25"], "d": ["Nakon povlačenja osmanske vojske, snage šaha Safija opsjele su Erivan i povratile ga za osam mjeseci. Tako brz gubitak tvrđave pokazao je koliko je logistički teško uspostaviti trajnu vlast na Kavkazu. Erivan će i mirom u Kasr-i Širinu 1639. ostati Iranu, a Osmanlije će odustati od pretenzija na Azerbejdžan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Ponovno osvajanje Bagdada", "4d2f27f3"], "d": ["Murat IV, koji je 8. maja 1638. krenuo iz Istanbula, nakon žestoke opsade od četrdeset dana povratio je Bagdad, koji je petnaest godina bio u rukama Safavida; u opsadi je kao šehid poginuo vezir Tajar Mehmed-paša. Osvajanjem grada ponovo je u Iraku uspostavljena osmanska uprava, a sultan je dobio nadimak 'Osvajač Bagdada'. Osvajanje je učvršćeno mirom u Kasr-i Širinu iduće godine, koji je postavio temelje današnje tursko-iranske granice.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Smrt Murata IV i stupanje na prijestolje sultana Ibrahima", "e2ca1ca0"], "d": ["Nakon smrti Murata IV u dvadeset sedmoj godini (po hidžretskom računanju dvadeset osmoj), na prijestolje je stupio njegov brat Ibrahim, jedini preživjeli muški član dinastije. Za vladavine novog sultana, koji je godinama živio u kafezu, dvorski troškovi i borbe za uticaj unutar saraja uzdrmali su državni poredak. Njegovim svrgavanjem i ubistvom osam godina kasnije dogodit će se drugo ubistvo sultana u osmanskoj historiji.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Povratak tvrđave Azov od kozaka", "e5fcf160"], "d": ["Tvrđava Azov, koju su donski kozaci zauzeli 1637, ispražnjena je pred zajedničkom akcijom Sultanzade Mehmed-paše i krimskog hana Mehmeda IV Giraja; kozaci su se povukli zapalivši tvrđavu. Povratak sjevernih vrata Crnog mora okončao je opasno razdoblje u kojem su kozački prepadi sezali sve do Bosfora. Tvrđavu će 1696, ovaj put, zauzeti ruski car Petar I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Početak kretskog pohoda i osvajanje Hanije", "a1b0c77f"], "d": ["Pod izgovorom da su malteški gusari napali osmanski hodočasnički brod i sklonili se na Kretu, Veneciji je objavljen rat, a flota pod zapovjedništvom Jusuf-paše iskrcala je vojsku na otok. Nakon opsade od pedeset četiri dana zauzeta je tvrđava Hanija i uspostavljena prva trajna osmanska baza na Kreti. Tako je počeo najduži rat u osmanskoj historiji; otok će se moći potpuno osvojiti tek dvadeset četiri godine kasnije, 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Osvajanje Retimna — dijeljenje Krete na dvoje", "8f2c4353"], "d": ["Godinu dana nakon zauzimanja Hanije pala je i tvrđava Retimno u središnjem dijelu otoka, a zapadna polovina Krete u cijelosti je ušla pod osmansku upravu. U venecijanskim rukama ostali su samo glavni grad Kandija i istočni vrh; otok je dvadeset tri godine živio podijeljen na dvoje. Zauzimanje Retimna bilo je korak koji je pokrenuo opsadu Kandije — tu je počela najduža opsada u historiji.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Gubitak Klisa u korist Venecije", "5473c22c"], "d": ["Na dalmatinskom bojištu Kretskog (Kandijskog) rata protunapad venecijanskog zapovjednika Leonarda Foscola obuhvatio je i Klis, sjedište sandžaka od 1537; tvrđava je prešla Veneciji. To što su se Osmanlije svom snagom usredsredile na Kretu onemogućilo je povratak ovog gubitka na dalmatinskoj granici — Klis se više nikada neće vratiti pod osmansku upravu; sjedište sandžaka premješteno je u Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Početak opsade Kandije", "13016b10"], "d": ["Nakon zauzimanja Hanije i Retimna, osmanska vojska opsjela je Kandiju, posljednje veliko uporište Venecije na otoku. Ta blokada, koja će trajati dvadeset jednu godinu, ušla je u historiju kao jedna od najdužih opsada u svjetskoj vojnoj historiji. Tokom opsade pokušaji venecijanske flote da zatvori Dardanele prenijet će rat u samo srce Egejskog mora.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Ubistvo velike valide Kosem-sultanije", "9d763f79"], "d": ["Kosem-sultaniju, staru oko šezdeset dvije godine, pronašli su u jednoj sobi harema i ubili glavni lala Uzun Sulejman-aga i njegovi ljudi, koji su postupali po naredbi Turhan-sultanije, majke Mehmeda IV. Smrt ove moćne žene iz dinastije, koja je upravljala državnom politikom tokom vladavine tri sultana, smatra se faktičkim krajem razdoblja zvanog 'sultanat žena'. Autoritet koji je ostao bez nosioca pet godina kasnije otvorio je put Mehmed-paši Ćupriliću da postane veliki vezir s izvanrednim ovlaštenjima.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Poraz kod Dardanela i gubitak Tenedosa i Lemnosa", "e01a1f7e"], "d": ["Velika pomorska pobjeda koju je venecijanski admiral Mocenigo izvojevao pred Dardanelima u junu 1656. gotovo je potpuno uništila osmansku flotu; zatim su zauzeti Tenedos, Lemnos i Samotraka. Venecijanskom blokadom moreuza cijene hrane u Istanbulu naglo su skočile, a proširio se strah od napada na prijestolnicu. Ta katastrofa bila je neposredan razlog da u septembru 1656. Mehmed-paša Ćuprilić bude postavljen za velikog vezira uz uslove i izvanredna ovlaštenja.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Pobjeda kod Dardanela i povratak Tenedosa", "603da863"], "d": ["Flota koju je mobilizirao Mehmed-paša Ćuprilić porazila je 19. jula 1657. venecijansku flotu pred moreuzom; zatim su snage pod zapovjedništvom Kurd-paše 25. augusta povratile Tenedos, a 30. augusta Venecijanci su potpuno ispraznili otok. U novembru je oslobođen i Lemnos, čime je probijena blokada Dardanela i ponovo otvoren put opskrbe Istanbula. Ćuprilić je lično prešao na otok i dao popraviti utvrđenja; taj uspjeh prvi je veliki vojni dobitak doba Ćuprilića.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Osvajanje Ineua (Janove) i erdeljski pohod", "d1089616"], "d": ["Mehmed-paša Ćuprilić, krenuvši u pohod da kazni erdeljskog kneza Đorđa II Rákóczija, koji je prekršio osmansko pokroviteljstvo krenuvši bez dozvole u pohod na Poljsku, krenuo je preko Beograda i zauzeo stratešku tvrđavu Janovu. Postavljanjem novog kneza u Erdelju oštro je podsjećeno na vazalnu vezu. Ovaj pohod bio je prva karika pokušaja Osmanlija da ponovo uspostave autoritet u Srednjoj Evropi. Erdelj je već bio kneževina podložna Osmanlijama; zauzimanje Janove nije bilo osvajanje od strane države, nego izuzimanje te tvrđave vazalnog Erdelja iz kneževske uprave i njeno neposredno pripajanje osmanskom sandžaku; ostatak kneževine zadržao je vazalni status.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Gušenje ustanka Abaza Hasan-paše", "4ba74321"], "d": ["Abaza Hasan-paša, koji je protiv strogih obračuna Mehmed-paše Ćuprilića stekao podršku anadolskih beglerbegova i sekbanskih aga, pokrenuo je veliki ustanak zahtijevajući smjenu velikog vezira. Ustanak je ugušen u Alepu, a njegovi kolovođe uklonjeni; to je bio posljednji zajednički otpor provincijskih paša prema centru. Autoritet Ćuprilića tako je postao neupitan, a položaj velikog vezira ponovo je postao stvarno izvršno središte države.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Osvajanje Varada (Oradea)", "0e6ad300"], "d": ["U okviru pohoda protiv erdeljskog kneza Đorđa II Rákóczija, koji je objavio rat Osmanlijama, zauzeti su tvrđava i grad Varad. Padom jedne od ključnih erdeljskih tvrđava u toj oblasti osnovan je novi osmanski ejalet (Varadski ejalet). Osvajanje je uzbunilo Habsburgovce i bilo jedan od neposrednih uzroka osmansko-austrijskog rata koji će početi tri godine kasnije. Ostala mjesta pripojena istog datuma: Varat. Ni ovdje zemlja nije oduzeta od strane države: Erdelj je već bio vazalna osmanska kneževina; time što je Varad postao ejalet uprava tog grada samo je izuzeta iz vazalne kneževine i neposredno vezana za sultana, baš kao dvije godine ranije u Janovi.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Bitka kod Svetog Gotharda (St. Gotthard)", "61ebc1f2"], "d": ["Osmanske snage koje su prešle rijeku Rabu zaustavila je saveznička evropska vojska pod zapovjedništvom Montecuccolija i pretrpjele su teške gubitke. Bitka se smatra prekretnicom u vojnoj historiji jer je prvi put jasno pokazala nadmoć disciplinirane puščane vatre pješadije nad osmanskim konjičkim jurišem. Uprkos porazu, Osmanlije su uspjele u Vašvarskom miru, potpisanom devet dana kasnije, postići povoljne uslove.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Vašvarski mir", "089c978c"], "d": ["Mirom potpisanim uprkos porazu kod Svetog Gotharda utvrđeno je da Uyvar i Varad ostaju Osmanlijama, da Erdelj ostane neutralan pod osmanskim pokroviteljstvom i da Austrija isplati 'dar' od 200.000 guruša. Ovaj dvadesetogodišnji mir jedan je od rijetkih primjera da strana koja je izgubila rat pobijedi za pregovaračkim stolom. Nezadovoljstvo koje je ugovor izazvao u habsburškoj javnosti hranit će pokret Srednje Ugarske i, posredno, bečki pohod 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Počela uprava deja u Alžiru", "e99faa51"], "d": ["Alžirski odžak i tajfa reisa (gusarski kapetani) smijenili su posljednjeg agu i doživotno izabrali Hadži Mehmeda za deja. Od toga datuma Alžirom nije upravljao beglerbeg kojeg je postavljao Istanbul, nego dej kojeg je lokalni odžak birao iz svojih redova; osmanska veza svela se na spominjanje sultanovog imena u hutbi, sandžak (zastavu) i obavezu učešća u pohodima. Alžir se tako iz ejaleta pretvorio u odžakluk — istu preobrazbu doživjeli su Tunis 1705. s Huseinidima i Tripoli 1711. s Karamanlijama.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Počeo poljski pohod — Mehmed IV i Fazil Ahmed-paša na čelu vojske", "75e15a39"], "d": ["Kako su se nastavljali poljski napadi na ukrajinskog hetmana Petra Dorošenka, koji je stupio pod osmansko pokroviteljstvo, Istanbul je od poljskog kralja zatražio da od napada odustane; kad potvrdan odgovor nije stigao, odlučeno je o pohodu na Poljsku. Veliki vezir Fazil Ahmed-paša s vojskom u kojoj je bio i sultan krenuo je 4. juna 1672. na Poljsku. Pohod će se završiti osvajanjem Kamenice i Bučačkim mirom.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Osvajanje Kamenice i osnivanje Podoljskog ejaleta", "c3f4f6d0"], "d": ["Nakon devetodnevne opsade zauzeta je Kamenica, smatrana najjačom poljskom tvrđavom na istoku; Mehmed IV 2. septembra klanjao je prvu džumu u džamiji pretvorenoj iz katedrale. Tvrđava je postala središte novoosnovanog Podoljskog ejaleta, a osmanska zastava dosegla je najsjeverniju tačku u današnjim ukrajinskim krajevima. Kamenica će do Karlovačkog mira 1699. ostati sjeverozapadni kraj carstva.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa-paša preuzeo Uman od Poljske", "0d3543a0"], "d": ["Kara Mustafa-paša, poslan protiv Poljske, preuzeo je Uman, jednu od tvrđava u poljskim rukama; grad je do Karlovačkog mira ostao pod osmanskom upravom.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Osvajanje tvrđave Čigirin", "a17cedd0"], "d": ["Nakon akcije Melek Ibrahim-paše prethodne godine koja nije donijela rezultat, veliki vezir Kara Mustafa-paša Merzifonlu lično je zapovijedao opsadom utvrđene tvrđave Čigirin (19/21. jula) i zauzeo je 21. augusta. Pad tvrđave, simbola osmansko-ruskog suparništva oko kozačkog hetmanata u Ukrajini, primorao je Rusiju na mir. Taj uspjeh bio je i jedan od izvora samopouzdanja Merzifonlua koje će ga okrenuti prema Beču.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Bahčisarajski mir — prvi zvanični mir s Rusijom", "df82bc0b"], "d": ["Nakon pohoda na Čigirin, pregovorima vođenim uz posredovanje krimskog hana potpisan je dvadesetogodišnji mir između Osmanske države i Rusije, kojim je rijeka Dnjepar (Özü) prihvaćena kao granica. Kao prvi sveobuhvatni ugovor između dviju država, smatra se početnim dokumentom osmansko-ruskih odnosa. Zahvaljujući miru osiguran je istočni front, pa se vojska mogla usmjeriti prema Srednjoj Evropi.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Dodjela berata o kraljevstvu Srednje Ugarske Imri Thökölyju", "3cd8d51d"], "d": ["Protestantski ugarski plemić Imre Thököly, koji se pobunio protiv habsburškog pritiska, od aprila 1682. smatran je 'izabranim kraljem Srednje Ugarske', a 16. septembra budimski beglerbeg Ibrahim-paša uručio mu je znamenja kneževskog dostojanstva. Tako je pod osmanskim pokroviteljstvom stvorena nova vazalna ugarska država. Ta intervencija učinila je rat s Austrijom neizbježnim i pokrenula lanac koji je doveo do Druge opsade Beča iduće godine.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Gubitak Lefkade (Aja Mavra) u korist Venecije", "e6905fee"], "d": ["Flota Venecije, koja je pristupila Svetoj ligi, nakon što je grad izložila topovskoj vatri, zauzela je otok Lefkadu u Jonskom moru. Padom Preveze iste godine slomljen je osmanski nadzor na ulazu u Jadran. Ti gubici bili su početni koraci akcije kojom će Morosini za tri godine zauzeti cijelu Moreju.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Gubitak Korona u korist Venecije", "2ed762bc"], "d": ["Venecijanske snage pod zapovjedništvom Morosinija zauzele su tvrđavu Koron na jugozapadnom kraju poluotoka Moreje; grad će od tada trideset godina ostati pod venecijanskom upravom. Pad Korona bio je prvi veliki uspjeh venecijanske akcije osvajanja Moreje. Tvrđavu je tek 1715. povratila osmanska vojska pod zapovjedništvom Silahdar Ali-paše.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Povratak Atine — povlačenje Venecije", "03393b46"], "d": ["Morosini, koji je u septembru 1687. bombardirao Akropolu i digao Partenon u zrak, nakon zimovanja u Atini shvatio je da se u gradu ne može održati. Zbog kuge, teškoća opskrbe i okupljanja osmanskih snaga venecijanska posada ispraznila je grad i povukla se u Moreju. Tako se Atina bez borbe vratila pod osmansku upravu, ali se razaranje koje je pretrpio Partenon nije moglo popraviti.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) predala se Caraffi — prešla u austrijske ruke", "7f0a8d38"], "d": ["Nakon trodnevne opsade Antonija Caraffe Lipova se predala između 12. i 22. juna 1688. i prešla u austrijske ruke. Osmanlije su kasnije povratile grad, Austrija ga je 1691. ponovo zauzela; u pohodu 1695. Osmanlije su ponovo uspostavile kontrolu. Ostala naselja koja su istog datuma u atlasu prešla od Osmanlija Habsburgovcima: Arad i Világos (Şiria). Za Arad izvor daje samo godinu (MKL, Arad: u osmanskim rukama 1551–1688); dan je preuzet od Lipove, a Világos slijedi lanac Arada (deklarirana približnost). Tvrđave Lugoj (Lugos) i Caransebeş (Karánsebes) također su krajem juna prešle Austriji (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Odbijanje venecijanske opsade Negroponta", "aae7e6a0"], "d": ["Nakon zauzimanja Moreje Morosini se okrenuo Egeju i opsadom dužom od tri mjeseca pokušao zauzeti Negropont; međutim, pred utvrđenjima ojačanim u zimu 1687–1688. i otporom posade morao se povući uz teške gubitke. Taj neuspjeh zaustavio je venecijansko napredovanje na Egeju i uzdrmao Morosinijev vojni ugled. Negropont će i u Karlovačkom miru ostati u osmanskim rukama.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Gubitak tvrđave Kaniže u korist Austrije", "553b45f3"], "d": ["Kaniža, koju je od januara 1690. u strogoj blokadi držala habsburška vojska od 60.000 ljudi, mjesecima se opirala ne dobijajući pomoć, a zatim je izgubljena sporazumom o predaji koji je potpisao posljednji zapovjednik Mustafa-paša. Tako je završena devedesetogodišnja osmanska vlast u tvrđavi koja se pamti po legendarnoj odbrani Tirjaki Hasan-paše. Gubitak Kaniže bio je slom posljednjeg velikog osmanskog uporišta u zapadnoj Ugarskoj.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Smrt Sulejmana II", "d2478080"], "d": ["Sulejman II, doveden na prijestolje 1687. nakon gotovo četrdeset godina u kafezu, umro je bolestan, prateći pripreme vojske, u petak 22. juna 1691. oko podne u Edirnama; vladao je tri godine, osam mjeseci i dva dana. Veliki vezir unaprijed je dao potrebna uputstva da u slučaju sultanove smrti na prijestolje bude doveden njegov brat Ahmed. Dženaza je klanjana istog dana u Alaj-köšku; tijelo je preneseno u Istanbul i sahranjeno u turbetu sultana Sulejmana Zakonodavca, s njegove desne strane.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Stupanje na prijestolje Ahmeda II", "52947b14"], "d": ["Nakon smrti Sulejmana II na prijestolje je u Edirnama stupio njegov četrdesetdevetogodišnji brat Ahmed II. Njegova vladavina pala je u najteže godine ratova sa Svetom ligom; dva mjeseca nakon stupanja na prijestolje, kod Slankamena je poginuo kao šehid veliki vezir Fazil Mustafa-paša. Nasuprot tome, sistem malikane, uveden u njegovo doba, postao je jedna od najvažnijih uredbi koja je dugoročno promijenila strukturu osmanskih finansija.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Smrt Mehmeda IV u Edirnama", "17388b7e"], "d": ["Mehmed Lovac (Avdži), svrgnut 1687, doveden je u Edirne za vrijeme ugarskog pohoda Sulejmana II 1689. i bio je svjedok i vladavine drugog brata Ahmeda II. Umro je u tom gradu koji je veoma volio. Tijelo mu je preneseno u Istanbul i sahranjeno u turbetu njegove majke Turhan-sultanije kraj Nove džamije.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Smrt Ahmeda II u Edirnama", "c6306c08"], "d": ["Ahmed II, čija je četverogodišnja vladavina protekla u ratu, umro je u Edirnama u pedeset drugoj godini od istiske (edema). Tijelo mu je preneseno u Istanbul i sahranjeno u turbetu sultana Sulejmana Zakonodavca. Na njegovo mjesto došao je njegov bratić Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Iranci zauzimaju Basru", "a9cdf3a3"], "d": ["Dok se Osmanska država na zapadu bavila ratovima sa Svetom ligom, Basra je nakon kuge 1690. bila izložena pljački najprije šejha plemena Muntefik Mania, a zatim huvejzanskog kana Feredžulaha. Koristeći tu pometnju, Iranci su 1696. zauzeli grad i u Basri ostavili zapovjednika posade.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Istanbulski mir — prepuštanje Azova Rusiji", "79db4724"], "d": ["U Karlovcima je s Rusijom bilo moguće sklopiti samo dvogodišnje primirje; trajni mir potpisan je u Istanbulu nakon mukotrpnih pregovora od godinu i po. Osmanska država zvanično je Rusiji prepustila tvrđavu Azov, izgubljenu 1696, i okolne zemlje, a krimski han odrekao se godišnjeg danka koji je primao od Moskve. Zauzvrat je Rusija stekla pravo na stalnog poslanika u Istanbulu; time je rusko prisustvo na sjevernoj obali Crnog mora i pravno potvrđeno.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa-paša povratio Kurnu i Basru", "7adb777d"], "d": ["Daltaban Mustafa-paša, nakon Karlovačkog mira postavljen za bagdadskog valiju i basranskog seraskera, krenuo je na jug sa snagama iz Alepa, Rake, Sivasa i Karamana i s riječnom flotom koja je sišla iz Biredžika. Šejhovi okolnih plemena jedan po jedan iskazali su pokornost, iranski zapovjednik Basre Davud-kan napustio je grad, a Kurna i Basra ponovo su ušle pod osmansku upravu.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Smrt Mustafe II", "626c394d"], "d": ["Mustafa II, koji je nakon Edirnskog događaja prepustio prijestolje bratu Ahmedu III, umro je oko pet mjeseci nakon svrgavanja u Edirnama, koje je veoma volio. Bolesti se pridružila i tuga zbog posljednjih zbivanja. Neki zapadni izvori pišu da je u narodu bilo rašireno uvjerenje da je otrovan.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Početak kolemenske (memlučke) uprave u Bagdadu", "abe52618"], "d": ["Postavljanjem Hasan-paše, gruzijskog porijekla, za bagdadskog valiju počelo je u Iraku razdoblje u kojem je umjesto valija imenovanih iz centra vladao sloj upravljača odgojenih iz vlastitih robova. Sistem se potpuno ukorijenio s valijstvom Sulejman-paše 1749, pa Visoka porta više nije mogla imenovati koga želi, nego je morala imenovati jednog od kolemena koji je preuzeo uticaj. Ta poluautonomna struktura, iako je bila korisna u odbrani iranske granice, vijek i po slabila je nadzor središnje vlasti nad Irakom.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Uspostava dinastije Huseinida u Tunisu", "cb1a98f9"], "d": ["U praznini vlasti nastaloj nakon što su alžirske snage upale u Tunis, spahijski aga turskog porijekla Husein b. Ali preuzeo je vlast nad bejlukom i stekao legitimitet iskazavši odanost osmanskom sultanu. Dinastija koju je osnovao vladala je Tunisom 1705–1735. i 1756–1957; upravu odžaka zamijenio je bejlučki poredak nasljedan s oca na sina. Tako je nastao prvi primjer dinastijskih struktura u sjevernoafričkim odžacima, vezanih za centar, ali faktički autonomnih.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Oduzimanje Orana i Mers el-Kebira od Španaca", "b67ce06a"], "d": ["Snage beglerbega alžirskog odžaka nakon duge opsade zauzele su Oran i njegovu luku Mers el-Kebir, koji su dva stoljeća bili u rukama španskog garnizona. Bio je to najveći uspjeh koji su sjevernoafrički odžaci pod osmanskim pokroviteljstvom ostvarili protiv Španije u zapadnom Sredozemlju, a njime je osigurano zapadno krilo Alžira. Grad će 1732. ponovo pasti pod špansku okupaciju, ali će 1792. biti konačno vraćen.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Prutski mir — povratak Azova i Taganroga", "bac5d2a1"], "d": ["Ugovor od sedam tačaka, potpisan predajom ruske vojske opkoljene na Prutu, predvidio je povratak tvrđave Azov s njenim zemljištem i municijom Osmanlijama. Utvrđenja Taganrog, Kamenka i Jenikale trebala su biti srušena, a strane u toj oblasti neće graditi nove tvrđave. Urušio se sistem flote i baza koji je Petar I šesnaest godina gradio u Voronježu i Azovu; ruski izlazak na Crno more odgođen je za otprilike pedeset godina.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Uspostava dinastije Karamanli u Tripoliju", "e1105d4a"], "d": ["U Tripoliju, iscrpljenom sukobima aga odžaka, konjički oficir Ahmed Karamanli preuzeo je vlast i svoj položaj ozvaničio beratom o beglerbeglučkom zvanju dobijenim iz Istanbula. Preko Ahmed-paše, njegovog sina Mehmed-paše i unuka Jusuf-paše nastala je dinastija koja je trajala od 1711. do 1835; pojavila se poluneovisna struktura koja je stvorila vlastitu flotu i neposredno potpisivala ugovore s evropskim državama. To razdoblje završilo se tek 1835, kad je ejalet neposredno vezan za centar.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Edirnski mir s Rusijom", "14901a70"], "d": ["Kako obećanja data na Prutu nisu ispunjena, rat je još dva puta objavljivan, a napokon, kad su Rusi prihvatili obaveze, u Edirnama je potpisan trajni mir. Ugovor je potvrdio prutske uslove; Rusija se neće miješati u poljske poslove, povući će se s kozačkih zemalja i neće sprečavati švedskog kralja Karla XII (Demirbaš Šarla) da se vrati u svoju zemlju. Tako zatvaranje sjevernog fronta omogućilo je Osmanskoj državi da se okrene prema Moreji i venecijanskom frontu. Ostala mjesta pripojena istog datuma: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Objava rata Veneciji — priprema pohoda na Moreju", "d970b122"], "d": ["Uz obrazloženje da Venecija pomaže crnogorske pobunjenike, da otima osmanske trgovačke brodove i da teškim porezima ugnjetava Moreju koju je stekla Karlovačkim mirom, u divanu je donesena odluka o ratu. Pohod koji je pripremio veliki vezir Silahdar damat Ali-paša iduće godine će se, za manje od sto dana, završiti povratkom cijelog poluotoka Moreje. Međutim, taj uspjeh pokrenut će Austriju i 1716. otvoriti vrata znatno težeg rata.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos (Istendil): predaja posljednjeg venecijanskog otoka u Egeju", "4abec891"], "d": ["Flota koja je krenula na morejski pohod usput se usidrila pred Tinosom, jedinim otokom koji je Veneciji ostao u Egeju. Otok, koji je zahvaljujući latinskom stanovništvu nosio venecijansku zastavu još stotinu pedeset godina iako je Naksoski dukat pao 1566, predao se bez krvi nakon kratke opsade. Tako je izbrisan posljednji venecijanski trag u Egejskom moru i more je u cijelosti postalo osmansko unutrašnje more.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Osvajanje Nauplije (Anabolu) — ključna tvrđava Moreje", "62a5808a"], "d": ["Anabolu, venecijanska prijestolnica u Moreji i najjače utvrđenje, pala je zauzimanjem tabije Palamidi nakon devetodnevnog bombardovanja. Tako brzo zauzimanje tvrđave slomilo je otpor na ostatku poluotoka. Povratak Moreje, izgubljene u Karlovcima, faktički je ovdje dovršen. Ostalo naselje koje je istog datuma u atlasu prešlo od Venecije Osmanlijama: Argos — slijedi lanac matičnog središta Nauplije (TDV anabolu; deklarirana približnost).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Predaja Modona", "43faa909"], "d": ["Nakon pada Nauplije tvrđava Modon na jugozapadnom kraju Moreje opsjednuta je s kopna vojskom, a s mora flotom i ubrzo se predala. Ta luka, koju je Venecija dvjesto godina koristila na svojim pohodima po istočnom Sredozemlju, bila je obavezna usputna tačka gdje su brodovi uzimali vodu i namirnice. Njen gubitak okončao je manevarsku sposobnost venecijanske flote u Egeju.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Predaja Korona — dovršetak morejskog pohoda", "e4b9c8a4"], "d": ["Predajom tvrđave Koron, koja drži ulaz u Mesenijski zaljev, venecijanska uprava na poluotoku Moreja potpuno je okončana. Poluotok izgubljen u Karlovcima u cijelosti je vraćen samo tri mjeseca nakon početka pohoda. U nastavku istog pohoda, u septembru 1715, od Venecije je oduzet i otok Lefkada (Aja Mavra) u Jonskom moru. Ta brzina primorala je Veneciju da uvuče Austriju u rat i tri godine kasnije otvorila put koji je vodio u Požarevac.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Zauzimanje otoka Kitere (Čuha)", "494de6c6"], "d": ["Otok Kiteru na južnom kraju Moreje flota je preuzela nakon dovršetka osvajanja poluotoka. Otok koji nadzire prolaz između Jonskog i Egejskog mora bio je isturena stražarnica kojom je Venecija nadzirala te vode. Ali nije ostao jedini zadržani osmanski otok: tri godine kasnije Požarevačkim mirom vraćen je Veneciji.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austrija i Venecija sklopile savez — vrata osmansko-austrijskog rata 1716–1718.", "99511ca2"], "d": ["Nakon što su Osmanlije povratile Moreju od Venecije, Austrija je, tvrdeći da je prekršen Karlovački mir, potpisala savez s Venecijom; princ Eugen u pismu velikom veziru zatražio je povrat mjesta oduzetih Veneciji. Na vijećanju u logoru Davutpaša, pod pritiskom velikog vezira Ali-paše, objavljen je rat Austriji, a za to je od šejhul-islama uzeta fetva.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Veliki vezir Ali-paša krenuo u pohod na Austriju", "2fbdce42"], "d": ["Nakon objave rata Austriji serdar-ekrem Ali-paša krenuo je s vojskom većom od 100.000 ljudi u pohod na Austriju; flota se istog ljeta usmjerila prema Krfu. Vojska će iz Beograda krenuti na Petrovaradin, a u porazu početkom augusta veliki vezir poginut će kao šehid.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Poraz kod Petrovaradina — pogibija damat Ali-paše", "265c1d81"], "d": ["Osmanska vojska, koja je preko Beograda prešla Dunav, sukobila se pred Petrovaradinom s austrijskim snagama pod zapovjedništvom princa Eugena; iako je u prvom naletu janjičarski juriš ugrozio neprijateljske rovove, slomom konjičkog krila redovi su se raspali. Veliki vezir Silahdar damat Ali-paša pogođen je u čelo i poginuo kao šehid, a logor i artiljerija potpuno su pali u neprijateljske ruke. Ovaj poraz, koji osmanske kronike nazivaju 'godinom Petrovaradina', bio je prva karika lanca koji je vodio do gubitka Temišvara i, iduće godine, Beograda.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Neuspjeh opsade Krfa", "b2aa7011"], "d": ["Morejski serasker Kara Mustafa-paša napadao je Krf s kopna, a kapudan-paša Džanim Hodža Mehmed-paša flotom s mora; otok je bio ključna venecijanska baza na Jadranu. Međutim, izuzetno snažna utvrđenja tvrđave, pojačanja koja je dovela venecijanska flota i vijesti o porazu s dunavskog fronta doveli su do dizanja opsade. Neuspjeh u zauzimanju Krfa ugasio je polet stvoren ponovnim osvajanjem Moreje i težište rata pomjerio u Ugarsku.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Gubitak Temišvara u korist Austrije", "27fe1365"], "d": ["Nakon poraza kod Petrovaradina princ Eugen krenuo je izravno na Temišvar, a tvrđava je nakon opsade duže od četrdeset dana predana uz pogodbu. Grad osvojen 1552. u doba Sulejmana Zakonodavca, koji se 164 godine kao sjedište beglerbegluka smatrao istočnim stubom odbrane Ugarske, tako je izgubljen. Padom Temišvara cijeli Banat prešao je Austriji, a osmanska granica potisnuta je južno od Dunava. Ostala naselja koja su istog datuma u atlasu prešla od Osmanlija Habsburgovcima: Csákóvár, Facset i Karánsebes (Caransebeş) — uz predaju Temišvarskog ejaleta (TDV timisvar; dan na nivou mjesta nije naveden u izvoru, lanac matičnog središta, deklarirana približnost).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Predaja tvrđave Haram (Nova Palanka) Austriji — izgubljena dunavska obala Banata", "38ee4c6d"], "d": ["Austrijski konjički general Mercy, zadužen da nakon pada Temišvara zauzme preostali Banat, krenuo je 14. novembra na Haram (Nova Palanka) na obali Dunava; kad je 16. novembra stigao do tvrđave, osmanska posada od 200 ljudi istakla je bijelu zastavu i predala se uz uslov slobodnog povlačenja. Tako je i dunavska linija Južnog Banata, u osmanskim rukama od 1552, prešla Austriji. Ostalo naselje koje je istog datuma u atlasu prešlo od Osmanlija Habsburgovcima: Vršac — slijedi lanac matičnog središta Harama (Bánlaky 0019/1703; deklarirana približnost).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Požarevački mir — Moreja dobivena, Beograd i Banat izgubljeni", "d46aa216"], "d": ["Moreja je vraćena od Venecije, ali je Austrija, koja je stupila u rat, pobjedama kod Petrovaradina i Beograda sjela za pregovarački sto u nadmoćnom položaju. Ugovor potpisan uz posredovanje Engleske i Holandije ostavio je Moreju Osmanlijama, a zauzvrat je Austriji prepušten Beograd zajedno sa Sjevernom Srbijom, Banatom i Malom Vlaškom; po riječima TDV-a 'Sjeverna Bosna potpuno je prepuštena Austriji' — tvrđave uz Savu, kao što su Bosanska Dubica i Bosanski Brod, od tog dana na karti prelaze Austriji (tačnu granicu komesari su povlačili jednu po jednu, TDV te tvrđave ne navodi po imenu); Venecija je, pak, zadržala položaje na jonskoj obali kao što su Preveza i Kitera. Trgovačkom ahdnamom potpisanom istog dana carina na austrijsku robu smanjena je s pet na tri posto. Ugovor je, potvrđujući povlačenje Osmanske države iz Srednje Evrope, otvorio dvadesetsedmogodišnji mir, koji je postavio temelje Doba tulipana (1718–1730): pod upravom damat Ibrahim-paše Nevšehirlija prva osmanska štamparija (1727, Ibrahim Muteferika), prevodilački odbori, zapažanja o vakcini protiv boginja i novi dvorsko-kulturni život plod su tih mirnih godina. Ostala naselja koja su istog dana u atlasu promijenila gospodara: Krajova (Craiova), Rimnik (Râmnicu Vâlcea) i Turnu Severin (Mala Vlaška/Oltenija, od Osmanlija Austriji) te Lefkada (Aja Mavra) (od Osmanlija Veneciji; TDV ayamavra: 1718. Požarevačkim mirom otok je prepušten Veneciji). U Maloj Vlaškoj Austriji prelazi i Târgu Jiu; Veneciji prelaze Vonitsa (Voniče, TDV pasarofca-antlasmasi) i otok Kitera (TDV cuka-adasi: 3. član požarevačkog ugovora).", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Istočni pohod: zauzimanje Tbilisija i početak rata s Iranom", "78343dc2"], "d": ["Kako se safavidska država raspadala pod afganistanskom invazijom, a Rusija silazila na obale Kaspijskog jezera, Osmanska država poslala je vojsku na istok da praznina ne bi u potpunosti ostala pod ruskim uticajem. Zauzimanjem Tbilisija Gruzija je pripojena osmanskoj upravi; zatim je nastavljeno napredovanje prema Gandži, Erivanu i Nahičevanu. Taj pohod, vođen iza miroljubivog lica Doba tulipana, bio je početak duge istočne pustolovine koja će trajati trinaest godina i završiti vraćanjem svih osvojenih mjesta.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Iranski pohod 1723: ulazak u Širvan i Gruziju", "c81189fc"], "d": ["Kad se safavidska država urušila pod afganistanskom invazijom, pod obrazloženjem da treba spriječiti silazak Rusije na obale Kaspijskog jezera pokrenut je pohod na istok. Erzurumska vojska preko Gruzije ušla je u Tbilisi, a širvanska kolona u Šamahi, te su vraćene zemlje izgubljene sto trideset godina ranije. Taj pohod bio je posljednje veliko osmansko napredovanje na Kavkazu.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Zauzimanje Kermanšaha — vrata Zagrosa", "ad14799f"], "d": ["Bagdadska vojska, prešavši zagroske prolaze, zauzela je Kermanšah, smatran zapadnim vratima Irana. Grad je ležao na karavanskom i vojnom putu od Bagdada do Isfahana, a njegovo zauzimanje osiguravalo je istočnu sigurnost iračkog ejaleta. To napredovanje pokrenulo je utrku Osmanlija i Rusije za podjelu raspadajuće safavidske zemlje.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Istanbulska mukasemenama — podjela Irana s Rusijom", "fce8eec2"], "d": ["Da bi se spriječio sukob Osmanlija i Rusije oko raspadajuće safavidske zemlje, uz posredovanje francuskog poslanika potpisan je ugovor o podjeli. Zapadne i južne obale Kaspijskog jezera pripale su Rusiji, a Gruzija, Širvan, Azerbejdžan i gradovi zapadnog Irana Osmanskoj državi. Ta podjela, koja je na papiru izgledala kao veliki dobitak, ubrzo će usponom Nadir-šaha faktički postati ništavna. Prema ugovoru, plodne zemlje Širvana, kao što su Šabran i Muškur, ostale su na ruskoj strani (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Zauzimanje Nahičevana", "bdf14d0a"], "d": ["Osmanske snage koje su napredovale duž Araksa zauzele su Nahičevan i Ordubad; i Džulfa je pripojena Nahičevanskom sandžaku. Grad je, kao sjeverozapadna vrata Irana, pripojen novoosnovanom Erivanskom ejaletu. Tako je osmanska granica ponovo dosegla najistočniju liniju iz doba Sulejmana Zakonodavca.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Osvajanje Hamadana", "e1339a97"], "d": ["Vojska koja je od Kermanšaha krenula na istok nakon duge opsade zauzela je Hamadan, na zapadnom pragu iranske visoravni. Grad je bio posljednja velika stanica na putu prema Isfahanu, najistočnijoj tački koju su osmanske vojske mogle dosegnuti od pohoda na dva Iraka. Iste godine s Rusijom potpisana Istanbulska mukavelenama stavila je na papir podjelu raspadajućeg Irana između Osmanlija i Rusije.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Ponovno osvajanje Erivana", "88acabef"], "d": ["Nakon teške opsade od devedeset dana Erivan, ključna tvrđava doline Araksa, ponovo je ušao pod osmansku upravu. Tvrđava sagrađena 1583. i izgubljena 1604. ovaj put je utvrđena jačom posadom. Dužina opsade pokazivala je da osmanska vojska više ne napreduje lako. Nahije Karpi (Üçkilise, tj. Ečmijadzin), Šerur, Maku i Šuregel također su pripojene Erivanskom ejaletu.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Zauzimanje Tabriza — osvajanje Azerbejdžana", "e502a4f7"], "d": ["Tabriz, ponovo opsjednut nakon neuspjelog pokušaja prethodne godine, predao se osmanskoj vojsci nakon žestokih borbi od ulice do ulice. Pod osmansku upravu ušli su i Marand, Maraga i Sovukbulak (Mahabad), pripadajući Tabriskom ejaletu. Iste godine zauzeti su i Lori, Gandža, Ardabil i Horamabad, čime su faktički zaposjednuta područja koja su po Istanbulskoj mukasemenami pripala Osmanlijama. Taj obim dostignut na istoku bio je najdalja granica od doba Ferhad-pašinog mira; ali njeno zadržavanje teško je opteretilo vojsku i riznicu.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Osvajanje Gandže — kraj kavkaskog pohoda", "875bca7a"], "d": ["Gandža, posljednji cilj kavkaske akcije, preuzeta je kao središte Karabaha između Kure i Araksa. Dovršetkom linije Širvan–Erivan–Nahičevan–Gandža Osmanska država na Kavkazu je dosegla obim iz 1590. Ali taj dobitak bio je kratkog vijeka: usponom Nadir-šaha cijela oblast bit će za deset godina vraćena.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Hamadanski mir — pripajanje zapadnog Irana Osmanlijama", "94a29dc3"], "d": ["Ugovorom potpisanim s afganistanskim vladarom Ešref-šahom završen je četverogodišnji rat i pravno priznate zapadnoiranske zemlje koje je zaposjela Osmanska država. Ešref-šah je zauzvrat priznao hilafet osmanskog sultana i obavezao se da se hutba u Iranu uči u sultanovo ime. Ta diplomatska pobjeda bila je kratkog vijeka; protunapad koji je Nadir-šah pokrenuo 1730. u nekoliko godina izbrisat će dobitke ugovora.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hećimoglu Ali-paša zauzeo Urmiju", "eac7f64d"], "d": ["U iranskom pohodu Hećimoglu Ali-paša najprije je zauzeo Urmiju (Rumiju), a zatim 15. novembra 1731. Tabriz, ispražnjen za Osmanlije. TDV ne navodi dan zauzimanja Urmije; poznata je samo godina i to da je zauzeta prije Tabriza.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Ahmed-pašin mir — povrat većeg dijela zapadnog Irana", "590d839f"], "d": ["Nakon pobjede Nadir-šaha kod Malajera i uzastopnih iranskih napada, bagdadski valija Ahmed-paša potpisao je tekst o miru ne savjetujući se s centrom. Prema ugovoru rijeka Araks prihvaćena je kao granica; zapadnoiranski gradovi kao što su Hamadan, Kermanšah, Ardalan, Ardabil i Tabriz vraćeni su Iranu, a Gandža i Tbilisi ostali su Osmanlijama. Taj tekst, dočekan s negodovanjem u Istanbulu, ni Nadir-šah nije smatrao dovoljnim, pa se rat ponovo rasplamsao još prije isteka 1732. Atlas i Kotur, koji slijedi lanac Hoja, smatra da je tog dana prešao od Osmanlija Safavidima (TDV hoy; dan specifičan za Kotur nije naveden u izvoru — deklarirana približnost).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Ponovni gubitak Orana u korist Španije", "20485027"], "d": ["Velika desantna flota koju je poslao španski kralj Filip V stigla je pod zapovjedništvom grofa Montemara pred Oran, porazila snage alžirskog odžaka i povratila grad. Luka osvojena dvadeset četiri godine ranije ostat će šezdeset godina ponovo u rukama španskog garnizona. Ovaj gubitak, koji je pokazao granice snage sjevernoafričkih odžaka u zapadnom Sredozemlju, mogao se nadoknaditi tek konačnim osvajanjem Orana 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reforma humbaradžijskog odžaka po evropskom uzoru i osnivanje Humbarahane", "d980cf2a"], "d": ["Humbaradži Ahmed-paša, Francuz porijeklom koji je stupio u osmansku službu, uz podršku velikog vezira Hećimoglu Ali-paše pretvorio je humbaradžijski odžak u plaćenu jedinicu uređenu po evropskom uzoru. Tri stotine vojnika regrutiranih iz Bosne dobilo je redovnu obuku zasnovanu na računu i geometriji; pripremljeni su novi propisi za ustrojstvo, opremu i penzionisanje, a savremenom tehnikom proizvedeno je sto merzera i pedeset hiljada bombi. Humbarahana, u kojoj se predavala geometrija, smatra se prvom klicom modernog vojnoinženjerskog obrazovanja kod Osmanlija.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Smrt Ahmeda III", "455f7fba"], "d": ["Ahmed III, svrgnut ustankom Patrone Halila 1730, posljednjih šest godina života proveo je u odajama Topkapi saraja namijenjenim svrgnutim sultanima i umro u šezdeset trećoj godini. Sahranjen je u Bahčekapiju, u turbetu svoje bake Turhan-sultanije kraj Nove džamije.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Istanbulski mir — prepuštanje Južnog Kavkaza Iranu", "8c205aab"], "d": ["Drugi iranski rat, koji je trajao četiri godine, nakon poraza na Arpačaju i gubitka Gandže i Tbilisija završen je ugovorom. Osmanska država povukla se sa svih zemalja Južnog Kavkaza i zapadnog Irana koje je zauzela od 1723, a granica se vratila na liniju Kasr-i Širina iz 1639. Od trinaestogodišnjih istočnih pohoda ostali su teško finansijsko breme i ispražnjena riznica; s druge strane, zatvaranje istočnog fronta zbog novog rata s Rusijom bio je životni dobitak.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Pad tvrđave Očakov (Özi) u ruske ruke", "f93e61f3"], "d": ["Ruska vojska pod zapovjedništvom maršala Münnicha opsjela je tvrđavu Očakov na ušću Dnjepra; eksplozijom barutane odbrana se urušila, a tvrđava je pala uz velike ljudske gubitke. Gubitak Očakova, smatranog ključem sjeverozapadne obale Crnog mora, otvorio je Rusima put na Krim i izazvao veliku paniku u Istanbulu. Tvrđavu će iduće godine Rusi isprazniti zbog epidemije i teškoća opskrbe, pa će se vratiti Osmanlijama.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Pobjeda kod Banje Luke — spas Bosne", "f603865a"], "d": ["Kad su austrijske snage ušle u Bosnu i opsjele Banju Luku, bosanski valija Hećimoglu Ali-paša pritekao je u pomoć snagama okupljenim od domaćeg stanovništva i teško porazio brojčano nadmoćnog neprijatelja. Ta pobjeda srušila je austrijski plan zauzimanja Bosne već na prvom koraku, a sjever ejaleta potpuno je povraćen. Banja Luka postala je jedna od prekretnica koje su popravile moral osmanske vojske, koja se poslije 1683. stalno povlačila pred Austrijom.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Pobjeda kod Grocke (Hisarcık) — otvaranje puta prema Beogradu", "2101cdff"], "d": ["Austrijska vojska, koja je napredovala da zaštiti Beograd, upala je u zasjedu u tjesnacu na obali Dunava i u bitki koja je trajala cijeli dan pretrpjela teške gubitke. Dok su se snage maršala Wallisa neuredno povlačile prema Beogradu, osmanska vojska stigla je pred tvrđavu i započela opsadu. Grocka je bila najodlučnija pobjeda na otvorenom polju nad Austrijom od Karlovaca i neposredno je omogućila povratak Beograda.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Niški mir — mir s Rusijom, neutralizacija Azova i zaustavljanje krimskih prepada", "674f974e"], "d": ["Rusija, ostavši sama kad je Austrija u Beogradu pristala na mir, morala je uz posredovanje francuskog poslanika Villeneuvea okončati rat. Utvrđenja tvrđave Azov srušena su, a područje je proglašeno neutralnom zemljom između dviju država; Rusija je prihvatila uslov da ne drži ratne ni trgovačke brodove na Crnom moru. Tako je ruski cilj izlaska na more odgođen za još jednu generaciju, a Osmanska država posljednji put u XVIII stoljeću ustala je od stola s dobitkom.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Očakov se vratio nakon ruske okupacije: po miru 1739. tvrđava predata nakon rušenja", "7ecc2bef"], "d": ["Rusi su Očakov zauzeli 11. jula 1737. Prema miru sklopljenom s Rusijom 1739, utvrđenja tvrđave srušena su, a zatim je ponovo predata Osmanlijama; Osmanlije su Očakov držale do 1788, prije Jaškog mira.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Odbrana Mosula — odbijanje Nadir-šaha", "c03ffbc1"], "d": ["Nadir-šah, koji je zauzeo Kirkuk i Erbil i stigao pred Mosul, četrdeset dana tukao je grad topovima i uzastopno izvodio opće juriše. Odbrana koju je valija Husein-paša el-Dželili vodio naoružavši i gradsko stanovništvo primorala je iransku vojsku da uz teške gubitke digne opsadu. Opstanak Mosula spriječio je gubitak cijelog Iraka i za stoljeće učvrstio uticaj porodice Dželili u gradu.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Dirijski savez — uspostava prvog Saudijskog emirata u Nedždu", "188751bf"], "d": ["Emir Muhammed b. Saud, primivši pod zaštitu u Diriji učenjaka Muhammeda b. Abdulvehhaba, protjeranog iz Ujejne, s njim je sklopio savez kojim je politički autoritet stavio u službu vjerskog poziva. Taj sporazum otvorio je novu historiju porodice Saud i ujedinio raštrkane oazne emirate Nedžda oko jednog pokreta. Ta snaga, koja će se za pola stoljeća protegnuti do Kerbele, Meke i Medine, primorat će Osmansku državu da brani svoju vlast u Hidžazu.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Kerdenski mir — kraj osmansko-iranskih ratova", "1d3a919e"], "d": ["Ugovorom potpisanim nakon posljednjeg četverogodišnjeg rata u cijelosti je obnovljena granica Kasr-i Širina iz 1639; nijedna strana nije stekla teritorij. Uporni zahtjev Nadir-šaha da se džaferijski pravac prizna kao peti mezheb ostao je bez odgovora, a zauzvrat je dogovoreno da iranski hadžije slobodno obavljaju hadž i da se razmjenjuju poslanici. Tako su faktički završeni osmansko-iranski ratovi, duži od dva stoljeća; ta granica uglavnom se održala do danas.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Smrt Mahmuda I i stupanje na prijestolje Osmana III", "30203700"], "d": ["Mahmud I, koji je tokom dvadeset četiri godine vladavine Beogradskim mirom povratio izgubljene zemlje i podržavao reformu humbaradžijskog odžaka, umro je na povratku sa svečanog odlaska na džumu. Na njegovo mjesto došao je brat Osman III, koji je do pedeset osme godine živio u kafezu. Počela je kratka i nemirna vladavina; u doba Osmana III, koji je za tri godine promijenio šest velikih vezira, u državnim poslovima vladao je izražen zastoj.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Smrt Osmana III i stupanje na prijestolje Mustafe III", "3ac10f85"], "d": ["Smrću Osmana III nakon trogodišnje vladavine na prijestolje je stupio Mustafa III, otvoren za reformske ideje i veoma zainteresiran za državne poslove. Novi sultan, oslanjajući se na iskustvo velikog vezira Kodža Ragib-paše, nastojao je srediti finansije i obnoviti vojsku; u to doba osnovani su brzometni topnici barona de Totta. Međutim, rat s Rusijom u koji se ušlo 1768. bacit će sjenu na sve dobitke sedamnaestogodišnje vladavine.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Objava rata Rusiji — incident u Balti i početak rata 1768–1774.", "9c6aabe0"], "d": ["Kad su ruske i kozačke jedinice, progoneći Barsku konfederaciju u Poljskoj, napale i spalile gradić Baltu na osmanskoj granici, divan je donio odluku o ratu, a ruski poslanik zatvoren je u Jedikulu. Rat u koji se ušlo bez ozbiljnih vojnih priprema i s objavom šest mjeseci unaprijed od početka je išao loše. Ta borba, koja će trajati šest godina, pretvorit će se u jedan od najtežih nizova poraza u osmanskoj historiji: napad kod Češme, poraz na Kagulu i okupacija Krima.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Gubitak tvrđave Hotin u korist Rusa", "66d43ea4"], "d": ["Iako su dva pokušaja ruske vojske pod zapovjedništvom kneza Golicina bila odbijena, nakon poraza velikog vezira između Kamenice i Hotina vojska se povukla, a branioci su ispraznili tvrđavu. Gubitak najjačeg osmanskog utvrđenja sjeverno od Dunava bez otpora otvorio je Rusima vrata Vlaške i Moldavije. Obje kneževine okupirane su iste godine; Hotin se mogao vratiti tek 1774. mirom u Küčük Kajnardži.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Poraz na Kagulskom polju", "6f408eaf"], "d": ["Tri sedmice nakon spaljivanja flote kod Češme, glavna osmanska vojska na Dunavu raspala se na Kagulskom polju pred brojčano znatno manjim, ali disciplinovanim jedinicama maršala Rumjanceva. Logor, komora i stotine topova pali su u neprijateljske ruke; jedinice u bijegu pretrpjele su velike gubitke prelazeći Dunav. Uništenje i flote i kopnene vojske istog ljeta dovelo je do uzastopnog pada Kilije, Akermana, Izmaila i Bendera te do okupacije Krima.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Ruska okupacija poluotoka Krima", "217837b0"], "d": ["Ruske vojske, koje su godinu ranije zauzele Budžak, pod zapovjedništvom kneza Dolgorukova prešle su Perekop i preplavile cijeli poluotok Krim. Kan je zbačen, a doveden je proruski Sahib Giraj, čime je učinjen prvi korak ka odvajanju kanata od Osmanlija. Gubitak Krima, koji je tri stoljeća bio sjeverni štit Osmanlija, bio je početak procesa koji je 1774. doveo do nezavisnosti, a 1783. do neposredne aneksije.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Smrt Mustafe III i stupanje na prijestolje Abdul-Hamida I", "42cba8e2"], "d": ["Na mjesto Mustafe III, umrlog u najkritičnijem trenutku ruskog rata, u četrdeset devetoj godini na prijestolje je stupio njegov brat Abdul-Hamid I, koji je četrdeset tri godine proveo u dvorskom kafezu. Novi sultan, preuzevši državu u jednom od najtežih razdoblja, morao se suočiti s teškim uslovima mira u Küčük Kajnardži, koji će se potpisati iste godine. Petnaestogodišnja vladavina proći će u gubitku Krima i novom ratu s Rusijom, a završit će 1789. moždanim udarom koji ga je zadesio dok je čitao vijest o padu Očakova.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Poraz kod Kozludže — poraz koji je vodio u Küčük Kajnardžu", "8e0542f9"], "d": ["Osmanske snage okupljene pred Šumenom poražene su kod Kozludže od združenih kolona Suvorova i Kamenskog, a veći dio vojske se raspao. Ovim porazom na Balkanu nije ostalo snaga za otpor; ruske prethodnice opsjele su Šumen, a štab velikog vezira našao se pod prijetnjom. To što se za manje od mjesec dana sjelo za sto u Küčük Kajnardži i prihvatili izuzetno teški uslovi neposredna je posljedica tog poraza.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Ustupanje Bukovine (Sjeverne Moldavije) Austriji", "190f9caa"], "d": ["Koristeći slabost nastalu nakon mira u Küčük Kajnardži, Austrija je zatražila oblast Bukovine, koja je spajala Moldaviju i Erdelj, i bez rata, prijetnjom i podmićivanjem, dobila tu zemlju. Gubitak te plodne i strateške oblasti jugozapadno od Hotina faktički je prepolovio Moldavsko vojvodstvo. To ustupanje bez ijednog ispaljenog metka smatralo se jednim od najjasnijih pokazatelja da je Osmanska država izgubila moć odvraćanja. Ustupanjem Bukovine 1775. Sučava i Černovci prešli su Austriji (dan nepotvrđen).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Iranska okupacija Basre", "0161e709"], "d": ["Sadik-han, brat zendskog vladara Kerim-hana, nakon jednogodišnje opsade zauzeo je Basru, pa je Osmanska država izgubila svoju najvažniju luku u Basranskom zaljevu. Okupacija je neposredno pogodila indijski trgovački put, prihode od datula i bisera i južnu odbranu Iraka. Grad se mogao vratiti tek 1779, tokom borbi za prijestolje koje su izbile u Iranu nakon smrti Kerim-hana.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Ajnalikavačka konvencija (tenkihnama) — privremeni sporazum o Krimu", "9b3b0468"], "d": ["Dvije države, koje su zbog pitanja ko će doći na čelo Krimskog kanata stigle na ivicu rata, uz francusko posredovanje potpisale su u paviljonu Ajnali Kavak objašnjavajući tekst. Rusija je pristala povući vojsku s Krima, a Osmanska država priznati kanstvo proruskog Šahin Giraja; potvrđeno je sultanovo vjersko pravo hilafeta nad Krimom. Ta krhka ravnoteža, koja će trajati četiri godine, potpuno će se urušiti 1783. kada Rusija neposredno anektira poluotok.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Gradnja tvrđave Anapa — kavkaska odbrambena linija", "be92a80f"], "d": ["Kad je Küčük Kajnardžom izgubljen Krim, radi očuvanja osmanskog uticaja na Kavkazu pristupilo se gradnji nove tvrđave na ušću rijeke Kuban. Anapa, sagrađena na ostacima đenoveške kolonije, sa čaršijom, hamamima i više od dvjesto pedeset dućana ubrzo je postala grad koji je održavao vezu sa čerkeskim plemenima. Tvrđava je četrdeset osam godina ostala najisturenija osmanska stražarnica protiv ruskog silaska na Kavkaz.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Smjena i pogubljenje velikog vezira Halil Hamid-paše", "c44001ca"], "d": ["Reformatorski veliki vezir Halil Hamid-paša, zadovoljstvo čijom je službom Abdul-Hamid I pokazivao u raznim prilikama, iznenada je pred jutro 31. marta 1785. smijenjen i prognan u Gelibolu, a sva imovina mu je zaplijenjena. Najprije su mu dodijeljeni Habeški ejalet, Džedanski sandžak i dužnost šejhul-harema Meke; dok je april 1785. provodio na Tenedosu pripremajući se za put, smijenjen je i s tog valijstva, a po izdatom fermanu o pogubljenju ubio ga je Karaćethudazade Ali, jedan od ljudi Džezairli Gazi Hasan-paše. Odsječena glava poslana je u Istanbul i izložena kod Ortakapije. Prema TDV-u, iako je taj nagli pad tumačen optužbom za zavjeru da se zbaci sultan i na njegovo mjesto dovede šehzada Selim, pravi razlozi mora da su bili ogorčenje zbog njegove šutnje o aneksiji Krima, neprijateljstvo krugova kojima su štetile njegove reforme i protivljenje Gazi Hasan-paše.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Objava rata Rusiji — počeo osmansko-ruski rat 1787–1792.", "3bfb870c"], "d": ["Zbog raskošnog putovanja Katarine II na Krim i njenog uzimanja Gruzije pod zaštitu, divan je donio odluku o ratu s ciljem poništavanja aneksije, a ruski poslanik ponovo je zatvoren u Jedikulu. Međutim, vojska nije bila spremna, riznica je bila prazna, a traganje za saveznicima ostalo je bez rezultata. Petogodišnji rat završit će se padom Očakova uz pokolj, gubitkom Izmaila i teškim uslovima Jaškog mira.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Ulazak Austrije u rat — borba na dva fronta", "ae912290"], "d": ["Na osnovu tajnog saveza koji je s Rusijom sklopio 1781, austrijski car Josip II objavio je rat Osmanskoj državi i krenuo prema Beogradu i Bosni. Osmanska vojska odjednom je morala ratovati na dva fronta: na sjeveru protiv Rusije, na zapadu protiv Austrije. Uprkos pobjedama nad Austrijancima kod Lazaretane, Mehadije i Šebeša, gubitkom Beograda 1789. urušit će se i zapadni front.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Osmansko-pruski savez", "03b88e51"], "d": ["Selim III, koji je čim je stupio na prijestolje tražio saveznike u Evropi, potpisao je s Pruskom ugovor o savezu koji je predviđao uzajamnu pomoć; Pruska se obavezala da objavi rat Rusiji i Austriji, a Osmanska država da ne sklopi mir dok se ne povrati Krim. Bio je to prvi pravi tekst uzajamnog saveza koji su Osmanlije u svojoj historiji potpisale s nekom evropskom državom i pokazivao je da je napušteno klasično shvatanje 'ne može biti saveza s nevjernicima'. Pruska nije ušla u rat, ali je primoravši Austriju na mir otvorila put Svištovskom miru.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Pad tvrđave Izmail i pokolj", "6a296b0c"], "d": ["Tvrđava Izmail, smatrana najjačim utvrđenjem delte Dunava, zauzeta je za jedan dan krvavim općim jurišem koji je organizirao general Suvorov; garnizon i stanovništvo grada u velikoj su mjeri posječeni sabljom. Taj pokolj, koji je imao širok odjek u Evropi, izazvao je dubok šok u osmanskoj javnosti i slomio kičmu dunavske odbrambene linije. Tvrđava će godinu kasnije biti vraćena Jaškim mirom, ali je sudbina rata tada već bila odavno odlučena.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Svištovski mir — zatvaranje austrijskog fronta", "58741f1d"], "d": ["Zahvaljujući pritisku Pruske i tome što je Francuska revolucija zaokupila Austriju na zapadu, dvije države postigle su mir na osnovu predratnih granica. Austrija je vratila sva zauzeta mjesta, uključujući Beograd; Osmanska država prihvatila je samo male ispravke na hrvatskoj granici. Zatvaranje zapadnog fronta pod tim uslovima omogućilo je Osmanskoj državi da svu snagu usmjeri protiv Rusije i ograničilo gubitak u Jaškom miru. Ovim ispravkama na hrvatskoj granici Cetin (Cetingrad) i Drežnik Grad prelaze od Osmanlija Habsburgovcima (TDV zistovi-antlasmasi; Korić 2016, br. 118, 4. član). Oršova (Stara Oršova) jedino je mjesto koje nije vraćeno (Bánlaky 0019/1796); atlas pravni prijenos bilježi pod ovim datumom (faktička okupacija 16. aprila 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Jaški mir — konačni gubitak Krima i granica na Dnjestru", "a56fd194"], "d": ["Ugovorom potpisanim na kraju petogodišnjeg rata rijeka Turla (Dnjestar) prihvaćena je kao granica; lijeva obala rijeke ostala je Rusiji, desna Osmanlijama, a Očakov s okolinom konačno je izgubljen. Osmanska država potpuno je napustila nadu u povratak Krima i pravno priznala aneksiju iz 1783; Vlaška i Moldavija vraćene su uz dvogodišnje oslobođenje od poreza. Prihvaćena je i obaveza ratne odštete od dvanaest miliona guruša, čime je sjever Crnog mora trajno prepušten Rusiji. Ostala mjesta pripojena istog datuma: Izmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Španci evakuiraju Oran i predaju ga Alžiru", "9f95cee6"], "d": ["Kad su u zemljotresu 1790. tvrđava i grad uglavnom razoreni, Španija, koja više nije mogla nositi skupu posadu koju je držala tri stoljeća, sporazumjela se s alžirskim odžakom i bez borbe predala Oran i Mers el-Kebir. Tako je likvidiran i posljednji evropski položaj na sjevernoafričkoj obali. Osmanski Alžir vladao je cijelom obalom trideset osam godina, sve do francuske okupacije.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Faktička vladavina Pazvandoglu Osmana u Vidinu", "0ce70361"], "d": ["Pazvandoglu Osman, koji se pobunio protiv uredbi Nizam-i džedida, natjerao je vidinskog valiju u bijeg, zauzeo grad i utvrdio ga dubokim opkopima duž Dunava. Na vrhuncu moći 1797. okupio je gotovo osamdeset hiljada ljudi i pod kontrolu stavio Nikopolj, Svištov, Ruse, Sofiju i Niš; sebe je predstavljao ne kao pobunjenika, nego kao reformatora. Višemjesečna opsada Visoke porte 1798–1799. ostala je bez rezultata, a on je do smrti 1807. poluneovisno vladao Sjevernom Bugarskom.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Otvaranje Mühendishane-i Berri-i Humajun", "e9a3a34b"], "d": ["Radi obrazovanja topničkih, inžinjerijskih i kartografskih oficira za vojsku Nizam-i džedida, u Hasköyu je otvorena kopnena inžinjerska škola; bila je kopneni pandan Pomorske inžinjerske škole osnovane 1773. U programu su se predavali algebra, geometrija, mehanika, fortifikacija i balistika, a s evropskih jezika prevođene su knjige iz matematike i artiljerije. Ta škola, smatrana korijenom modernog inžinjerskog obrazovanja u Turskoj, priznaje se kao početak današnjeg Istanbulskog tehničkog univerziteta.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Objava rata Francuskoj i savez s Rusijom i Engleskom", "80e95bd7"], "d": ["Nakon Napoleonove okupacije Egipta, Osmanska država, prekinuvši dva i po stoljeća staro tradicionalno prijateljstvo s Francuskom, objavila joj je rat. U istom procesu prvi put u historiji sklopila je savez s Rusijom i dozvolila ruskoj floti da kroz moreuze izađe u Sredozemno more; zatim je potpisan savez i s Engleskom. Zahvaljujući tim savezima Jonski otoci oduzeti su Francuzima, ali je otvaranje moreuza stranoj floti stvorilo presedan koji će kasnije imati tešku cijenu.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Oduzimanje Preveze od Francuza — bitka kod Nikopolisa", "d8e5e892"], "d": ["Kad je 1797. pala Venecijanska Republika, Jonski otoci i na kopnu Preveza, Parga i Vonitsa prešli su u francuske ruke. Janjinski valija Ali-paša Tepelenski, koristeći rat objavljen zbog francuske okupacije Egipta, krenuo je na Prevezu i kod ruševina Nikopolisa izvan grada teško porazio francusku posadu. Tako je ta luka, ostavljena Veneciji u Požarevcu, osamdeset godina kasnije ušla pod osmansku upravu. Butrint (Butrinto) pao je 25. oktobra nakon što je francuska posada digla utvrđenja u zrak i povukla se na Krf (Curlin, Preveza B, 2010; atlas dan preuzima od Preveze) i ušao pod osmansku upravu.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Odbrana Akke — odbijanje Napoleona", "56b5c45b"], "d": ["Napoleon, koji je napredovao iz Egipta prema Siriji, opsjeo je Akku i dva mjeseca uzastopno jurišao; Džezar Ahmed-paša branio je grad uz podršku engleske flote i jedinica Nizam-i džedida poslanih iz Istanbula. Napoleon, prisiljen da digne opsadu i povuče se u Egipat, pred tim je zidinama sahranio san o širenju na istok. Vijest je u Istanbulu dočekana s velikom radošću i smatrana dokazom da je novoosnovana obučena vojska položila prvi ozbiljni ispit.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Vehabijski prepad na Kerbelu", "522341ed"], "d": ["Vehabijske snage koje su krenule iz Nedžda ušle su u Kerbelu, opljačkale grad, razorile turbe hazreti Husejna i ubile više od tri hiljade ljudi. Kolemenski valije Osmanske države u Iraku nisu mogli spriječiti prepad; događaj je izazvao veliku reakciju i u Iranu i u Istanbulu. Taj napad bio je objava da je saudijski pokret prestao biti oazni emirat i pretvorio se u regionalnu silu koja prijeti osmanskim svetim gradovima.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kahetija (Istočna Gruzija) anektirana Rusiji", "3b650c5e"], "d": ["Kartlijsko-kahetinsko carstvo, koje je 1783. prihvatilo rusko pokroviteljstvo i 1795. pretrpjelo razorni iranski pohod, ukinuto je; naredbom od 12. septembra 1801. proglašeno je ruskom pokrajinom i počeo se uvoditi ruski upravni sistem. Gruzija je od tada izgubila nezavisnost; za nekoliko godina pod rusku vlast dospjele su i Megrelija (1803), Imeretija i Gurija (1804), a Rusija se naslonila na osmansku kavkasku granicu. Ovim događajem Gori, Dušeti (Kartli) i Telavi (Kahetija) prešli su Rusiji.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evakuacija Francuza iz Egipta", "00cfdc8c"], "d": ["Kao rezultat združene akcije osmanskih i engleskih snaga s kopna i mora, najprije je preuzet Kairo, zatim Aleksandrija, a francuske snage brodovima su poslane u domovinu. Dok se završavala trogodišnja okupacija, Egipat se na papiru vratio pod osmansku upravu, ali je borba za vlast između kolemenskih begova i albanskih jedinica gurnula zemlju u haos. Ta će praznina za nekoliko godina pripremiti tlo za uspon Mehmed Alije Kavalalija.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Pariški mir — ponovna uspostava mira s Francuskom", "1b76991f"], "d": ["Ugovorom potpisanim nakon evakuacije Egipta ratno stanje između Osmanske države i Francuske zvanično je okončano i obnovljene su stare kapitulacije. Francuskim trgovačkim brodovima dozvoljen je ulazak u Crno more; zauzvrat je Francuska priznala osmanski teritorijalni integritet. Uspostava mira vratila je manevarski prostor vanjskoj politici Selima III, koja se bila stisnula uz Rusiju i Englesku.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Vehabije zauzimaju Taif", "7b791359"], "d": ["Vehabijske snage pod zapovjedništvom Sauda b. Abdulaziza u prvom potezu prema Hidžazu opsjele su i opljačkale Taif; grad je pao kao prva kapija ka svetim zemljama. Za osmanskog sultana, koji je nosio naslov zaštitnika Haremejna, to je bio udarac koji je neposredno uzdrmao legitimitet vlasti. Dva i po mjeseca kasnije ista vojska krenut će na Meku.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Vehabije prvi put zauzimaju Meku", "21157c05"], "d": ["Dva i po mjeseca nakon pada Taifa vehabijske snage ušle su u Meku, srušile turbeta i uspostavile poredak po svom shvatanju; šerif Galib morao se povući u Džedu. Zatvaranje hadžijskih puteva odjeknulo je u cijelom islamskom svijetu i primoralo Istanbul da od egipatskog valije Mehmed Alije zatraži vojnu pomoć. Ta prva vlast trajat će samo tri mjeseca.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Šerif Galib povratio Meku", "83d08dff"], "d": ["Šerif Galib, koji se povukao u Džedu, sa sakupljenim snagama opsjeo je Meku i nakon dvadesetpetodnevne opsade povratio grad od vehabija; hutba se ponovo učila u ime Osmanlija. Ni ta druga vlast neće biti trajna: saudijske snage ponovo će zauzeti grad 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Početak Prvog srpskog ustanka", "0f6e8767"], "d": ["Kad su pobunjeni janjičarski dahije, koji su preuzeli upravu u Beogradu, masovno pogubili srpske prvake, pod vodstvom Karađorđa počeo je oružani otpor. Pokret, koji se u početku vodio samo protiv dahija uz odanost sultanu, ubrzo se pretvorio u nacionalni ustanak koji je tražio autonomiju i nezavisnost. Srpske snage zauzele su Beograd 1806; ovaj ustanak bio je prva karika nacionalističkih pokreta za nezavisnost na Balkanu.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Vehabijska okupacija Medine", "84e310d7"], "d": ["Nakon Meke i Medina je pala u ruke vehabijskih snaga; riznica Ravzai-mutahhare razdijeljena je, a turbeta s kupolama u gradu srušena. Tako su oba sveta grada istovremeno izašla ispod osmanskog nadzora, a hadžijski karavani iz Damaska i Egipta godinama nisu mogli krenuti na put. Medinu je tek sedam godina kasnije, 1812, povratila egipatska vojska pod zapovjedništvom Tosun-paše, sina Mehmed Ali-paše.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Početak rata s Rusijom (osmansko-ruski rat 1806–1812) i zatvaranje moreuza", "ea170804"], "d": ["Kad je Selim III, koji se nakon Napoleonove pobjede kod Austerlitza približio Francuskoj, uprkos ruskom pritisku smijenio vojvode Vlaške i Moldavije, ruske vojske okupirale su obje kneževine i rat je počeo. Osmanska država zatvorila je moreuze ruskoj floti; zauzvrat je i Engleska stala na stranu Rusije i poslala flotu u Istanbul. Taj šestogodišnji rat, isprepleten s Kabakčijevim ustankom i svrgavanjem Selima III, završit će gubitkom Besarabije u Bukureštanskom miru 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Dolazak engleske flote pred Istanbul (Duckworthova akcija)", "195bb58f"], "d": ["Engleska, želeći primorati Osmansku državu da prekine vezu s Francuskom, provela je flotu pod zapovjedništvom admirala Duckwortha kroz Dardanele i usidrila je pred Istanbulom. I uz usmjeravanje francuskog poslanika Sébastianija stanovništvo Istanbula se mobiliziralo, obalne baterije pojačane su u nekoliko dana, a flota se morala povući ne mogavši bombardirati grad; pri povratku je u Dardanelima pretrpjela teške gubitke. To što je prijestolnicu prvi put tako izbliza ugrozila strana flota postavilo je pitanje moreuza u središte evropske diplomacije.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Ubistvo Mustafe IV davljenjem", "eeb75c20"], "d": ["Kad je Alemdar Mustafa-paša doživio prepad i poginuo, a pobunjenici htjeli krenuti na saraj, svrgnuti Mustafa IV zadavljen je po naredbi svog brata Mahmuda II. Tijelo je sahranjeno u Bahčekapiju, u turbetu njegovog oca Abdul-Hamida I; među pobunjenicima proširila se glasina da je tabut prazan.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Sultanijski mir (Kal'a-i Sultanije) — mir s Engleskom i pravilo o moreuzima", "fe282117"], "d": ["Ugovorom potpisanim s Engleskom nakon neuspjeha Duckworthove akcije okončan je rat između dviju država i engleskim trgovcima vraćene su stare povlastice. Odredba u tekstu, poznata kao 'drevno pravilo', zapisala je da u mirno doba nijedan strani ratni brod ne smije proći kroz moreuze. To načelo postalo je pravni temelj svih međunarodnih uredbi koje će tokom XIX stoljeća oblikovati režim moreuza.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Poraz kod Slobozije — opkoljavanje dunavske vojske", "54b60fd1"], "d": ["Veći dio osmanske vojske koja je prešla Dunav kod Rusčuka bio je stisnut kod Slobozije manevrom opkoljavanja koji je Kutuzov izveo s druge obale rijeke i prepušten gladi. Hiljade vojnika morale su se predati; snaga u rukama velikog vezira faktički se istopila, a Visoka porta morala je mjesec dana kasnije zatražiti primirje. Taj poraz neposredan je uzrok pristanka na ustupanje Besarabije u Bukureštanskom miru 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Povratak Beograda i gušenje Prvog srpskog ustanka", "06f56f52"], "d": ["Srpski ustanici, lišeni ruske podrške Bukureštanskim mirom, nisu mogli izdržati zajedničku akciju snaga iz Bosne i Rumelije; Huršid Ahmed-paša ušao je u Beograd i devetogodišnji ustanak potpuno je ugušen. Karađorđe je pobjegao u Austriju, a Smederevski sandžak ponovo je neposredno vezan za osmansku upravu. Međutim, primijenjene oštre mjere dvije godine kasnije pokrenut će drugi i trajni ustanak pod vodstvom Miloša Obrenovića.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Drugi srpski ustanak i vrhovno kneštvo Miloša Obrenovića", "e6e82ad2"], "d": ["Protiv teških mjera primijenjenih nakon gušenja prvog ustanka izbio je novi ustanak pod vodstvom Miloša Obrenovića; ovaj put je Visoka porta umjesto sile izabrala nagodbu. Sklopljenim sporazumom Miloš je priznat kao 'vrhovni knez', a ovlaštenje za ubiranje poreza i vođenje unutrašnjih poslova prepušteno je srpskim knezovima. Ta prva klica faktičke autonomije bila je polazište procesa koji je vodio do fermana 1830. i nezavisnosti 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Vlaški ustanak — Ipsilantijev prelazak Pruta i ustanak Vladimireskua", "67d46a98"], "d": ["Aleksandar Ipsilanti, general u ruskoj vojsci, u ime Filiki Eterije prešao je Prut i pokušao pokrenuti opći grčki ustanak u Vlaškoj i Moldaviji; istih dana Tudor Vladimirescu pokrenuo je i domaće seljake. Dva pokreta nisu se mogla ujediniti: na Ipsilantijev poziv na zajedničku borbu protiv Turaka Vladimirescu je odgovorio 'Ja sam ustao ne protiv Turaka nego protiv Grka' i ubrzo su ga ubili Ipsilantijevi ljudi. Ustanak su osmanske snage ugušile u maju, ali je fanariotski sistem vojvodstva okončan, a plamen ustanka prenio se na Moreju.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Uspostava Druge saudijske države u Rijadu", "34dad3bd"], "d": ["Šest godina nakon pada Dirije 1818. i rušenja prve saudijske države, Turki b. Abdullah istjerao je egipatske garnizone iz Nedžda i uspostavio novi saudijski emirat sa središtem u Rijadu. Nova struktura, izbjegavajući širenje na Hidžaz, radije je ostala u Nedždu i držala se podalje od neposrednog sukoba s osmansko-egipatskim snagama. Ta druga država trajat će do kraja stoljeća i činit će drugu kariku lanca koji vodi do osnivanja današnje Saudijske Arabije. Ostala naselja izgubljena istog datuma: Dirija (Nedžd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Akermanski ugovor — ustupci Srbiji i kneževinama", "c75f15d0"], "d": ["Odmah nakon ukidanja janjičarskog odžaka Osmanska država, ostavši bez vojske, morala je pred ruskim ultimatumom prihvatiti ugovor s teškim uslovima. Potvrđena je autonomija obećana Srbiji, prihvaćeno je da vojvode Vlaške i Moldavije ne mogu biti smijenjene bez ruske saglasnosti, a ruskim trgovačkim brodovima priznata je potpuna sloboda u moreuzima. Kad je Visoka porta dvije godine kasnije zbog grčkog pitanja objavila da ne priznaje ugovor, Rusija će to uzeti kao povod za rat.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Ukidanje timarskog sistema", "84d5d1d6"], "d": ["Godinu dana nakon ukidanja janjičarskog odžaka, oko 5.200 timarskih spahija u pedeset tri sandžaka Rumelije i Anadolije, zajedno s timarskim prihodima, pretvoreno je u konjicu Asakir-i Mansure. Tako je faktički završen timarski režim, četiri stoljeća stara okosnica osmanskog zemljišnog, poreskog i vojnog poretka. Oslobođeni timari preneseni su u državnu riznicu i otvoren je put prelasku na centralno plaćenu vojsku i novčani porez.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Osnivanje Tiphane-i Amire — početak modernog medicinskog obrazovanja", "ac3e57c0"], "d": ["Da bi se za novoosnovanu vojsku Asakir-i Mansure obrazovali liječnici i hirurzi, na prijedlog glavnog liječnika Mustafa Behčet-efendije u Šehzadebašiju otvorena je Tiphane-i Amire. Predavanja su uređena po evropskom programu, a nastava se u početku izvodila na francuskom jeziku; nekoliko godina kasnije osnovana je i Džerahhane-i Amire, pa su dvije ustanove spojene. Ta škola, smatrana početkom modernog medicinskog obrazovanja u Turskoj, priznaje se kao korijen današnjeg Istanbulskog medicinskog fakulteta.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Početak osmansko-ruskog rata 1828–1829.", "9dff4e05"], "d": ["Nakon spaljivanja flote kod Navarina i objave Visoke porte da ne priznaje Akermanski ugovor, Rusija je objavila rat na dva fronta. Budući da je janjičarski odžak tek bio ukinut, a nova vojska bila u fazi formiranja, osmanska odbrana bila je od početka slaba; Rusi su, prešavši Dunav, na istoku zauzeli Kars i Ahalcihe. Ruska vojska, koja je za godinu dana napredovala do Edirna, nametnut će teške uslove Jedrenskog mira 1829. i nezavisnost Grčke.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Prvi ugovor sa Sjedinjenim Američkim Državama", "d737516f"], "d": ["Ugovorom o trgovini i plovidbi, potpisanim nakon višegodišnjih kontakata, SAD su stekle status najpovlaštenije nacije u osmanskoj zemlji i pravo trgovačkog prolaza kroz moreuze. Posebna tajna klauzula predviđala je da Osmanlije po želji mogu graditi brodove u američkim brodogradilištima i kupovati gotove brodove i drvenu građu; američki Senat ratificirao je ugovor, ali je tu tajnu klauzulu odbacio s 27 glasova protiv 18. Put prema brodovima ipak se nije zatvorio: Henry Eckford prodao je 1831. Osmanlijama brod koji je dovezao, a američki majstori koji su radili u Ajnali Kavaku donijeli su floti brodove novog tipa. Ovaj ugovor postao je dokument prvog sveobuhvatnog odnosa koji je Osmanska država uspostavila s nekom neevropskom državom.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Okončanje kolemenske uprave u Bagdadu", "7e1d38a3"], "d": ["Mahmud II, koji je vodio politiku centralizacije, proglasio je pobunjenikom bagdadskog valiju Davud-pašu, koji nije slao traženi novac i koji je dao ubiti činovnika poslanog iz centra. Snaga pod zapovjedništvom Ali Riza-paše nakon opsade od devedeset dana zauzela je grad, a gotovo svi kolemeni su uklonjeni. Tako je okončana poluneovisna kolemenska uprava koja je trajala od 1704, a Irak ponovo neposredno vezan za centar.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Osnivanje Mekteb-i Harbije u kasarni Mačka", "bf31c7d9"], "d": ["Da bi se Asakir-i Mansure-i Muhammedije obezbijedili oficiri obrazovani po evropskom uzoru, u kasarni Mačka otvoren je Mekteb-i Funun-i Harbije. Učenicima su se predavali matematika, kartografija, fortifikacija i strani jezici; ubrzo su učenici poslani u Beč i Pariz radi jačanja kadra. Ta škola postala je mjesto rođenja tradicije školovanih oficira u osmanskoj vojsci, a time i nove generacije vojnika-intelektualaca koja će se pojaviti krajem XIX stoljeća.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Neposredno pripajanje Tripolija centru — kraj dinastije Karamanli", "faabcb96"], "d": ["Zbog borbi za prijestolje u porodici Karamanli i sve većeg evropskog pritiska nakon francuske okupacije Alžira 1830, Visoka porta neposredno je intervenirala u Tripoliju. Flota poslana iz Istanbula ušla je u grad, posljednji karamanlijski beg smijenjen je i doveden u Istanbul, a ejalet predat valiji imenovanom iz centra. Dok se završavalo 124 godine dugo dinastijsko razdoblje, učvršćen je posljednji dio teritorija u Sjevernoj Africi kojim je Osmanska država neposredno upravljala.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Ukidanje defterdarstva i osnivanje Ministarstva finansija", "89f8125e"], "d": ["Ukinut je položaj defterdara, glave klasičnog osmanskog finansijskog poretka, i osnovano Ministarstvo finansija, ministarstvo po evropskom uzoru, a raspršene riznice objedinjene su pod jednom rukom. Iste godine i druge jedinice Visoke porte preuređene su pod nazivom ministarstava, čime se prešlo na moderno ustrojstvo vijeća ministara. Ta uredba bila je jedan od najvažnijih koraka koji su pripremili upravnu infrastrukturu Tanzimatskog fermana, proglašenog godinu kasnije.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Englezi se nastanjuju u Adenu", "ddbd556b"], "d": ["Engleska je, pozivajući se na sporazum o trgovini i prijateljstvu koji je 1802. potpisala sa sultanom Lehedža Ahmedom b. Abdulkerimom, iskrcala vojsku u adenskoj luci i preuzela nadzor nad gradom. Ta luka, koja je držala ušće Crvenog mora, postala je ključna tačka britanske imperijalne strategije kao stanica za opskrbu ugljem na putu za Indiju. Iako se osmanska pretenzija na Jemen na papiru nastavljala, faktička vlast na južnoj obali nakon ovog datuma više se nikada nije vratila.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Povratak na obalu Tihame: zauzimanje Hodeide, Zebida i Moke", "353982d2"], "d": ["Na obalu Jemena, ostalu bez gospodara povlačenjem egipatske vojske 1840, iskrcale su se snage pod zapovjedništvom Tevfik-paše uz nadzor mekanskog šerifa i pripojile luke Hodeidu, Zebid i Moku osmanskoj upravi. Iako se željelo napredovati do Sane, zbog otpora stanovništva vratilo se u Hodeidu; tako su visoravni ostale zejdijskim imamima, a osmanska vlast dvadeset tri godine trajala je samo u pojasu Tihame. Unutrašnji Jemen vraćen je tek 1872. pohodom Ahmed Muhtar-paše.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Baltalimanska konvencija: zajedničko osmansko-rusko pokroviteljstvo u Vlaškoj i Moldaviji", "d3bb22e9"], "d": ["Kad su se revolucije 1848. proširile na Vlašku i Moldaviju, osmanske i ruske snage zajedno su okupirale kneževine. Konvencijom potpisanom u Baltalimanu dogovoreno je da vojvode neće birati nego ih postavljati sultan na sedam godina te da dvije države uspostave zajednički nadzor nad oblašću. Sporazum je čuvao osmanski suverenitet na papiru, ali je Rusiji priznao faktičko pravo partnerstva i ubrzao odvajanje dunavskih kneževina od Osmanlija.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Pitanje mađarskih izbjeglica: Kossuth i njegovi drugovi sklanjaju se kod Osmanlija", "1c7d7ef4"], "d": ["Nakon gušenja mađarske revolucije 1848–1849. rusko-austrijskom intervencijom, Lajos Kossuth i hiljade mađarskih i poljskih izbjeglica sklonili su se na osmanske zemlje. Austrija i Rusija oštro su tražile izručenje izbjeglica; Visoka porta, uz podršku Engleske i Francuske, odbila je izručenje i nastanila grupu u Kütahyi. Kossuthov krug tu je ostao oko osamnaest mjeseci, a stotine izbjeglica primile su islam i stupile u osmansku službu. Događaj se smatra jednom od rijetkih diplomatskih pobjeda koje su uzdigle ugled tanzimatskih Osmanlija u evropskoj javnosti.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Osnivanje Endžumen-i Daniša: prva osmanska akademija u Istanbulu", "6fda1365"], "d": ["Endžumen-i Daniš, osnovan odlukom Medžlis-i Maarif-i Umumijje, prva je osmanska naučna akademija ustanovljena radi pripremanja naučnih i školskih knjiga na turskom. Svečano je otvoren 18. jula 1851. u zgradi Darulmaarifa; među domaćim i stranim članovima bio je i Ahmed Dževdet-paša. Iako kratkog vijeka, djela kao što su Dževdet-pašina Historija i Kavaid-i Osmanijje bila su plod te ustanove, i ona se smatrala kamenom temeljcem za to da turski postane jezik nauke.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Pobjeda kod Oltenice: prvi osmanski uspjeh na dunavskom frontu", "a660ad2f"], "d": ["U početnoj fazi Krimskog rata serdar-ekrem Omer Lutfi-paša prešao je Dunav i kod Oltenice uz teške gubitke odbio ruske snage. Pobjeda je zaustavila rusko napredovanje na samom početku rata i pokazala Evropi snagu koju je osmanska vojska stekla obukom nakon Tanzimata. Taj uspjeh pripremio je psihološku podlogu koja je olakšala odluku Engleske i Francuske da uđu u rat na strani Osmanlija.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Ugovor o savezu s Engleskom i Francuskom u Istanbulu", "04809278"], "d": ["Ugovorom o savezu potpisanim u Krimskom ratu protiv Rusije između Osmanske države, Engleske i Francuske utvrđeno je da tri države vode zajedničke operacije i da saveznici prije kraja rata neće sklopiti zaseban mir. Tako je Osmanska država prvi put u historiji stupila u vojni savez s velikim evropskim državama kao ravnopravna strana. Taj ugovor stvorio je i pravnu osnovu za zvanično primanje Osmanlija u evropski sistem država u Parizu dvije godine kasnije.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Osnivanje Istanbulskog šehremaneta: prvo moderno gradsko ustrojstvo", "be4af27f"], "d": ["Kriza infrastrukture nastala zbog savezničkih vojnika nagomilanih u Istanbulu tokom Krimskog rata i rasta stanovništva razotkrila je nedostatnost klasične gradske uprave sa središtem u kadijstvu. Osnivanjem Šehremaneta po evropskim uzorima poslovi čistoće, narha, nadzora čaršije i izgradnje objedinjeni su pod jednom rukom; iduće godine u Bejoglu-Galati ustanovljena je kao pilot-područje Šesta općinska uprava. Taj korak smatra se početkom moderne komunalne uprave kod Osmanlija.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Pariški mir: kraj Krimskog rata i primanje Osmanlija u evropski sistem država", "4aee0e2a"], "d": ["Pariškim mirom, kojim je okončan Krimski rat, Osmanska država proglašena je ravnopravnim članom evropskog međunarodnog prava, a njen teritorijalni integritet stavljen pod zajedničku garanciju velikih sila. Crno more je neutralizirano, poništena je ruska pretenzija na pokroviteljstvo nad pravoslavnim podanicima, stečena od mira u Küčük Kajnardži, a južna Besarabija (kadiluci Kilija, Kagul, Izmail i Bolgrad) pripala je Moldaviji. Međutim, isti ugovor pretvorio je Islahat-ferman u međunarodnu obavezu i time odškrinuo vrata miješanju u unutrašnje poslove.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Otvaranje saraja Dolmabahče: preseljenje sjedišta uprave iz Topkapija", "71ad26d0"], "d": ["Saraj, koji je Abdul-Medžid 1842. naručio od porodice Baljan, otvoren je nakon četrnaest godina gradnje, a sjedište državne uprave preseljeno je iz četiri stoljeća starog Topkapija na obalu Bosfora. Sa svojim evropskim stilom, kristalnim stepeništem i Dvoranom za bajramske čestitke saraj je postao kameni izraz zapadnjačke pretenzije Tanzimata. Njegova golema cijena postala je jedna od najkritikovanijih stavki godina u kojima su osmanske finansije ušle u spiralu vanjskog zaduživanja.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Ujedinjenje Vlaške i Moldavije pod Cuzom: rođenje Rumunije", "baef4da5"], "d": ["Na izborima organiziranim nakon Pariškog mira obje kneževine izabrale su pukovnika Alexandrua Ioana Cuzu za vojvodu i time ostvarile faktičko ujedinjenje. Iako su se Visoka porta i Austrija tome protivile, morao se prihvatiti svršeni čin koji je podržavala Francuska. Taj savez, na papiru i dalje vezan za Osmanlije, 1862. uzet će ime Rumunija, a 1877. jednostrano proglasiti nezavisnost; on je prekretnica u raspadanju osmanske vlasti na Dunavu.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Incident u Kuleliju: prvi pokušaj državnog udara protiv Abdul-Medžida u Istanbulu", "e3653b21"], "d": ["Tajno društvo sastavljeno od vojnika i civila, koje je reagovalo na tanzimatsku politiku i na jednakost koju je Islahat-ferman priznao nemuslimanima, planirajući zbacivanje sultana, zatečeno je prepadom na sastanku u džamiji Kilič Ali-paše. Budući da su optuženici suđeni u kasarni Kuleli, događaj se tako zove; smrtne kazne preinačene su u progonstvo. Smatra se prvim pokušajem dvorskog udara u osmanskoj historiji koji je preduzela organizacija osnovana iz ideoloških pobuda.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Druzsko-maronitski građanski rat u Džebel-i Libanu i događaji u Damasku", "5595fdd6"], "d": ["Sukobi koji su izbili u maju 1860. nakon ubistva dvojice Druza u blizini Sidona pretvorili su se u najkrvaviji druzsko-maronitski građanski rat u planini, a u julu su se prenijeli na Damask i završili smrću hiljada kršćana. Kad je Francuska iskrcala vojsku, Visoka porta poslala je u tu oblast Fuad-pašu s izvanrednim ovlaštenjima; provedena je oštra kaznena akcija. Događaji su postali povod za evropsku intervenciju i neposredan uzrok tome što je Liban dobio poseban status.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Početak izlaženja lista Terdžuman-i Ahval: prve privatne turske novine u Istanbulu", "24792957"], "d": ["Terdžuman-i Ahval, koji je izdavao Agah-efendija, a uredništvo preuzeo Šinasi, prve su turske novine koje su izlazile bez državne potpore. U uvodniku prvog broja branjeno je pravo naroda da kaže svoju riječ o vlastitim poslovima, a novine su, objavljujući u nastavcima Šinasijevu 'Ženidbu pjesnika', otvorile vrata i modernoj turskoj književnosti. Rođenje pojma javnog mnijenja i opozicione štampe kod Osmanlija veže se za ovaj datum.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Nizamnama o Džebel-i Libanu: povlašteni status mutasarifluka za Liban", "bf375603"], "d": ["Nizamnama, pripremljena pod pritiskom velikih sila nakon pokolja 1860, pretvorila je Džebel-i Liban u povlašteni mutasarifluk neposredno vezan za Visoku portu, kojim je upravljao upravni savjet sastavljen po ravnoteži među vjerskim zajednicama. Propisano je da mutasarif mora biti katolički kršćanin i osmanski podanik, a njegovo imenovanje podneseno na odobrenje velikim silama; prvi mutasarif bio je Davud-paša. Taj poredak trajat će do 1915. i činiti jezgro moderne libanske države.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Smrt Abdul-Medžida i stupanje na prijestolje sultana Abdul-Aziza", "27204d7c"], "d": ["Kad je Abdul-Medžid, koji je u dvadeset dvije godine vladavine potpisao Tanzimatski i Islahat ferman, podlegao tuberkulozi, na prijestolje je stupio njegov brat Abdul-Aziz. Novi sultan u prvim je godinama mjerama štednje i jednostavnim životom ulijevao nadu; flotu je pretvorio u jednu od rijetkih velikih snaga svijeta. Ali pri kraju njegove vladavine nagomilaju se teški vanjski dug, bankrot 1875. i balkanski ustanci, što će pripremiti tlo za njegovo svrgavanje 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Ujedinjene kneževine dobivaju ime Rumunija", "d960e3fc"], "d": ["Vlaška i Moldavija, faktički ujedinjene dvostrukim izborom Cuze 1859, objedinivši 1862. svoje skupštine i vlade pod jednim krovom u Bukureštu, zvanično su uzele ime Rumunija. Iako je Osmanska država pravno zadržala status suzerena i godišnji danak, faktički je izgubila nadzor nad kneževinom. Kraj četiristoljetnog osmanskog uticaja sjeverno od Dunava simbolizira ovaj datum.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Pripajanje Suakina, Masave i Dahlaka Egiptu", "a0924860"], "d": ["Masava, koju je sultan Abdul-Medžid 1846. zajedno sa Suakinom dao egipatskom hedivu Mehmed Ali-paši kao saljanu (dodjelu prihoda), za hediva Ismail-paše zajedno s Dahlakom i Suakinom uključena je u egipatske posjede i uređena kao kajmakamluk. Tako su te tri luke na afričkoj obali Crvenog mora, iako su pravno ostale osmanski teritorij, upravno iz neposredne nadležnosti Visoke porte prešle Kairu — ušle su u isti vazalni sloj kao susjedni Egipat i Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Početak Kretskog ustanka (1866–1869)", "3679b861"], "d": ["Široki ustanak koji je izbio na otoku uz otvorenu podršku Grčke prvi put je zahtjev kretskih Grka za enosisom (pripajanjem Grčkoj) učinio međunarodnim pitanjem. Trogodišnji teški gorski rat nanio je osmanskoj vojsci velike gubitke i snažno odjeknuo u evropskoj javnosti. Ustanak se mogao ugasiti tek 1868, kad je Ali-paša otišao na otok i uveo nizamnamu koja je priznala široke povlastice.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Povlačenje posljednjih osmanskih posada iz Beograda i tvrđava Srbije", "b34217db"], "d": ["Pod pritiskom velikih sila i na uporan zahtjev kneza Mihaila, Visoka porta pristala je isprazniti posljednje vojne baze koje su joj ostale u Srbiji; 18. aprila 1867. osmanska zastava na Beogradskoj tvrđavi spuštena je, a ključevi predati knezu. Tako je okončano faktičko osmansko vojno prisustvo koje je trajalo od 1521. i uklonjena posljednja velika prepreka na putu Srbije k nezavisnosti. Sultanov suzerenitet sveo se samo na simbolično pitanje zastave i danka.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Dodjela titule hediva egipatskim valijama", "09e10c12"], "d": ["Zahvaljujući snažnom lobiranju Ismail-paše iz trećeg koljena dinastije Kavalali i novcu koji je slivao u Istanbul, egipatskom valiji dodijeljena je titula hediva, kojom se naglašavala njegova nadređenost drugim valijama. Istih godina i način nasljeđivanja izmijenjen je tako da prelazi s oca na sina, a Egiptu su priznata ovlaštenja suverenog karaktera, kao što su vanjsko zaduživanje, dodjela odlikovanja i držanje konzulata. Ti su koraci prva karika lanca koji je ubrzao pravno odvajanje Egipta od Osmanlija.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Kretska nizamnama: široke upravne povlastice za otok", "12052262"], "d": ["Da bi se okončao trogodišnji ustanak, veliki vezir Ali-paša lično je prešao na otok, a nizamnamom objavljenom uz sultanovo odobrenje Krećanima su priznati mješoviti upravni savjeti, mjesni sudovi, upotreba grčkog jezika u službenim poslovima i poreske olakšice. Ta uredba održala je osmansku vlast na otoku još trideset godina. Međutim, povlastice priznate kršćanskom stanovništvu oslabile su položaj muslimanskih Krećana i posijale sjeme krize 1896–1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Otvaranje Šura-yi Devleta: osnivanje osmanskog Državnog vijeća", "70b16497"], "d": ["Iradom od 5. marta 1868. Medžlis-i Ahkam-i Adlijje podijeljen je na dvoje: upravno-zakonodavni poslovi prepušteni su Šura-yi Devletu, a sudski Divan-i Ahkam-i Adlijje; ustanova je svečano otvorena u Visokoj porti, a za prvog predsjednika doveden je Midhat-paša. Zadužena je da priprema nacrte zakona, rješava upravne sporove i vodi suđenja činovnicima. Sa svojim mješovitim muslimansko-nemuslimanskim članstvom smatra se prvom institucionalnom primjenom ideje podjele vlasti kod Osmanlija.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Otvaranje Sueskog kanala: skraćivanje puta za Indiju preko Egipta", "377ccd04"], "d": ["Gradnja započeta 1859. trajala je deset godina, a kanal od 163 kilometra, koji povezuje Sredozemno i Crveno more, uz veličanstvenu svečanost pušten je u upotrebu. Kad se put koji Evropu povezuje s Indijom skratio za hiljade milja, Egipat je odjednom postao ključna tačka svjetske trgovine. Ta geostrateška vrijednost bit će glavni razlog što će Engleska trinaest godina nakon otvaranja kanala okupirati Egipat; a dug koji je kanal natovario Egiptu odvest će hedivat u bankrot.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Osnivanje Bugarskog egzarhata: odvajanje bugarske crkve od Fenera", "33a8272c"], "d": ["Sultanovim fermanom osnovana je zasebna, samostalna bugarska crkva (egzarhat), odvojena od Grčke patrijaršije, a narodnom glasanju prepušteno je koji će kadiluci biti vezani za egzarhat. Iako je Visoka porta taj korak preduzela da slomi grčki uticaj, ishod je bio suprotan: crkva se pretvorila u organizirano središte bugarskog nacionalnog identiteta i bugarske pretenzije na Makedoniju. Tako je postavljena institucionalna podloga bugarsko-grčko-srpskog suparništva na Balkanu i ustanaka 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Stavljanje Asira pod neposrednu upravu", "4559e099"], "d": ["Kad je otvaranjem Sueskog kanala porasla strateška vrijednost Crvenog mora, uvidjelo se da se planine Asir na sredini kopnenog puta za Jemen ne mogu ostaviti bez nadzora. Snage Redif-paše, koji je krenuo u jemenski pohod, ušle su u Abhu, pripojile oblast neposrednoj osmanskoj upravi i osnovan je Asirski sandžak. Zbog brdovitog reljefa i uticaja Idrisija ta vlast nikada se nije potpuno učvrstila.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Nedžedski pohod Midhat-paše: ponovna uspostava osmanske vlasti u Lahsi", "7db51461"], "d": ["Bagdadski valija Midhat-paša, koristeći borbu za prijestolje u porodici Saud, uputio je vojsku na zapadnu obalu Perzijskog zaljeva i oblast Lahsa pod imenom Nedžedski sandžak pripojio Basranskom vilajetu. Abdullah b. Fejsal postavljen je za mutasarifa, čime je osmanska vlast uspostavljena na papiru. Pohod je imao cilj zaustaviti širenje engleskog uticaja u zaljevu i iste godine doveo je do toga da i Katar uđe pod osmanski nadzor.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Smrt velikog vezira Ali-paše: kraj tanzimatskog kadra", "1cf0141c"], "d": ["Smrću Ali-paše, koji je nakon smrti Fuad-paše 1869. sam nosio tanzimatsku politiku, iscrpljena je generacija vještih diplomata koja je trideset godina vodila državnu vanjsku politiku. Proruska i samovoljna uprava Mahmud Nedim-paše, koji je došao na njegovo mjesto, učvrstila je ličnu vladavinu Abdul-Aziza. U pet godina nakon smrti Ali-paše finansije su bankrotirale, Balkan se digao na ustanak, a smjena na prijestolju postala je neizbježna.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Uspostava osmanske kontrole u Kataru", "3b453165"], "d": ["Na poziv šejha Kasima b. Sanija, koji je bio pod engleskim pritiskom, osmanske snage iskrcale su se na poluotok Katar i u jesen 1871. uspostavljena je osmanska kontrola u toj oblasti. Katar je ustrojen kao kadiluk Nedžedskog sandžaka, a šejh je postavljen za kajmakama. Taj potez bio je najopipljiviji dobitak ofanzivne politike koju je Midhat-paša u zaljevu vodio protiv Engleske; osmanska zastava na poluotoku vijorila se do 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Ferman o nasljeđivanju za Tunis — bejluk porodici Mehmed Sadik-paše", "1509ebb0"], "d": ["Fermanom donesenim zahvaljujući nastojanjima Hajrudin-paše, koga je tuniski beg Mehmed Sadik-paša, koristeći francuski poraz od Pruske, poslao u Istanbul, Tunis je, uz neposrednu vezanost za Istanbul, dat Mehmed Sadik-paši i njegovim potomcima uz pravo nasljeđivanja. Bez sultanove dozvole neće se voditi ni rat ni mirovni pregovori, nikakva zemlja neće se dati drugome, a osmanski zahtjev za vojnicima bit će ispunjen. Francuska nije priznala ferman; deset godina kasnije okupirala je Tunis.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Zauzimanje Sane: ponovna uspostava osmanske vlasti u Jemenu", "978e20a0"], "d": ["Kad je otvaranjem Sueskog kanala porasla strateška vrijednost Crvenog mora, Visoka porta uputila je u Jemen pričuvnu vojsku pod zapovjedništvom Ahmed Muhtar-paše. Zauzimanjem Sane u unutrašnjem Jemenu, faktički izgubljenom dva stoljeća, ponovo je uspostavljen državni autoritet, a oblast je pretvorena u vilajet. Međutim, borba sa zejdijskim imamima nikada nije prestala; ustanci 1891, 1898. i 1904. činili su najskuplji i najdugotrajniji unutrašnji front Osmanlija. Ostala mjesta pripojena istog datuma: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Početak Hercegovačkog ustanka: ponovno rasplamsavanje Istočnog pitanja", "571b18ec"], "d": ["Ustanak kršćanskih seljaka oko Nevesinja zbog teških poreza i pritiska ajana ubrzo se proširio na cijelu Hercegovinu i hranio se dobrovoljcima iz Srbije i Crne Gore. Ustanak, koji je doveo do toga da Austrija i Rusija nametnu reforme, iduće godine pokrenuo je bugarske ustanke i srpsko-crnogorske objave rata. Tako je pukla prva karika velikog lanca koji je vodio do rata 1877–78. i gubitka Balkana Berlinskim ugovorom.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bankrot osmanskih finansija: prepolovljene otplate vanjskog duga", "2cac2fa5"], "d": ["Zajmovi uzimani jedan za drugim od 1854, troškovi Krimskog rata, gradnja saraja i anadolska glad 1873–74. pretvorili su budžetski deficit u ponor veći od pet miliona lira. Vlada Mahmud Nedim-paše objavila je da će otplate kamata i glavnice duga na pet godina biti prepolovljene, čime je faktički proglasila moratorij. Ta odluka, koja je izazvala veliku reakciju na evropskim berzama, pokrenula je proces koji će šest godina kasnije rezultirati Muharemskom uredbom i osnivanjem Uprave Dujun-i Umumijje.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Svrgavanje Murata V i stupanje na prijestolje Abdul-Hamida II", "cffb2271"], "d": ["Murat V, koji je stupio na prijestolje nakon svrgavanja Abdul-Aziza, zbog duševnog zdravlja uzdrmanog smrću strica i incidentom Čerkeza Hasana postao je nesposoban za obavljanje dužnosti; od devedeset tri dana vladavine samo je sedam dana bio pri zdravom razumu. Svrgnut je fetvom šejhul-islama, a na njegovo mjesto doveden je brat Abdul-Hamid II. Novi sultan stupio je na prijestolje dajući Midhat-paši obećanje da će proglasiti ustavnu monarhiju; počinjalo je doba koje će trajati trideset tri godine.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Konferencija u brodogradilištu (Tersane): velike sile nameću balkanske reforme", "b5006a2c"], "d": ["Konferencija koju su velike sile sazvale u Istanbulu radi rješavanja balkanske krize zahtijevala je da se Bugarska podijeli na dva autonomna vilajeta i da se u Bosni i Hercegovini provedu reforme pod međunarodnim nadzorom. Visoka porta, na dan otvaranja konferencije topovskim plotunima objavivši proglašenje Kanun-i Esasija, pokušala je na nametanja odgovoriti ustavnom reformom. Delegati su to smatrali odugovlačenjem i 20. januara 1877. razišli se; četiri mjeseca kasnije Rusija je objavila rat.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Otvaranje prvog Medžlis-i Mebusana u Dolmabahčeu", "429bb279"], "d": ["115 poslanika izabranih na osnovu Kanun-i Esasija prvi se put sastalo 19. marta 1877. na svečanosti u Dvorani za bajramske čestitke saraja Dolmabahče; tako je u osmanskoj historiji počelo doba predstavničke skupštine. Muslimanski i nemuslimanski poslanici oštro su ispitivali vladu i raspravljali o vođenju rata i odgovornosti ministara. Ta hrabra opozicija bit će glavni razlog što će skupštini biti skraćen vijek.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Početak odbrane Plevne: otpor Gazi Osman-paše", "0e04a878"], "d": ["Osman-paša, koji je iz Vidina krenuo na Plevnu da presiječe put prema Istanbulu ruskoj vojsci koja je u ratu 1877–78. prešla Dunav, utvrdio je gradić tabijama i rovovima i započeo petomjesečnu legendarnu odbranu. Uzastopna tri velika rusko-rumunska napada odbijena su uz teške gubitke, a vojska kojom je lično zapovijedao car Aleksandar II bila je prisiljena na opsadu. Plevna je ušla u historiju kao najblistaviji odbrambeni uspjeh osmanske vojske u 19. stoljeću.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Pad Plevne: slom dunavskog fronta", "185e7602"], "d": ["Osman-paša, kojem su u petomjesečnoj opsadi nestale zalihe, preduzeo je ispad preko rijeke Vit; kad je ranjen pao u zarobljeništvo, grad se predao. Ruski zapovjednici pozdravili su zarobljenog pašu vrativši mu sablju, a Osman-paša dobio je nadimak 'Gazi'. Padom Plevne ruskoj vojsci otvoren je put; u roku od dva mjeseca pali su Sofija, Plovdiv i Edirne, a ruske prethodnice stigle su do Ješilköya.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Ruska okupacija Sofije", "ef369d22"], "d": ["Ruska vojska, koja je nakon pada Plevne prešla Balkan, ušla je u nezaštićenu Sofiju. Grad se više nikada neće vratiti pod osmansku upravu; postat će krajem 1878. dio autonomne Kneževine Bugarske, a 1879. faktički njen glavni grad. Na karti Sofija od tog datuma izlazi iz neposredne osmanske uprave i prelazi u privremenu rusku okupaciju, a zatim u autonomnu bugarsku upravu.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Jedrensko primirje: utihnulo oružje u ratu 1877–78.", "1f899180"], "d": ["Kad su Sofija, Plovdiv i Edirne pali jedno za drugim, a ruska vojska doprla do obala Mramornog mora, Visoka porta morala je tražiti primirje. Primirje potpisano u Edirnama primoralo je Osmanlije da prihvate preliminarne uslove mira kao što su autonomija Bugarske, nezavisnost Crne Gore, Srbije i Rumunije te teška ratna odšteta. Ti uslovi će mjesec dana kasnije u Svetom Stefanu postati tekst ugovora.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdul-Hamid II raspušta Medžlis-i Mebusan na neodređeno vrijeme", "e770b540"], "d": ["Zbog oštrih kritika poslanika koji su vladu i saraj smatrali odgovornima za katastrofalan ishod rata, Abdul-Hamid II, pozivajući se na ovlaštenje koje mu je davao Kanun-i Esasi, raspustio je skupštinu na neodređeno vrijeme. Tako je zatvoren prvi osmanski parlament, koji je radio oko jedanaest mjeseci, i počelo je doba apsolutizma koje će trajati trideset godina. Skupština se mogla ponovo sastati tek nakon revolucije 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Sanstefanski mir: projekt Velike Bugarske", "2c7cc611"], "d": ["Sanstefanski mir, kojim je završen rat 1877–78, stvarao je golemu autonomnu Bugarsku koja je dopirala do Egeja i obuhvatala Makedoniju; priznavao nezavisnost Srbije, Crne Gore i Rumunije; Kars, Ardahan, Batum i Doğubayazıt ostavljao Rusiji, a uz to nametao ratnu odštetu koju je bilo nemoguće platiti. Taj tekst, koji je Rusiju spuštao na Sredozemno more, izazvao je žestoku reakciju Engleske i Austrije. Prije nego što je proveden, za četiri mjeseca ponovo je uređen na Berlinskom kongresu; ipak je ostao dokument koji je objavio kraj osmanske Rumelije.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan i Batum prepušteni Rusiji — Elvije-i Selase", "99bdfad2"], "d": ["Berlinskim ugovorom Osmanska država prepustila je Rusiji Kars, Ardahan i Batum na ime dijela ratne odštete; Doğubayazıt i dolina Eleškirta, dati Rusiji u Svetom Stefanu, ostali su Osmanlijama. Iako je Batum dat kao slobodna luka, taj status mogao je zadržati samo do 1886. Rusi su Kars učinili oblašću vezanom za zakavkasko generalno guvernerstvo sa sjedištem u Tbilisiju; stanovništvo iz Elvije-i Selase, čiji je broj dostizao 100.000, moralo je iseliti prema Erzurumu. Istim ugovorom Južna Besarabija (Kilija, Kagul, Bolgrad) vraćena je od Rumunije Rusiji.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Austrougarska okupacija Bosne i Hercegovine i Novopazarskog sandžaka", "e5f901df"], "d": ["Na osnovu ovlaštenja datog Berlinskim ugovorom austrougarske vojske ušle su u Bosnu; iako je osmanska vlada pristala da se ne opire, domaće muslimansko i pravoslavno stanovništvo u Sarajevu i Mostaru latilo se oružja i tri mjeseca pružalo žilav otpor. Okupacija je mogla biti završena tek 20. oktobra 1878. Sultanov pravni suverenitet trajao je na papiru do 1908, ali je četiristoljetna osmanska Bosna faktički izgubljena i počeo je veliki val iseljavanja muslimana. Ostala naselja izgubljena istog datuma: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Muharemska uredba i osnivanje Uprave Dujun-i Umumijje", "02b7cc03"], "d": ["Pregovori vođeni s predstavnicima država povjerilaca nakon bankrota 1875. okončani su uredbom od 28. muharema 1299 (20. decembra 1881): glavnica duga smanjena je za više od polovine, a zauzvrat su najplodnije stavke prihoda, kao što su takse na so, duhan, svilu, taksene marke i ribu, prenesene na Upravu Dujun-i Umumijje, kojom su neposredno upravljali povjerioci. Ta uprava, koja je zapošljavala hiljade činovnika, pretvorila se u zasebnu finansijsku organizaciju unutar države. Smatra se datumom faktičkog kraja osmanske finansijske nezavisnosti.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — jedina luka koja nije pala u Mahdijeve ruke", "5a37b198"], "d": ["Dok su od februara 1884. sve istočnosudanske oblasti osim Suakina prelazile pod vlast Muhammeda Ahmeda el-Mahdija, luka se održala zahvaljujući vojnoj zaštiti britanskih snaga od tri bataljona pod zapovjedništvom generala Grahama. Bio je to početak razdoblja u kojem su se faktičko i pravno stanje razdvojili: iako je obala faktički bila pod britanskim vojnim nadzorom, njena upravna veza 1885. oduzeta je Egiptu i neposredno vezana za Jemenski vilajet, odnosno za Visoku portu — taj poredak trajao je dok 1888. nije okončan francuskom okupacijom Zejle.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Ubistvo Midhat-paše u tamnici u Taifu", "f4562261"], "d": ["Midhat-paša, arhitekt Kanun-i Esasija i simbolično ime Prve ustavne monarhije, na Jildiskom sudu proglašen je krivim u vezi sa smrću Abdul-Aziza, smrtna kazna mu je preinačena u progonstvo i poslan je u Taif. Prema zapisu TDV-a, u noći 7–8. maja 1884. zadavljen je u ćeliji, a kao zvanični uzrok navedena je bolest 'šir-pendže' (karbunkul). Njegova smrt postala je simbol likvidacije ustavne opozicije u doba Abdul-Hamida II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Dodjela koncesije za željeznicu Hajdarpaša–Ankara Nijemcima", "5705b163"], "d": ["Sultanovom iradom koncesija za izgradnju i eksploataciju linije Hajdarpaša–Ankara dodijeljena je bankaru Alfredu von Kaulli, predstavniku Deutsche Banka, i osnovano je Anadolsko željezničko društvo. Ta koncesija bila je prekretnica koja je u osmanskoj saobraćajnoj i vanjskoj politici slomila englesko-francuski monopol i učvrstila njemački uticaj. Uz koncesiju za bagdadsku liniju, koja će istom društvu biti data jedanaest godina kasnije, rodit će se san 'Berlin–Bagdad', koji će postati jedna od glavnih osa suparništva velikih sila prije Prvog svjetskog rata.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Osnivanje Društva Ittihad-i Osmani u Istanbulu", "b7187939"], "d": ["Četvorica učenika Vojne medicinske škole osnovala su Društvo Ittihad-i Osmani kao tajnu organizaciju protiv apsolutističke uprave; ta struktura ubrzo se pretvorila u Komitet jedinstva i napretka, koji će pod svojim krovom okupiti sve opozicione elemente mladoturskog pokreta. Organizacija zasnovana na ćelijama spojila se s izgnanicima u Evropi i oficirima u Solunu. Kadar koji će 1908. natjerati na proglašenje Druge ustavne monarhije i od 1913. sam upravljati državom izrastao je iz te male studentske ćelije.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Prepad na Osmansku banku: akcija dašnačkih aktivista u Galati", "08b3095f"], "d": ["Naoružana grupa armenske organizacije Dašnakcutjun, s ciljem da privuče pažnju Evrope na armensko pitanje, upala je u sjedište Osmanske banke u Galati, uzela taoce i prijetila da će zgradu dići u zrak. Kriza je okončana, uz posredovanje ambasadora, u zamjenu za to da akteri brodom napuste zemlju. Krvavi događaji u Istanbulu u danima nakon prepada bili su presudni za to da se armensko pitanje pretvori u polugu međunarodne intervencije.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Početak osmansko-grčkog rata 1897: tesalijsko bojište", "33e490ab"], "d": ["Zbog grčkog slanja flote i vojske na Kretu i napada četa na rumelijskoj granici, Osmanska država objavila je rat. Osmanska vojska, koju je obučavala njemačka reformska misija, brzo je napredovala u Tesaliji i za mjesec dana zauzela Larisu, Farsalu i Domokos; grčka vojska se raspala. Posredovanjem velikih sila osvojene zemlje vraćene su, ali je rat ostao jedina odlučna vojna pobjeda doba Abdul-Hamida II i nije mogao spriječiti faktički gubitak Krete.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Dodjela koncesije za liniju Konya–Bagdad Nijemcima", "fd8b6cbd"], "d": ["Nakon posjeta cara Wilhelma II Istanbulu i Damasku 1898, Anadolskom željezničkom društvu dodijeljena je prethodna koncesija za liniju koja će se protezati od Konye do Bagdada i Basre. Projekt Bagdadske željeznice za Osmanlije je značio jačanje centralnog nadzora nad arapskim vilajetima, a za Njemačku dolazak do Perzijskog zaljeva. Taj projekt, kojem su se Engleska i Rusija žestoko protivile, postao je jedan od najspornijih predmeta imperijalističkog suparništva koje je vodilo u Prvi svjetski rat.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Početak gradnje Hidžaške željeznice u Damasku", "62f58f68"], "d": ["Linija koju je Abdul-Hamid II naredio iradom od 2. maja 1900. počela se graditi zvaničnom svečanošću u Damasku 1. septembra 1900. Projekt, izveden u potpunosti prilozima prikupljenim iz islamskog svijeta i radom osmanskih inžinjera i vojnika, skratio je put hadžija od Damaska do Medine s četrdeset dana na pet. Bio je i prestižno djelo koje je učvršćivalo duhovni autoritet hilafeta i strateško ulaganje koje je jačalo vojni nadzor nad Hidžazom.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Mürzsteški program: međunarodni nadzor nad reformama u Makedoniji", "4c7464da"], "d": ["Nakon Ilindenskog ustanka ruski i austrijski car sastali su se u Mürzstegu i pripremili novi reformski paket za Makedoniju. Program je predviđao da uz osmanskog generalnog inspektora budu postavljena dva strana civilna agenta, da evropski oficiri reorganizuju žandarmeriju i da se upravne granice promijene po nacionalnom načelu. Iako se Visoka porta opirala tvrdeći da su povrijeđena njena suverena prava, pred zajedničkim pritiskom morala je pristati; program je postao jedan od glavnih faktora koji su među mladim oficirima ubrzali itihadističko organiziranje.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Smrt Murata V", "396659a7"], "d": ["Murat V, koji je 1876. bio na prijestolju oko tri mjeseca i bio svrgnut, nakon pokušaja da se vrati na prijestolje dvadeset osam godina živio je zatočen pod strogim nadzorom i umro od šećerne bolesti. Sahranjen je u turbetu Džedid Havatin kod Nove džamije, uz svoju majku. Ušao je u historiju kao osmanski sultan koji je najkraće bio na prijestolju.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Gubitak Sane u korist imama Jahje", "e7f876cb"], "d": ["Ustanak koji je 1904. pokrenuo zejdijski imam Jahja Hamiduddin završio je u aprilu 1905. padom Sane nakon opsade; grad je izašao iz osmanske uprave, a tokom opsade zavladali su glad i epidemije. Brdoviti reljef Jemena, dužina linija opskrbe i lokalni legitimitet zejdijskog imamata činili su ovdašnju osmansku vlast od samog nastanka krhkom. Grad će pet mjeseci kasnije uz teške gubitke biti vraćen, ali se jemensko pitanje neće zatvoriti sve do 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Jildiski atentat: bombaški napad na Abdul-Hamida II", "1ee2e1a6"], "d": ["Organizacija Dašnakcutjun izvela je atentat aktiviranjem fijakera s tempiranom bombom kod kola sultana koji je izlazio sa svečanog odlaska na džumu; to što je Abdul-Hamid zbog razgovora sa šejhul-islamom zakasnio nekoliko minuta spasilo mu je život. U eksploziji je poginulo dvadeset šest ljudi, a više od pedeset ih je ranjeno. Događaj je još pooštrio sultanovu opsesiju sigurnošću i apsolutističku upravu zasnovanu na mreži doušnika; bio je i tema pjesme Tevfika Fikreta 'Trenutak zakašnjenja'.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Povratak Sane: gušenje ustanka imama Jahje", "dec3b8f9"], "d": ["Ustanak započet 1904. pod vodstvom zejdijskog imama Jahje završio je u aprilu 1905. padom Sane, a u gradu su zavladali glad i epidemije. Pojačane vojske pod zapovjedništvom Ali Riza-paše i Ahmed Fejzi-paše, akcijom vođenom od 15. jula do 1. septembra 1905, koju su podržale i snage u Taizu, uz teške gubitke povratile su grad, a ustanak je ugušen. Jemenski pohod donio je osmanskoj vojsci desetine hiljada gubitaka i golemo finansijsko breme; među oficirima u Rumeliji strah od 'progonstva u Jemen' bio je na čelu pritužbi koje su hranile itihadističko organiziranje.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Sastanak prvog Medžlis-i Mebusana Druge ustavne monarhije", "e7fd2716"], "d": ["Skupština, nastala na dvostepenim izborima održanim nakon tridesetogodišnje pauze, otvorena je 17. decembra 1908. sultanovim govorom, a za predsjednika je izabran vođa mladoturskog pokreta Ahmed Riza-beg. Skupština sastavljena od turskih, arapskih, albanskih, grčkih, armenskih i jevrejskih poslanika bila je posljednji veliki pokušaj ideala osmanizma. Međutim, nezavisnost Bugarske, aneksija Bosne i objava Krete o pripajanju Grčkoj zasjenile su taj optimizam i prije nego što je skupština otvorena.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Hareket ordusu i svrgavanje Abdul-Hamida II: stupanje na prijestolje Mehmeda V Rešada", "6a65a704"], "d": ["Hareket ordusu (Akciona armija), koja je krenula iz Soluna zbog incidenta od 31. marta, u noći 22–23. aprila s četiri strane ušla je u Istanbul, a 24. aprila predao se saraj Jildiz. Medžlis-i Umumi-i Milli 27. aprila odlučio je da svrgne Abdul-Hamida II; sultan je poslan u Solun, a na prijestolje je doveden njegov brat Mehmed V Rešad. Tako je okončana tridesettrogodišnja lična uprava, ali je njeno mjesto zauzelo novo doba u kojem je sultan postao simbol, a Komitet jedinstva i napretka vladao uz podršku vojske.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Albanski ustanak: oružani otpor na Kosovu i u Skadru", "93ed30c6"], "d": ["Centralistička poreska politika itihadističke vlade, kampanja oduzimanja oružja i rasprava o latinskom pismu digle su na ustanak albanska plemena, koja su dotad smatrana među državi najodanijim elementima. Iako je vojska pod zapovjedništvom Mahmud Ševket-paše oštro ugušila ustanak, nemir se ponovo rasplamsao 1911. i 1912. Ti ustanci iscrpili su osmansku vojsku uoči Balkanskog rata i ubrzali rođenje albanskog nacionalnog pokreta.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Ušijski mir: prepuštanje Tripolija i Bengazija Italiji", "4ffa1fd2"], "d": ["Visoka porta, ne mogavši se pred ratnim pripremama balkanskih država odvažiti na sukob na dva fronta, potpisala je u švicarskom gradiću Ouchyju tajni mir s Italijom i napustila Tripolitaniju i Bengazi. Tako je Osmanska država izgubila posljednji posjed u Africi; zauzvrat je obećan povrat Rodosa i Dvanaest otoka koje je Italija okupirala, ali to obećanje nikada nije ispunjeno. Kad je ugovor potpisan, Balkanski rat već je bio počeo. Ovim događajem pod italijansku upravu prešli su Murzuk (Fezan), Gat, Sebha, Ubari, Traghan, Zawila i El-Katrun (Fezan, sandžak Tripoliskog vilajeta).", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Grčka okupacija Lemnosa", "9555af1d"], "d": ["U Prvom balkanskom ratu grčka flota okupirala je Lemnos; luka Mudros na otoku postala je baza za blokadu Dardanela. Otok je u Lausannei (24. jula 1923) ostavljen Grčkoj.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Grčka okupacija Tasosa", "6c03c7f0"], "d": ["U Prvom balkanskom ratu Grčka je okupirala Tasos i Samotraku.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Grčka okupacija Samotrake", "911e82a3"], "d": ["U Prvom balkanskom ratu Grčka je okupirala Samotraku.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Grčka okupacija Lezbosa (Mitilene)", "6b2b07ba"], "d": ["Grčka flota iskrcala se na Lezbos; otok su krajem Prvog balkanskog rata zauzele grčka vojska i flota. Londonska konferencija (maj 1913) potvrdila je to stanje.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Grčko iskrcavanje na Hios", "901c6539"], "d": ["Na Hios, bombardiran 7. aprila 1912. u Prvom balkanskom ratu, Grci su izvršili iskrcavanje; osmanska posada predala se 3. januara 1913. Otok je Lozanskim ugovorom (24. jula 1923) ostavljen Grčkoj.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Ubistvo velikog vezira Mahmud Ševket-paše u atentatu u Istanbulu", "68e60e63"], "d": ["Mahmud Ševket-paša, postavljen za velikog vezira nakon upada na Visoku portu, na putu u Ministarstvo rata ubijen je pucnjevima na kola kod Čaršikapija. Komitet jedinstva i napretka, svalivši atentat na opoziciju, pokrenuo je širok val hapšenja i pogubljenja; Stranka slobode i sporazuma faktički je likvidirana. Ovim događajem konačno je uspostavljena jednopartijska diktatura itihadista zasnovana na trojici Enver-Talat-Džemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Početak Drugog balkanskog rata: saveznička svađa oko podjele", "48d088a2"], "d": ["Balkanski saveznici, koji nisu mogli podijeliti zemlje oduzete Osmanlijama Londonskim ugovorom, sukobili su se među sobom; napadom Bugarske na srpske i grčke položaje počeo je drugi rat. Kad su i Rumunija i Crna Gora stupile u rat protiv Bugarske, bugarska vojska se urušila. Osmanska država, iskoristivši tu priliku, prešla je liniju Midija–Enez povučenu Londonskim ugovorom i povratila Istočnu Trakiju zajedno s Edirnama.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Istanbulski mir: mir s Bugarskom i potvrda Edirna", "c8c18b2d"], "d": ["Ugovor potpisan između Osmanske države i Bugarske nakon Drugog balkanskog rata, prihvatajući rijeku Maricu kao granicu, pravno je potvrdio da Edirne, Kırklareli, Didimotihon i Istočna Trakija ostaju Osmanlijama. Aleksandrupolis (Dedeagač) ostavljen je Bugarskoj (a Kavala je nakon bugarske okupacije u jesen 1912. u julu 1913. prešla Grčkoj i potvrđena kao grčka Bukureštanskim mirom od 10. augusta 1913), te su uređeni uzajamna razmjena stanovništva dviju zemalja i prava muslimana u Bugarskoj. Jedini dio teritorija koji se mogao povratiti iz balkanske katastrofe jamči upravo ovaj tekst. Ostala mjesta pripojena istog datuma: Komotini (Gümüldžina).", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Povratak Tenedosa i Imbrosa — Atinski mir", "ec084d09"], "d": ["Od sjevernoegejskih otoka koje je Grčka okupirala u Balkanskom ratu, Tenedos i Imbros, koji drže ulaz u moreuz, u pregovorima o Atinskom miru smatrani su neophodnima za odbranu Čanakkalea i vraćeni su Osmanlijama. Ostali otoci ostali su Grčkoj. Ta dva otoka postala su posljednje zemlje koje je Carstvo držalo u Egeju i u Lausannei su također ostavljene Turskoj.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Atinski mir: mir s Grčkom i prijenos Soluna i Janjine", "8e94def7"], "d": ["Ugovor potpisan između Osmanske države i Grčke zvanično je priznao prelazak Soluna, Janjine i Južne Makedonije, izgubljenih u Balkanskom ratu, Grčkoj te su napuštena osmanska prava na Kreti. Detaljno su uređena vjerska i imovinska prava muslimana koji su ostali u Grčkoj, status vakufa i imenovanje muftija. Status egejskih otoka ostao je neriješen i ostao trajan izvor napetosti između dviju država.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Potpisivanje tajnog osmansko-njemačkog ugovora o savezu u Istanbulu", "0472efb3"], "d": ["Čim je u Evropi izbio rat, u konaku velikog vezira Said Halim-paše potpisan je tajni ugovor o savezu između Osmanske države i Njemačke; tekst je predviđao da, ako Rusija stupi u rat protiv Njemačke, i Osmanlije stanu na stranu Njemačke. Ugovor je skriven čak i od kabineta, znale su ga samo četiri osobe. Tri mjeseca kasnije prepadom na Crnom moru Osmanska država faktički će biti uvučena u rat, a sudbina carstva bit će vezana za ovaj dokument.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Jednostrano ukidanje kapitulacija", "ec773d18"], "d": ["Osmanska vlada, u trenutku kad je Evropa bila zauzeta ratom, objavila je da od 1. oktobra 1914. jednostrano ukida kapitulacije, koje su strancima davale sudske, finansijske i carinske povlastice. Okončanje tog četiri stoljeća starog povlasničkog poretka u zemlji je dočekano s velikim zanosom nezavisnosti, a u Istanbulu su održane proslave. Sve države, uključujući saveznicu Njemačku, protestirale su protiv odluke; kapitulacije će konačno otići u historiju tek 1923. u Lausannei.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Prepad na Crnom moru: osmanska flota bombardira ruske luke", "8ad4ef61"], "d": ["Goeben i Breslau (Yavuz i Midilli), koji su pobjegli iz Njemačke i kao 'kupljeni' pridruženi osmanskoj floti, isplovili su pod zapovjedništvom admirala Souchona na Crno more, topovima tukli ruske luke i potopili brodove. Ta naredba, koju je Enver-paša dao krijući od kabineta, faktički je okončala neutralnost. Za sedmicu dana Rusija, Engleska i Francuska objavile su rat, a Osmanska država nepovratno je ušla u Prvi svjetski rat.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Britansko-indijske snage zauzimaju Fao — otvaranje iračkog fronta", "08663813"], "d": ["Ujutro, dan nakon što su države Antante objavile rat Osmanskoj državi, britansko-indijska brigada koja je čekala u Bahreinu iskrcala se u Fao na ušću Šat al-Araba. Mala osmanska jedinica u ruševnoj tvrđavi Fao povukla se pod vatrom ratnih brodova, a stanica indijske telegrafske linije pala je u britanske ruke. Tako je otvoren irački front.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proglašenje Velikog džihada: čitanje fetve o džihadu u Fatihovoj džamiji", "2a6174e8"], "d": ["Pet fetvi šejhul-islama Urguplu Hajri-efendije pročitano je u Fatihovoj džamiji u ime halife-sultana, i svi muslimani pozvani su na džihad protiv sila Antante. Taj potez, na koji je Njemačka polagala velike nade, imao je cilj podići muslimane u britanskim i francuskim kolonijama. Očekivani opći ustanak nije se dogodio; naprotiv, dvije godine kasnije ustanak mekanskog emira šerifa Huseina uz britansku podršku gorko je pokazao granice političkog uticaja hilafeta.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Predaja Kurne Britancima", "621d36b0"], "d": ["Snage basranskog valije Subhi-bega, koji se nakon pada Basre povukao u Kurnu na sastavu Tigrisa i Eufrata, nakon borbi 4–8. decembra predale su se ujutro 9. decembra 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Sarikamiška operacija: katastrofa na kavkaskom frontu", "5cbde7f0"], "d": ["Enver-paša, s ciljem da povrati Kars, Ardahan i Batum, izgubljene 1878, i digne Turke na Kavkazu, gurnuo je Treću armiju u manevar opkoljavanja ruskih snaga zimi preko planina Allahuekber. Zbog nedovoljne zimske opreme, iscrpljene opskrbe i mećave na minus trideset stepeni armija se istopila i prije nego što je stupila u bitku; desetine hiljada vojnika smrzle su se na smrt. Operacija je postala jedna od najtežih osmanskih katastrofa u ratu i ostavila istočni front dvije godine nezaštićenim.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Prvi pohod na Kanal: napad na Suez preko Sinajske pustinje", "02dd72f5"], "d": ["Zapovjednik Četvrte armije Džemal-paša, s ciljem da oslobodi Egipat od britanske okupacije i zatvori Sueski kanal za plovidbu, organizirao je napad preko Sinajske pustinje. Iako su osmanske jedinice stigle do istočne obale kanala, a dio ih uspio prijeći na drugu stranu, zbog britanske nadmoći i izostanka očekivanog ustanka egipatskog naroda povukle su se. Operacija nije postigla cilj, ali je, prisilivši Englesku da u Egiptu drži velike snage, ostvarila posredan strateški učinak.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Donošenje Zakona o upućivanju i naseljavanju (deportaciji)", "2f2bc22c"], "d": ["Nakon ustanka u Vanu i ruskog napredovanja vlada je donijela privremeni zakon koji je dopuštao da vojni zapovjednici premjeste u druge oblasti stanovništvo za koje se smatralo da narušava sigurnost u pozadini fronta, a sultan ga je potvrdio 27. maja 1915. Kao rezultat primjene veći dio armenskog stanovništva istočnih i južnih anadolskih vilajeta upućen je prema Siriji i Mosulu; tokom transporta zbog bolesti, gladi i napada došlo je do vrlo velikih ljudskih gubitaka. Ta odluka ostala je najteže i do danas najspornije pitanje posljednjih godina Osmanlija.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Osmanske jedinice povratile Muš od ruske okupacije", "fb1be113"], "d": ["Šest mjeseci nakon prve ruske okupacije Muša osmanski 16. korpus ušao je u gradić u protunapadu na pravcu Bitlis–Muš.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muš ponovo prešao u ruske ruke", "43ad8a03"], "d": ["Pred ruskim protunapadom osmanski odred ispraznio je Muš; gradić je između 22. i 25. augusta 1916. ponovo pao pod rusku okupaciju i ostao u njihovim rukama do proljeća 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muš konačno oslobođen od ruske okupacije", "f0e89703"], "d": ["Muš, koji je u Prvom svjetskom ratu pao pod rusku okupaciju, osmanske su snage 1. maja 1917. konačno povratile.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Smrt Abdul-Hamida II u saraju Bejlerbeji", "c9662582"], "d": ["Abdul-Hamid II, svrgnut 1909, najprije poslan u Solun, a nakon gubitka grada u Balkanskom ratu doveden u Istanbul i držan pod nadzorom u saraju Bejlerbeji, umro je. Tokom trideset tri godine vladavine nastojao je držati državu daleko od ratova i dobiti na vremenu, ali se pamtio i po apsolutističkoj upravi. Njegov pogreb uz veliko mnoštvo obavljen je u turbetu Mahmuda I na Divanyoluu; njegova smrt poklopila se s ratnom godinom u kojoj je poredak koji je uspostavio već odavno bio likvidiran.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Brest-litovski mir: povratak Karsa, Ardahana i Batuma", "da82636f"], "d": ["Ugovor potpisan između Rusije, koja se nakon boljševičke revolucije povukla iz rata, i Centralnih sila zatvorio je istočni front i Osmanskoj državi vratio Kars, Ardahan i Batum (Elvije-i Selase), izgubljene Berlinskim ugovorom 1878. Bio je to jedini teritorijalni dobitak u osmanskoj historiji stečen nakon četrdeset godina pauze. Međutim, nakon Mudroskog primirja oblast će ponovo biti izgubljena, a konačno rješenje doći će Karskim ugovorom 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Osmanske jedinice ušle u Artvin", "ca7d1778"], "d": ["Osmanske jedinice, koje su 25. marta prešle granicu iz 1914, krenule su na Elvije-i Selase, koje je Brest-Litovsk vratio na granicu prije 1878, i ušle u Artvin 28. marta 1918. Artvin je kao dio Batumskog sandžaka 1878. ostavljen Rusiji; članak TDV-a o Artvinu povratak bilježi samo kao 'mart 1918', a dan daje Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan prešao u ruke turske vojske", "7fd9e3db"], "d": ["U akciji za Elvije-i Selase osmanska vojska nakon Artvina zauzela je 3. aprila 1918. Ardahan; Ardahan je pao u ratu 1877–78, godine 1877, i 1878. ostavljen Rusiji. Kars će biti zauzet mjesec dana kasnije, 25. aprila.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Povratak Batuma", "d37a1a0d"], "d": ["Osmanska vojska, koja je nakon povlačenja Rusije iz rata Brest-litovskim mirom napredovala na istok, četrdeset godina kasnije povratila je luku Batum, izgubljenu 1878. Ta luka na istočnom kraju Crnog mora bila je morski izlaz bakinske nafte. Dobitak je trajao samo sedam mjeseci; nakon Mudroskog primirja oblast će biti ispražnjena.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elvije-i Selase: Kars ulazi pod osmansku upravu", "02cbf0b3"], "d": ["U Brest-Litovsku je dogovoren povrat triju sandžaka izgubljenih Berlinskim ugovorom 1878. — Karsa, Ardahana i Batuma; osmanska vojska ušla je u Ardahan 3. aprila, u Batum 14. aprila, a u Kars 25. aprila 1918. i uprava je faktički uspostavljena. Te zemlje, nazivane 'Elvije-i Selase' (Tri sandžaka), smatrane su nadoknadom gubitka koji je trajao od rata 1877–78. Nakon primirja ponovo će biti izgubljene, a Turskoj će konačno pripasti tek Karskim ugovorom 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Zauzet Igdir — napredovanje dolinom Araksa", "87ebf4d3"], "d": ["U okviru ofanzive započete u februaru 1918. turske jedinice porazile su armenske jedinice kod Sardarapata sjeverno od Araksa i 20. maja 1918. zauzele Igdir. Igdir nije spadao u Elvije-i Selase, nego je bio kadiluk Surmalu Erivanske gubernije; nakon otprilike 180 godina u toj oblasti uspostavljena je prva osmanska uprava.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Smrt Mehmeda V Rešada i stupanje na prijestolje Mehmeda VI Vahdeddina", "d302ba07"], "d": ["Mehmed V Rešad, čija je devetogodišnja vladavina protekla u tripoliskom, balkanskom i svjetskom ratu, umro je u najkritičnijem periodu rata, a na prijestolje je pod imenom Mehmed VI stupio njegov brat Vahdeddin. Novi sultan pokušao se osloboditi tutorstva itihadističkog kadra; četiri mjeseca kasnije, kad je potpisano primirje, morat će voditi likvidaciju carstva. Bio je trideset šesti i posljednji sultan dinastije Osmanlija.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Dolazak flote Antante pred Istanbul i faktička okupacija grada", "d10cb14d"], "d": ["Nakon Mudroskog primirja saveznička flota od više od šezdeset jedinica, sastavljena od britanskih, francuskih, italijanskih i grčkih brodova, usidrila se pred Dolmabahčeom, a Istanbul je faktički okupiran. Nakon četiri stotine šezdeset pet godina prijestolnica je prvi put prešla pod nadzor stranih vojnika. Riječi 'Otići će onako kako su i došli', za koje se prenosi da ih je istog dana izgovorio Mustafa Kemal-paša, sišavši na Hajdarpaši i vidjevši prizor, postat će jedna od simboličnih rečenica Narodne borbe.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Povlačenje u oblasti Araksa: Igdir ispražnjen", "57572ab4"], "d": ["U skladu s odredbom Mudroskog primirja o povlačenju iza granice iz 1914, Jakup Ševki-paša naredbom od 21. novembra naredio je da se jedinice izvan brest-litovske granice povuku do 4. decembra; Igdir i okolina tada su potpuno ispražnjeni. Zatim su Armenci krajem decembra 1918. srušili Araks-tursku vladu.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Englezi se smjestili u Artvinu", "e2cb3153"], "d": ["Budući da je Mudroskim primirjem od 30. oktobra 1918. bilo uslovljeno povlačenje osmanske vojske iza granice iz 1914, Artvin je ispražnjen i 17. decembra 1918. okupirali su ga Britanci. Prema članku TDV-a o Artvinu britanska okupacija trajala je do aprila 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Britanska uprava u Batumu nakon Mudrosa", "9dd768fc"], "d": ["Prema Mudroskom primirju od 30. oktobra 1918. Osmanska država morala se povući iz Batuma; grad su 24. decembra 1918. zaposjele britanske jedinice. Batum, koji je u aprilu 1918. postao sjedište samostalnog sandžaka, od tada do jula 1920. ostao je pod britanskim nadzorom.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan prešao pod gruzijsku vlast", "97cf47f6"], "d": ["Ardahan, ispražnjen nakon Mudrosa, gruzijske snage okupirale su 20. aprila 1919, u danima kada su Englezi raspustili Vladu Jugozapadnog Kavkaza. Gruzijska vlast trajat će do 23. februara 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston predao upravu Karsa armenskom guverneru", "efa81cb0"], "d": ["Britanski zapovjednik Preston, koji je 12–13. aprila 1919. raspustio Vladu Jugozapadnog Kavkaza, 30. aprila 1919. ukinuo je privremenu vijećnu vladu i upravu grada predao Armencu Karganovu, postavljenom za guvernera Karsa; u Karsu je počelo razdoblje armenske uprave, koje je trajalo do pobjede Kazima Karabekira 30. oktobra 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Erzurumski kongres: odluka istočnih vilajeta o nacionalnom otporu", "41ef0457"], "d": ["Kongres koji je sazvalo Društvo za odbranu prava Istočne Anadolije, odgođen zbog britanskog pritiska, otvoren je s pedeset šest delegata, a za predsjednika je izabran Mustafa Kemal-paša, koji je dao ostavku na vojnu službu. Kongres je proglasio da je domovina unutar nacionalnih granica cjelina, da se mandat i protektorat ne mogu prihvatiti te da će narod, u slučaju raspada vlade, sam uzeti sudbinu u svoje ruke. Te odluke će šest mjeseci kasnije činiti jezgro teksta Nacionalnog pakta.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Sivaski kongres: ujedinjenje nacionalnog otpora pod jednim krovom", "0e9ad36b"], "d": ["Kongres, koji je počeo s radom 4. septembra 1919. u Sivaskoj gimnaziji (Sivas Sultanisi), ujedinio je društva za odbranu prava sa svih strana zemlje pod imenom Društvo za odbranu prava Anadolije i Rumelije i izabrao Predstavnički odbor. Prijedlog o američkom mandatu odbačen je nakon dugih rasprava. Deklaracijom objavljenom 11. septembra Narodna borba postala je legitimni politički pokret s jednim središtem i počela je otvorena borba za moć s istanbulskom vladom.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Amasijski protokol: razgovori istanbulske vlade s Predstavničkim odborom", "40e6a6ab"], "d": ["Nakon pada Damat Ferida i formiranja vlade Ali Riza-paše, ministar mornarice Salih-paša poslan je u Amasyu na razgovore s Predstavničkim odborom. Postignutim protokolima istanbulska vlada faktički je priznala postojanje anadolskog pokreta; prihvaćeni su sazivanje Medžlis-i Mebusana, slobodno održavanje izbora i očuvanje nacionalnih granica. To je prvi zvanični politički dobitak Narodne borbe nasuprot Istanbulu.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Prihvatanje Nacionalnog pakta (Misak-i Milli) u posljednjoj osmanskoj skupštini", "6322865e"], "d": ["Tekst Nacionalne zakletve (Ahd-i Milli), koji je u posljednjem osmanskom Medžlis-i Mebusanu potpisao 121 poslanik, uslovljavao je nedjeljivu cjelovitost zemalja unutar mudroske linije u kojima živi muslimansko-turska većina, plebiscit u arapskim vilajetima i Zapadnoj Trakiji, ukidanje kapitulacija i potpunu političko-finansijsku nezavisnost. Tekst je 17. februara 1920. jednoglasno usvojen i objavljen svijetu. Ta deklaracija bila je i politički program Narodne borbe i karta granica koje će se braniti u Lausannei; postala je neposredan uzrok zvanične okupacije Istanbula od sila Antante 16. marta.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Pri povlačenju Britanaca Artvin ostao Gruziji", "6d086b06"], "d": ["Prema članku TDV-a o Artvinu britanska okupacija trajala je do aprila 1920; povlačeći se, Britanci su grad ostavili Gruziji. Artvin je u gruzijskim rukama ostao do ultimatuma TBMM od 23. februara 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum predan gruzijskoj upravi", "6523d095"], "d": ["Zvanična primopredaja Batuma od Britanaca Gruzijcima obavljena je 7. jula 1920. (članak TDV-a o Batumu navodi samo 'juli 1920'). Ankarska vlada protestirala je 25. jula, nazivajući predaju 'okupacijom'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Ugovor u Gjumriju: prvi međunarodni ugovor vlade TBMM", "9232c690"], "d": ["Kad je vojska istočnog fronta pod zapovjedništvom Kazima Karabekira povratila Sarikamiš i Kars, Armenija je zatražila mir i ugovorom potpisanim u Gjumriju prihvatila da ne priznaje Sèvres i da se odriče teritorijalnih zahtjeva na istoku. Taj prvi ugovor koji je potpisala ankarska vlada postao je prvi međunarodni dokument koji je faktički odbacio Sèvres i otvorio TBMM-u put ka pravnom priznanju. Tako je osigurana istočna granica i postalo je moguće prebaciti snage na zapadni front.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Prva bitka kod Inönüa: prva pobjeda regularne vojske", "4add3719"], "d": ["Novoformirana regularna vojska zaustavila je na položajima kod Inönüa grčke snage koje su napredovale iz pravca Burse i primorala ih na povlačenje. Taj uspjeh, vojno ograničenog obima, po političkim posljedicama bio je vrlo velik: ankarska vlada pozvana je na Londonsku konferenciju, otvoren je put Moskovskom ugovoru sa Sovjetskom Rusijom i usvojen je Zakon o ustavnom ustrojstvu (Teškilat-i Esasijje). Tom pobjedom učvrstilo se i povjerenje domaće javnosti u regularnu vojsku.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Druga bitka kod Inönüa: grčki napad slomljen drugi put", "a974521c"], "d": ["Grčka vojska, koja na Londonskoj konferenciji nije postigla rezultat, krenula je u novi napad iz pravaca Burse i Ušaka, ali je opet zaustavljena na grebenima Inönüa i morala se povući. Nakon te pobjede napisan je telegram Mustafa Kemal-paše Ismet-paši: 'Vi ste tamo pobijedili ne samo neprijatelja nego i zlu sudbinu naroda'. Bitka je podigla međunarodni ugled Narodne borbe i ubrzala proces povlačenja Italije iz Anadolije.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Ankarski sporazum: mir s Francuskom i zatvaranje južnog fronta", "35fc32db"], "d": ["Sporazumom potpisanim u Ankari s Francuskom nakon pobjede na Sakarji okončan je rat na južnom frontu; francuske snage ispraznile su Čukurovu i jugoistok, uključujući Adanu, Antep, Maraš i Urfu, i povukle se na sirijsku granicu. Tako je jedna od država Antante faktički priznala ankarsku vladu i otvorila prvu pukotinu na sevrskom frontu. Oružje preuzeto iz ispražnjenih područja i oslobođene jedinice odigrali su ključnu ulogu u pripremi Velike ofanzive.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Mudanijsko primirje: prijenos Istanbula i moreuza bez rata", "ac0d9baf"], "d": ["Konferencija sazvana u Mudanyi nakon što se turska vojska nakon Velike ofanzive u Čanakkaleu i Izmitu našla licem u lice s britanskim snagama završila je primirjem nakon jedanaestodnevnih teških pregovora. Dogovoreno je da Grčka u roku od petnaest dana isprazni Istočnu Trakiju do Marice i preda je turskoj upravi te da se Istanbul i moreuzi predaju mirovnim ugovorom. Tako je oružana faza Narodne borbe završena diplomatskom pobjedom stečenom bez ijednog ispaljenog metka i otvorena su vrata Lausannee.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Odlazak Mehmeda VI Vahdeddina iz Istanbula i izbor Abdul-Medžid-efendije za halifu", "8ab0e847"], "d": ["Posljednji sultan Mehmed VI Vahdeddin, čiji je položaj nakon ukidanja sultanata postao sporan, u petak ujutro 17. novembra 1922. napustio je Istanbul britanskim oklopnjačom Malaya i otišao na Maltu. TBMM je dva dana kasnije, 19. novembra, za halifu bez političkih ovlaštenja izabrao Abdul-Medžid-efendiju. Tako je faktički okončana šest stotina dvadeset tri godine duga vladavina osmanske dinastije; hilafet će, pak, simbolično trajati još petnaest mjeseci. Vahdeddin, koji je prešao na Maltu, a zatim u Italiju, nastanio se u Villa Nobel u San Remu; njegovi zahtjevi za prijem u neku muslimansku zemlju ostali su bez rezultata i ondje je umro 16. maja 1926, ponavljajući da se nikada nije odrekao prava na sultanat i hilafet.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Smrt posljednjeg sultana Mehmeda VI Vahdeddina u San Remu", "7149ed0e"], "d": ["Posljednji osmanski sultan Mehmed Vahdeddin, koji se nakon odlaska iz Istanbula nastanio u italijanskom gradu San Remu, umro je 16. maja 1926. ne saznavši da se sastao kongres o hilafetu (13. maja 1926), kojem je poručio da se nikada nije odrekao prava na sultanat i hilafet. Bio je u teškoj novčanoj oskudici; trgovcima San Rema dugovao je 60.000 lira, a povjerioci koji su čuli za njegovu smrt dali su zaplijeniti namještaj njegove kuće.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Konuralpovo osvajanje oblasti Bolua — Mudurnu, Konurapa i Bolu", "e245cd27"], "d": ["Konuralp, jedan od zapovjednika Orhan Gazija, krenuo je prema brdovitoj oblasti istočno od Sakarje i pripojio Mudurnu, Konurapu i oblast Bolua osmanskoj upravi; gradić u Düzce-ravnici nazvan je po njemu. Tačan datum osvajanja nije poznat; priča se oslanja na predaju Ašik-paša-zadea. Oblast je tada bila krajiško područje koje je prelazilo iz ruke u ruku između Džandarogulla i Bizanta; osvajanje je Osmanlije prvi put približilo zapadnoj obali Crnog mora. Nakon Ankarske bitke oblast će opet prijeći Džandarogullima, ali će u doba Mehmeda II Osvajača biti konačno vraćena.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Zauzimanje bizantskih gradića južno od Mramornog mora — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Nakon zauzimanja Nikeje i Izmita, gradići koje je Bizant držao zapadno od burske ravnice jedan po jedan ušli su pod osmansku upravu. Gölyazı oko jezera Uluabat te Kirmasti i Mihaliç uz potok Susurluk upotpunili su koridor koji južnu obalu Mramornog mora povezuje sa zemljama Karesija. Ti su se gradići dugo bez opsade predavali zbog presijecanja njihove okoline; tako se bizantsko prisustvo u oblasti stisnulo na Gemlički zaljev.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korint prešao Morejskoj despotovini", "392495eb"], "d": ["Korint, koji je od 1358. bio leno firentinske porodice Acciajuoli u sklopu Ahajske kneževine, 1395. prešao je u ruke bizantskog despota Moreje Teodora. Grad je od tada do osmanskog osvajanja ostao pod upravom despotovine.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksija Bejluka Hadžiemirogulla — Ordu i Ünye", "c064f07f"], "d": ["Turkmenski bejluk, koji je Bajram-beg osnovao oko Ordua, a njegov sin Hadži Emir proširio 1350-ih, bio je mala, ali strateška obalna država sa središtem u današnjem Eskipazaru: jedino nezavisno područje vlasti između Samsuna i Trabzona. Emir Sulejman 1398. je u džaničkoj akciji Bajazida I Munje iskazao odanost, a nakon Ankarske bitke bejluk je ponovo bio slobodan. U doba Murata II, istih godina kada su likvidirani Tadžeddinogulli, zemlje bejluka neposredno su pripojene osmanskoj upravi, a crnomorska obala od Samsuna do Giresuna objedinjena je pod jednom rukom.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Osvajanje Korinta", "87a2bc59"], "d": ["U morejskom pohodu Mehmeda II Osvajača tvrđava Akrokorint opsjedana je tri mjeseca i na kraju preuzeta mirnim putem. Tako je Korintska prevlaka, smatrana vratima Moreje, prešla Osmanlijama.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Pripajanje Crne Gore osmanskoj upravi — Cetinje", "7fdb7cc8"], "d": ["Kad je dinastija Crnojevića, koja je vladala Zetom, 1496. napustila vlast, brdovita oblast Crne Gore, zaleđe Skadra, stavljena je pod neposrednu osmansku upravu i najprije ustrojena kao zaseban sandžak, a zatim kao dio Skadarskog sandžaka. Cetinjski manastir ostavljen je kao vjersko središte oblasti. Zbog surovosti reljefa uprava ovdje nikada nije funkcionirala tako čvrsto kao u ravnicama; dva stoljeća kasnije vladičanska uprava rođena iz istog manastira bit će jezgro faktičke nezavisnosti.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Tvrđava Bajazit prihvatila osmansku vlast u pohodu na dva Iraka", "f29e2e17"], "d": ["Kad je veliki vezir Ibrahim-paša u pohodu na dva Iraka stigao u okolinu Bingöla, tvrđave Van, Toprakkale, Avnik i Bajazit, zajedno s mnogim kurdskim plemenima te oblasti, pristale su ući pod osmansku vlast. Bajazit je 1514. u Selimovom pohodu pripojen Osmanlijama, ali kad se vojska vratila, Safavidi su povratili oblast.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz ponovo prešao Safavidima — povratak s pohoda na dva Iraka", "80b8b761"], "d": ["U pohodu na dva Iraka vojska je ušla u Tabriz, ali budući da je pravi cilj bio Bagdad, u gradu nije ostavljena stalna posada. Dok se vojska, koja je zimu provela u Bagdadu, vraćala na zapad, šah Tahmasp ponovo je ušao u ispražnjeni Azerbejdžan i povratio Tabriz. To je bio ponavljani obrazac osmansko-safavidskih ratova: Tabriz je pet puta zauzet i nijednom od tih pet puta nije zadržan; grad će tek 1585. dobiti dugotrajnu osmansku posadu.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van i Erciş pali u Tahmaspove ruke (osmansko držanje okončano 1534–35.)", "cb93d561"], "d": ["U oblasti koja je Van 1534. predala osmanskoj vlasti Ulama-paša odolijevao je safavidskoj opsadi u Vanskoj tvrđavi; tvrđava je prešla u safavidske ruke, a safavidske snage koje su opsjedale Erciş povukle su se zbog osmanske pomoći. Kad je Sulejman Zakonodavac stigao u Ahlat (23. septembra 1535), Van je već bio u Tahmaspovim rukama. Van je ostao safavidski do 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Prelazak Bajazitskog sandžaka pod safavidsku vlast (Van i Erciş već su 1535. bili safavidski)", "806a2cf1"], "d": ["Bajazitski sandžak na sredini osmansko-safavidske granice ponovo je prešao u iranske ruke (Kaya 2017 to spominje kao 'zajedno s Vanom i Erdžišem'; međutim, Van i Erciş su se prema Karataşu 2025. i TDV-u 22. septembra 1535. vratili Safavidima — vidi prethodni zapis); pri toj promjeni vlasti neka mjesta sandžaka opustošena su. Sandžak je do posljednje četvrtine 16. stoljeća više puta prelazio iz ruke u ruku između dviju država.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Povratak Bajazitskog sandžaka Osmanlijama za nahičevanskog pohoda", "cf0171fa"], "d": ["Za trećeg iranskog (nahičevanskog) pohoda Sulejmana Zakonodavca Bajazitski sandžak ponovo je stavljen pod osmansku upravu. U pohodu 1554. Bajazit je bio važna baza za vojsku; sandžak je 1578. konačno ušao pod osmansku vlast.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Gubitak Erivana u korist šaha Abasa", "34413cf2"], "d": ["U godinama kad su dželalijski ustanci paralizirali Anadoliju i istočni front ostao nezaštićen, šah Abas, koji je svoju vojsku preuredio po evropskom uzoru, prešao je u napad. Erivanska tvrđava, koju je 1583. dao sagraditi Ferhad-paša, predala se nakon sedmomjesečne opsade. Pukla je prva karika kavkaske linije dobivene Ferhad-pašinim mirom, a u iduće tri godine bit će izgubljen cijeli Južni Kavkaz.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Gubitak Tbilisija i Gandže", "3fb51753"], "d": ["Nakon pada Erivana safavidska vojska napredovala je dolinom Kure; Gandža, središte Karabaha, i Tbilisi, glavni grad Gruzije, jedan za drugim su izgubljeni. Osmanska država istovremeno je na austrijskom frontu vodila trinaestogodišnji dugi rat i bavila se dželalijama u Anadoliji; nije bilo snage koja bi se uputila na istok. Tako je faktički okončan poredak širokih kavkaskih ejaleta uspostavljen Ferhad-pašinim mirom 1590.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Gubitak Širvana — Šamahi, Baku i Derbent", "81beab11"], "d": ["Ejalet Širvan na obali Kaspijskog jezera, osvojen pohodima Ozdemiroglu Osman-paše 1578–1585, kao glavni izvor trgovine svilom donosio je osmanskim finansijama značajan prihod. Safavidska akcija prema sjeveru redom je zauzela Šamahi, Baku i Derbent i likvidirala taj ejalet. Gubitak nije bio samo teritorijalni: i put kojim je iranska svila preko Osmanlija tekla u Evropu izašao je ispod kontrole, a safavidska država počela je prodavati svilu preko Indijskog okeana.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Gubitak Taiza", "65f20d53"], "d": ["Osmanlije su 1038. (1629), zajedno s vlašću nad Jemenom prepuštenom kasimskoj upravi u Sani, napustile i Taiz — prvi veliki korak procesa u kojem su zejdijski imami povratili unutrašnji Jemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Gubitak Jemena — vlast kasimskih imama", "49e83e3c"], "d": ["Jemen je od 1538. bio osmanski ejalet, ali otpor zejdijskih imama nikada nije prestao. Ustanak koji je pokrenuo imam Kasim u doba njegovog sina el-Muejjeda Muhammeda proširio se po cijeloj zemlji, a osmanske posade redom su opsjedane. U godinama kad se Murat IV usredsredio na Bagdad i Erivan nije se moglo poslati pojačanje; Taiz je izgubljen 1629, a Moka je ispražnjena u posljednjoj fazi istog sloma 22. oktobra 1635. Godine 1635. i posljednje jedinice u Sani i Zebidu napustile su Jemen. Tako je istočna obala Crvenog mora ostala izvan carstva dvjesto trideset sedam godina i mogla se vratiti tek 1872. Lehedž (el-Havta) je, prema Islamskoj enciklopediji TDV-a, do 1635. bio u osmanskim rukama; od tada su ondje djelovali zejdijski imami.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evakuacija Moke", "c6b3061a"], "d": ["Mustafa-beg je 10. džumadel-ula 1045. (22. oktobra 1635) s preostalom snagom i oružjem ispraznio Moku; zatim je Hasan b. Kasim, sin imama Kasima, postavio svoje ljude u Zebidu i Moki i uspostavio kasimski nadzor i na obali Tihame.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Gubitak Lahse u korist Emirata Benu Halid", "a9b6131a"], "d": ["Lahsa je bila ejalet osnovan 1550. da zapadnu obalu Basranskog zaljeva zatvori Portugalcima, ali je bila veoma daleko od Istanbula, na kraju jedinog pustinjskog puta. U godinama kad je opsada Krete trošila resurse, pleme Benu Halid u toj oblasti pod vodstvom Barraka b. Gurejra istjeralo je osmansku posadu i uspostavilo vlastiti emirat. Zapadna obala zaljeva vijek i po ostala je u plemenskim emiratima; 1795. prijeći će Saudijcima, a 1871. ponovo Osmanlijama.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Gubitak Preveze i Vonitse u korist Venecije — otvaranje epirske obale", "1201204c"], "d": ["Venecija, koja je pristupila Svetoj ligi, prije početka morejskog pohoda zauzela je dvije tvrđave koje drže ulaz u Ambrakijski zaljev: Prevezu i Vonitsu na suprotnoj obali. Istog ljeta pala je i Lefkada (Aja Mavra). Ta tri položaja omogućila su floti da se iz Jonskog mora sigurno uvuče u unutrašnjost Grčke i postala baza morejske akcije koja će početi iduće godine. Preveza i Vonitsa i u Požarevcu su ostavljene Veneciji; pod osmansku upravu vratit će se tek 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Gubitak Solnoka — raspadanje linije Tise", "51c2c8ef"], "d": ["Nakon pada Uyvara u augustu habsburška vojska okrenula se na jug i zauzela mostobran na Tisi, Solnok. Grad je bio jedini siguran prijelaz između Budima i Erdelja; njegov gubitak značio je da se osmanske tvrđave u istočnoj polovini Ugarske odvajaju jedna od druge. Iduće godine u opsadi Budima presudno je bilo to što je put opskrbe bio presječen.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Gubitak Modona u korist Venecije", "114c9cc0"], "d": ["Modon na jugozapadnom kraju Moreje bio je luka koju je Venecija izgubila tri stoljeća ranije i nazivala 'jednim od dva oka države'. Tvrđava opsjednuta nakon pada Korona preuzeta je istovremenim granatiranjem s kopna i s mora. Morosinijeva morejska akcija tako je zauzela cijelu zapadnu obalu poluotoka i otvorila put ka unutrašnjosti.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Gubitak Pečuha", "99d54cf4"], "d": ["Nakon pada Budima u septembru habsburške snage spustile su se na jug zapadno od Dunava i zauzele Pečuh, osmanski od doba Sulejmana Zakonodavca. Grad, koji se pamti po džamiji Gazi Kasim-paše, bio je jedno od najrazvijenijih sandžačkih središta Budimskog ejaleta. Njegov gubitak značio je otvaranje puta prema mohačkoj ravnici; iduće godine upravo ovdje dogodit će se poraz u Drugoj bitki kod Mohača.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Gubitak Segedina", "9fbee1b2"], "d": ["Segedin na sastavu rijeka Tise i Moriša bio je južna vrata Panonske ravnice i držao je put prema Temišvarskom ejaletu. Tvrđava, opsjednuta nakon pada Budima i Pečuha iste jeseni, ubrzo se predala. Gubitak triju tvrđava u jednom godišnjem dobu bio je znak da se osmanska upravna struktura u Ugarskoj, uspostavljena od 1541, počinje urušavati. Atlas istog dana i Sentu na Tisi smatra pređenom od Osmanlija na habsburšku stranu (dan predaje specifičan za Sentu nije pročitan u izvoru, dan je preuzet od Segedina; TDV zenta: od oktobra 1686. počeli su sukobi između Osmanlija i saveznika pod habsburškim vodstvom — deklarirana približnost).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Gubitak Patrasa (Baljabadra) — sjeverna vrata Moreje", "b9cff63c"], "d": ["Patras na ulazu u Korintski zaljev bio je luka koja nadzire prolaz između Moreje i Rumelije. Kad je venecijanska vojska zauzela grad, i tvrđave na obje obale zaljeva pale su jedna za drugom, a poluotok je potpuno odsječen s kopna. Na kraju te akcije cijela Moreja prešla je Veneciji; oblast će do 1715. biti upravljana pod imenom 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Prepuštanje Korinta Veneciji", "9a25b6b9"], "d": ["Nakon pada Patrasa Korint je mirnim putem prepušten Venecijancima, a muslimansko stanovništvo napustilo je grad. U augustu 1687. Morosinijeva vojska okupljala se u Korintu za pohod na Atinu.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Gubitak Jegra", "983391aa"], "d": ["Jegar je zauzet 1596. u pohodu u kojem je lično učestvovao Mehmed III i bio je središte ejaleta nazvanog po njemu. Ta posljednja velika osmanska tvrđava u Sjevernoj Ugarskoj, nakon poraza u Drugoj bitki kod Mohača potpuno opkoljena, godinu dana se opirala i predala se zbog gladi. Njenim gubitkom sjeverno krilo Osmanske države u Ugarskoj u cijelosti je likvidirano.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Gubitak Stolnog Biograda — krunidbenog grada ugarskih kraljeva", "c6147255"], "d": ["Grad u kojem su se ugarski kraljevi stoljećima krunili i sahranjivali zauzeo je 1543. Sulejman Zakonodavac i bio je jedno od najvažnijih sandžačkih središta Budimskog ejaleta. Otprilike dvije godine nakon pada Budima tvrđava, potpuno odsječena od okoline, predala se. Tim gubitkom osmansko prisustvo zapadno od Dunava stisnulo se na okolinu Srijema i Osijeka.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Gubitak Sigeta", "834910a7"], "d": ["Siget je bio tvrđava kod koje je sultan Sulejman Zakonodavac u svom trinaestom i posljednjem pohodu 1566. umro dok je opsada trajala; zato je u osmanskom pamćenju imao simbolično mjesto. Sto dvadeset tri godine kasnije, nakon pada svih okolnih tvrđava, i tvrđava zaštićena močvarama se predala. Turbe u kojem su sahranjeni unutrašnji organi Sulejmana Zakonodavca i gradić oko njega srušeni su nakon prelaska pod habsburšku upravu. Ostalo naselje koje je istog datuma u atlasu prešlo od Osmanlija Habsburgovcima: Barcs — slijedi lanac matičnog središta Sigeta (Bánlaky 0017/1449; deklarirana približnost).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Gubitak Varada", "6cce360d"], "d": ["Varad je bio ključna tvrđava prema Erdelju, koju je 1660. zauzeo Mehmed-paša Ćuprilić i učinio je središtem ejaleta nazvanog po njoj. Tvrđava, koja je nakon poraza kod Slankamena ostala potpuno sama, predala se zbog gladi nakon gotovo dvogodišnje blokade. Njenim gubitkom faktički je okončan osmanski uticaj nad Erdeljom, a habsburška vlast učvrstila se istočno od Tise.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Gubitak Janove — zatvaranje puta za Erdelj", "4b5e30d8"], "d": ["Janova, zauzeta 1658, bila je tvrđava koja je držala vezu između Varada i Temišvara. Kad je neposredno nakon pada Varada odsječena od okoline, i ona je izgubljena. Tako je Temišvarski ejalet potpuno odsječen sa sjevera i do Karlovačkog mira opstao je kao jedina ugarska zemlja koja je ostala u osmanskim rukama.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Uspostava vladičanske uprave u Crnoj Gori — faktičko odvajanje Cetinja", "a924b778"], "d": ["U godinama kad je rat Svete lige oslabio osmanski nadzor na Balkanu, mitropolija na čelu Cetinjskog manastira postala je u porodici Petrovića položaj koji se prenosio s koljena na koljeno, a oblast je faktički stekla zasebnu upravu. Zahvaljujući nepristupačnosti planina ta vladičanska država dva stoljeća opstajala je ni potpuno nezavisna ni potpuno podložna; pravno će njena nezavisnost biti priznata tek Berlinskim ugovorom 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Povratak Korinta", "26f53e3a"], "d": ["Prva velika stanica morejskog pohoda damat Ali-paše bio je Korint; Osmanlije su u junu 1715. povratile grad od Venecijanaca i odatle napredovale prema ostatku poluotoka.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Nadirov napad: gubitak Tabriza, Nahičevana, Hamadana, Kermanšaha, Marage i Kasr-i Širina", "d95efd59"], "d": ["Zapadnoiranski gradovi, zauzeti 1723–1727. korištenjem sloma safavidske države, redom su izgubljeni napadom Nadir-kana, koji je faktički preuzeo vlast u Iranu. U Azerbejdžanu su i Ardabil i Halhal prešli u Nadirove ruke. Gubitak Hamadana, Kermanšaha i Kasr-i Širina snažno je odjeknuo u Istanbulu; to što vojska nije krenula u pohod, nego je čekala u Uskudaru, i pokušaj da se gubitak zataška bili su jedan od neposrednih uzroka ustanka Patrone Halila, koji je izbio šest sedmica kasnije. Atlas i Kotur, koji slijedi lanac Hoja, smatra da je tog dana prešao od Osmanlija Safavidima (Uluerler 2015, Turkish Studies 10/5, str. 6; dan specifičan za Kotur nije naveden u izvoru — deklarirana približnost).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Poraz kod Baghavarda (Arpačaj) — gubitak Kavkaza u korist Nadir-kana", "4262f54c"], "d": ["Kavkaski ejaleti, zauzeti 1723–1725. korištenjem sloma safavidske države, mogli su se zadržati deset godina. Nadir-kan, koji je faktički preuzeo vlast u Iranu, kod Baghavarda blizu Erivana teško je porazio osmansku vojsku; serdar Abdullah-paša Ćuprilić poginuo je na bojnom polju. Nakon poraza Erivan, Tbilisi, Gandža i Širvan ispražnjeni su u roku od nekoliko mjeseci. Istočna granica vratila se na liniju Kasr-i Širina iz 1639, što će biti potvrđeno 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Gubitak Bendera u korist Rusa", "0daca453"], "d": ["Nakon poraza na Kagulskom polju osmanska vojska povukla se južno od Dunava, a tvrđave između Moldavije i Očakova ostale su same. Bender, koji drži prijelaz rijeke Turle (Dnjestra), zauzet je jurišem nakon dvomjesečne opsade; grad je opljačkan. Gubitak tvrđave prekinuo je srednju kariku odbrambene linije sjevernog Crnog mora, a za njim su pali i Akerman i Kilija. U Küčük Kajnardži Bender će biti vraćen, ali će 1806. biti još jednom izgubljen.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Ulazak emirata Sabah u Kuvajtu pod osmansko pokroviteljstvo", "3584dba0"], "d": ["Prema članku TDV-a o Kuvajtu, pristanište je početkom 18. stoljeća osnovalo pleme Utub koje je došlo iz Nedžda, a porodica Sabah preuzela je upravu pred kraj stoljeća. Istih godina kad je Lahsa prešla Saudijcima, emirat, kojem pred vehabijskim pritiskom nije ostao drugi izbor nego osloniti se na Basru, stupio je pod osmansko pokroviteljstvo. Ta veza ozvaničit će se 1871. Midhat-pašinim uređenjem Basre, i Kuvajt će se smatrati jednim od triju kadiluka Basranskog sandžaka; i kasnija iračka teritorijalna pretenzija oslanja se na taj zapis.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Gubitak Meke u korist vehabija", "2da23acd"], "d": ["Vehabijski pokret, rođen u Nedždu, u doba Sauda b. Abdulaziza okrenuo se Hidžazu; nakon Taifa i Medine i Meka je po drugi put zauzeta — mekanski emir šerif Galib predao je grad vehabijama pod uslovom da ostane na emirskom položaju. Turbeta su srušena, a put hadžijskih karavana iz Damaska i Kaira presječen; i surra koju je sultan svake godine slao u Haremejn prekinuta je tih godina — jedini izuzetak te dodjele, koja je neprekidno trajala do 1915, jeste razdoblje vehabijske vlasti. Budući da je naslov zaštitnika Haremejna bio jedan od temeljnih oslonaca sultanovog legitimiteta, taj gubitak, više od teritorijalnog gubitka, bio je težak politički udarac; povratak će trajati sedam godina i postat će moguć s vojskom Mehmed Ali-paše Kavalalija.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Kraj Dubrovačke Republike — francuska okupacija", "f8e27bf1"], "d": ["Francuzi, koji su se Campoformijskim mirom (1797) smjestili na dalmatinskoj obali, 27. maja 1806. zauzeli su Dubrovnik i okončali malu trgovačku republiku. Tako je okončan tri i po stoljeća dug vazalni status Dubrovnika, koji je od 1458. plaćajući harač Osmanlijama čuvao autonomiju i trgovačke povlastice; grad i otok Mljet republike na karti prelaze pod neposrednu francusku upravu.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Gubitak Suhuma u korist Rusa — otvaranje istočne obale Crnog mora", "adc96bd4"], "d": ["U osmansko-ruskom ratu 1806–1812. ruska flota uputila se prema istočnoj obali Crnog mora i zauzela Suhum-kale, na kojem je u Abhaziji počivala osmanska vlast. Tvrđava je bila središte veza s kavkaskim plemenima i obalne trgovine. Njenim gubitkom Rusija se prvi put trajno učvrstila na istočnoj obali Crnog mora; osmanski uticaj na Kavkazu stisnuo se na okolinu Anape i Potija.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Prepuštanje Parge osmanskoj upravi", "66e0cc5d"], "d": ["Parga je od 1401. bila u venecijanskim rukama i nikada nije bila pod osmanskom upravom; nakon pada Venecije prelazila je redom Francuskoj i Engleskoj. Članak TDV-a o Ali-paši Tepelenskom ovako sažima stanje: grad se predao Englezima, a Ali-pašinoj upravi prepušten je tek 1819. Prijenos je rezultirao iseljenjem velikog dijela stanovništva na Jonske otoke. Tako je i posljednji iz trojke Preveza–Parga–Vonitsa, ostavljene Veneciji u Požarevcu, pripojen carstvu; Parga će devedeset četiri godine ostati osmanska.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Argos prešao u ruke grčkih ustanika", "be66a696"], "d": ["U prvim mjesecima morejskog ustanka Argos i okolina izašli su ispod osmanske uprave i prešli u ruke grčkih ustanika; grad će u maju 1821. biti poprište osmanske protuakcije.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmed Kihaja zauzeo Argos, grad opljačkan i spaljen", "d6d3ac7b"], "d": ["Snage Ahmed Kihaje porazile su Grke u Argosu, opljačkale i spalile grad; grad se nakratko vratio pod osmanski nadzor.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ahmed Kihaja se u Argosu spojio s muslimanima Tripolice i krenuo prema Tripolici", "9d679fd5"], "d": ["Ahmed Kihaja se u Argosu spojio s muslimanima Tripolice i krenuo prema Tripolici; Argos je ponovo prešao pod nadzor grčkih ustanika.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Korint prešao grčkim ustanicima", "892dcdc6"], "d": ["Tokom grčkog rata za nezavisnost Akrokorint je prešao u ruke ustanika, a zapovjednik tvrđave Kamil-beg zarobljen je.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Dramali Mahmud-paša postavio štab u Argosu", "c79abbfb"], "d": ["Vojska Dramali Mahmud-paše ušla je u argoško polje, a paša je postavio štab u gradiću Argosu; grad je ponovo prešao pod osmanski nadzor.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Dramali Mahmud-paša počeo se povlačiti iz Argosa", "5e5afb74"], "d": ["Dramali Mahmud-paša, prisiljen na povlačenje prije nego što su prošle dvije sedmice od okupacije Argosa, počeo je prvu diviziju svoje vojske povlačiti prema Korintu; Argos je ponovo prešao u ruke grčkih ustanika.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Gubitak Nauplije (Anabolu) u korist ustanika", "1a67fa50"], "d": ["Anabolu, luka s najjačim utvrđenjima u Moreji, predala se zbog gladi nakon blokade duže od godinu dana. Tvrđava je od početka ustanka bila posljednje veliko uporište osmanske kontrole na poluotoku; njenim gubitkom cijela Moreja prešla je u ruke ustanika. Grad će ubrzo postati prvi glavni grad nove grčke države.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Prelazak Nafpakta (Lepanta) pod grčku upravu", "c9d19d4b"], "d": ["Nafpaktos (Lepanto) na sjevernoj obali Korintskog zaljeva, koji je do grčkog ustanka bio u osmanskim rukama, izgubljen je u aprilu 1829. i ušao pod grčku upravu; ime gradića promijenjeno je u antičko Nafpaktos. Muslimansko i jevrejsko stanovništvo grada potpuno je nestalo, a mjesto se pretvorilo u mali gradić.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Francuska okupacija Alžira — kraj tri stoljeća starog odžaka", "0be8f568"], "d": ["Pod izgovorom incidenta s lepezom, nastalog iz spora o dugovima, Francuska je tri godine blokirala alžirsku obalu, a zatim iskrcala vojsku kod Sidi Ferrucha. Na kraju trosedmične akcije Husein-dej se predao i okončan je osmanski alžirski odžak, koji je trajao od 1516. Okupacija se nije ograničila na prijestolnicu; istog ljeta izgubljeni su i Tlemcen, Cherchell i Médéa u unutrašnjosti. Da cijela obala dođe pod francuski nadzor trajat će još dvadeset četiri godine.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Predaja Negroponta (Eubeje) Grčkoj — zajedno s otokom (Karistos, Oreoi)", "7b524aa4"], "d": ["Negropont (Eubeja), poprište žestokih sukoba tokom cijelog grčkog rata za nezavisnost, ali koji je ostao u osmanskim rukama, nakon stupanja mirovnog ugovora na snagu predat je 1831. Grcima. Muslimansko stanovništvo grada, od 1470. važne pomorske baze, prodavši svu imovinu po vrlo niskim cijenama, masovno se iselilo na osmanske zemlje; grad je dugo ostao prazan, a njemački putopisac Fallmerayer 1842. nazvao ga je gradom duhova.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Francuska okupacija Orana", "a8415d66"], "d": ["Oran, koji je Španija 1792. predala bez borbe, bio je najveća luka na zapadu Alžira. Šest mjeseci nakon pada prijestolnice francuske jedinice ušle su u grad. Zapadna akcija koja je odavde pokrenuta ubrzo će se suočiti s petnaestogodišnjim otporom emira Abdelkadera.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Okupacija Annabe (Bône)", "21f37fb1"], "d": ["Annaba, luka istočnog Alžira blizu tuniske granice, zauzeta je od francuskih snaga i pretvorena u bazu za marš na Konstantin. Grad je istovremeno bio i najbliža afrička luka nasuprot otoku Sardiniji.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Prepuštanje Atine novoj grčkoj državi (dan kada su bavarske jedinice preuzele Akropolu)", "deee4d37"], "d": ["Atina, osmanska od 1456, tokom grčkog rata za nezavisnost nekoliko je puta mijenjala gospodara, a posada na Akropoli 1827. ponovo je prešla pod osmanski nadzor. Budući da je ostala sjeverno od granice povučene Londonskim protokolom, grad je predat novom kraljevstvu, a posada je ispraznila Akropolu. Dan u atlasu je dan kada su bavarske jedinice preuzele Akropolu; stvarni izlazak osmanske posade dogodio se nekoliko dana kasnije (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, pogl. 13; Finlay, Journals and Letters, sv. I, str. 67). Iduće godine Atina je umjesto Nauplije proglašena glavnim gradom Grčke.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Okupacija Bedžaje (Bougie)", "a8927e00"], "d": ["Luka Bedžaja, gdje se kabilijske planine otvaraju prema moru, bila je posljednja nezavisna karika obalne linije između Alžira i Annabe. Zauzeta je uz podršku pomorske artiljerije; ali brdovita unutrašnjost iza nje neće još trideset godina doći pod francuski nadzor. Te obalne okupacije čine godinu po godinu topljenje osmanskog Alžira na karti.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Okupacija Sétifa", "2073731a"], "d": ["Nakon pada Konstantina godinu ranije francuske snage popele su se na visoravan, zauzele stari rimski grad Sétif i ondje uspostavile trajnu posadu. Sétif je bio tačka u kojoj se ukrštaju karavanski putevi između obale i Sahare; njegova okupacija pokazala je da Francuska više ne nadzire samo luke, nego počinje nadzirati i unutrašnju trgovačku mrežu.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Okupacija Biskre — gubitak vrata Sahare", "d895cad0"], "d": ["Biskra je bila vrata prema Sahari u južnom podnožju planina Atlas i središte oaza datulinih palmi. Njenim zauzimanjem u godinama kad se otpor emira Abdelkadera počeo lomiti francuski nadzor prvi put je stigao do sjevernog ruba pustinje. Nakon toga slijedit će pustinjska akcija koja napreduje oazu po oazu.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Okupacija Touggourta — gubitak cijelog Alžira", "33c056e2"], "d": ["Zauzimanjem Touggourta, oaznog grada na sjeveru Sahare, okupacija započeta 1830. dovršena je u sjevernoj polovini današnjeg Alžira. Osmanska država tih je godina u Krimskom ratu ratovala na istoj strani s Francuskom; iako nikada zvanično nije napustila pravnu pretenziju na Alžir, faktički nije mogla učiniti nijedan korak. Jedina zemlja koja je ostala u Sjevernoj Africi bio je Tripoli.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Pad El-Obeida — prelazak Kordofana u ruke Mahdijevih snaga", "58299f62"], "d": ["Pokret koji je pokrenuo Muhammed Ahmed, proglasivši se mahdijem, brzo se širio protiv egipatske uprave u Sudanu. Središte Kordofana El-Obeid palo je nakon četveromjesečne opsade i postalo prijestolnica ustanka; riznica i skladišta oružja u gradu omogućili su pokretu da se pretvori u vojsku. Sudan je pravno još bio teritorij egipatskog hedivata vezanog za Osmanlije, pa gubitak na karti odlazi s trupa carstva.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Pad Kartuma — gubitak cijelog Sudana", "d4b98464"], "d": ["Nakon desetomjesečne opsade Mahdijeve snage ušle su u Kartum, na sastavu Plavog i Bijelog Nila; guverner grada Gordon ubijen je, a britanska kolona poslana u pomoć zakasnila je dva dana. Od tada je cijeli Sudan, uključujući Sennar, Dongolu i Kordofan, četrnaest godina ostao pod upravom Mahdijske države. Oblast će tek 1899, s potpuno prekinutom osmanskom vezom, ući pod zajedničku britansko-egipatsku upravu.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Italijanska okupacija Masave — gubitak zapadne obale Crvenog mora", "c333b95b"], "d": ["Luku Masavu, središte Habeškog ejaleta, okupirala je Italija koristeći pometnju u kojoj je Mahdijev ustanak zahvatio Sudan; to je činilo jezgro italijanske Eritreje. Suakin na sjeveru i arhipelag Dahlak na pučini izgubljeni su u istom procesu. Tako je okončana osmanska vlast na zapadnoj obali Crvenog mora, koja je trajala od doba Selima I Javuza, a more je sada postalo voda kojoj su obje obale strane.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Italijanska okupacija Rodosa", "e08662c5"], "d": ["Italija, želeći primorati Osmansku državu da sjedne za pregovarački sto u ratu za Tripolitaniju, prenijela je rat u Sredozemlje i iskrcala vojsku na Rodos. Otok je preuzet za nekoliko dana. Tako je Rodos, koji je Sulejman Zakonodavac 1522. zauzeo dugom opsadom i držao tri stotine devedeset godina, prestao biti najveća otočna baza carstva u istočnom Sredozemlju; iako se u Ušijskom miru smatrao privremenom okupacijom, više se nikada nije mogao vratiti.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Italijanska okupacija Dodekaneza", "200aacf2"], "d": ["U roku od sedmicu dana od zauzimanja Rodosa italijanska flota okupirala je i okolne otoke; taj arhipelag kasnije će dobiti ime 'Dodekanez' (Dvanaest otoka). Većina otoka bila je nekoliko milja od anadolske obale i nadzirala jugoistočni prolaz Egeja. Okupacija se u Ušijskom miru smatrala privremenom u zamjenu za napuštanje Tripolitanije, ali Italija nikada nije ispraznila otoke; 1947. bit će predani Grčkoj.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Okupacija Kosa", "ab246c62"], "d": ["Kos, posljednja karika akcije na Dodekanezu, bio je plodan i napučen otok tik preko puta poluotoka Bodrum. Okupacijom su svi otoci u jugoistočnom uglu Egeja došli pod italijanski nadzor, a jugozapadna obala Anadolije cijelom dužinom bila je okružena stranim lancem otoka.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Proglašenje nezavisnosti Nikarije", "c4452033"], "d": ["Na malom otoku Nikariji, između Samosa i Hiosa, narod se u neizvjesnosti stvorenoj italijanskim okupacijama pobunio, istjerao osmansku žandarmeriju s otoka i proglasio 'slobodnu državu' koja je sa svojom zastavom, markama i skupštinom trajala pet mjeseci. U novembru 1912. otok se pripojio Grčkoj. Uprkos njegovoj malenosti, taj je događaj jasan pokazatelj kako se na Egeju raspadala centralna uprava.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Izlazak Samosa ispod osmanske uprave", "3a862f2b"], "d": ["Samos je od 1832. bio autonomna kneževina koja je plaćala porez Osmanlijama i kojom je upravljao beg imenovan iz Istanbula. U praznini nastaloj zbog rata za Tripolitaniju pokret za ujedinjenje na otoku preuzeo je upravu, a poredak autonomne kneževine faktički je okončan; otok je iste godine proglasio pripajanje Grčkoj. Taj otok, udaljen dva kilometra od anadolske obale, postao je jedna od prvih izgubljenih zemalja u Egeju.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Pad Janjine — gubitak Epira i Parge", "d42fce18"], "d": ["Janjina, opsjednuta pet mjeseci u Balkanskom ratu, predala se nakon pada položaja kod Bizanija; zajedno s gradom cijeli Epir prešao je Grčkoj. I Parga, vezana za Janjinski sandžak, tada je izgubljena, čime je okončana devedesetčetverogodišnja osmanska uprava. Gubitak Janjine značio je zatvaranje posljednjeg prozora carstva prema Jadranu.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Pad Edirna u bugarske ruke", "459d2e56"], "d": ["Nakon opsade od pet i po mjeseci Edirne, kojem su ponestali municija i namirnice, predalo se; Šukri-paša pao je u zarobljeništvo. Pad grada, osmanskog od 1361. i prijestolnice devedeset dvije godine, smatran je najtežim udarcem Balkanskog rata. Edirne će četiri mjeseca kasnije, u Drugom balkanskom ratu, biti povraćeno korištenjem sloma Bugarske na drugim frontovima.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Gubitak Janbua u korist snaga šerifa Huseina", "e291c816"], "d": ["Ustanak koji je šerif Husein pokrenuo u junu proširio se na obalu Crvenog mora; Janbu, medinska luka, uz podršku britanske flote prešao je u ruke ustanika. Luka je postala glavna kapija dotoka oružja i novca izvana u ustanak. Tako je snagama Fahrudin-paše u Medini presječena veza s morem, a grad je ostao sam na kraju Hidžaške željeznice.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Treća bitka za Gazu — gubitak Gaze i Han Junisa", "c142a069"], "d": ["Nakon dva neuspjela pokušaja Allenby je u trećem napadu probio front zaobišavši kod Bir es-Sebe i linija Gaze, držana šest mjeseci, urušila se. Gaza i Han Junis južno od nje ispražnjeni su istog dana. Taj proboj bio je početak raspadanja palestinskog fronta; Jeruzalem će pasti pet sedmica kasnije.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Okupacija Komotinija — gubitak Zapadne Trakije", "904d813c"], "d": ["Zapadna Trakija, koja je nakon Mudrosa najprije došla pod nadzor jedinica Antante, odlukom konferencije u San Remu prepuštena je Grčkoj, a grčka vojska ušla je u Komotini. Oblast, 1913. povraćena od Bugarske, bila je posljednja zemlja koju je carstvo izgubilo u Rumeliji. Status turskog stanovništva u oblasti bit će tri godine kasnije uređen u Lausannei režimom manjina. Ovom okupacijom Grčkoj su prešli kadiluci Zapadne Trakije Komotini, Ksanti, Aleksandrupolis (Dedeagač) i Sufli.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Raspad Ilhanata: smrt Ebu Saida Bahadur-hana", "0f187469"], "d": ["Prema članku o Ilhanidima u Enciklopediji islama TDV, smrt Ebu Saida bez nasljednika dovela je do raspada Ilhanata, koji je stoljeće vladao Iranom; emiri su, iskoristivši borbe za prijestolje, osnovali mjesne dinastije poput Džalairida, Kara-Kojunlua, Muzafferida, horasanskih Serbedara i Eretnaogula. Taj raspad podijelio je područje na mozaik bejluka koji će trajati stoljeće; na kraju će ga ponovo ujediniti Timurovi pohodi.", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["Timur stavio veći dio Irana pod svoju vlast", "1cee2b82"], "d": ["Prema članku o Timuru u Enciklopediji islama TDV, Timur je od početka 1380-ih jednu po jednu uklanjao mjesne dinastije nakon Ilhanata, poput Serbedara, Kerta i Muzafferida, a tokom 'trogodišnjeg pohoda' 1386-1388. veći dio Irana stvarno stavio pod svoju vlast; konačan kraj dinastiji Muzafferida donijet će 1393. Područje je tako nakon stoljeća rascjepkanosti ponovo vezano za jedinstvenu središnju vlast.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Pobjeda na Araksu: Kara Jusuf porazio Timuridu Ebu Bekra Mirzu", "4b61a75a"], "d": ["Kara Jusuf, beg Kara-Kojunlua koji se nakon Timurove smrti 1405. vratio iz izgnanstva, zauzeo je Avnik i ponovo došao u posjed svojih zemalja u istočnoj Anadoliji, a zatim krenuo na Timurovog unuka Ebu Bekra Mirzu, koji je smatran gospodarem Azerbejdžana i dva Iraka, i porazio ga na obali Araksa. Ta pobjeda nije Kara-Kojunluima dala Tabriz: TDV `tebriz` navodi da je grad 1408. bio u rukama Ebu Bekra Mirze; bitka koja im je donijela Azerbejdžan jeste bitka kod Serdruda 13. aprila 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Pobjeda kod Serdruda: Tabriz i Azerbejdžan prešli Kara-Kojunluima", "1f0a429d"], "d": ["Kara Jusuf je nakon Araksa po drugi put porazio Timuridu Ebu Bekra Mirzu, kod Serdruda blizu Tabriza; ta je pobjeda Kara-Kojunluima donijela Azerbejdžan. Kara Jusuf zatim je Bistam-begu povjerio osvajanje Iraka Adžema;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemija kuge u Istanbulu i preseljenje saraja u Edirne", "70c7a163"], "d": ["Prema članku o Istanbulu u Islamskoj enciklopediji TDV-a, brzo i gusto naseljavanje grada povremeno je pripremalo tlo za širenje epidemija; tokom kuge 1466. saraj i državni velikodostojnici privremeno su se povukli u Edirne. Stanovništvo grada u takvim epidemijama pretrpjelo je ozbiljne gubitke.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan okončao državu Kara-Kojunlu", "ef68399e"], "d": ["Prema članku o Uzun Hasanu u Enciklopediji islama TDV, vladar Ak-Kojunlua Uzun Hasan je 12. rebiul-ahira 872 / 10. novembra 1467. u području Bingöl-Sandžak porazio i ubio vladara Kara-Kojunlua Džihan-šaha; Džihan-šahov sin Hasan Ali poražen je kod Maranda u septembru 1468, a ubijen pred Hamadanom u aprilu-maju 1469. i time je država Kara-Kojunlu konačno okončana. Zemlje su prešle pod vlast Ak-Kojunlua; država će se u narednom desetljeću proširiti duboko u Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Početak nastave u medresama Sahn-i Seman", "021f2a83"], "d": ["Prema članku o Sahn-i Semanu u Islamskoj enciklopediji TDV-a, ovih osam medresa, osnovanih u okviru Fatihovog kompleksa (külliye), zamišljeno je kao najviša obrazovna ustanova toga doba i činile su vrh osmanske ilmijske hijerarhije. Muderrisluk i diplomiranje na njima u kasnijim su se stoljećima smatrali najuglednijom stepenicom karijere kadije i muderrisa.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Dovršetak Topkapi saraja (Saraj-i Džedid)", "d2db6323"], "d": ["Prema članku o Topkapi saraju u Islamskoj enciklopediji TDV-a, izvori tog doba razilaze se o datumima početka i završetka gradnje; prema datumu 883 (1478) na natpisu Bab-i Humajuna, gradnja, vjerovatno započeta 1465. po naredbi Mehmeda II Osvajača, do te je godine uglavnom bila dovršena i saraj je zamijenio državno središte u starom saraju. Tako se sultan preselio u novu rezidenciju, koja će tri stoljeća biti upravno i ceremonijalno srce države.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Stupanje Bajazida II na prijestolje u Istanbulu", "9b686d04"], "d": ["Prema članku o Bajazidu II u Islamskoj enciklopediji TDV-a, šehzada Bajazid, sandžakbeg Amasye, na vijest o očevoj smrti brzo je stigao u Istanbul i stupio na prijestolje; uz podršku janjičara ostavio je za sobom brata Džema koji je krenuo iz Konye. Pri stupanju na prijestolje janjičarima je podijeljen uobičajeni džulus-bakšiš. Ta smjena na prijestolju zapalila je i fitilj borbe dvojice braće.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Džem-sultan se u Bursi proglasio sultanom", "b355168a"], "d": ["Prema članku o Džem-sultanu u Islamskoj enciklopediji TDV-a, Džem, koji je preko Karamana stigao u Bursu, zauzeo je grad, proglasio se sultanom i dao učiti hutbu u svoje ime. Ta kratkotrajna vladavina okončana je kad su snage koje je poslao njegov stariji brat Bajazid II porazile Džema kod Jenišehira. Nakon poraza Džem je morao pobjeći prema Egiptu.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Pogubljenje Gedik Ahmed-paše", "6d75a58c"], "d": ["Prema članku o Gedik Ahmed-paši u Islamskoj enciklopediji TDV-a, paša poznat po pohodu na Otranto i po dužnosti velikog vezira pogubljen je u Edirnama po naredbi Bajazida II zbog svog držanja u pitanju Džem-sultana i zabrinutosti zbog njegovog uticaja. Smrt jednog od najiskusnijih zapovjednika doba Mehmeda II Osvajača snažno je odjeknula u saraju.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Osnivanje prve štamparije u Istanbulu", "04475930"], "d": ["Prema članku o štampariji u Islamskoj enciklopediji TDV-a, jevrejski useljenici iz Španije, braća David i Samuel ibn Nahmias, osnovali su u Istanbulu prvu štampariju koja je štampala hebrejskim slovima. To je zabilježeno kao prvi štamparski poduhvat koji je djelovao na osmanskim zemljama; štampanje turskog arapskim pismom, pak, postat će moguće mnogo kasnije, u XVIII stoljeću.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Šah Ismail zauzeo Tabriz: osnivanje safavidske države", "014d81e6"], "d": ["Prema člancima o Safavidima i Ak-Kojunluima u Enciklopediji islama TDV, mladi šejh ardabilske tekije Ismail, s vojskom stvorenom od svojih kizilbaških murida iz Anadolije, u području Nahčivana nanio je težak poraz sultanu Ak-Kojunlua Elvendu; Elvend je pobjegao u Dijarbekir, a Ismail je ušao u Tabriz, sjeo na prijestolje i proglasio šiizam dvanaest imama službenim mezhebom. Time su zatvoreni i vlast Ak-Kojunlua i razdoblje bejluka na tom području nakon Ilhanata; osnovana je safavidska država koja će trajati tri stoljeća.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Zemljotres 'Mali sudnji dan' u Istanbulu", "53e3b1d6"], "d": ["Prema članku o Istanbulu u Islamskoj enciklopediji TDV-a, snažni zemljotres koji je pogodio grad u narodu je toga doba pamćen kao 'Mali sudnji dan' (Küčük Kijamet); nastala je teška šteta na zidinama, džamijama i mnogim zgradama, a bilo je i mnogo ljudskih žrtava. Po naredbi Bajazida II u gradu je pokrenuta opsežna akcija obnove i izgradnje.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Početak ustanka Šahkulua", "3d9a4a90"], "d": ["Prema članku o Šahkulu Baba Tekeliju u Islamskoj enciklopediji TDV-a, Šahkulu, kojeg je hranila safavidska propaganda, okupio je u oblasti Teke široku turkmensku masu i pokrenuo veliki ustanak vjersko-društvenog karaktera. Ustanak, kao jedna od najozbiljnijih unutrašnjih sigurnosnih kriza toga doba, duboko je uzdrmao centralni autoritet države.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Smrt Bajazida II na putu u Didimotihon", "c46e98c9"], "d": ["Nekadašnji sultan, koji je nakon odricanja od prijestolja napustio Istanbul da ode u svoj rodni grad Didimotihon, putujući u nosiljci koja je dnevno prelazila samo 5–6 km, pozlio mu je u selu Abalar kod Çorlua i umro je 25. rebiul-evvela 918. (10. juna 1512). Islamska enciklopedija TDV-a uzrok smrti smatra veoma sumnjivim; prema nekim domaćim i stranim izvorima razmatra se mogućnost da je otrovan. Tako je nakon tridesetjednogodišnje vladavine umro osmi sultan iz loze Osman Gazija.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Pogubljenje šehzade Ahmeda po naredbi Selima I Javuza", "65abb2f2"], "d": ["Prema članku o Selimu I u Islamskoj enciklopediji TDV-a, šehzada Ahmed, miljenik oca Bajazida II i glavni suparnik za prijestolje, u borbi u koju je ušao nakon stupanja na prijestolje brata Selima poražen je na Jenišehirskom polju i, bježeći s bojnog polja, uhvaćen i ubijen. Ovim događajem Selim je uglavnom okončao suparništvo za prijestolje među braćom i bratićima.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ibrahim-paša imenovan velikim vezirom", "9c94c1e3"], "d": ["Prema članku o Ibrahim-paši Makbulu u Islamskoj enciklopediji TDV-a, Ibrahim-paša, koji je s dužnosti has odabaše uzdignut na zvanje rumelijskog beglerbega i istog dana na položaj velikog vezira, postao je veliki vezir 13. šabana 929. (27. juna 1523). Bilo je to bez presedana imenovanje, pri kojem se iz dvorske službe neposredno prelazilo na položaj velikog vezira i koje je pokazivalo izvanrednu Ibrahim-pašinu bliskost sa Sulejmanom Zakonodavcem.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hajrudin-paša imenovan kapudan-pašom", "a0ff6bab"], "d": ["Prema članku o Barbaros Hajrudin-paši u Islamskoj enciklopediji TDV-a, Hajrudin-paša, poznat po uspjesima u Alžiru, pozvan je 6. aprila 1534. u Istanbul i postavljen za kapudan-pašu i beglerbega Džezair-i Bahr-i Sefida. To imenovanje smatra se početkom preustroja osmanske flote i institucionalizacije pomorske moći u Sredozemlju.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rustem-paša prvi put postao veliki vezir", "ddfcc014"], "d": ["Prema članku o Rustem-paši u Islamskoj enciklopediji TDV-a, nakon smjene Hadum Sulejman-paše zbog spora s jednim vezirom, Rustem-paša je 17. ramazana 951. (2. decembra 1544) postavljen za velikog vezira. Rustem-paša, čija je bliskost sa sarajem porasla brakom s Mihrimah-sultanijom, na toj je dužnosti postao jedan od najuticajnijih državnika doba Sulejmana Zakonodavca.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebussuud-efendija postao šejhul-islam", "11ed04f8"], "d": ["Prema članku o Ebussuud-efendiji u Islamskoj enciklopediji TDV-a, Ebussuud-efendija, koji je osam godina bio rumelijski kazasker, u šabanu 952. (oktobar 1545) doveden je na položaj šejhul-islama i na toj dužnosti ostao dvadeset osam godina i jedanaest mjeseci. Ebussuud-efendija, poznat po fetvama kojima je kanunname Sulejmana Zakonodavca uskladio sa šerijatskim pravom, imao je presudnu ulogu u oblikovanju pravnih i obrazovnih ustanova svoga doba.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Umro Barbaros Hajrudin-paša", "3378a0bf"], "d": ["Prema članku o Barbaros Hajrudin-paši u Islamskoj enciklopediji TDV-a, nakon kratke bolesti umro je u Istanbulu 6. džumadel-ula 953. (5. jula 1546). Smrt Barbarosa, sahranjenog u turbetu uz medresu koju je sam sagradio u Beşiktaşu, doživljena je kao zatvaranje jednog doba u sredozemnoj nadmoći koju je uspostavila osmanska flota.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Počela gradnja Sulejmanije džamije i kompleksa", "101ec36f"], "d": ["Prema članku o Sulejmanija džamiji i kompleksu u Islamskoj enciklopediji TDV-a, kompleks čiji su temelji položeni 1550. pod glavnim arhitektom Mimarom Sinanom zamišljen je kao veliki društveni kompleks koji uz džamiju obuhvata medrese, bolnicu (daruššifa), imaret i biblioteku. Gradnja je bila jedan od najvećih graditeljskih programa koji simboliziraju moć vladavine Sulejmana Zakonodavca i izgradnju Istanbula.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["U Istanbulu i okolini počeo novi val kuge", "547d6bf6"], "d": ["Prema članku o kugi (taun) u Islamskoj enciklopediji TDV-a, jedna od epidemija 16. stoljeća koje su pogodile islamski svijet trajala je 1552–1566. i bila je naročito snažna u Istanbulu, Anadoliji, Rumeliji, Egiptu i Sjevernoj Africi. Sve širi trgovački putevi i sve veća pokretljivost stanovništva navode se među faktorima koji su u doba najveće moći carstva olakšali širenje epidemija.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed-paša imenovan velikim vezirom", "a7d7748e"], "d": ["Prema članku o Kara Ahmed-paši u Islamskoj enciklopediji TDV-a, Kara Ahmed-paša, koji je služio kao drugi vezir, nakon iznenadne smjene tadašnjeg velikog vezira uzdignut je 27. ševvala 960. (5. oktobra 1553) na položaj velikog vezira. Ta promjena upućuje na razdoblje u kojem su se, istih dana kad i pogubljenje šehzade Mustafe, ravnoteže moći unutar saraja brzo mijenjale.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Pogubljen kapudan-paša Piri Reis", "3b2ad7a0"], "d": ["Prema članku o Piri Reisu u Islamskoj enciklopediji TDV-a, kad su u Egipat stigle optužbe da je, dižući opsadu Hormuza, za mito opljačkao imovinu muslimana i napustio svoju vojsku na bojnom polju, slavni pomorac i kartograf pogubljen je u Kairu krajem 960. (krajem 1553). Smrt Piri Reisa, čija je imovina zaplijenjena, ocjenjuje se kao posljedica suparništva među pašama u pomorskoj politici toga doba u Basri i na Indijskom okeanu.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Pogubljen Kara Ahmed-paša, Rustem-paša ponovo veliki vezir", "9a85076a"], "d": ["Prema člancima o Rustem-paši i Kara Ahmed-paši u Enciklopediji islama TDV, umjesto Kara Ahmed-paše, koji je 13. zul-kadea 962. (29. septembra 1555) iznenada pogubljen tokom sjednice divana, Rustem-paša je istog dana, uz podršku sultanija Hurem i Mihrimah, po drugi put doveden na položaj velikog vezira. Pozadina događaja u izvorima je ostala nerazjašnjena, a ocjenjuje se da je bio posljedica dvorskih spletki.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Umrla Hurem-sultanija", "1ae998b5"], "d": ["Prema članku o Hurem-sultaniji u Enciklopediji islama TDV, Hurem-sultanija, koja je kao haseki-sultanija Sulejmana Zakonodavca godinama imala velik utjecaj na dvoru, umrla je u Istanbulu 26. džumadel-uhra 965. (15. aprila 1558) i sahranjena je u svom turbetu u sklopu kompleksa Sulejmanije džamije. Smrt Hurem-sultanije, koja je nakon smrti valide-sultanije Hafse 1534. učvrstila svoju vlast nad haremom, uklonila je i uravnotežujući činilac pred borbom za prijestolje između njenih sinova Bajazida i Selima.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Mehmed-paša Sokolović postao veliki vezir", "896391a2"], "d": ["Prema članku o Mehmed-paši Sokoloviću u Enciklopediji islama TDV, Mehmed-paša Sokolović, koji je postao veliki vezir nakon smrti Semiz Ali-paše 30. zul-kadea 972. (29. juna 1565), bio je posljednji veliki vezir Sulejmana Zakonodavca; tu je dužnost zadržao i nakon njega, za vladavine Selima II i Murata III, postavši jedan od velikih vezira s najdužim stažem u osmanskoj historiji.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II stigao u Istanbul i stupio na prijestolje", "0289ef97"], "d": ["Nakon smrti sultana Sulejmana Zakonodavca kod Sigeta, Mehmed-paša Sokolović sedmicama je tu vijest držao u tajnosti kako se ne bi narušio red. Prema Enciklopediji islama TDV, Selaniki kao datum Selimovog dolaska u Istanbul navodi 15. rebiul-evvel 974. (30. septembra 1566), dok većina savremenih historičara tačnim smatra 9. rebiul-evvel (24. septembra). Smrt Sulejmana Zakonodavca službeno je objavljena tek 24-25. oktobra 1566. u Beogradu.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Zaplovila flota koju je ponovo izgradio Kilidž Ali-paša", "d0fc9f48"], "d": ["Nakon teškog poraza kod Lepanta (7. oktobra 1571), tokom cijele zime u brodogradilištima su građeni brodovi. Prema Enciklopediji islama TDV, 1. safera 980. (13. juna 1572) nova flota od 250 galija i oko 300 čamaca s veslima kojima su zapovijedali dobrovoljni reisi porinuta je u more uz demonstraciju moći.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Mehmed-paša Sokolović ubijen u atentatu", "6ffa8dec"], "d": ["Mehmed-pašu Sokolovića, koji je četrnaest godina bio veliki vezir za vrijeme trojice sultana, 20. šabana 987. (12. oktobra 1579) na ikindijskom divanu u njegovom konaku nožem je ubio derviš koji mu je prišao kao da će predati molbu. Prema Enciklopediji islama TDV, raspravlja se o tome da li je atentat mogao biti povezan s osvetom za pogubljenog hamzevijskog šejha Hamzu Balija.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Prva trgovačka ahdnama s Engleskom — Englezima date kapitulacije", "59c8e3ee"], "d": ["Engleski predstavnik William Harborne, poslan u Istanbul u oktobru 1578, uz podršku Mehmed-paše Sokolovića i Hodže Sadedin-efendije dobio je od Murata III ahdnamu iz 1580. godine. Tom su ahdnamom engleski trgovci stekli pravo da u jednakoj mjeri koriste trgovačke povlastice (kapitulacije) koje su ranije bile priznate Francuzima i Mlečanima. Kraljica Elizabeta I i Murat III razmijenili su pisma, a između dvije države uspostavljen je i službeni odnos. Odmah nakon tih povlastica, 1581. u Londonu je osnovana Levantska kompanija (Levant Company); Englezi su svoju trgovinu na tom području do 1825. vodili preko ove kompanije.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Istanbulska opservatorija srušena carskim hatihumajunom", "3bc0c78c"], "d": ["Pod utjecajem fetve da opservatorije donose nesreću zemljama i protivljenja na dvoru, Istanbulska opservatorija je hatihumajunom od 4. zul-hidždžea 987. (22. januara 1580) srušena zajedno sa svim instrumentima u njoj. Prema Enciklopediji islama TDV, to je bio kraj kratkog vijeka ustanove koju je osnovao Takijudin er-Rasid.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Počelo sunet-slavlje princa Mehmeda na At-mejdanu", "c2926d5d"], "d": ["Princ Mehmed, sin Murata III, obrezan je uz veličanstvene svečanosti koje su počele 6. džumadel-ula 990. (29. maja 1582) i trajale pedeset šest do pedeset sedam dana. Prema Enciklopediji islama TDV, svečanosti na At-mejdanu bile su jedno od najraskošnijih dvorskih slavlja tog doba.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Umrla valide-sultanija Nurbanu", "77d0a577"], "d": ["Nurbanu-sultanija, majka Murata III, umrla je 22. zul-kadea 991. (7. decembra 1583). Prema Enciklopediji islama TDV, kao valide-sultanija vodila je prepisku s dvorovima Venecije i Francuske, a mletački Senat te je godine odlučio da joj za njene usluge pošalje poklon vrijedan 2000 mletačkih zlatnika.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Zbog iskvarene akče izbio Beglerbegov slučaj", "db2f2e61"], "d": ["Kada je država isplate počela vršiti akčom sa smanjenim udjelom srebra, spahije i janičari opkolili su dvor i digli krvavu pobunu koja je u historiju ušla pod imenom Beglerbegov slučaj. Prema članku o Abdulkadiru Šejhi-efendiji u Enciklopediji islama TDV, šejhul-islam je zbog tog događaja smijenjen s dužnosti.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III stupio na prijestolje, zadavljeno devetnaest prinčeva", "2cd9a8c5"], "d": ["Nakon smrti oca Murata III, Mehmed III stigao je u Istanbul u petak 16. džumadel-ula 1003. (27. januara 1595) i stupio na prijestolje. Prema Enciklopediji islama TDV, iste je noći zadavljeno devetnaest prinčeva, među njima četvorica odraslih (Mustafa, Bajazid, Osman i Abdullah); bilo je to najbrojnije bratoubistvo u osmanskoj historiji.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safije-sultanija stekla utjecaj kao valide-sultanija", "000bec21"], "d": ["Safije-sultanija, supruga Murata III i majka Mehmeda III, stupanjem svog sina na prijestolje uzdigla se kao valide-sultanija na odlučujući položaj u dvorskoj politici. Prema Enciklopediji islama TDV, u tom je razdoblju utjecaj iz harema dosegao razinu neposrednog miješanja u državne poslove.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III pod pritiskom janičara lično krenuo u pohod", "d3c50656"], "d": ["Uprkos protivljenju velikog vezira Damada Ibrahim-paše, Mehmed III je pod pritiskom janičara 20. juna 1596. krenuo iz Istanbula u pohod kao prvi sultan nakon Sulejmana Zakonodavca koji je lično stao na čelo vojske. Prema Enciklopediji islama TDV, to je značilo oživljavanje stare tradicije gaze.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Epidemija kuge započeta 1570-ih i dalje je pogađala Istanbul", "eb4ca37a"], "d": ["Prema članku o kugi u Enciklopediji islama TDV, epidemija koja je počela 1570-ih trajala je do početka XVII stoljeća i pogodila prije svega Istanbul, a zatim Anadoliju, Balkan, Egipat i Sjevernu Afriku. Razdoblja epidemije predstavljala su hroničnu prijetnju koja je često prekidala život na dvoru i u gradu.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Umro Karajazidži Abdulhalim, ustanički pokret oslabio", "876ca7a6"], "d": ["Karajazidži Abdulhalim, koji se ranjen povukao nakon teškog poraza 12. augusta 1601. kod Sepetlija u blizini Elbistana, umro je 1010. godine (1602). Prema Enciklopediji islama TDV, vijest o njegovoj smrti stigla je u Istanbul u ramazanu 1010. (februar-mart 1602); izvori navode da je sporno je li umro od posljedica rane ili su ga ubili njegovi vlastiti ljudi.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Stvarni kraj tradicije bratoubistva", "9046c607"], "d": ["Ahmed I, za razliku od prethodnih sultana, prilikom stupanja na prijestolje nije dao pogubiti svog brata princa Mustafu, nego mu je poštedio život; ta se odluka smatra početkom stvarnog prihvatanja načela nasljeđivanja po starješinstvu i sposobnosti (ekber-eršed) u osmanskom sistemu nasljeđivanja. Članak \"Mustafa I\" u Enciklopediji islama TDV navodi da je Mustafa nakon toga na dvoru živio izdvojeno. Ova praksa stvarno je okončala stoljećima prisutna ubistva pri stupanju na prijestolje.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Položen temelj Sultanahmedove džamije", "1683262f"], "d": ["Po naredbi Ahmeda I na At-mejdanu je uz svečanost položen temelj džamije koju će graditi arhitekta Sedefkar Mehmed-aga. Prema članku \"Džamija i kompleks sultana Ahmeda\" u Enciklopediji islama TDV, građevina je bila predmet kritika svog vremena i po tome što je bila prva velika sultanska džamija podignuta neposredno iz državne blagajne, bez osvajačke pobjede. Kompleks je zamišljen tako da uz džamiju obuhvata i medresu, imaret i turbe.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Janičarsko ubistvo Mladog Osmana (Haile-i Osmanije)", "324f6582"], "d": ["Janičari i spahije, pobunjeni zbog glasina da sultan pod izgovorom hadža namjerava otići iz Istanbula i raspustiti janičarski odžak, svrgnuli su Osmana II i zadavili ga u tamnicama Jedikule. Prema članku \"Osman II\" u Enciklopediji islama TDV, to je prvi slučaj u osmanskoj historiji da je sultan otvoreno ubijen u vojnoj pobuni, što je stvorilo dubok lom u odnosu dinastije i vojske. Njegovi posljednji sati protekli su ovako: pošto pokušaj da se skloni u konak janičarskog age Ali-age nije uspio, sultana su, kako piše TDV, 'na strašan način, gologlavog i u neurednom izgledu' posadili na nekog tegleći konja i uz teške uvrede odveli najprije u Orta džamiju, gdje se nalazio Mustafa I, a istog dana poslijepodne u Jedikule; prema nekim historičarima, kao dokaz njegove smrti odsječeni su mu uho i nos i pokazani majci Mustafe I. Nakon događaja Mustafa I po drugi je put postavljen na prijestolje. Događaj nazvan 'Haile-i Osmanije' (Osmanova tragedija) trajno je narušio ravnotežu između dvora i odžaka i pokrenuo rasprave o legitimnosti koje će trajati cijelo stoljeće.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Mustafa I po drugi put postavljen na prijestolje", "34a0b29a"], "d": ["Nakon što su janičari ubili Mladog Osmana, Mustafa I po drugi je put postavljen na prijestolje jer u dinastiji nije bilo drugog odraslog muškog člana. Prema članku \"Mustafa I\" u Enciklopediji islama TDV, i ta je druga vladavina, nimalo drukčija od prve, protekla a da on stvarno nije vodio državne poslove, a upravljanje državom ostalo je u rukama vezira i valide-sultanije. To razdoblje od četrnaest mjeseci završilo je stupanjem Murata IV na prijestolje 1623.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Požar u Džibaliju", "3e42fb08"], "d": ["Požar koji je izbio u Džibaliju i pod utjecajem vjetra se brzo proširio pretvorio je u pepeo velik dio Istanbula; prema članku \"Istanbul\" u Enciklopediji islama TDV, izvori tog vremena navode da je izgorjelo hiljade domaćinstava. Povezivanje požara s drvenom gradnjom kuća i pušenjem duhana postalo je neposredni povod za strogu zabranu duhana i kafana koju će Murat IV uskoro proglasiti. Katastrofa je bila samo jedan od velikih požara koji su se u tadašnjem Istanbulu ponavljali.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Zabrana duhana i kafana Murata IV", "5dd71297"], "d": ["Nakon požara u Džibaliju, iz zabrinutosti zbog požara i javnog reda, Murat IV zabranio je pušenje duhana i kafane; prekršiteljima zabrane izricane su teške kazne, uključujući i smrtnu. Prema članku \"Murad IV\" u Enciklopediji islama TDV, sultan je provodio tako strogu politiku unutrašnje discipline da je i sam, prerušen, obilazio gradske ulice kako bi nadzirao provođenje zabrane. Te se oštre mjere ocjenjuju kao dio nastojanja Murata IV da ponovo uspostavi središnju vlast.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemija kuge u Istanbulu", "f33f58c5"], "d": ["Za vladavine Murata IV Istanbul je potresla teška epidemija kuge koja je zahvatila znatan dio stanovništva; gradska trgovina i svakodnevni život mjesecima su bili poremećeni. Članak \"Istanbul\" u Enciklopediji islama TDV bilježi da su ponavljajuće epidemije u XVII stoljeću ozbiljno utjecale na demografsku ravnotežu grada. Tokom epidemije dvor i otmjeni slojevi neko su se vrijeme preselili u bašte i ljetnikovce izvan grada.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Let Hezarfena Ahmeda Čelebije s krilima (predanje)", "df474c04"], "d": ["Prema predanju koje prenosi Evlija Čelebija, Hezarfen Ahmed Čelebija uspio je s krilima koja je sam napravio skočiti s Galatske kule i doletjeti jedreći sve do Uskudara; iako je historijska pouzdanost sporna, on je postao simbol tehničke mašte. Sultan je Hezarfena najprije nagradio, a zatim ga je zbog odjeka koji je događaj izazvao prognao u Alžir.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Džindži-hodža Husein-efendija stiče utjecaj na dvoru", "41d21572"], "d": ["Husein-efendija, vračar pozvan na dvor da liječi duševne tegobe sultana Ibrahima, ubrzo je stekao sultanovo povjerenje i uzdigao se sve do anadolskog kazaskera. Prema članku \"Husein-efendija, Džindži-hodža\" u Enciklopediji islama TDV, taj je utjecaj koristio za gomilanje bogatstva i miješanje u političke događaje tog vremena. Nakon Ibrahimove smrti smijenjen je sa svih dužnosti i 1648. pogubljen.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Pogubljenje Kemankeša Mustafa-paše", "0ecc8030"], "d": ["Kemankeš Mustafa-paša, veliki vezir još od vremena Murata IV, koji je finansijskim reformama donio blagajni znatan višak, zadavljen je i tako pogubljen nakon što su njegovi dvorski suparnici utjecali na Ibrahima i optužili ga za izazivanje janičarske pobune. Prema članku \"Kemankeš Mustafa-paša\" u Enciklopediji islama TDV, pogubljen je 21. zul-kadea 1053 / 31. januara 1644: Kemankeš Kara Mustafa-pašu na Hodžapaša čaršiji zadavio je dželat Kara Ali, a sahranjen je u vlastitom turbetu na Čaršikapiji. Njegova se smrt pominje kao upečatljiv primjer nestabilnosti položaja velikog vezira u to doba, a njome je okončano i kratko razdoblje strogih reformi.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Divan odlučio o pohodu na Kretu, flota isplovila", "9076827e"], "d": ["U Carskom divanu odlučeno je da se pokrene veliki pohod na mletačko ostrvo Kretu i osmanska flota pod zapovjedništvom kapudan-paše isplovila je iz Istanbula prema Kreti. Prema članku \"Kreta\" u Enciklopediji islama TDV, ta je odluka bila politički početak dugog razdoblja opsada i ratovanja koje će trajati oko dvadeset pet godina. Pokretanje pohoda, kao najveći vanjskopolitički poduhvat Ibrahimovog razdoblja, izazvalo je široke rasprave među državnim dostojanstvenicima.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Mehmed IV stupio na prijestolje sa sedam godina", "a197a3bc"], "d": ["Odmah nakon Ibrahimovog svrgavanja, njegov tek sedmogodišnji sin Mehmed postavljen je na prijestolje i postao sultan pod imenom Mehmed IV. Prema članku \"Mehmed IV\" u Enciklopediji islama TDV, dolazak na prijestolje u tako mladoj dobi rasplamsao je borbu za utjecaj na dvoru između njegove bake Kosem-sultanije i majke Turhan-sultanije. Ta borba za vlast završit će 1651. ubistvom Kosem-sultanije.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reforma uravnoteženog budžeta Tarhundžua Ahmed-paše", "376fc7f2"], "d": ["Veliki vezir Tarhundžu Ahmed-paša, kako bi prevladao finansijsku krizu koju su izazvale duge godine rata, proveo je oštar program štednje koji je obuhvatao i dvorske rashode te sačinio prvi poznati uravnoteženi budžet u osmanskoj historiji (Tarhundžuov nacrt). Prema članku \"Tarhundžu Ahmed-paša\" u Enciklopediji islama TDV, ta je reforma donijela blagajni znatan višak, ali je izazvala široko nezadovoljstvo u dvorskim krugovima i visokoj birokratiji. To će nezadovoljstvo godinu kasnije dovesti do njegovog pogubljenja.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Slučaj platana (Vaka-i Vakvakije)", "4c6ed90f"], "d": ["Prema članku \"Slučaj platana\" u Enciklopediji islama TDV, janičari i spahije koji su se bez isplate vratili s pohoda na Kretu pobunili su se u Istanbulu i zahtijevali pogubljenje državnika koje su optuživali za zloupotrebe. Prijedlog velikog vezira Zurnazena Mustafa-paše o konfiskaciji i progonstvu nije prihvaćen; najprije su pogubljena tri službenika, a zatim blizu trideset državnika, čija su tijela obješena o platane na Sultanahmedovom trgu. Zbog toga je događaj nazvan Slučaj platana.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Mehmed-paša Ćuprilić imenovan velikim vezirom uz uslove", "3a6b7f8f"], "d": ["Prema članku o Mehmed-paši Ćupriliću u Enciklopediji islama TDV, Mehmed-paša Ćuprilić, blizu osamdesete godine života, preuzeo je pečat tek nakon što su valide-sultanija Turhan i Mehmed IV prihvatili njegove teške uslove -da se ne miješaju u njegova imenovanja i da ne vjeruju onome što se protiv njega govori-. Dužnost je preuzeo 26. zul-kadea 1066. umjesto Bojnuegrija Mehmed-paše i prionuo da oštrim mjerama ponovo uspostavi državnu disciplinu.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Mehmed-paša Ćuprilić ugušio pokret kadizadelija", "5ec3ce84"], "d": ["Prema članku o kadizadelijama u Enciklopediji islama TDV, čim je preuzeo dužnost, Mehmed-paša Ćuprilić pozabavio se vjerskim sukobom između kruga Kadizade Mehmed-efendije i pripadnika tarikata. Nakon savjetovanja s ulemom izdao je fermane o pogubljenju vođa pokreta Ustuvanija Mehmed-efendije, Turka Ahmeda i Divane Mustafe, ali je ta kazna preinačena u progonstvo i sva trojica poslana su na Kipar; time je okončana druga faza pokreta.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Veliki požar u Istanbulu: izgorjela Agina kapija", "b9253b66"], "d": ["Prema članku o Aginoj kapiji (Ağakapısı) u Enciklopediji islama TDV, u velikom požaru koji je izbio u julu 1660, za vrijeme Mehmeda IV, Agina kapija, službeno sjedište janičarskog age, potpuno je izgorjela, a zatim je ponovo sagrađena. Taj je požar bio jedan od velikih gradskih požara koji su iznova pogađali tadašnji Istanbul.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Fazil Ahmed-paša Ćuprilić imenovan velikim vezirom", "c1999b5c"], "d": ["Prema članku o Fazil Ahmed-paši Ćupriliću u Enciklopediji islama TDV, nakon smrti njegovog oca Mehmed-paše Ćuprilića doveden je na položaj velikog vezira 8. rebiul-evvela 1072. (1. novembra 1661). Fazil Ahmed-paša, poznat, za razliku od oca, kao blage naravi, pobožan i zaštitnik učenjaka i umjetnika, tokom više od petnaest godina svog vezirovanja dao je podići biblioteke i dobrotvorne ustanove u Istanbulu i na osvojenim područjima.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Vani Mehmed-efendija imenovan vaizom Nove džamije i sultanovim učiteljem", "7ea6aaae"], "d": ["Prema članku o Vaniju Mehmed-efendiji u Enciklopediji islama TDV, Vani Mehmed-efendija, pozvan u Istanbul kada je Fazil Ahmed-paša Ćuprilić postao veliki vezir i predstavljen Mehmedu IV, ubrzo je stekao sultanovu bliskost i naklonost. Godine 1665. postavljen je za vaiza Nove džamije i sultanovog učitelja, postavši jedan od najutjecajnijih vjerskih ljudi na dvoru.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Merzifonlu Kara Mustafa-paša imenovan velikim vezirom", "3d1e836c"], "d": ["Prema članku o Merzifonlu Kara Mustafa-paši u Enciklopediji islama TDV, nakon smrti Fazil Ahmed-paše doveden je na položaj velikog vezira 28. šabana 1087. (5. novembra 1676). Merzifonlu, zet i štićenik porodice Ćuprilića, s dugim iskustvom u upravljanju državom, postao je jedan od najmoćnijih i najutjecajnijih velikih vezira Mehmeda IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Vani Mehmed-efendija umro u progonstvu", "cda714aa"], "d": ["Prema članku o Vaniju Mehmed-efendiji u Enciklopediji islama TDV, Vani Mehmed-efendija, koji se smatra jednim od glavnih ljudi što su sultana nagovorili na pohod na Beč, nakon što je pohod završio porazom pao je pod pritiskom javnosti u nemilost i prognan u kasabu Kestel kod Burse. Tu je umro 14. zul-kadea 1096. (12. oktobra 1685) i sahranjen je na ulazu u džamiju koju je sam dao sagraditi.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Fazil Mustafa-paša Ćuprilić imenovan velikim vezirom i finansijske reforme", "b048570e"], "d": ["Prema članku o Fazil Mustafa-paši Ćupriliću u Enciklopediji islama TDV, Fazil Mustafa-paša, doveden na položaj velikog vezira 11. muharrema 1101. (25. oktobra 1689), preuredio je način ubiranja džizje prema šerijatskim načelima, borio se protiv inflacije izazvane mangirom i ojačao blagajnu prenošenjem sredstava iz dvorskih ustanova. Pored toga, ojačao je pokrajinsku upravu pouzdanim službenicima i dao osnovati mjesna vijeća nalik središnjem divanu.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Stupio na snagu sistem malikane", "316b8426"], "d": ["Prema članku o malikani u Enciklopediji islama TDV, u posljednjoj četvrtini XVII stoljeća povećanje ratnih troškova i smanjenje prihoda zbog gubitka teritorija uvalili su blagajnu u tešku finansijsku krizu. Sistemom malikane, koji je stupio na snagu 1106. (1695), zakupcima poreza priznato je doživotno pravo na stalni porez, čime je umjesto kratkoročnog iskorištavanja uveden poticaj za očuvanje proizvodnje.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Mustafa II stupio na prijestolje", "b53656c7"], "d": ["Prema članku o Mustafi II u Enciklopediji islama TDV, Mustafa II, koji je na prijestolje došao u trideset prvoj godini, proglasio je svoju vladavinu ne čekajući odobrenje velikog vezira i šejhul-islama; obred opasivanja sablje obavljen je nekoliko dana kasnije u Staroj džamiji. Sultan, koji je na prijestolje došao u razdoblju kada su se nakon poraza pod Bečom vodili ratovi na više frontova, bio je posljednji sultan u osmanskoj historiji koji je lično išao u pohod.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Fejzulah-efendija po drugi put imenovan šejhul-islamom", "1cf14cff"], "d": ["Prema članku o Sejjidu Fejzulah-efendiji u Enciklopediji islama TDV, nakon stupanja Mustafe II na prijestolje, 11. ševvala 1106. (25. maja 1695) po drugi je put doveden na položaj šejhul-islama. Njegov utjecaj na sultana postepeno je rastao tokom te službe koja je trajala više od osam godina.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Fejzulah-efendija postavlja sinove na visoke položaje, nezadovoljstvo se gomila", "a6398280"], "d": ["Prema članku o Sejjidu Fejzulah-efendiji u Enciklopediji islama TDV, šejhul-islam je od Mustafe II dobio ferman bez presedana da će njegov sin Fethulah-efendija nakon njega postati šejhul-islam, a rođake je u mladim godinama postavljao na visoke položaje. Ti su postupci izazvali široko nezadovoljstvo među ilmijom, vojskom i stanovništvom Istanbula; u spoju s glasinama da će se prijestonica preseliti u Edirne pripremili su tlo za Edirnski događaj 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Počeo Edirnski događaj", "5a106458"], "d": ["Prema članku \"Edirnski događaj\" Enciklopedije islama TDV, pokret koji je počeo pobunom vojnika koji nisu primili uluf ubrzo je prerastao u široku pobunu u kojoj su učestvovali janičari, učenici medresa, zanatlije i narod. Glavna meta pobune bio je šejhul-islam Fejzulah-efendija, za koga se tvrdilo da se pretjerano miješa u državne poslove. Mnoštvo od oko 60.000 ljudi krenulo je iz Istanbula na Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Veliko vezirovanje Nevšehirlije Damada Ibrahim-paše", "8d627a6f"], "d": ["Prema članku \"Damad Ibrahim-paša, Nevšehirli\" Enciklopedije islama TDV, tokom mirovnih pregovora s Austrijom koji su bili u toku doveden je na položaj velikog vezira 8. džumadel-uhra 1130. (9. maja 1718) i čim je imenovan, okrenuo se pregovorima kojima će se rat okončati; dva mjeseca kasnije potpisan je Požarevački mir (21. jula 1718). Prema riječima TDV, 'htio se baviti društvenim i finansijskim pitanjima i čeznuo je za mirnim razdobljem koje će učiniti da se zaborave ratovi koji su godinama završavali porazima'. Reformama u finansijama smanjio je vojničke plaće i stvorio znatan višak u državnoj blagajni. Njegovo vezirovanje, koje će trajati dvanaest godina, činilo je politički okvir razdoblja koje nosi njegov pečat (Doba tulipana).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Osnovan vatrogasni odžak (tulumbadžije)", "f58b0d97"], "d": ["Prema članku \"Tulumbacı\" Enciklopedije islama TDV, nakon uspjeha koji je s pumpom u istanbulskim požarima pokazao Gerček Davud, povratnik s pohoda na Moreju 1715, veliki vezir Nevšehirli Damad Ibrahim-paša povjerio mu je da osnuje službeni vatrogasni odžak. Odžak, osnovan u kasarni adžemi-oglana sa šest zapovjednika i pedeset vojnika, 1724. dosegao je 150, a 1755. godine 461 čovjeka. Davud je ostao na čelu odžaka do smrti 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Izgradnja dvorca Sadabad", "aec9c65e"], "d": ["Prema članku \"Sadabad\" Enciklopedije islama TDV, na obali potoka Kagithane sagrađen je prostran kompleks za zabavu i izlete koji se sastojao od dvorca inspiriranog francuskom dvorskom arhitekturom, kanala, česmi i ljetnikovaca. Sadabad, koji je postao najomiljenije mjesto zabave tog doba, ovjekovječen je u stihovima pjesnika Nedima. Kompleks je u velikoj mjeri uništen tokom pobune Patrone Halila 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Ruske snage zauzele Derbent: kaspijski pohod Petra I", "c2b269f9"], "d": ["Dok je safavidska država zbog afganske invazije bila uvučena u unutrašnje nemire, ruski car Petar I krenuo je u pohod s ciljem da zauzme iranske zemlje na obali Kaspijskog jezera; obalni grad Derbent predao se ruskim snagama bez znatnog otpora. Prema članku o Derbentu u Enciklopediji islama TDV, ta je okupacija bila početak privremene ruske vlasti koja će trajati trinaest godina; i Osmanska država, koristeći iste nemire, okrenula se zapadnom dijelu Kavkaza. Vojska je iz Astrahana morskim putem iskrcana u Agrahanskom zaljevu, a odatle je kopnom uz obalu preko Tarkija krenula pješke; tarkijski šamhal ugostio je Petra i stupio u rusko podaništvo.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Ukinut tarkijski šamhalat: izravna ruska uprava", "b0f029c6"], "d": ["Tarkijski šamhal Adil-Girej, koji je 1722. ugostio Petra i stupio u rusko podaništvo, pobunio se 1725; Jeropkin je u jesen 1725. razorio Tarki, šamhal je sredinom maja 1726. uhapšen i prognan, a šamhalat ukinut. Tarki i okolina ostali su pod izravnom ruskom upravom do Gandžinskog ugovora 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Ibrahimu Muteferiki dozvoljeno da otvori štampariju", "0659dd0a"], "d": ["Prema članku \"Ibrahim Muteferika\" Enciklopedije islama TDV, fermanom Ahmeda III i fetvom šejhul-islama Jenišehirlije Abdullah-efendije dozvoljeno je osnivanje prve turske štamparije. Štamparija je počela raditi u istanbulskoj četvrti Javuzselim. Muteferika je do smrti 1747. odštampao sedamnaest djela u dvadeset tri toma.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Dovršena prva štampana knjiga, Vankulijev rječnik", "684700e8"], "d": ["Prema članku \"Ibrahim Muteferika\" Enciklopedije islama TDV, prvo djelo štamparije, turski prijevod Džewherijevog Sihaha (Vankulijev rječnik), dovršeno je početkom 1729. To je bila prva knjiga štampana arapskim pismom na osmanskim područjima i smatra se početkom historije turskog štamparstva.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Pogubljenje Nevšehirlije Damada Ibrahim-paše", "50c64341"], "d": ["Prema članku \"Damad Ibrahim-paša, Nevšehirli\" Enciklopedije islama TDV, tijelo velikog vezira, ubijenog na dvoru tokom pobune Patrone Halila, vučeno je istanbulskim ulicama i ostavljeno kod česme Ahmeda III na Sultanahmedovom trgu. Tako su njegovo dvanaestogodišnje vezirovanje i Doba tulipana završili krvavo.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Ahmed III se odrekao prijestolja, Mahmud I stupio na prijestolje", "a43f5d40"], "d": ["Prema članku \"Mahmud I\" Enciklopedije islama TDV, pod pritiskom pobunjenika Ahmed III odrekao se prijestolja, osiguravši jamstva za sebe i svoju djecu, i sam je na prijestolje posadio svog nećaka princa Mahmuda. Mahmud I, koji je sjeo na prijestolje uz amidžin savjet \"državne poslove uzmi u svoje ruke, nikome ne vjeruj\", kao prvi posao prionuo je da slomi utjecaj pobunjeničke skupine koja ga je dovela na vlast.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reforma artiljerijskog odžaka Humbaradži Ahmed-paše", "ea3a7c64"], "d": ["Prema članku \"Humbaradži\" Enciklopedije islama TDV, Ahmed-paša, časnik francuskog porijekla koji je prešao na islam, u vrijeme velikog vezira Hećimoglu Ali-paše prionuo je reformi plaćene organizacije bombardijera po evropskom uzoru. Stvorio je novu postrojbu neposredno podređenu velikom veziru od 601 čovjeka, od čega 300 na plaći i 301 s timarom. Tehnologijom tog vremena dao je proizvesti 100 merzera i 50.000 topovskih zrna.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Osnivanje Hendesehane (prve inženjerske škole)", "a77ed1f3"], "d": ["Prema članku \"Mahmud I\" Enciklopedije islama TDV, Humbaradži Ahmed-paša osnovao je u Uskudaru Hendesehanu, zvanu i Humbarahana, i učenicima koje je odabrao među dvorskim slugama i bostandžijama davao vojno obrazovanje utemeljeno na matematici i geometriji. Ova se ustanova smatra prvim uzorom inženjerskih škola koje će se kasnije razviti.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Gandžinski ugovor: Derbent i Baku vraćeni Iranu", "ff19d531"], "d": ["Rusija, koja je tražila savez s Iranom protiv osmanske prijetnje, Gandžinskim ugovorom vratila je Iranu, pod zapovjedništvom Nadir-hana (koji još nije uzeo naslov šaha), gradove na kaspijskoj obali koje je držala trinaest godina. Prema članku o Derbentu u Enciklopediji islama TDV, to povlačenje bilo je posljedica ruske nevoljkosti da se na jugu istovremeno bori na dva fronta (osmanskom i iranskom) i učvrstilo je Nadirov vojni ugled koji je za nekoliko godina otvorio put njegovom stupanju na prijestolje. Tim se povlačenjem Iranu vratio i Tarki, pod ruskom upravom (na karti se koristi dan Gandžinskog ugovora). Tim se povlačenjem Iranu vraćaju i Salijan i Šabran, pod ruskom upravom (dan specifičan za ta naselja nije naveden u izvoru, na karti se koristi dan Gandžinskog ugovora — deklarirano približno određenje).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Nadir-šah stupio na prijestolje u Muganskoj ravnici: stvarni kraj dinastije Safavida", "4f640979"], "d": ["Prema članku o Nadir-šahu u Enciklopediji islama TDV, skupština od oko dvadeset hiljada ljudi okupljena u Muganskoj ravnici uporno je tražila da stane na čelo Irana; Nadir je tu ponudu prihvatio pod uslovom da se napusti krajnje šiitsko shvatanje koje je bilo uzrok ratova između Safavida i Osmanlija i da se prihvati umjereni džaferijski mezheb, te je 24. ševvala 1148. (8. marta 1736) stupio na prijestolje s naslovom Nadir-šah. To je značilo stvarni kraj dvostoljetne dinastije Safavida i osnivanje dinastije Afšarida.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Počela epidemija kuge u Istanbulu", "9fa82b56"], "d": ["Prema članku \"Kuga\" Enciklopedije islama TDV, epidemija kuge koja je harala islamskim svijetom između 1739. i 1743. u to je doba pogodila i Istanbul. Članak navodi da su epidemije u XVIII stoljeću u poređenju s prethodnim stoljećima bile razmjerno blaže. Među razdobljima epidemije navode se i 1713, 1719, 1728-1729. i 1759-1765.", "d650b99e"]}
});
